window.EXERCISE_GUIDES = {"3_4_Sit-Up":{"version":1,"steps":{"hu":["Feküdj hanyatt hajlított térddel és rögzített lábfejjel. Kezed a fejed mellett legyen.","Emeld a törzsed a térded felé.","Ne húzd a nyakad; visszafelé csak az út háromnegyedéig engedd le a törzsed."],"en":["Lie on your back with bent knees, feet secured and hands beside your head.","Raise your torso toward your knees.","Do not pull your neck; lower only three quarters of the way back."]},"reviewed":true,"summaryMethod":"curated"},"90_90_Hamstring":{"version":1,"steps":{"hu":["Feküdj hanyatt. Az egyik combod emeld függőlegesre, térded hajlítsd derékszögbe.","A combot megtartva nyújtsd a térded kényelmes tartományban.","Lassan hajlítsd vissza, majd válts lábat."],"en":["Lie on your back with one thigh vertical and that knee bent to a right angle.","Hold the thigh steady and straighten the knee through a comfortable range.","Bend it back slowly, then switch legs."]},"reviewed":true,"summaryMethod":"curated"},"Ab_Crunch_Machine":{"version":1,"steps":{"hu":["Állíts be kis ellenállást, ülj be a hasgépbe, akaszd a lábfejedet a párnák alá, és fogd meg a felső fogantyúkat.","Kezdd el egyszerre felfelé emelni a lábadat és előrehajlítani a felsőtestedet.","Egy másodperc szünet után lassan térj vissza a kiinduló helyzetbe, közben lélegezz be."],"en":["Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles.","At the same time, begin to lift the legs up as you crunch your upper torso.","After a second pause, slowly return to the starting position as you breathe in."]},"reviewed":false,"summaryMethod":"source-extract","board":"img/guide/Ab_Crunch_Machine.webp"},"Ab_Roller":{"version":1,"steps":{"hu":["Térdelj le, két kézzel fogd a haskereket a vállad alatt.","Gurítsd előre addig, amíg a törzsedet stabilan tudod tartani.","Ne ejtsd be a derekad; kontrolláltan húzd vissza a kereket."],"en":["Kneel with both hands on the ab wheel beneath your shoulders.","Roll forward only as far as you can keep your trunk steady.","Avoid sagging at your lower back; pull the wheel back with control."]},"reviewed":true,"summaryMethod":"curated"},"Adductor":{"version":1,"steps":{"hu":["Támaszkodj hason, egyik hajlított lábad belső combját tedd a hengerre.","Lassan gördülj a comb belső oldalán a csípő és a térd között.","A nyomás maradjon elviselhető; utána válts oldalt."],"en":["Support yourself face down with the inner thigh of one bent leg on a foam roller.","Roll slowly along the inner thigh between hip and knee.","Use tolerable pressure, then switch sides."]},"reviewed":true,"summaryMethod":"curated"},"Adductor_Groin":{"version":1,"steps":{"hu":["Feküdj hanyatt, lábad emeld és nyisd szét; társad a bokádnál tartson.","Próbáld összezárni a lábad, miközben társad ellenáll.","Lazíts, és engedj finom szétnyitást; jelezd a kényelmes határt."],"en":["Lie on your back with legs raised and apart, your partner holding your ankles.","Try to bring your legs together against your partner’s resistance.","Relax into a gentle assisted opening; communicate your comfortable limit."]},"reviewed":true,"summaryMethod":"curated"},"Advanced_Kettlebell_Windmill":{"version":1,"steps":{"hu":["Vedd fel a kettlebellt a válladhoz, majd nyomd ki egy kézzel a fejed fölé.","Ereszkedj le, amilyen mélyre csak tudsz.","Tarts egy másodperc szünetet, majd fordítsd meg a mozgást, és térj vissza a kiinduló helyzetbe."],"en":["Clean and press a kettlebell overhead with one arm.","Lower yourself as far as possible.","Pause for a second and reverse the motion back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Air_Bike":{"version":1,"steps":{"hu":["Feküdj a hátadra a talajon úgy, hogy a derekad a talajhoz simuljon.","Térj vissza a kiinduló helyzetbe, közben lélegezz be.","Folytasd így váltakozva, amíg mindkét oldalra el nem végzed az előírt ismétlésszámot."],"en":["Lie flat on the floor with your lower back pressed to the ground.","Go back to the initial position as you breathe in.","Continue alternating in this manner until all of the recommended repetitions for each side have been completed."]},"reviewed":false,"summaryMethod":"source-extract"},"All_Fours_Quad_Stretch":{"version":1,"steps":{"hu":["Indulj négykézláb helyzetből, majd emeld fel az egyik lábadat a talajról, és fogd meg a lábfejedet a kezeddel.","A kezeddel tartsd a lábfejedet vagy a bokádat, a térded legyen teljesen behajlítva, így nyújtod a combfeszítőt és a csípőhajlítót.","Koncentrálj a csípőd kinyújtására, told a talaj felé."],"en":["Start off on your hands and knees, then lift your leg off the floor and hold the foot with your hand.","Use your hand to hold the foot or ankle, keeping the knee fully flexed, stretching the quadriceps and hip flexors.","Focus on extending your hips, thrusting them towards the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Alternate_Hammer_Curl":{"version":1,"steps":{"hu":["Állj egyenes törzzsel, mindkét kezedben egy-egy kézisúlyzóval, nyújtott karral.","A felkarodat mozdulatlanul tartva hajlítsd fel a jobb oldali súlyzót, közben feszítsd meg a bicepszedet, és fújd ki a levegőt.","Folytasd így váltott karral az előírt ismétlésszámban."],"en":["Stand up with your torso upright and a dumbbell in each hand being held at arms length.","While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out.","Continue alternating in this manner for the recommended amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Alternate_Heel_Touchers":{"version":1,"steps":{"hu":["Feküdj a talajra behajlított térddel, a talpad legyen a talajon, egymástól kb.","Most lassan térj vissza a kiinduló helyzetbe, közben lélegezz be.","Folytasd így oldalt váltva, amíg el nem végzed az összes előírt ismétlést."],"en":["Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart.","Now go back slowly to the starting position as you inhale.","Continue alternating sides in this manner until all prescribed repetitions are done."]},"reviewed":false,"summaryMethod":"source-extract"},"Alternate_Incline_Dumbbell_Curl":{"version":1,"steps":{"hu":["Ülj le egy ferde padra, mindkét kezedben egy-egy kézisúlyzóval, nyújtott karral.","Lassan kezdd el visszaengedni a súlyzót a kiinduló helyzetbe, közben lélegezz be.","Folytasd így váltott karral az előírt ismétlésszámban."],"en":["Sit down on an incline bench with a dumbbell in each hand being held at arms length.","Slowly begin to bring the dumbbell back to starting position as your breathe in.","Continue alternating in this manner for the recommended amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Alternate_Leg_Diagonal_Bound":{"version":1,"steps":{"hu":["Állj kényelmesen úgy, hogy az egyik lábad kissé a másik előtt legyen.","Rugaszkodj el az elöl lévő lábadról, az ellentétes térdedet pedig lendítsd előre és minél magasabbra, mielőtt talajt érsz.","Segíthet, ha egy talajon lévő vonalhoz viszonyítva méred fel az oldalirányú távolságot."],"en":["Assume a comfortable stance with one foot slightly in front of the other.","Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing.","It may help to use a line on the ground to guage distance from side to side."]},"reviewed":false,"summaryMethod":"source-extract","board":"img/guide/Alternate_Leg_Diagonal_Bound.webp"},"Alternating_Cable_Shoulder_Press":{"version":1,"steps":{"hu":["Állítsd a csigákat a torony aljára, és válassz megfelelő súlyt.","A fejedet és a mellkasodat megemelve nyújtsd ki a könyöködet, és nyomd ki az egyik oldalt egyenesen a fejed fölé.","A felső ponton tarts szünetet, majd térj vissza a kiinduló helyzetbe, és ismételd meg a másik oldalon."],"en":["Move the cables to the bottom of the tower and select an appropriate weight.","Keeping your head and chest up, extend through the elbow to press one side directly over head.","After pausing at the top, return to the starting position and repeat on the opposite side."]},"reviewed":false,"summaryMethod":"source-extract"},"Alternating_Deltoid_Raise":{"version":1,"steps":{"hu":["Állva tarts egy pár kézisúlyzót a tested mellett.","Engedd vissza a súlyzókat a tested mellé.","Engedd vissza a súlyzókat a kiinduló helyzetbe, és folytasd felváltva az előre- és az oldalemelést."],"en":["In a standing position, hold a pair of dumbbells at your side.","Return the weights to your side.","Return the weights to the starting position and continue alternating to the front and side."]},"reviewed":false,"summaryMethod":"source-extract"},"Alternating_Floor_Press":{"version":1,"steps":{"hu":["Feküdj a talajra úgy, hogy két kettlebell legyen a vállad mellett.","Nyújtsd ki mindkét karodat úgy, hogy a kettlebellek a mellkasod fölött legyenek.","Nyomd ki a kettlebellt, és ismételd meg a másik oldalon."],"en":["Lie on the floor with two kettlebells next to your shoulders.","Extend both arms, so that the kettlebells are being held above your chest.","Raise the kettlebell and repeat on the opposite side."]},"reviewed":false,"summaryMethod":"source-extract"},"Alternating_Hang_Clean":{"version":1,"steps":{"hu":["Tegyél két kettlebellt a lábad közé.","Vedd fel az egyik kettlebellt a válladhoz, a másikat pedig tartsd függő helyzetben.","Engedd le a felvett kettlebellt függő helyzetbe, és vedd fel a másikat."],"en":["Place two kettlebells between your feet.","Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position.","Lower the cleaned kettlebell to a hanging position and clean the alternate kettlebell."]},"reviewed":false,"summaryMethod":"source-extract"},"Alternating_Kettlebell_Press":{"version":1,"steps":{"hu":["Vegyél fel két kettlebellt a válladhoz.","Nyomd ki az egyiket egyenesen a fejed fölé a könyököd kinyújtásával, és fordítsd úgy, hogy a tenyered előre nézzen, miközben a másik kettlebellt mozdulatlanul tartod.","Engedd vissza a kinyomott kettlebellt a kiinduló helyzetbe, és azonnal nyomj a másik karoddal."],"en":["Clean two kettlebells to your shoulders.","Press one directly overhead by extending through the elbow, turning it so the palm faces forward while holding the other kettlebell stationary .","Lower the pressed kettlebell to the starting position and immediately press with your other arm."]},"reviewed":false,"summaryMethod":"source-extract"},"Alternating_Kettlebell_Row":{"version":1,"steps":{"hu":["Tegyél két kettlebellt a lábad elé.","Emeld fel az egyik kettlebellt a talajról, miközben a másikat tartod.","Engedd le a kettlebellt a dolgozó karoddal, és ismételd meg a másik karoddal."],"en":["Place two kettlebells in front of your feet.","Pull one kettlebell off of the floor while holding on to the other kettlebell.","Lower the kettlebell in the working arm and repeat with your other arm."]},"reviewed":false,"summaryMethod":"source-extract"},"Alternating_Renegade_Row":{"version":1,"steps":{"hu":["Tegyél két kettlebellt a talajra, kb.","Az egyik kettlebellt nyomd a talajba, a másikkal pedig evezz: a dolgozó oldalon húzd hátra a lapockádat, hajlítsd a könyöködet, és húzd a kettlebellt az oldaladhoz.","Ezután engedd vissza a kettlebellt a talajra, és kezdd el a mozdulatot a másik kezedben lévő kettlebell-lel."],"en":["Place two kettlebells on the floor about shoulder width apart.","Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side.","Then lower the kettlebell to the floor and begin the kettlebell in the opposite hand."]},"reviewed":false,"summaryMethod":"source-extract"},"Ankle_Circles":{"version":1,"steps":{"hu":["Kapaszkodj meg egy stabil tárgyban, például egy guggolóállványban.","Emeld fel a jobb lábadat (csak kb.","Ha végeztél a jobb lábaddal, ismételd meg a ballal."],"en":["Use a sturdy object like a squat rack to hold yourself.","Lift the right leg in the air (just around 2 inches from the floor) and perform a circular motion with the big toe.","When you are done with the right foot, then repeat with the left leg."]},"reviewed":false,"summaryMethod":"source-extract"},"Ankle_On_The_Knee":{"version":1,"steps":{"hu":["Fekvő helyzetben hajlítsd be a térdedet, a talpad maradjon a talajon.","Tedd az egyik lábad bokáját az ellentétes térdedre.","Fogd meg az alul lévő lábad combját vagy térdét, és húzd mindkét lábadat a mellkasodhoz."],"en":["From a lying position, bend your knees and keep your feet on the floor.","Place your ankle of one foot on your opposite knee.","Grasp the thigh or knee of the bottom leg and pull both of your legs into the chest."]},"reviewed":false,"summaryMethod":"source-extract"},"Anterior_Tibialis-SMR":{"version":1,"steps":{"hu":["Ülj a talajra behajlított lábbal, a talpad legyen a talajon.","Masszázsrúddal (Muscle Roller) vagy sodrófával gyakorolj nyomást a sípcsontod külső oldalán lévő izmokra."],"en":["Begin seated on the ground with your legs bent and your feet on the floor.","Using a Muscle Roller or a rolling pin, apply pressure to the muscles on the outside of your shins."]},"reviewed":false,"summaryMethod":"source-extract"},"Anti-Gravity_Press":{"version":1,"steps":{"hu":["Tegyél egy rudat a talajra egy ferde pad fejrésze mögé.","Kezdésként nyomd ki a rudat a fejed elé a könyököd kinyújtásával.","Térj vissza a kiinduló helyzetbe, és ismételd, amíg be nem fejezed a sorozatot."],"en":["Place a bar on the ground behind the head of an incline bench.","To begin, press the barbell out in front of your head by extending your elbows.","Return to the starting position and repeat to complete the set."]},"reviewed":false,"summaryMethod":"source-extract"},"Arm_Circles":{"version":1,"steps":{"hu":["Állj fel, és nyújtsd ki a karodat egyenesen oldalra.","Kezdj el lassan kb.","Folytasd a kinyújtott karok körzését kb."],"en":["Stand up and extend your arms straight out by the sides.","Slowly start to make circles of about 1 foot in diameter with each outstretched arm.","Continue the circular motion of the outstretched arms for about ten seconds."]},"reviewed":false,"summaryMethod":"source-extract"},"Arnold_Dumbbell_Press":{"version":1,"steps":{"hu":["Ülj le egy háttámlás edzőpadra, és tarts két kézisúlyzót magad előtt, nagyjából a mellkasod felső részének magasságában, a tenyered nézzen a tested felé, a könyököd legyen behajlítva.","Emeld tovább a súlyzókat, amíg a karod teljesen ki nem nyúlik a fejed fölött.","A felső ponton tarts egy másodperc szünetet, majd kezdd el visszaengedni a súlyzókat a kiinduló helyzetbe úgy, hogy a tenyeredet magad felé fordítod."],"en":["Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent.","Continue lifting the dumbbells until your arms are extended above you in straight arm position.","After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you."]},"reviewed":false,"summaryMethod":"source-extract"},"Around_The_Worlds":{"version":1,"steps":{"hu":["Feküdj le egy sík padra, mindkét kezedben egy-egy kézisúlyzóval, a tenyered nézzen a mennyezet felé.","Most vidd a súlyzókat félkörívben a kiinduló helyzetből a fejed fölé.","Fordítsd meg a mozgást, és vidd vissza a súlyzókat a kiinduló helyzetbe, közben fújd ki a levegőt."],"en":["Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling.","Now move the dumbbells by creating a semi-circle as you displace them from the initial position to over the head.","Reverse the movement to return the weight to the starting position as you exhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Atlas_Stone_Trainer":{"version":1,"steps":{"hu":["Ez a gyakorlóeszköz hatékonyan fejleszti az Atlasz-kő emeléshez szükséges erőt azoknál, akiknek nincs hozzáférésük kövekhez; általában rúdvégekből vagy vastag csőből készül.","Kezdd el a súlyt a térded fölé húzni a csípőd nyújtásával.","A mozdulat befejezéséhez nyújtsd ki a csípődet és a térdedet, hogy a súlyt minél magasabbra emeld."],"en":["This trainer is effective for developing Atlas Stone strength for those who don't have access to stones, and are typically made from bar ends or heavy pipe.","Begin by pulling the weight up past the knees, extending through the hips.","Finish the movement by extending through your hips and knees to raise the weight as high as possible."]},"reviewed":false,"summaryMethod":"source-extract"},"Atlas_Stones":{"version":1,"steps":{"hu":["Kiinduláskor az Atlasz-kő legyen a lábad között.","Amint a kő elhagyja a térdedet, vedd az öledbe: ülj hátra, és húzd a követ a combod tetejére.","Ülj mélyre, és vidd a követ magasra a mellkasodra, miközben fogást váltasz, és átnyúlsz a kő fölött."],"en":["Begin with the atlas stone between your feet.","As the stone passes the knees, lap it by sitting backward, pulling the stone on top of your thighs.","Sit low, getting the stone high onto your chest as you change your grip to reach over the stone."]},"reviewed":false,"summaryMethod":"source-extract"},"Axle_Deadlift":{"version":1,"steps":{"hu":["Állj a rúdhoz úgy, hogy az a lábfejed közepe fölött legyen.","Miután a rúd elhagyta a térdedet, húzd erőteljesen hátra a rudat, zárd össze a lapockáidat, és told előre a csípődet a rúd felé.","Engedd le a rudat úgy, hogy csípőből előrehajolsz, és a talajra vezeted."],"en":["Approach the bar so that it is centered over your feet.","After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Back_Flyes_-_With_Bands":{"version":1,"steps":{"hu":["Vess át egy gumiszalagot egy rögzített oszlopon, például egy guggolóállvány oszlopán.","Nyújtsd ki és emeld a karodat egyenesen magad elé.","Rövid szünet után térj vissza a kiinduló helyzetbe, közben lélegezz be."],"en":["Run a band around a stationary post like that of a squat rack.","Extend and lift the arms straight in front of you.","After a pause, go back to the original position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Backward_Drag":{"version":1,"steps":{"hu":["Pakold fel a szánra a kívánt súlyt, és rögzíts hozzá egy kötelet vagy hevedert, amelybe kapaszkodni tudsz.","Kezdd a gyakorlatot úgy, hogy hátrafelé haladsz egy megadott távolságon."],"en":["Load a sled with the desired weight, attaching a rope or straps to the sled that you can hold onto.","Begin the exercise by moving backwards for a given distance."]},"reviewed":false,"summaryMethod":"source-extract"},"Backward_Medicine_Ball_Throw":{"version":1,"steps":{"hu":["Ezt a gyakorlatot a legjobb társsal végezni.","Guggolj le, majd robbanékonyan válts irányt, nyújtózz ki teljesen, és dobd a labdát a fejed fölött hátra a társadnak.","A társad ezután visszaguríthatja neked a labdát."],"en":["This exercise is best done with a partner.","Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner.","Your partner can then roll the ball back to you."]},"reviewed":false,"summaryMethod":"source-extract"},"Balance_Board":{"version":1,"steps":{"hu":["Tegyél magad elé egy egyensúlyozó deszkát.","Állj rá, és próbálj egyensúlyozni.","Tartsd meg az egyensúlyodat, ameddig csak szeretnéd."],"en":["Place a balance board in front of you.","Stand up on it and try to balance yourself.","Hold the balance for as long as desired."]},"reviewed":false,"summaryMethod":"source-extract"},"Ball_Leg_Curl":{"version":1,"steps":{"hu":["Feküdj a hátadra a talajon, a lábfejedet tedd a labda tetejére.","Emeld el a csípődet a talajról, a testsúlyod a lapockádon és a lábfejeden legyen.","Rövid szünet után térj vissza a kiinduló helyzetbe."],"en":["Begin on the floor laying on your back with your feet on top of the ball.","Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet.","After a brief pause, return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Band_Assisted_Pull-Up":{"version":1,"steps":{"hu":["Hurkold a gumiszalagot a húzódzkodó rúd közepére.","Húzd fel magad a széles hátizmod megfeszítésével, miközben hajlítod a könyöködet.","Rövid szünet után térj vissza a kiinduló helyzetbe."],"en":["Choke the band around the center of the pullup bar.","Pull yourself upward by contracting the lats as you flex the elbow.","After a brief pause, return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Band_Good_Morning":{"version":1,"steps":{"hu":["Állj rá egy kb.","A lábadat nyújtva tartva nyújtsd ki a csípődet, és emelkedj fel majdnem függőleges helyzetbe.","Ügyelj arra, hogy ne gömbölyítsd a hátadat, miközben visszaereszkedsz a kiinduló helyzetbe."],"en":["Using a 41 inch band, stand on one end, spreading your feet a small amount.","Keeping your legs straight, extend through the hips to come to a near vertical position.","Ensure that you do not round your back as you go down back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Band_Good_Morning_Pull_Through":{"version":1,"steps":{"hu":["Hurkold a gumiszalagot egy oszlop köré.","Kezdésként hajolj előre csípőből, és told hátra a feneked, amennyire csak tudod.","Térj vissza a kiinduló helyzetbe: a csípődet előretolva egyenesedj fel álló helyzetbe."],"en":["Loop the band around a post.","Begin by bending at the hips, getting your butt back as far as possible.","Return to the starting position be driving through with the hips to come back to a standing position."]},"reviewed":false,"summaryMethod":"source-extract"},"Band_Hip_Adductions":{"version":1,"steps":{"hu":["Rögzíts egy gumiszalagot egy stabil oszlophoz vagy más tárgyhoz.","A térdedet nyújtva tartva emeld a jobb lábadat oldalra, amilyen messzire csak tudod.","Válts oldalt."],"en":["Anchor a band around a solid post or other object.","Keeping the knee straight, raise your right legs out to the side as far as you can.","Switch sides."]},"reviewed":false,"summaryMethod":"source-extract"},"Band_Pull_Apart":{"version":1,"steps":{"hu":["Kiinduláskor a karod legyen egyenesen előrenyújtva, a gumiszalagot mindkét kezeddel fogd.","A mozdulat közben tartsd nyújtva a könyöködet, és húzd a szalagot a mellkasodhoz.","A mozdulat végén tarts szünetet, majd kontrolláltan térj vissza a kiinduló helyzetbe."],"en":["Begin with your arms extended straight out in front of you, holding the band with both hands.","Keep your elbows extended as you perform the movement, bringing the band to your chest.","Pause as you complete the movement, returning to the starting position under control."]},"reviewed":false,"summaryMethod":"source-extract"},"Band_Skull_Crusher":{"version":1,"steps":{"hu":["Rögzíts egy gumiszalagot egy állvány aljához vagy a padhoz.","Fogd meg a szalagot, és emeld fel a könyöködet úgy, hogy a felkarod merőleges legyen a talajra.","Nyújtsd ki a könyöködet, hogy a karod kiegyenesedjen, a felkarod közben maradjon a helyén."],"en":["Secure a band to the base of a rack or the bench.","Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor.","Extend through the elbow to straighten your arm, keeping your upper arm in place."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Ab_Rollout":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz vegyél fel fekvőtámasz helyzetet, de a kezed ne a talajon legyen, hanem egy olimpiai rudat fogj (mindkét oldalán 2,5–5 kg-os tárcsával).","A hátadat enyhén homorítva emeld meg a csípődet, és gurítsd a rudat a lábad felé, közben fújd ki a levegőt.","A felső ponton tartsd meg a megfeszítést egy másodpercig, majd lassan kezdd el visszagurítani a rudat előre a kiinduló helyzetbe, közben lélegezz be."],"en":["For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead.","While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale.","After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Ab_Rollout_-_On_Knees":{"version":1,"steps":{"hu":["Fogj meg egy olimpiai rudat, amelynek mindkét oldalán 2,5–5 kg-os tárcsa van, és térdelj le a talajra.","Lassan gurítsd a rudat egyenesen előre, és nyújtsd ki a testedet egyenes vonalba.","A nyújtott helyzetben tarts egy másodperc szünetet, majd kezdd el visszahúzni magad a kiinduló helyzetbe, közben fújd ki a levegőt."],"en":["Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.","Slowly roll the barbell straight forward, stretching your body into a straight position.","After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Bench_Press_-_Medium_Grip":{"version":1,"steps":{"hu":["Feküdj hanyatt egy sík padra.","Rövid szünet után nyomd vissza a rudat a kiinduló helyzetbe, közben fújd ki a levegőt.","Ha végeztél, tedd vissza a rudat az állványra."],"en":["Lie back on a flat bench.","After a brief pause, push the bar back to the starting position as you breathe out.","When you are done, place the bar back in the rack."]},"reviewed":false,"summaryMethod":"source-extract","board":"img/guide/Barbell_Bench_Press_-_Medium_Grip.webp"},"Barbell_Curl":{"version":1,"steps":{"hu":["Állj egyenes törzzsel, és fogj egy rudat vállszéles fogással.","Folytasd a mozdulatot, amíg a bicepszed teljesen meg nem feszül, és a rúd vállmagasságba nem kerül.","Lassan kezdd el visszaengedni a rudat a kiinduló helyzetbe, közben lélegezz be."],"en":["Stand up with your torso upright while holding a barbell at a shoulder-width grip.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level.","Slowly begin to bring the bar back to starting position as your breathe in."]},"reviewed":false,"summaryMethod":"source-extract","board":"img/guide/Barbell_Curl.webp"},"Barbell_Curls_Lying_Against_An_Incline":{"version":1,"steps":{"hu":["Feküdj rá egy ferde padra, a rudat tartó karod lógjon lefelé, a rúd legyen vízszintes.","A felkarodat mozdulatlanul tartva hajlítsd fel a súlyt olyan magasra, amennyire csak tudod, közben feszítsd meg a bicepszedet.","Tartsd meg a megfeszítést egy másodpercig, majd lassan térj vissza a kiinduló helyzetbe, közben lélegezz be."],"en":["Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line.","While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps.","After a second contraction, slowly go back to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Deadlift":{"version":1,"steps":{"hu":["Állj egy súlytárcsákkal megpakolt rúd elé.","A rudat fogva indítsd az emelést a lábaddal nyomva, és ezzel egy időben egyenesítsd fel a törzsedet, közben fújd ki a levegőt.","Végezd el a programban előírt ismétlésszámot."],"en":["Stand in front of a loaded barbell.","While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out.","Perform the amount of repetitions prescribed in the program."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Full_Squat":{"version":1,"steps":{"hu":["A biztonság kedvéért ezt a gyakorlatot guggolóállványban érdemes végezni.","Lépj el az állványtól, és állj közepes, vállszéles terpeszbe, enyhén kifelé fordított lábfejjel.","Kezdd el felfelé emelni a rudat, közben fújd ki a levegőt: a sarkaddal vagy a talpad közepével nyomd a talajt, nyújtsd ki a lábadat és a csípődet, és térj vissza a kiinduló helyzetbe."],"en":["This exercise is best performed inside a squat rack for safety purposes.","Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out.","Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract","board":"img/guide/Barbell_Full_Squat.webp"},"Barbell_Glute_Bridge":{"version":1,"steps":{"hu":["Ülj a talajra úgy, hogy egy megpakolt rúd legyen a lábad fölött.","Indítsd a mozdulatot a sarkaddal nyomva, és told a csípődet függőlegesen felfelé a rúdnak.","Nyújtsd ki a csípődet, amennyire csak tudod, majd fordítsd meg a mozgást, és térj vissza a kiinduló helyzetbe."],"en":["Begin seated on the ground with a loaded barbell over your legs.","Begin the movement by driving through with your heels, extending your hips vertically through the bar.","Extend as far as possible, then reverse the motion to return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Guillotine_Bench_Press":{"version":1,"steps":{"hu":["Közepes fogásszélességgel (olyan fogással, amelynél a mozdulat közepén az alkar és a felkar 90 fokos szöget zár be) emeld ki a rudat az állványból, és tartsd egyenesen a nyakad fölött, nyújtott karral.","Egy másodperc szünet után vidd vissza a rudat a kiinduló helyzetbe: fújd ki a levegőt, és a mellizmoddal nyomd a rudat.","Ha végeztél, tedd vissza a rudat az állványra."],"en":["Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles.","When you are done, place the bar back in the rack."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Hack_Squat":{"version":1,"steps":{"hu":["Állj egyenesen, vállszéles terpeszben, és tarts egy rudat a hátad mögött nyújtott karral.","A fejedet és a tekintetedet fent, a hátadat egyenesen tartva guggolj le, amíg a combod párhuzamos nem lesz a talajjal.","Főként a sarkaddal nyomva és a combodat megfeszítve emelkedj vissza, közben fújd ki a levegőt."],"en":["Stand up straight while holding a barbell behind you at arms length and your feet at shoulder width.","While keeping your head and eyes up and back straight, squat until your upper thighs are parallel to the floor.","Pressing mainly with the heel of the foot and squeezing the thighs, go back up as you breathe out."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Hip_Thrust":{"version":1,"steps":{"hu":["Ülj a talajra úgy, hogy egy pad legyen közvetlenül mögötted.","Gurítsd a rudat közvetlenül a csípőd fölé, és dőlj hátra a padnak úgy, hogy a lapockád a pad felső széle közelében legyen.","Indítsd a mozdulatot a talpaddal nyomva, és told a csípődet függőlegesen felfelé a rúdnak."],"en":["Begin seated on the ground with a bench directly behind you.","Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.","Begin the movement by driving through your feet, extending your hips vertically through the bar."]},"reviewed":false,"summaryMethod":"source-extract","board":"img/guide/Barbell_Hip_Thrust.webp"},"Barbell_Incline_Bench_Press_-_Medium_Grip":{"version":1,"steps":{"hu":["Feküdj a ferde padra, talpad támaszd le. A rudat fogd kissé vállszélesen kívül.","Engedd a rudat a felső mellkasodhoz, majd nyomd fel.","Lapockád maradjon támaszon; ne pattintsd a rudat."],"en":["Lie on the incline bench, feet planted, with a grip slightly wider than your shoulders.","Lower the bar to your upper chest, then press up.","Keep your shoulder blades supported; do not bounce the bar."]},"reviewed":true,"summaryMethod":"curated","board":"img/guide/Barbell_Incline_Bench_Press_-_Medium_Grip.webp"},"Barbell_Incline_Shoulder_Raise":{"version":1,"steps":{"hu":["Feküdj hanyatt egy ferde padra.","A karodat nyújtva tartva emeld meg a rudat a lapockáid előretolásával úgy, hogy a vállad elemelkedjen a padról, közben fújd ki a levegőt.","Engedd vissza a rudat a kiinduló helyzetbe, közben lélegezz be."],"en":["Lie back on an Incline Bench.","While keeping the arms straight, lift the bar by protracting your shoulder blades, raising the shoulders from the bench as you breathe out.","Bring back the bar to the starting position as you breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Lunge":{"version":1,"steps":{"hu":["A biztonság kedvéért ezt a gyakorlatot guggolóállványban érdemes végezni.","Lépj el az állványtól, majd lépj előre a jobb lábaddal, és ereszkedj le csípőből, miközben a törzsedet egyenesen tartod, és megőrzöd az egyensúlyodat.","Főként a sarkaddal nyomva told fel magad, és térj vissza a kiinduló helyzetbe, közben fújd ki a levegőt."],"en":["This exercise is best performed inside a squat rack for safety purposes.","Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance.","Using mainly the heel of your foot, push up and go back to the starting position as you exhale."]},"reviewed":false,"summaryMethod":"source-extract","board":"img/guide/Barbell_Lunge.webp"},"Barbell_Rear_Delt_Row":{"version":1,"steps":{"hu":["Állj egyenesen, és fogj egy rudat széles (vállszélességnél szélesebb), felső fogással (a tenyered a tested felé néz).","A felkarodat a törzsedre merőlegesen tartva húzd a rudat a mellkasod felső része felé, közben feszítsd meg a hátsó deltaizmodat, és fújd ki a levegőt.","Lassan térj vissza a kiinduló helyzetbe, közben lélegezz be."],"en":["Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip.","While keeping the upper arms perpendicular to the torso, pull the barbell up towards your upper chest as you squeeze the rear delts and you breathe out.","Slowly go back to the initial position as you breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Rollout_from_Bench":{"version":1,"steps":{"hu":["Tegyél egy megpakolt rudat a talajra, egy pad végéhez közel.","Kezdésként nyújtsd ki a csípődet, és lassan gurítsd előre a rudat.","Amikor a rudat a lehető legmesszebbre gurítottad előre, térj vissza a kiinduló helyzetbe."],"en":["Place a loaded barbell on the ground, near the end of a bench.","To begin, extend through the hips to slowly roll the bar forward.","When the bar has been moved as far forward as possible, return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Seated_Calf_Raise":{"version":1,"steps":{"hu":["Tegyél egy dobogót kb.","Kérj meg valakit, hogy tegyen egy rudat a combodra, kb.","Tartsd meg a megfeszítést egy másodpercig, majd lassan térj vissza a kiinduló helyzetbe."],"en":["Place a block about 12 inches in front of a flat bench.","Have someone place a barbell over your upper thighs about 3 inches above your knees and hold it there.","After a second contraction, slowly go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Shoulder_Press":{"version":1,"steps":{"hu":["Ülj le egy háttámlás padra egy guggolóállványban.","Engedd le lassan a rudat a válladig, közben lélegezz be.","Nyomd vissza a rudat a kiinduló helyzetbe, közben fújd ki a levegőt."],"en":["Sit on a bench with back support in a squat rack.","Lower the bar down to the shoulders slowly as you inhale.","Lift the bar back up to the starting position as you exhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Shrug":{"version":1,"steps":{"hu":["Állj egyenesen, vállszéles terpeszben, és tarts magad előtt egy rudat két kézzel, felső fogással (a tenyered a combod felé néz).","Húzd fel a válladat, amilyen magasra csak tudod, közben fújd ki a levegőt, és tartsd meg a megfeszítést egy másodpercig.","Lassan térj vissza a kiinduló helyzetbe, közben lélegezz be."],"en":["Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs).","Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second.","Slowly return to the starting position as you breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Shrug_Behind_The_Back":{"version":1,"steps":{"hu":["Állj egyenesen, vállszéles terpeszben, és tarts a hátad mögött egy rudat két kézzel, felső fogással (a tenyered hátrafelé néz).","Húzd fel a válladat, amilyen magasra csak tudod, közben fújd ki a levegőt, és tartsd meg a megfeszítést egy másodpercig.","Lassan térj vissza a kiinduló helyzetbe, közben lélegezz be."],"en":["Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back).","Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second.","Slowly return to the starting position as you breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Side_Bend":{"version":1,"steps":{"hu":["Állj egyenesen, a rúd legyen a vállad hátsó részén (kicsivel a nyakad alatt).","A hátadat egyenesen, a fejedet fent tartva hajolj jobbra, csak derékból, amennyire csak tudsz.","Most ismételd meg a mozdulatot, de balra hajolva."],"en":["Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck).","While keeping your back straight and your head up, bend only at the waist to the right as far as possible.","Now repeat the movement but bending to the left instead."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Side_Split_Squat":{"version":1,"steps":{"hu":["Állj egyenesen, a rúd legyen a vállad hátsó részén (kicsivel a nyakad alatt).","Térj vissza a kiinduló helyzetbe a vezető lábad csípőjének és térdének kinyújtásával.","Az előírt ismétlésszám elvégzése után ismételd meg a mozdulatot a másik lábaddal."],"en":["Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck).","Return to the starting position by extending the hip and knee of the lead leg.","After performing the recommended amount of reps, repeat the movement with the opposite leg."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Squat":{"version":1,"steps":{"hu":["A biztonság kedvéért ezt a gyakorlatot guggolóállványban érdemes végezni.","Lépj el az állványtól, és állj közepes, vállszéles terpeszbe, enyhén kifelé fordított lábfejjel.","Kezdd el felfelé emelni a rudat, közben fújd ki a levegőt: a sarkaddal nyomd a talajt, nyújtsd ki újra a lábadat, és térj vissza a kiinduló helyzetbe."],"en":["This exercise is best performed inside a squat rack for safety purposes.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Squat_To_A_Bench":{"version":1,"steps":{"hu":["A biztonság kedvéért ezt a gyakorlatot guggolóállványban érdemes végezni.","Lépj el az állványtól, és állj közepes, vállszéles terpeszbe, enyhén kifelé fordított lábfejjel.","Kezdd el felfelé emelni a rudat, közben fújd ki a levegőt: a sarkaddal nyomd a talajt, nyújtsd ki a lábadat és a csípődet, és térj vissza a kiinduló helyzetbe."],"en":["This exercise is best performed inside a squat rack for safety purposes.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs and extend the hips to go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Barbell_Step_Ups":{"version":1,"steps":{"hu":["Állj egyenesen, a rúd legyen a vállad hátsó részén (kicsivel a nyakad alatt), és állj egy megemelt dobogó mögé (például olyan mögé, amilyenre a segítő áll a sík pad mögött).","Tedd a jobb lábfejedet a dobogóra.","Lépj le a bal lábaddal úgy, hogy közben a jobb lábad csípőjét és térdét hajlítod, és lélegezz be."],"en":["Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat bench).","Place the right foot on the elevated platform.","Step down with the left leg by flexing the hip and knee of the right leg as you inhale."]},"reviewed":false,"summaryMethod":"source-extract","board":"img/guide/Barbell_Step_Ups.webp"},"Barbell_Walking_Lunge":{"version":1,"steps":{"hu":["Állj vállszéles terpeszben, a rúd legyen a hátad felső részén.","Nyomd a talajt az elöl lévő lábad sarkával, és nyújtsd ki mindkét térdedet, hogy visszaemelkedj.","Lépj előre a hátsó lábaddal, és ismételd meg a kitörést a másik lábaddal."],"en":["Begin standing with your feet shoulder width apart and a barbell across your upper back.","Drive through the heel of your lead foot and extend both knees to raise yourself back up.","Step forward with your rear foot, repeating the lunge on the opposite leg."]},"reviewed":false,"summaryMethod":"source-extract"},"Battling_Ropes":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz egy nehéz kötélre lesz szükséged, amely a közepénél, tőled kb.","Miközben ezt a karodat visszaengeded a kiinduló helyzetbe, emeld a másikat.","Folytasd felváltva a bal és a jobb karoddal, és csapkodd a köteleket fel-le, amilyen gyorsan csak tudod."],"en":["For this exercise you will need a heavy rope anchored at its center 15-20 feet away.","As you let that arm drop to the starting position, raise the opposite side.","Continue alternating your left and right arms, whipping the ropes up and down as fast as you can."]},"reviewed":false,"summaryMethod":"source-extract"},"Bear_Crawl_Sled_Drags":{"version":1,"steps":{"hu":["Vegyél fel hámot vagy egy lazán meghúzott súlyemelő övet, és rögzítsd a láncot hátul úgy, hogy háttal állj a szánnak.","Kezdj el a lábaddal tolni, felváltva a ballal és a jobbal."],"en":["Wearing either a harness or a loose weight belt, attach the chain to the back so that you will be facing away from the sled.","Begin by driving with legs, alternating left and right."]},"reviewed":false,"summaryMethod":"source-extract"},"Behind_Head_Chest_Stretch":{"version":1,"steps":{"hu":["Ülj egyenes háttal a talajra, a társad legyen mögötted.","Legalább 10 másodpercig próbáld óvatosan előrehúzni a könyöködet úgy, hogy a kezed továbbra is a fejed mögött van.","Most lazítsd el az izmaidat, és a társad óvatosan húzza hátra a könyöködet addig, ameddig még kényelmes."],"en":["Sit upright on the floor with your partner behind you.","Gently attempt to pull your elbows forward with your hands still behind your head for 10 or more seconds.","Now, relax your muscles and have your partner gently pull the elbows back as far as it comfortable for you."]},"reviewed":false,"summaryMethod":"source-extract"},"Bench_Dips":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz helyezz egy padot a hátad mögé.","Lélegezz be, és közben lassan engedd le a testedet a könyököd hajlításával, amíg a felkarod és az alkarod 90 foknál kicsit kisebb szöget nem zár be.","A tricepszeddel emeld vissza a törzsedet, és nyomd ki magad a kiinduló helyzetbe."],"en":["For this exercise you will need to place a bench behind your back.","Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm.","Using your triceps to bring your torso up again, lift yourself back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Bench_Jump":{"version":1,"steps":{"hu":["Kiinduláskor legyen előtted egy doboz vagy pad, kb.","Ebből a helyzetből rugaszkodj el: nyújtsd ki a csípődet, a térdedet és a bokádat, és ugorj a lehető legmagasabbra.","Fordulj meg, hogy az ellenkező irányba nézz, majd ugorj vissza a pad fölött."],"en":["Begin with a box or bench 1-2 feet in front of you.","Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible.","Turn around and face the opposite direction, then jump back over the bench."]},"reviewed":false,"summaryMethod":"source-extract"},"Bench_Press_-_Powerlifting":{"version":1,"steps":{"hu":["Feküdj a padra, és ha lehet, a fejed kerüljön a rúdon túlra.","Engedd le a rudat a mellkasod alsó részére vagy a hasad felső részére.","Tarts szünetet, amikor a rúd a törzsedhez ér, majd nyomd ki a rudat a lehető legnagyobb erővel."],"en":["Begin by lying on the bench, getting your head beyond the bar if possible.","Lower the bar to your lower chest or upper stomach.","Pause when the barbell touches your torso, and then drive the bar up with as much force as possible."]},"reviewed":false,"summaryMethod":"source-extract"},"Bench_Press_-_With_Bands":{"version":1,"steps":{"hu":["Egy sík padnál rögzítsd a gumiszalagot a pad fejedhez közelebbi lába alá.","Vállszélességben tartva fordítsd előre a csuklód, hogy a tenyered tőled elfelé nézzen.","Kilégzés közben nyomd fel a fogantyúkat a mellizmod erejével."],"en":["Using a flat bench secure a band under the leg of the bench that is nearest to your head.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you.","As you breathe out, bring the handles up using your pectoral muscles."]},"reviewed":false,"summaryMethod":"source-extract"},"Bench_Press_with_Chains":{"version":1,"steps":{"hu":["Állítsd be a vezetőláncot: rövidítsd a kívánt hosszra.","Emeld ki a rudat az állványból úgy, hogy a vállad ne csússzon előre.","Állj meg, amikor a rúd hozzáér a törzsedhez, majd nyomd ki a rudat a lehető legnagyobb erővel."],"en":["Adjust the leader chain, shortening it to the desired length.Place the chains on the sleeves of the bar.","Pull the bar out of the rack without protracting your shoulders.","Pause when the barbell touches your torso, and then drive the bar up with as much force as possible."]},"reviewed":false,"summaryMethod":"source-extract"},"Bench_Sprint":{"version":1,"steps":{"hu":["Állj a talajon úgy, hogy az egyik lábfejed egy padon vagy dobozon van, a sarkad a széléhez közel.","Érkezz az ellenkező lábaddal a doboz tetejére, a másik lábad pedig vidd vissza a kiinduló helyzetbe.","Folytasd a lábak váltogatását a sorozat végéig."],"en":["Stand on the ground with one foot resting on a bench or box with your heel close to the edge.","Land with the opposite foot on top of the box, returning your other foot back to the start position.","Continue alternating from one foot to another to complete the set."]},"reviewed":false,"summaryMethod":"source-extract"},"Bent-Arm_Barbell_Pullover":{"version":1,"steps":{"hu":["Feküdj sík padra egy rúddal, vállszéles fogással.","A karodat végig hajlítva tartva engedd le lassan a súlyt ívben a fejed mögé, közben lélegezz be, amíg nyúlást nem érzel a mellkasodban.","Tartsd meg a súlyt a kiinduló helyzetben egy másodpercig, majd ismételd a mozdulatot az előírt ismétlésszámban."],"en":["Lie on a flat bench with a barbell using a shoulder grip width.","While keeping your arms in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.","Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Bent-Arm_Dumbbell_Pullover":{"version":1,"steps":{"hu":["Állíts fel egy kézisúlyzót az egyik végére egy sík padon.","A karodat a hajlított helyzetben rögzítve engedd le lassan a súlyt ívben a fejed mögé, közben lélegezz be, amíg nyúlást nem érzel a mellkasodban.","Tartsd meg a súlyt a kiinduló helyzetben egy másodpercig, majd ismételd a mozdulatot az előírt ismétlésszámban."],"en":["Place a dumbbell standing up on a flat bench.","While keeping your arms locked in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.","Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Bent-Knee_Hip_Raise":{"version":1,"steps":{"hu":["Feküdj hanyatt a talajra, a karod a tested mellett.","Az alsó hasizmod erejével húzd a térded magad felé, miközben megtartod a lábad 75 fokos hajlítását.","A mozdulat tetején feszítsd meg a hasad egy másodpercre, majd belégzés közben lassan térj vissza a kiinduló helyzetbe."],"en":["Lay flat on the floor with your arms next to your sides.","Using your lower abs, bring your knees in towards you as you maintain the 75 degree angle bend in your legs.","Squeeze your abs at the top of the movement for a second and then return to the starting position slowly as you breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Bent_Over_Barbell_Row":{"version":1,"steps":{"hu":["Fogd meg a rudat felső fogással (a tenyér lefelé néz), hajlítsd be enyhén a térded, és derékból előrehajolva döntsd előre a törzsed egyenes háttal, amíg majdnem párhuzamos nem lesz a talajjal.","Most a törzsedet mozdulatlanul tartva fújd ki a levegőt, és húzd a rudat magadhoz.","Ezután lélegezz be, és lassan engedd vissza a rudat a kiinduló helyzetbe."],"en":["Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor.","Now, while keeping the torso stationary, breathe out and lift the barbell to you.","Then inhale and slowly lower the barbell back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract","board":"img/fig/row.webp"},"Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench":{"version":1,"steps":{"hu":["Állj egyenesen, mindkét kezedben egy-egy kézisúlyzóval, előtted egy ferde paddal.","A törzsedet előredöntve és mozdulatlanul, a karodat nyújtva, a könyöködet csak enyhén hajlítva tartva emeld a kézisúlyzókat egyenesen oldalra, amíg mindkét karod párhuzamos nem lesz a talajjal.","A felső ponton tartsd megfeszítve egy másodpercig, majd lassan engedd vissza a kézisúlyzókat a kiinduló helyzetbe."],"en":["Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you.","Keeping your torso forward and stationary, and the arms straight with a slight bend at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor.","After a one second contraction at the top, slowly lower the dumbbells back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Bent_Over_Low-Pulley_Side_Lateral":{"version":1,"steps":{"hu":["Válassz súlyt, és fogd meg az alsó csiga fogantyúját a jobb kezeddel.","Emeld a jobb karod enyhén hajlított könyökkel oldalra, amíg párhuzamos nem lesz a talajjal, és egy vonalba nem kerül a jobb füleddel.","Belégzés közben lassan engedd vissza a súlyt a kiinduló helyzetbe."],"en":["Select a weight and hold the handle of the low pulley with your right hand.","Raise your right arm, elbow slightly bent, to the side until the arm is parallel to the floor and in line with your right ear.","Slowly lower the weight back to the starting position as you breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Bent_Over_One-Arm_Long_Bar_Row":{"version":1,"steps":{"hu":["Tegyél súlyt egy olimpiai rúd egyik végére.","Most fogd meg a rudat egy kézzel közvetlenül a tárcsák mögött, azon a végén, ahová a súlyt tetted, a másik kezed pedig tedd a térdedre.","Engedd le lassan a rudat a kiinduló helyzetbe, hogy a széles hátizmod szépen megnyúljon."],"en":["Put weight on one of the ends of an Olympic barbell.","Now grab the bar with one arm just behind the plates on the side where the weight was placed and put your other hand on your knee.","Slowly lower the bar to the starting position getting a nice stretch on the lats."]},"reviewed":false,"summaryMethod":"source-extract"},"Bent_Over_Two-Arm_Long_Bar_Row":{"version":1,"steps":{"hu":["Tegyél súlyt egy olimpiai rúd egyik végére.","Most fogd meg a rudat két kézzel közvetlenül a tárcsák mögött, azon a végén, ahová a súlyt tetted.","Engedd le lassan a rudat a kiinduló helyzetbe, hogy a széles hátizmod szépen megnyúljon."],"en":["Put weight on one of the ends of an Olympic barbell.","Now grab the bar with both arms just behind the plates on the side where the weight was placed and put your other hand on your knee.","Slowly lower the bar to the starting position getting a nice stretch on the lats."]},"reviewed":false,"summaryMethod":"source-extract"},"Bent_Over_Two-Dumbbell_Row":{"version":1,"steps":{"hu":["Mindkét kezedben egy-egy kézisúlyzóval (a tenyér a törzsed felé néz) hajlítsd be enyhén a térded, és derékból előrehajolva döntsd előre a törzsed; hajlás közben ügyelj rá, hogy a hátad egyenes maradjon, és addig dőlj, amíg majdnem párhuzamos nem lesz a talajjal.","A törzsedet mozdulatlanul tartva húzd a kézisúlyzókat az oldaladhoz (közben fújd ki a levegőt), a könyöködet a testedhez közel tartva (az alkaroddal ne fejts ki erőt, csak a súlyokat tartsd vele).","Belégzés közben lassan engedd vissza a súlyt a kiinduló helyzetbe."],"en":["With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor.","While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights).","Slowly lower the weight again to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Bent_Over_Two-Dumbbell_Row_With_Palms_In":{"version":1,"steps":{"hu":["Mindkét kezedben egy-egy kézisúlyzóval (a tenyerek egymás felé néznek) hajlítsd be enyhén a térded, és derékból előrehajolva döntsd előre a törzsed egyenes háttal, amíg majdnem párhuzamos nem lesz a talajjal.","A törzsedet mozdulatlanul tartva, kilégzés közben húzd a kézisúlyzókat az oldaladhoz, és zárd össze a lapockáidat.","Belégzés közben lassan engedd vissza a súlyt a kiinduló helyzetbe."],"en":["With a dumbbell in each hand (palms facing each other), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor.","While keeping the torso stationary, lift the dumbbells to your side as you breathe out, squeezing your shoulder blades together.","Slowly lower the weight again to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Bent_Press":{"version":1,"steps":{"hu":["Vedd fel a kettlebellt a válladra.","Kezdj el a kettlebell-lel ellentétes oldalra dőlni, és folytasd addig, amíg a szabad kezeddel meg nem tudod érinteni a talajt; a szemedet végig tartsd a kettlebellen.","Egyenesedj fel úgy, hogy a kettlebell a fejed fölött van."],"en":["Clean a kettlebell to your shoulder.","Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell.","Return to an upright position, with the kettlebell above your head."]},"reviewed":false,"summaryMethod":"source-extract"},"Bicycling":{"version":1,"steps":{"hu":["Kezdésként ülj fel a kerékpárra, és állítsd be az ülést a magasságodhoz."],"en":["To begin, seat yourself on the bike and adjust the seat to your height."]},"reviewed":false,"summaryMethod":"source-extract"},"Bicycling_Stationary":{"version":1,"steps":{"hu":["Kezdésként ülj fel a kerékpárra, és állítsd be az ülést a magasságodhoz.","Válaszd ki a kívánt opciót a menüből."],"en":["To begin, seat yourself on the bike and adjust the seat to your height.","Select the desired option from the menu."]},"reviewed":false,"summaryMethod":"source-extract"},"Board_Press":{"version":1,"steps":{"hu":["Kezdésként feküdj a padra, és csúsztasd a fejed lehetőleg a rúdon túlra.","Foghatod a rudat a szokásos fekvenyomó fogással, vagy vállszélességben, ha a tricepszre akarsz koncentrálni.","Engedd le a rudat a deszkákra, majd nyomd ki a lehető legnagyobb erővel."],"en":["Begin by lying on the bench, getting your head beyond the bar if possible.","You can take a standard bench grip, or shoulder width to focus on the triceps.","Lower the bar to the boards, and then drive the bar up with as much force as possible."]},"reviewed":false,"summaryMethod":"source-extract"},"Body-Up":{"version":1,"steps":{"hu":["Helyezkedj plank pozícióba a talajon.","A tenyeredet erősen a talajba nyomva nyújtsd ki a könyököd, és emeld el a tested a talajról.","Engedd vissza lassan az alkarod a talajra a könyököd hajlításával."],"en":["Assume a plank position on the ground.","Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground.","Slowly lower your forearms back to the ground by allowing the elbows to flex."]},"reviewed":false,"summaryMethod":"source-extract"},"Body_Tricep_Press":{"version":1,"steps":{"hu":["Állíts be egy rudat az állványban mellmagasságba.","Kezdd a könyököd hajlításával, és engedd magad a rúd felé.","Ha a saját testsúly már kevés, nehezíts a válladra vetett láncokkal."],"en":["Position a bar in a rack at chest height.","Begin by flexing the elbow, lowering yourself towards the bar.","Progress from bodyweight by adding chains over your shoulders."]},"reviewed":false,"summaryMethod":"source-extract"},"Bodyweight_Flyes":{"version":1,"steps":{"hu":["Tegyél egymás mellé a talajra két egyformán megpakolt EZ-rudat.","Tedd a kezed a rudakra.","Miután a rudakat a lehető legmesszebb gurítottad egymástól, húzd össze őket, és térj vissza a kiinduló helyzetbe."],"en":["Position two equally loaded EZ bars on the ground next to each other.","Place your hands on the bars.","After moving the bars as far apart as you can, return to the starting position by pulling them back together."]},"reviewed":false,"summaryMethod":"source-extract"},"Bodyweight_Mid_Row":{"version":1,"steps":{"hu":["Kezdésként fogd meg a húzódzkodó rudat közepes vagy széles fogással úgy, hogy a tenyered tőled elfelé nézzen.","Nyújtott karral indulva hajlítsd be a könyököd, húzd hátra a lapockáidat, és emeld a tested addig, amíg a lábad hozzá nem ér a húzódzkodó állványhoz.","Rövid szünet után térj vissza a kiinduló helyzetbe."],"en":["Begin by taking a medium to wide grip on a pull-up apparatus with your palms facing away from you.","Beginning with your arms straight, flex the elbows and retract the shoulder blades to raise your body up until your legs contact the pull-up apparatus.","After a brief pause, return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Bodyweight_Squat":{"version":1,"steps":{"hu":["Állj vállszéles terpeszbe.","Kezdd a mozdulatot a térded és a csípőd hajlításával, a csípődet hátratolva, mintha leülnél.","Ha képes vagy rá, menj le teljes mélységig, majd gyorsan fordítsd meg a mozdulatot, és térj vissza a kiinduló helyzetbe."],"en":["Stand with your feet shoulder width apart.","Begin the movement by flexing your knees and hips, sitting back with your hips.","Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Bodyweight_Walking_Lunge":{"version":1,"steps":{"hu":["Állj vállszéles terpeszbe, a kezed a csípődön.","Az elöl lévő lábad sarkából tolva nyújtsd ki mindkét térded, és emelkedj vissza.","Lépj előre a hátsó lábaddal, és ismételd meg a kitörést a másik lábra."],"en":["Begin standing with your feet shoulder width apart and your hands on your hips.","Drive through the heel of your lead foot and extend both knees to raise yourself back up.","Step forward with your rear foot, repeating the lunge on the opposite leg."]},"reviewed":false,"summaryMethod":"source-extract"},"Bosu_Ball_Cable_Crunch_With_Side_Bends":{"version":1,"steps":{"hu":["Csatlakoztass egy-egy normál fogantyút a kábeles gép mindkét karjára, és állítsd őket a legalsó helyzetbe.","Széles terpeszben tartott lábbal nyújtsd ki a karod egyenesen magad elé, a térdeid közé.","Engedd le a karod a tested mellé, és tartsd nyújtva."],"en":["Connect a standard handle to each arm of a cable machine, and position them in the most downward position.","With your feet positioned in a wide stance, extend your arms straight out in front of you and in between your knees.","Lower your arms down to your side; keep them straight."]},"reviewed":false,"summaryMethod":"source-extract"},"Bottoms-Up_Clean_From_The_Hang_Position":{"version":1,"steps":{"hu":["Kezdd a gyakorlatot egyenesen állva, egyik kezedben egy kettlebell-lel.","Lendítsd hátra erőteljesen a kettlebellt, majd ugyanolyan erőteljesen fordítsd meg a mozdulatot."],"en":["Initiate the exercise by standing upright with a kettlebell in one hand.","Swing the kettlebell back forcefully and then reverse the motion forcefully."]},"reviewed":false,"summaryMethod":"source-extract"},"Bottoms_Up":{"version":1,"steps":{"hu":["Feküdj hanyatt a talajra.","A mozdulathoz húzd a térded a mellkasod felé a csípőd és a térded hajlításával.","Rövid szünet után térj vissza a kiinduló helyzetbe."],"en":["Begin by lying on your back on the ground.","To perform the movement, tuck the knees toward your chest by flexing the hips and knees.","After a brief pause, return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Box_Jump_Multiple_Response":{"version":1,"steps":{"hu":["Állj lazán a dobozzal vagy emelvénnyel szemben, nagyjából karnyújtásnyira tőle.","A karoddal segítve a kezdeti elrugaszkodást ugorj felfelé és előre, és érkezz mindkét lábbal egyszerre a doboz vagy emelvény tetejére.","Azonnal ereszkedj le vagy ugorj vissza az eredeti kiindulási helyre, majd ismételd a sorozatot."],"en":["Assume a relaxed stance facing the box or platform approximately an arm's length away.","Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform.","Immediately drop or jump back down to the original starting place; then repeat the sequence."]},"reviewed":false,"summaryMethod":"source-extract"},"Box_Skip":{"version":1,"steps":{"hu":["Több dobozra lesz szükséged, egymástól kb.","Rugaszkodj el a hátsó lábadról, és próbáld a csípődet a lehető legmagasabbra emelni.","Ezután lépj a következő dobozra, és ismételd."],"en":["You will need several boxes lined up about 8 feet apart.","Drive off the back leg, attempting to gain as much height with the hips as possible.","Then, step to the next box and repeat."]},"reviewed":false,"summaryMethod":"source-extract"},"Box_Squat":{"version":1,"steps":{"hu":["A dobozra guggolás lehetővé teszi, hogy a kívánt mélységig guggolj, és fejleszti a robbanékony erőt a guggoló mozdulatban.","Feszes háttal, vállal és törzzsel told ki a térded és a feneked, ahogy megkezded a leereszkedést.","A súlyt a sarkadon tartva, a lábfejedet és a térdedet kifelé tolva robbanj fel a dobozról úgy, hogy a mozdulatot a fejeddel vezeted."],"en":["The box squat allows you to squat to desired depth and develop explosive strength in the squat movement.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head."]},"reviewed":false,"summaryMethod":"source-extract"},"Box_Squat_with_Bands":{"version":1,"steps":{"hu":["Kezdd egy erőkeretben úgy, hogy mögötted megfelelő magasságú doboz áll.","Feszes háttal, vállal és törzzsel told ki a térded és a feneked, ahogy megkezded a leereszkedést.","A súlyt a sarkadon tartva, a lábfejedet és a térdedet kifelé tolva robbanj fel a dobozról úgy, hogy a mozdulatot a fejeddel vezeted."],"en":["Begin in a power rack with a box at the appropriate height behind you.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head."]},"reviewed":false,"summaryMethod":"source-extract"},"Box_Squat_with_Chains":{"version":1,"steps":{"hu":["Kezdd egy erőkeretben úgy, hogy mögötted megfelelő magasságú doboz áll.","Kezdésként lépj a rúd alá, és helyezd a vállad hátsó részére.","A súlyt a sarkadon tartva, a lábfejedet és a térdedet kifelé tolva robbanj fel a dobozról úgy, hogy a mozdulatot a fejeddel vezeted."],"en":["Begin in a power rack with a box at the appropriate height behind you.","Begin by stepping under the bar and placing it across the back of the shoulders.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head."]},"reviewed":false,"summaryMethod":"source-extract"},"Brachialis-SMR":{"version":1,"steps":{"hu":["Feküdj az oldaladra úgy, hogy a felkarod a hengeren legyen.","Emeld el a csípőd a talajról, a súlyodat a karodon és a lábfejeden tartva."],"en":["Lie on your side, with your upper arm against the foam roller.","Raise your hips off of the floor, supporting your weight on your arm and on your feet."]},"reviewed":false,"summaryMethod":"source-extract"},"Bradford_Rocky_Presses":{"version":1,"steps":{"hu":["Ülj le egy vállból nyomó padra, a rúd legyen vállmagasságban, és fogd meg felső fogással (a tenyér előre néz).","Kilégzés közben nyomd vissza a rudat a kiinduló helyzetbe.","Így váltogatva folytasd, amíg el nem éred az előírt ismétlésszámot."],"en":["Sit on a Military Press Bench with a bar at shoulder level with a pronated grip (palms facing forward).","Lift the bar back up to the starting position as you exhale.","Alternate in this manner until you complete the recommended amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Butt-Ups":{"version":1,"steps":{"hu":["Helyezkedj fekvőtámasz helyzetbe, de a könyököd legyen a talajon, és az alkarodon támaszkodj.","Emeld a feneked a plafon felé, és feszítsd meg erősen a hasad, hogy csökkentsd a bordakosarad és a csípőd közötti távolságot.","Belégzés közben ereszkedj vissza lassan a kiinduló helyzetbe."],"en":["Begin a pushup position but with your elbows on the ground and resting on your forearms.","Raise your glutes toward the ceiling, squeezing your abs tightly to close the distance between your ribcage and hips.","Lower back down slowly to your starting position as you breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Butt_Lift_Bridge":{"version":1,"steps":{"hu":["Feküdj hanyatt a talajra, a kezed a tested mellett, a térded behajlítva.","Főleg a sarkaddal tolva emeld el a csípőd a talajról, miközben a hátad egyenes marad.","Belégzés közben lassan térj vissza a kiinduló helyzetbe."],"en":["Lie flat on the floor on your back with the hands by your side and your knees bent.","Pushing mainly with your heels, lift your hips off the floor while keeping your back straight.","Slowly go back to the starting position as you breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Butterfly":{"version":1,"steps":{"hu":["Ülj a gépre úgy, hogy a hátad teljesen a háttámlához simuljon.","Nyomd össze lassan a fogantyúkat, közben feszítsd meg a melled középen.","Belégzés közben térj vissza lassan a kiinduló helyzetbe, amíg a mellizmaid teljesen meg nem nyúlnak."],"en":["Sit on the machine with your back flat on the pad.","Push the handles together slowly as you squeeze your chest in the middle.","Return back to the starting position slowly as you inhale until your chest muscles are fully stretched."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Chest_Press":{"version":1,"steps":{"hu":["Állítsd be a megfelelő súlyt, ülj le, és fogd meg a fogantyúkat.","A teljes nyújtásnál tarts egy kis szünetet, majd térj vissza a kiinduló helyzetbe úgy, hogy a kábelek végig feszesek maradnak.","A gyakorlatot végezheted úgy is, hogy a hátad nem támaszkodik a háttámlának, ferde vagy negatív szögben, illetve váltott karral."],"en":["Adjust the weight to an appropriate amount and be seated, grasping the handles.","After pausing at full extension, return to th starting position, keeping tension on the cables.","You can also execute this movement with your back off the pad, at an incline or decline, or alternate hands."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Crossover":{"version":1,"steps":{"hu":["A kiinduló helyzet felvételéhez állítsd a csigákat magasra (a fejed fölé), válaszd ki az ellenállást, és fogd meg mindkét kezeddel egy-egy csiga fogantyúját.","A könyöködet enyhén hajlítva, hogy ne terheld a bicepszínt, nyisd a karod oldalra (egyenesen kifelé mindkét oldalon) széles ívben, amíg nyúlást nem érzel a melledben.","Tartsd meg egy másodpercig a kiinduló helyzetben, majd ismételd a mozdulatot az előírt ismétlésszámban."],"en":["To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest.","Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Crunch":{"version":1,"steps":{"hu":["Térdelj le egy felső csiga alá, amelyre kötél van szerelve.","Hajlítsd be enyhén a csípőd, és engedd, hogy a súly túlnyújtsa (homorítsa) a derekad.","Belégzés közben lassan térj vissza a kiinduló helyzetbe."],"en":["Kneel below a high pulley that contains a rope attachment.","Flex your hips slightly and allow the weight to hyperextend the lower back.","Slowly return to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract","board":"img/guide/Cable_Crunch.webp"},"Cable_Deadlifts":{"version":1,"steps":{"hu":["Állítsd a kábeleket a tornyok aljára, és válassz megfelelő súlyt.","Miután megfogtad őket, kezdj el felemelkedni.","Miután teljesen felegyenesedtél, térj vissza a kiinduló helyzetbe, és ismételd."],"en":["Move the cables to the bottom of the towers and select an appropriate weight.","After grasping them, begin your ascent.","After reaching a full standing position, Return to the starting position and repeat."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Hammer_Curls_-_Rope_Attachment":{"version":1,"steps":{"hu":["Szerelj kötelet az alsó csigára, és állj a géppel szembe, kb.","Húzd a könyököd a tested mellé, és tartsd ott mozdulatlanul az egész mozdulat alatt.","Tartsd megfeszítve a bicepszed 1 másodpercig, majd lassan kezdd visszaengedni a súlyt a kiinduló helyzetbe."],"en":["Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.","Put your elbows in by your side and keep them there stationary during the entire movement.","After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Hip_Adduction":{"version":1,"steps":{"hu":["Állj egy alsó csiga elé, arccal előre, úgy, hogy az egyik lábad a csiga mellett, a másik távolabb legyen.","Állj arra a lábadra, amelyiken nincs bokapánt (a távolabbi lábra), és engedd, hogy a kábel a pántos lábadat az alsó csiga felé húzza.","Belégzés közben lassan térj vissza a kiinduló helyzetbe."],"en":["Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away.","Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley.","Slowly return to the starting position as you breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Incline_Pushdown":{"version":1,"steps":{"hu":["Feküdj egy ferde padra háttal egy felső csigás gépnek, amelyre egyenes rúd van szerelve.","A karodat mereven tartva emeld vissza félkörívben, amíg a rúd egyenesen a fejed fölé nem kerül.","A széles hátizmod erejével térj vissza lassan a kiinduló helyzetbe, és ott tartsd megfeszítve az izmot."],"en":["Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.","Keeping the upper arms stationary, lift your arms back in a semi circle until the bar is straight over your head.","Slowly go back to the starting position using your lats and hold the contraction once you reach the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Incline_Triceps_Extension":{"version":1,"steps":{"hu":["Feküdj egy ferde padra háttal egy felső csigás gépnek, amelyre egyenes rúd van szerelve.","A felkarodat mozdulatlanul tartva nyújtsd ki a karod, és feszítsd meg a tricepszed.","Lassan térj vissza a kiinduló helyzetbe."],"en":["Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.","Keeping the upper arms stationary, extend the arms as you flex the triceps.","Slowly go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Internal_Rotation":{"version":1,"steps":{"hu":["Ülj le oldalt egy alsó csiga mellé (a lábad előrenyújtva vagy keresztbe téve), és fogd meg az egykezes fogantyút a kábelhez közelebbi kezeddel.","Húzd az egykezes fogantyút a tested felé a vállad befelé forgatásával, amíg az alkarod a hasad elé nem kerül.","Lassan térj vissza a kiinduló helyzetbe."],"en":["Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable.","Pull the single hand cable attachment toward your body by internally rotating your shoulder until your forearm is across your abs.","Slowly go back to the initial position."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Iron_Cross":{"version":1,"steps":{"hu":["Kezdésként állítsd a csigákat felső helyzetbe, válaszd ki az ellenállást, és fogj meg egy-egy fogantyút mindkét kezeddel.","A könyöködet nyújtva tartva húzd le a karod egyenesen a tested mellé.","Folytasd a mozdulatot az előírt ismétlésszámban."],"en":["Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.","Keeping the elbows extended, pull your arms straight to your sides.","Continue the movement for the prescribed number of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Judo_Flip":{"version":1,"steps":{"hu":["Szerelj kötelet a toronyra, és állítsd a kábelt a legalsó csigahelyzetbe.","Helyezd át a testsúlyod egyik lábadról a másikra, miközben elfordulsz és hasprés-mozdulattal előrehajolsz, lefelé húzva a kábelt.","Ezután állj át, és ismételd meg ugyanezt a mozdulatsort a másik oldalra."],"en":["Connect a rope attachment to a tower, and move the cable to the lowest pulley position.","Shift your weight between your feet as you twist and crunch forward, pulling the cable downward.","Then, reposition and repeat the same series of movements on the opposite side."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Lying_Triceps_Extension":{"version":1,"steps":{"hu":["Feküdj sík padra, és fogd meg az alsó csigára szerelt egyenes rudat szűk felső fogással.","Engedd le a rudat a könyököd hajlításával, miközben a felkarod mozdulatlan, a könyököd pedig bent marad.","Tartsd meg egy másodpercig a megfeszített helyzetben, majd ismételd az előírt ismétlésszámban."],"en":["Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip.","Lower the bar by bending at the elbow while keeping the upper arms stationary and elbows in.","Hold for a second at the contracted position and repeat for the recommended amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_One_Arm_Tricep_Extension":{"version":1,"steps":{"hu":["A felső csiga fogantyúját egy kézzel, tenyérrel felfelé fogd. Könyököd a törzsed mellett legyen.","Nyújtsd a könyököd, told lefelé a fogantyút.","Felkarod maradjon helyben; lassan engedd vissza."],"en":["Take the high-pulley handle in one hand with an underhand grip, elbow beside your torso.","Straighten your elbow to push the handle down.","Keep your upper arm still; return slowly."]},"reviewed":true,"summaryMethod":"curated"},"Cable_Preacher_Curl":{"version":1,"steps":{"hu":["Állíts egy Scott-padot kb.","Fogd meg a rudat, és nyújtsd ki teljesen a karod a Scott-pad párnáján.","Most lassan engedd vissza a súlyt a kiinduló helyzetbe."],"en":["Place a preacher bench about 2 feet in front of a pulley machine.","Grab the bar and fully extend your arms on top of the preacher bench pad.","Now slowly lower the weight to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Rear_Delt_Fly":{"version":1,"steps":{"hu":["A felső csigák fogantyúit keresztben fogd: jobb kézzel a balt, ballal a jobbat.","Enyhén hajlított könyökkel nyisd a karod oldalra és hátra.","Törzsed maradjon stabil; kontrolláltan zárd vissza."],"en":["Cross-grip the high-pulley handles: left handle in your right hand and vice versa.","With a slight elbow bend, open your arms out and back.","Keep your torso steady; return with control."]},"reviewed":true,"summaryMethod":"curated"},"Cable_Reverse_Crunch":{"version":1,"steps":{"hu":["Csatlakoztass bokapántot egy alsó csiga kábeléhez, és teríts elé egy matracot a talajra.","Feküdj le, emeld fel a lábad, és hajlítsd be a térded 90 fokos szögben.","Tarts egy pillanatnyi szünetet, majd lassan, kontrolláltan engedd le a csípőd, és vidd vissza a lábad a kiinduló 90 fokos szögbe."],"en":["Connect an ankle strap attachment to a low pulley cable and position a mat on the floor in front of it.","Lie down, elevate your legs and bend your knees at a 90-degree angle.","Pause for a moment and in a slow and controlled manner drop your hips and bring your legs back to the starting 90-degree angle."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Rope_Overhead_Triceps_Extension":{"version":1,"steps":{"hu":["Az alsó csiga kötelét két kézzel tartsd a fejed fölött. Törzsed legyen stabil.","Könyöködet hajlítva engedd a kezed a fejed mögé, majd nyújtsd vissza.","Felkarod maradjon a fejed mellett; ne homoríts."],"en":["Hold a low-pulley rope overhead with both hands and brace your trunk.","Bend your elbows to lower your hands behind your head, then extend again.","Keep your upper arms beside your head; avoid arching your back."]},"reviewed":true,"summaryMethod":"curated"},"Cable_Rope_Rear-Delt_Rows":{"version":1,"steps":{"hu":["Ülj le az alsó csigás evezőgéphez ugyanúgy, mintha hátra végeznél ülő kábeles evezést.","Tartsd a derekad egyenesen, és csúsztasd hátra a csípőd annyira, hogy a térded enyhén hajlítva legyen.","Térj vissza a kiinduló helyzetbe, ahol a karod nyújtva van, a vállad pedig előrenyúlik."],"en":["Sit in the same position on a low pulley row station as you would if you were doing seated cable rows for the back.","Keep your lower back upright and slide your hips back so that your knees are slightly bent.","Go back to the initial position where the arms are extended and the shoulders are stretched forward."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Russian_Twists":{"version":1,"steps":{"hu":["Csatlakoztass egy normál fogantyút, és állítsd a kábelt középső csigahelyzetbe.","Tartsd megemelve a csípőd és feszesen a hasad.","Ezután állj át, és ismételd meg ugyanezt a mozdulatsort a másik oldalra."],"en":["Connect a standard handle attachment, and position the cable to a middle pulley position.","Keep your hips elevated and abs engaged.","Then, reposition and repeat the same series of movements on the opposite side."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Seated_Crunch":{"version":1,"steps":{"hu":["Ülj le egy sík padra háttal egy felső csigának.","A csípődet mozdulatlanul tartva hajolj előre derékból úgy, hogy a könyököd a csípőd felé haladjon.","Belégzés közben lassan térj vissza a kiinduló helyzetbe."],"en":["Seat on a flat bench with your back facing a high pulley.","With the hips stationary, flex the waist so the elbows travel toward the hips.","As you inhale, go back to the initial position slowly."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Seated_Lateral_Raise":{"version":1,"steps":{"hu":["Állj két egymással szemben lévő alsó csiga közé középre, és tegyél közvetlenül magad mögé egy sík padot (rád merőlegesen; a pad keskeny vége legyen mögötted).","Kérj meg valakit, hogy adja a kezedbe a csigákra szerelt egykezes fogantyúkat.","Belégzés közben lassan engedd vissza a karod a kiinduló helyzetbe."],"en":["Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you).","Have someone give you the single handles attached to the pulleys.","Slowly lower your arms to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Shoulder_Press":{"version":1,"steps":{"hu":["Állítsd a kábeleket a tornyok aljára, és válassz megfelelő súlyt.","A fejedet és a mellkasodat fent tartva nyújtsd ki a könyököd, és nyomd a fogantyúkat egyenesen a fejed fölé.","Fent tarts egy kis szünetet, majd térj vissza a kiinduló helyzetbe, és ismételd."],"en":["Move the cables to the bottom of the towers and select an appropriate weight.","Keeping your head and chest up, extend through the elbow to press the handles directly over head.","After pausing at the top, return to the starting position and repeat."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Shrugs":{"version":1,"steps":{"hu":["Fogd meg az alsó csigára szerelt rudat vállszéles vagy annál kicsit szélesebb felső fogással (a tenyér lefelé néz).","Kilégzés közben emeld a rudat úgy, hogy a vállad a lehető legmagasabbra húzod.","Engedd vissza a rudat a kiinduló helyzetbe."],"en":["Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip.","Lift the bar by elevating the shoulders as high as possible as you exhale.","Lower the bar back to the original position."]},"reviewed":false,"summaryMethod":"source-extract"},"Cable_Wrist_Curl":{"version":1,"steps":{"hu":["Kezdésként tegyél egy sík padot egy alsó csiga elé, amelyre egyenes rúd van szerelve.","Kezdd a csuklód felfelé hajlításával, közben fújd ki a levegőt.","Az alkarod maradjon mozdulatlan, mert a gyakorlathoz csak a csuklód mozgására van szükség."],"en":["Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment.","Start out by curling your wrist upwards and exhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise."]},"reviewed":false,"summaryMethod":"source-extract"},"Calf-Machine_Shoulder_Shrug":{"version":1,"steps":{"hu":["Állj be a vádligépbe úgy, hogy a vállpárnák a vállad fölött legyenek.","Kilégzés közben húzd fel a vállad a füled felé, és tartsd megfeszítve egy teljes másodpercig.","Belégzés közben lassan térj vissza a kiinduló helyzetbe."],"en":["Position yourself on the calf machine so that the shoulder pads are above your shoulders.","Raise your shoulders up towards your ears as you exhale and hold the contraction for a full second.","Slowly return to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Calf_Press":{"version":1,"steps":{"hu":["Állítsd be az ülést úgy, hogy a lábad a kiinduló helyzetben csak enyhén legyen hajlítva.","Nyújtsd ki a lábad a térded nyújtásával, épp csak megemelve a súlyt a súlytömbről.","Rövid szünet után fordítsd meg a mozdulatot, és ismételd."],"en":["Adjust the seat so that your legs are only slightly bent in the start position.","Straighten the legs by extending the knees, just barely lifting the weight from the stack.","After a brief pause, reverse the motion and repeat."]},"reviewed":false,"summaryMethod":"source-extract"},"Calf_Press_On_The_Leg_Press_Machine":{"version":1,"steps":{"hu":["Ülj be a lábtoló gépbe, és tedd a lábad közvetlenül magad elé a lapra, közepes (vállszéles) terpeszben.","Kilégzés közben nyomd a lapot a sarkad megemelésével: nyújtsd ki a bokád, amennyire csak tudod, és feszítsd meg a vádlid.","Belégzés közben térj vissza lassan a kiinduló helyzetbe: engedd le a sarkad a bokád hajlításával, amíg a vádlid meg nem nyúlik."],"en":["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.","Press on the platform by raising your heels as you breathe out by extending your ankles as high as possible and flexing your calf.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched."]},"reviewed":false,"summaryMethod":"source-extract"},"Calf_Raise_On_A_Dumbbell":{"version":1,"steps":{"hu":["Kapaszkodj meg egy stabil tárgyban az egyensúly érdekében, és állj rá egy kézisúlyzó markolatára; lehetőleg kerek tárcsás súlyzót válassz, hogy guruljon, mert így keményebben kell dolgoznod a stabilizálásért, ami növeli a gyakorlat hatékonyságát.","Emelkedj fel vádliból, miközben a lábfejed átgördül a markolat tetején, hogy teljes legyen a nyújtás.","Most lélegezz be, és leereszkedés közben gurítsd a kézisúlyzót kissé előre, hogy jobban megnyúljon a vádlid."],"en":["Hang on to a sturdy object for balance and stand on a dumbbell handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise.","Lift the calf as you roll your foot over the top of the handle so that you get a full extension.","Now inhale as you roll the dum by bending at the hips and guiding it to the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Car_Drivers":{"version":1,"steps":{"hu":["Egyenesen állva tarts két kézzel egy súlytárcsát, a 3 és a 9 óránál megfogva.","Indítsd a mozdulatot úgy, hogy a tárcsát az egyik irányba a lehető legmesszebbre elforgatod.","Fordítsd meg a mozdulatot, és forgasd el teljesen az ellenkező oldalra."],"en":["While standing upright, hold a barbell plate in both hands at the 3 and 9 o'clock positions.","Initiate the movement by rotating the plate as far to one side as possible.","Reverse the motion, turning it all the way to the opposite side."]},"reviewed":false,"summaryMethod":"source-extract"},"Carioca_Quick_Step":{"version":1,"steps":{"hu":["Kezdésként a lábfejed legyen kb.","A jobb lábaddal lépj gyorsan hátra, a másik mögé, és húzd fel a térded.","Amikor a jobb térded felhúzod, lendítsd vissza a karod felfelé, és ügyelj rá, hogy a térded egyenesen fel és le mozogjon."],"en":["Begin with your feet a few inches apart and your left arm up in a relaxed, athletic position.","With your right foot, quick step behind and pull the knee up.","Fire your arms back up when you pull the right knee, being sure that your knee goes straight up and down."]},"reviewed":false,"summaryMethod":"source-extract"},"Cat_Stretch":{"version":1,"steps":{"hu":["Helyezkedj el a talajon négykézláb, a kezeden és a térdeden.","Húzd be a hasad, és domborítsd a gerinced, a derekad, a vállad és a nyakad, a fejed pedig engedd le.","Tartsd meg 15 másodpercig."],"en":["Position yourself on the floor on your hands and knees.","Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop.","Hold for 15 seconds."]},"reviewed":false,"summaryMethod":"source-extract"},"Catch_and_Overhead_Throw":{"version":1,"steps":{"hu":["Állj szemben egy fallal vagy egy társsal.","Két kézzel vidd a labdát a fejed mögé, nyújtózz meg, amennyire csak tudsz, majd dobd erőteljesen előre a labdát.","Ügyelj rá, hogy a dobást végigvidd, és állj készen a visszapattanó labda elkapására."],"en":["Begin standing while facing a wall or a partner.","Using both hands, position the ball behind your head, stretching as much as possible, and forcefully throw the ball forward.","Ensure that you follow your throw through, being prepared to receive your rebound from your throw."]},"reviewed":false,"summaryMethod":"source-extract"},"Chain_Handle_Extension":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz két kábelfogantyúra, egy sík padra és láncokra lesz szükséged.","Nyújtsd ki a karod könyökből úgy, hogy a felkarod mozdulatlan marad, a fogantyúkat pedig felső fogással (pronált csuklóval) tartod.","A teljesen kinyújtott helyzetben tarts egy pillanatnyi szünetet, majd a mozdulatot megfordítva térj vissza a kiinduló helyzetbe."],"en":["You will need two cable handle attachments and a flat bench, as well as chains, for this exercise.","Begin by extending through the elbow, keeping your upper arm still, with your wrists pronated.","Pause at the lockout, and reverse the motion to return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Chain_Press":{"version":1,"steps":{"hu":["Először rögzítsd a láncokat a kábelfogantyúkhoz.","Könyökből hajlítva engedd le a láncokat úgy, hogy a lánc egy része lefeküdjön a padlóra, és ezzel csökkenjen a terhelés.","Folytasd, amíg a könyököd 90 fokos szöget nem zár be, majd fordítsd meg a mozdulatot, és nyújtsd ki a karod teljesen."],"en":["Begin by connecting the chains to the cable handle attachments.","Lower the chains by flexing the elbows, unloading some of the chain onto the floor.","Continue until your elbow forms a 90 degree angle, and then reverse the motion by extending through the elbow to lockout."]},"reviewed":false,"summaryMethod":"source-extract"},"Chair_Leg_Extended_Stretch":{"version":1,"steps":{"hu":["Ülj egyenes háttal egy székre, és fogd meg kétoldalt az ülőlapot.","Emeld fel az egyik lábad, nyújtsd ki a térded, és közben feszítsd vissza a lábfejed.","Lassan vidd a lábad oldalra, amennyire csak tudod, majd vissza középre, és engedd le."],"en":["Sit upright in a chair and grip the seat on the sides.","Raise one leg, extending the knee, flexing the ankle as you do so.","Slowly move that leg outward as far as you can, and then back to the center and down."]},"reviewed":false,"summaryMethod":"source-extract"},"Chair_Lower_Back_Stretch":{"version":1,"steps":{"hu":["Ülj egyenes háttal egy székre.","Hajolj az egyik oldalra úgy, hogy a karod a fejed fölé emeled.","Tartsd ki 10 másodpercig, majd ismételd meg a másik oldalra."],"en":["Sit upright on a chair.","Bend to one side with your arm over your head.","Hold for 10 seconds, and repeat for your other side."]},"reviewed":false,"summaryMethod":"source-extract"},"Chair_Squat":{"version":1,"steps":{"hu":["Először állítsd a rudat a magasságodnak leginkább megfelelő helyzetbe.","Lépj előre úgy, hogy a lábfejed kb.","Kilégzés közben kezdd el felfelé nyomni a rudat: told el magad a sarkaddal a talajtól, nyújtsd ki a térded, és térj vissza a kiinduló helyzetbe."],"en":["To begin, first set the bar to a position that best matches your height.","Move your feet forward about 18 inches in front of the bar.","Begin to raise the bar as you exhale by pushing the floor with the heels of your feet, extending the knees and returning to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Chair_Upper_Body_Stretch":{"version":1,"steps":{"hu":["Ülj egy szék szélére, és fogd meg a háttámláját.","Nyújtsd ki a karod, tartsd egyenesen a hátad, és húzd előre a felsőtested, amíg nyúlást nem érzel."],"en":["Sit on the edge of a chair, gripping the back of it.","Straighten your arms, keeping your back straight, and pull your upper body forward so you feel a stretch."]},"reviewed":false,"summaryMethod":"source-extract"},"Chest_And_Front_Of_Shoulder_Stretch":{"version":1,"steps":{"hu":["Állj zárt lábbal, a kezedben egy tornabottal (bodybar) vagy seprűnyéllel.","Fogd meg a botot vállszélesnél kicsit szélesebb fogással, és tartsd magad előtt lefelé néző tenyérrel.","Óvatosan emeld fel a botot, és vidd a fejed mögé."],"en":["Start off by standing with your legs together, holding a bodybar or a broomstick.","Take a slightly wider than shoulder width grip on the pole and hold it in front of you with your palms facing down.","Carefully lift the pole up and behind your head."]},"reviewed":false,"summaryMethod":"source-extract"},"Chest_Push_from_3_point_stance":{"version":1,"steps":{"hu":["Helyezkedj hárompontos állásba: guggolj le egyenes háttal, az egyik kezed legyen a talajon.","Indításként tedd meg az első lépést, közben húzd a labdát a mellkasodhoz, és helyezd rá mindkét kezed, hogy felkészülj a dobásra.","A második lépésnél robbanékonyan, a lehető legnagyobb erővel lökd előre a labdát."],"en":["Begin in a three point stance, squatted down with your back flat and one hand on the ground.","To begin, take your first step as you pull the ball to your chest, positioning both hands to prepare for the throw.","As you execute the second step, explosively release the ball forward as hard as possible."]},"reviewed":false,"summaryMethod":"source-extract"},"Chest_Push_multiple_response":{"version":1,"steps":{"hu":["Térdelj le egy fallal szemben, vagy dolgozz párban.","Kísérd végig a mozdulatot: ess előre, és a kezeddel támaszd meg magad.","Azonnal térj vissza egyenes törzsű térdelésbe."],"en":["Begin in a kneeling position facing a wall or utilize a partner.","Follow through by falling forward, catching yourself with your hands.","Immediately return to an upright position."]},"reviewed":false,"summaryMethod":"source-extract"},"Chest_Push_single_response":{"version":1,"steps":{"hu":["Térdelj le, és tartsd a medicinlabdát két kézzel szorosan a mellkasodhoz.","Hajtsd végre a passzt: a csípődből robbanékonyan előre és kifelé indulva lökd el a labdát, amilyen messzire csak tudod.","Kísérd végig a mozdulatot: ess előre, és a kezeddel támaszd meg magad."],"en":["Begin in a kneeling position holding the medicine ball with both hands tightly into the chest.","Execute the pass by exploding forward and outward with the hips while pushing the ball as far as possible.","Follow through by falling forward, catching yourself with your hands."]},"reviewed":false,"summaryMethod":"source-extract"},"Chest_Push_with_Run_Release":{"version":1,"steps":{"hu":["Állj atlétikus alapállásba: hajlított térd, hátratolt csípő, egyenes hát.","Az első lépés közben húzd a medicinlabdát a mellkasodhoz.","A második lépésnél robbanékonyan lökd előre a labdát, majd az elengedés után azonnal sprintelj kb."],"en":["Begin in an athletic stance with the knees bent, hips back, and back flat.","While taking your first step draw the medicine ball into your chest.","As you take the second step, explosively push the ball forward, immediately sprinting for 10 yards after the release."]},"reviewed":false,"summaryMethod":"source-extract"},"Chest_Stretch_on_Stability_Ball":{"version":1,"steps":{"hu":["Ereszkedj négykézlábra egy fitlabda mellett.","Tedd a könyököd a labda tetejére úgy, hogy a karod oldalra nyúlik.","Engedd a törzsed a padló felé, a könyököd maradjon a labda tetején."],"en":["Get on your hands and knees next to an exercise ball.","Place your elbows on top of the ball, keeping your arm out to your side.","Lower your torso towards the floor, keeping your elbow on top of the ball."]},"reviewed":false,"summaryMethod":"source-extract"},"Childs_Pose":{"version":1,"steps":{"hu":["Ereszkedj négykézlábra, és a kezeddel lépkedj előre.","Engedd le a feneked, és ülj rá a sarkadra.","Amikor már a sarkadon ülsz, vidd a kezed a lábfejed mellé, és lazíts."],"en":["Get on your hands and knees, walk your hands in front of you.","Lower your buttocks down to sit on your heels.","Once you settle onto your heels, bring your hands next to your feet and relax."]},"reviewed":false,"summaryMethod":"source-extract"},"Chin-Up":{"version":1,"steps":{"hu":["Fogd meg a húzódzkodó rudat magad felé néző tenyérrel, vállszélesnél szűkebb fogással.","Kilégzés közben húzd fel magad, amíg a fejed nagyjából a húzódzkodó rúd magasságába nem kerül.","A felső, megfeszített helyzetben egy másodpercig feszítsd meg a bicepszed, majd lassan engedd vissza magad a kiinduló helyzetbe, amíg a karod teljesen ki nem nyúlik."],"en":["Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.","As you breathe out, pull your torso up until your head is around the level of the pull-up bar.","After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended."]},"reviewed":false,"summaryMethod":"source-extract"},"Chin_To_Chest_Stretch":{"version":1,"steps":{"hu":["Ülj le a padlóra.","Tedd mindkét kezed a tarkódra összekulcsolt ujjakkal úgy, hogy a hüvelykujjaid lefelé, a könyököd pedig egyenesen előre mutasson."],"en":["Get into a seated position on the floor.","Place both hands at the rear of your head, fingers interlocked, thumbs pointing down and elbows pointing straight ahead."]},"reviewed":false,"summaryMethod":"source-extract"},"Circus_Bell":{"version":1,"steps":{"hu":["A circus bell egy túlméretezett, vastag markolatú kézisúlyzó.","Ügyelj rá, hogy a súlyzó egyik feje a vállad mögé kerüljön, különben kibillent az egyensúlyodból.","Óvatosan vezesd vissza a súlyzót a padlóra, és amennyire csak lehet, tartsd kontroll alatt."],"en":["The circus bell is an oversized dumbbell with a thick handle.","Ensure that you get one of the dumbbell heads behind the shoulder to keep from being thrown off balance.","Carefully guide the bell back to the floor, keeping it under control as much as possible."]},"reviewed":false,"summaryMethod":"source-extract"},"Clean":{"version":1,"steps":{"hu":["A rúd a padlón van, közel a sípcsontodhoz.","Ezután jön a második húzás, amely a felvétel fő gyorsító szakasza.","Azonnal állj fel: told el magad a sarkadból, a törzsed maradjon függőleges, a könyököd fent."],"en":["With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs.","Next comes the second pull, the main source of acceleration for the clean.","Immediately recover by driving through the heels, keeping the torso upright and elbows up."]},"reviewed":false,"summaryMethod":"source-extract"},"Clean_Deadlift":{"version":1,"steps":{"hu":["Állj a rúdhoz úgy, hogy az közel legyen a sípcsontodhoz.","Indítsd a mozdulatot úgy, hogy a sarkad elülső részével elnyomod magad a padlótól.","Miután a rúd elhaladt a térded előtt, fejezd be az emelést: told a csípőd a rúdhoz, amíg a csípőd és a térded teljesen ki nem nyúlik."],"en":["Begin standing with a barbell close to your shins.","Begin by driving through the floor through the front of your heels.","After the bar crosses the knees, complete the lift by driving the hips into the bar until your hips and knees are extended."]},"reviewed":false,"summaryMethod":"source-extract"},"Clean_Pull":{"version":1,"steps":{"hu":["A rúd a padlón van, közel a sípcsontodhoz.","Kezdd az első húzást: told el magad a sarkadból, és nyújtsd a térded.","Ezután jön a második húzás, amely a felvétel fő gyorsító szakasza."],"en":["With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs.","Begin the first pull by driving through the heels, extending your knees.","Next comes the second pull, the main source of acceleration for the clean."]},"reviewed":false,"summaryMethod":"source-extract"},"Clean_Shrug":{"version":1,"steps":{"hu":["Fogd a rudat vállszéles, kétkezes felső vagy kampós fogással úgy, hogy a combod közepénél függjön.","Húzd fel a vállad a füled felé."],"en":["Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position.","Shrug your shoulders towards your ears."]},"reviewed":false,"summaryMethod":"source-extract"},"Clean_and_Jerk":{"version":1,"steps":{"hu":["A rúd a padlón van, közel a sípcsontodhoz.","Azonnal állj fel: told el magad a sarkadból, a törzsed maradjon függőleges, a könyököd fent.","Abban a pillanatban, amikor a lábad elhagyja a talajt, a lehető leggyorsabban az átvételi helyzetbe kell tenned."],"en":["With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs.","Immediately recover by driving through the heels, keeping the torso upright and elbows up.","At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible."]},"reviewed":false,"summaryMethod":"source-extract"},"Clean_and_Press":{"version":1,"steps":{"hu":["Állj vállszéles terpeszbe úgy, hogy a térded a két karod között legyen.","A legmagasabb ponton a lábad elemelkedik a padlótól, és el kell kezdened a rúd alá húzni magad.","A lábad elmozdítása nélkül, kilégzés közben nyomd a rudat a fejed fölé."],"en":["Assume a shoulder-width stance, with knees inside the arms.","At maximum elevation, your feet should clear the floor and you should start to pull yourself under the bar.","Without moving your feet, press the bar overhead as you exhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Clean_from_Blocks":{"version":1,"steps":{"hu":["A rúd a kívánt magasságú bakokon vagy állványokon van.","A teljes kinyúlás pillanatában válts át az átvételi helyzetbe: erőteljesen vonj vállat, és hajlítsd a karod úgy, hogy a könyököd felfelé és kifelé mozduljon.","Azonnal állj fel: told el magad a sarkadból, a törzsed maradjon függőleges, a könyököd fent."],"en":["With a barbell on boxes or stands of the desired height, take an overhand or hook grip just outside the legs.","As full extension is achieved, transition into the receiving position by aggressively shrugging and flexing the arms with the elbows up and out.","Immediately recover by driving through the heels, keeping the torso upright and elbows up."]},"reviewed":false,"summaryMethod":"source-extract"},"Clock_Push-Up":{"version":1,"steps":{"hu":["Helyezkedj hason fekvő helyzetbe a padlón, a súlyodat a kezeden és a lábujjaidon tartva.","Az alsó ponton fordítsd meg a mozdulatot: a könyököd nyújtásával told ki magad olyan gyorsan, hogy elemelkedj a talajtól.","Térj vissza a kiinduló helyzetbe, és ismételd a gyakorlatot körbe haladva, amíg vissza nem érsz oda, ahonnan indultál."],"en":["Move into a prone position on the floor, supporting your weight on your hands and toes.","At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible until you are air borne.","Return to the starting position and repeat the exercise, working all the way around until you are back where you started."]},"reviewed":false,"summaryMethod":"source-extract"},"Close-Grip_Barbell_Bench_Press":{"version":1,"steps":{"hu":["Feküdj hanyatt egy sík padra.","Egy másodperc szünet után kilégzés közben nyomd vissza a rudat a kiinduló helyzetbe a tricepszed erejével.","Ha végeztél, tedd vissza a rudat az állványra."],"en":["Lie back on a flat bench.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles.","When you are done, place the bar back in the rack."]},"reviewed":false,"summaryMethod":"source-extract"},"Close-Grip_Dumbbell_Press":{"version":1,"steps":{"hu":["Állíts egy kézisúlyzót a végére egy sík padon.","Fogd meg a súlyzót két kézzel, és tartsd nyújtott karral egyenesen a mellkasod fölött.","A könyököd nyújtásával térj vissza a kiinduló helyzetbe."],"en":["Place a dumbbell standing up on a flat bench.","Grasp the dumbbell with both hands and hold it straight over your chest at arm's length.","Return to the starting position by extending the elbows."]},"reviewed":false,"summaryMethod":"source-extract"},"Close-Grip_EZ-Bar_Curl_with_Band":{"version":1,"steps":{"hu":["Rögzítsd a gumiszalagot a rúd mindkét végéhez.","Folytasd a mozdulatot, amíg a bicepszed teljesen meg nem feszül, és a rúd vállmagasságba nem kerül.","Belégzés közben lassan engedd vissza a rudat a kiinduló helyzetbe."],"en":["Attach a band to each end of the bar.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level.","Slowly begin to bring the bar back to starting position as your breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Close-Grip_EZ-Bar_Press":{"version":1,"steps":{"hu":["Feküdj egy sík padra a megfelelő súllyal felpakolt EZ-rúddal.","Belégzés közben engedd le a rudat a mellkasod alsó részéhez.","A tricepszed erejével, a könyököd nyújtásával nyomd vissza a rudat a kiinduló helyzetbe, közben fújd ki a levegőt."],"en":["Lie on a flat bench with an EZ bar loaded to an appropriate weight.","Now lower the bar down to your lower chest as you breathe in.","Using the triceps to push the bar back up, press it back to the starting position by extending the elbows as you exhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Close-Grip_EZ_Bar_Curl":{"version":1,"steps":{"hu":["Állj egyenes törzzsel, és fogd az EZ-rudat a belső, szűkebb markolatnál.","Folytasd a mozdulatot, amíg a bicepszed teljesen meg nem feszül, és a rúd vállmagasságba nem kerül.","Belégzés közben lassan engedd vissza a rudat a kiinduló helyzetbe."],"en":["Stand up with your torso upright while holding an E-Z Curl Bar at the closer inner handle.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level.","Slowly begin to bring the bar back to starting position as your breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Close-Grip_Front_Lat_Pulldown":{"version":1,"steps":{"hu":["Ülj le a lehúzógéphez, amelynek felső csigájára széles rúd van rögzítve.","Mindkét karod nyújtva van előtted, és a választott fogásszélességgel tartod a rudat; döntsd hátra a törzsed kb.","Tartsd a megfeszített helyzetet egy másodpercig, a lapockáidat összezárva, majd lassan engedd vissza a rudat a kiinduló helyzetbe, amíg a karod teljesen ki nem nyúlik, és a széles hátizmod teljesen meg nem nyúlik."],"en":["Sit down on a pull-down machine with a wide bar attached to the top pulley.","As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back.","6."]},"reviewed":false,"summaryMethod":"source-extract"},"Close-Grip_Push-Up_off_of_a_Dumbbell":{"version":1,"steps":{"hu":["Helyezkedj el a padlón, és tedd a kezed egy végére állított kézisúlyzóra.","A könyököd nyújtásával nyomd vissza magad a kiinduló helyzetbe.","A felső, megfeszített helyzetben tarts egy rövid szünetet, majd ismételd a mozdulatot az előírt ismétlésszámban."],"en":["Lie on the floor and place your hands on an upright dumbbell.","Press yourself back up to the starting position by extending the elbows.","After a pause at the contracted position, repeat the movement for the prescribed amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Close-Grip_Standing_Barbell_Curl":{"version":1,"steps":{"hu":["Fogd meg a rudat két kézzel, felfelé néző tenyérrel úgy, hogy a két kezed között néhány centiméter legyen.","Hajlítsd fel a rudat félkörívben, amíg az alkarod a bicepszedhez nem ér.","Belégzés közben lassan engedd vissza a rudat a kiinduló helyzetbe."],"en":["Hold a barbell with both hands, palms up and a few inches apart.","Curl the bar up in a semicircular motion until the forearms touch your biceps.","Slowly go back down to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Cocoons":{"version":1,"steps":{"hu":["Feküdj hanyatt a talajra.","A mozdulathoz húzd a térded a mellkasod felé, és billentsd a medencéd úgy, hogy a feneked elemelkedjen a padlótól.","Rövid szünet után térj vissza a kiinduló helyzetbe."],"en":["Begin by lying on your back on the ground.","To perform the movement, tuck the knees toward your chest, rotating your pelvis to lift your glutes from the floor.","After a brief pause, return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Conans_Wheel":{"version":1,"steps":{"hu":["A felpakolt eszköz végét fogd Zercher-fogásba.","Kezdésként emeld el a súlyt a talajról."],"en":["With the weight loaded, take a zurcher hold on the end of the implement.","Begin by lifting the weight from the ground."]},"reviewed":false,"summaryMethod":"source-extract"},"Concentration_Curls":{"version":1,"steps":{"hu":["Ülj le egy sík padra úgy, hogy előtted, a két lábad között van egy kézisúlyzó.","A felkarodat mozdulatlanul tartva, kilégzés közben hajlítsd fel a súlyt a bicepszed megfeszítésével.","Belégzés közben lassan engedd vissza a súlyzót a kiinduló helyzetbe."],"en":["Sit down on a flat bench with one dumbbell in front of you between your legs.","While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out.","Slowly begin to bring the dumbbells back to starting position as your breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Cross-Body_Crunch":{"version":1,"steps":{"hu":["Feküdj hanyatt, és hajlítsd be a térded kb.","Most emelkedj fel, és vidd a jobb könyököd és vállad keresztbe a tested előtt, miközben a bal térded a bal vállad felé húzod.","Folytasd így felváltva, amíg az összes előírt ismétlést el nem végzed."],"en":["Lie flat on your back and bend your knees about 60 degrees.","Now curl up and bring your right elbow and shoulder across your body while bring your left knee in toward your left shoulder at the same time.","Continue alternating in this manner until all prescribed repetitions are done."]},"reviewed":false,"summaryMethod":"source-extract"},"Cross_Body_Hammer_Curl":{"version":1,"steps":{"hu":["Állj egyenesen, mindkét kezedben egy-egy kézisúlyzóval.","Belégzés közben lassan engedd le a súlyzót ugyanazon az úton, majd végezd el ugyanezt a mozdulatot a bal karoddal.","Folytasd így felváltva, amíg mindkét karral el nem végzed az előírt ismétlésszámot."],"en":["Stand up straight with a dumbbell in each hand.","Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.","Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm."]},"reviewed":false,"summaryMethod":"source-extract"},"Cross_Over_-_With_Bands":{"version":1,"steps":{"hu":["Rögzíts egy gumiszalagot egy stabil oszlop köré.","A karod nyújtva tartva, kilégzés közben vidd félkörívben előre, a mellkasod elé, és feszítsd meg a mellizmod.","Végezd el az előírt ismétlésszámot."],"en":["Secure an exercise band around a stationary post.","While keeping your arms straight, bring them across your chest in a semicircular motion to the front as you exhale and flex your pecs.","Perform for the recommended amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Crossover_Reverse_Lunge":{"version":1,"steps":{"hu":["Állj vállszéles terpeszbe.","Végezz hátralépő kitörést: lépj hátra az egyik lábaddal, és hajlítsd a csípőd és az elöl lévő térded.","Rövid szünet után térj vissza a kiinduló helyzetbe, ismételd meg a másik oldalra, és folytasd felváltva."],"en":["Stand with your feet shoulder width apart.","Perform a rear lunge by stepping back with one foot and flexing the hips and front knee.","After a brief pause, return to the starting position and repeat on the other side, continuing in an alternating fashion."]},"reviewed":false,"summaryMethod":"source-extract"},"Crucifix":{"version":1,"steps":{"hu":["A crucifix (kereszttartás) során időre, statikusan tartasz súlyokat oldalra kinyújtott karral.","Állva emeld a karod oldalra, az eszközökkel a kezedben."],"en":["In the crucifix, you statically hold weights out to the side for time.","Begin standing, and raise your arms out to the side holding the implements."]},"reviewed":false,"summaryMethod":"source-extract"},"Crunch_-_Hands_Overhead":{"version":1,"steps":{"hu":["Feküdj hanyatt a padlóra úgy, hogy a hátad a talajra simul, a térded pedig be van hajlítva, a combhajlítód és a vádlid között kb.","Gördítsd előre a felsőtested, és emeld a lapockáid éppen csak el a padlótól.","Belégzés közben lassan ereszkedj vissza a kiinduló helyzetbe."],"en":["Lie on the floor with your back flat and knees bent with around a 60-degree angle between the hamstrings and the calves.","Curl your upper body forward and bring your shoulder blades just off the floor.","Slowly lower down to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Crunch_-_Legs_On_Exercise_Ball":{"version":1,"steps":{"hu":["Feküdj hanyatt úgy, hogy a lábfejed egy fitlabdán pihen, a térded pedig 90 fokos szögben be van hajlítva.","Nyomd a derekad a padlóba, hogy jobban izoláld a hasizmaid.","Belégzés közben lassan ereszkedj vissza a kiinduló helyzetbe."],"en":["Lie flat on your back with your feet resting on an exercise ball and your knees bent at a 90 degree angle.","Push the small of your back down in the floor in order to better isolate your abdominal muscles.","Slowly go back down to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Crunches":{"version":1,"steps":{"hu":["Feküdj hanyatt úgy, hogy a talpad a talajon van, vagy a lábad egy padon pihen 90 fokos szögben behajlított térddel.","Nyomd a derekad a padlóba, hogy jobban izoláld a hasizmaid, és közben kezdd el felgördíteni a vállad a padlóról.","Az egy másodperces megfeszítés után belégzés közben kezdj el lassan visszaereszkedni a kiinduló helyzetbe."],"en":["Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle.","While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.","After the one second contraction, begin to come down slowly again to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Cuban_Press":{"version":1,"steps":{"hu":["Állva fogj mindkét kezedbe egy-egy kézisúlyzót felső fogással.","Most nyomd ki a súlyzókat a könyököd nyújtásával, és nyújtsd ki a karod a fejed fölé.","Belégzés közben, a lépéseket fordított sorrendben végezve térj vissza a kiinduló helyzetbe."],"en":["Take a dumbbell in each hand with a pronated grip in a standing position.","Now press the dumbbells by extending at the elbows, straightening your arms overhead.","Return to the starting position as you breathe in by reversing the steps."]},"reviewed":false,"summaryMethod":"source-extract"},"Dancers_Stretch":{"version":1,"steps":{"hu":["Ülj fel a padlón.","Tedd a bal karod a jobb lábadra, a jobb kezed pedig a padlóra.","Fordítsd a felsőtested jobbra, és tartsd ki 10–20 másodpercig."],"en":["Sit up on the floor.","Place your left arm on your right leg and your right hand on the floor.","Rotate your upper body to the right, and hold for 10-20 seconds."]},"reviewed":false,"summaryMethod":"source-extract"},"Dead_Bug":{"version":1,"steps":{"hu":["Feküdj hanyatt, a karod nyújtsd magad fölé, a mennyezet felé.","A gyakorlat indításához nyújtsd ki az egyik lábad: a térded és a csípőd kiegyenesítésével vidd a lábad közvetlenül a talaj fölé.","Maradj feszes, és vidd vissza a dolgozó lábad a kiinduló helyzetbe."],"en":["Begin lying on your back with your hands extended above you toward the ceiling.","Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.","Stay tight and return the working leg to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Deadlift_with_Bands":{"version":1,"steps":{"hu":["Ha rövid gumiszalagokkal húzol fel, egyszerűen vesd át őket a rúdon, mielőtt elkezded, és a beálláshoz lépj beléjük.","Ha a lábad és a fogásod a helyén van, vegyél egy nagy levegőt, majd engedd le a csípőd, és hajlítsd a térded, amíg a sípcsontod a rúdhoz nem ér.","Engedd le a rudat csípőből hajolva, és vezesd a padlóig."],"en":["To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up.","With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar.","Lower the bar by bending at the hips and guiding it to the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Deadlift_with_Chains":{"version":1,"steps":{"hu":["A láncokat rögzítheted a rúd tárcsatartó végeire, vagy egyszerűen átvetheted a közepüket a rúdon, így emelés közben nagyobb mértékben nő a súly.","Nézz előre, tartsd kiemelve a mellkasod és homorítva a hátad, majd a sarkadból tolva indítsd felfelé a súlyt.","Engedd le a rudat csípőből hajolva, és vezesd a padlóig."],"en":["You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift.","Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.","Lower the bar by bending at the hips and guiding it to the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Decline_Barbell_Bench_Press":{"version":1,"steps":{"hu":["Rögzítsd a lábad a negatív pad végén, és lassan feküdj le a padra.","Belégzés közben lassan engedd le a rudat, amíg meg nem érzed a mellkasod alsó részén.","Ha végeztél, tedd vissza a rudat az állványra."],"en":["Secure your legs at the end of the decline bench and slowly lay down on the bench.","As you breathe in, come down slowly until you feel the bar on your lower chest.","When you are done, place the bar back in the rack."]},"reviewed":false,"summaryMethod":"source-extract"},"Decline_Close-Grip_Bench_To_Skull_Crusher":{"version":1,"steps":{"hu":["Rögzítsd a lábad a negatív pad végén, és lassan feküdj le a padra.","A tricepszed erejével, kilégzés közben nyomd vissza a rudat a kiinduló helyzetbe.","A tricepszed megfeszítésével, kilégzés közben emeld vissza a rudat a kiinduló helyzetbe."],"en":["Secure your legs at the end of the decline bench and slowly lay down on the bench.","Using the triceps to push the bar back up, press it back to the starting position as you exhale.","Lift the bar back to the starting position by contracting the triceps and exhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Decline_Crunch":{"version":1,"steps":{"hu":["Rögzítsd a lábad a negatív pad végén, és feküdj le.","Nyomd a derekad a padba, hogy jobban izoláld a hasizmaid, és közben kezdd el felgördíteni a vállad a padról.","Az egy másodperces megfeszítés után belégzés közben kezdj el lassan visszaereszkedni a kiinduló helyzetbe."],"en":["Secure your legs at the end of the decline bench and lie down.","While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it.","After the one second contraction, begin to come down slowly again to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Decline_Dumbbell_Bench_Press":{"version":1,"steps":{"hu":["Rögzítsd a lábad a negatív pad végén, és feküdj le úgy, hogy mindkét kezedben egy-egy kézisúlyzó van a combod tetején.","Vállszélességben tartva fordítsd előre a csuklód, hogy a tenyered tőled elfelé nézzen.","Kilégzés közben nyomd fel a súlyzókat a mellizmod erejével."],"en":["Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you.","As you breathe out, push the dumbbells up using your pectoral muscles."]},"reviewed":false,"summaryMethod":"source-extract"},"Decline_Dumbbell_Flyes":{"version":1,"steps":{"hu":["Rögzítsd a lábad a negatív pad végén, és feküdj le úgy, hogy mindkét kezedben egy-egy kézisúlyzó van a combod tetején.","A könyököd enyhén behajlítva – így kíméled a bicepszínt – engedd le a karod kétoldalt széles ívben, amíg nyúlást nem érzel a mellkasodban.","Tartsd meg egy másodpercig a megfeszített helyzetet, majd ismételd a mozdulatot az előírt ismétlésszámban."],"en":["Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest.","Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Decline_Dumbbell_Triceps_Extension":{"version":1,"steps":{"hu":["Rögzítsd a lábad a negatív pad végén, és feküdj le úgy, hogy mindkét kezedben egy-egy kézisúlyzó van a combod tetején.","Belégzés közben, a felkarodat mozdulatlanul tartva (a könyököd maradjon bent) engedd le lassan a súlyzókat: az alkarod mozogjon félkörívben feléd, amíg a hüvelykujjad a füled mellé nem kerül.","A tricepszed megfeszítésével, kilégzés közben emeld vissza a súlyzókat a kiinduló helyzetbe."],"en":["Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs.","As you breathe in and you keep the upper arms stationary (and elbows in), bring the dumbbells down slowly by moving your forearms in a semicircular motion towards you until your thumbs are next to your ears.","Lift the dumbbells back to the starting position by contracting the triceps and exhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Decline_EZ_Bar_Triceps_Extension":{"version":1,"steps":{"hu":["Rögzítsd a lábad a negatív pad végén, és lassan feküdj le a padra.","Belégzés közben, a felkarodat mozdulatlanul tartva engedd le lassan a rudat: az alkarod mozogjon félkörívben feléd, amíg a rúd finoman meg nem érinti a homlokod.","A tricepszed megfeszítésével, kilégzés közben emeld vissza a rudat a kiinduló helyzetbe."],"en":["Secure your legs at the end of the decline bench and slowly lay down on the bench.","As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead.","Lift the bar back to the starting position by contracting the triceps and exhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Decline_Oblique_Crunch":{"version":1,"steps":{"hu":["Rögzítsd a lábad a negatív pad végén, és lassan feküdj le a padra.","A kiinduló helyzetből lassan emeld a felsőtested, közben fordítsd a törzsed balra.","Miután a jobb oldalra elvégezted a sorozatot az előírt ismétlésszámban, válts a bal oldalra."],"en":["Secure your legs at the end of the decline bench and slowly lay down on the bench.","Raise your upper body slowly from the starting position while turning your torso to the left.","After completing one set on the right for the recommended amount of repetitions, switch to your left side."]},"reviewed":false,"summaryMethod":"source-extract"},"Decline_Push-Up":{"version":1,"steps":{"hu":["Feküdj hasra a padlón, tedd le a kezed egymástól kb.","Most fújd ki a levegőt, és nyomd vissza a felsőtested a kiinduló helyzetbe, közben feszítsd meg a mellizmod.","A felső, megfeszített helyzetben tarts egy rövid szünetet, majd kezdj el újra leereszkedni, és végezz annyi ismétlést, amennyi szükséges."],"en":["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.","Now breathe out and press your upper body back up to the starting position while squeezing your chest.","After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."]},"reviewed":false,"summaryMethod":"source-extract"},"Decline_Reverse_Crunch":{"version":1,"steps":{"hu":["Feküdj hanyatt egy negatív padra, és két kézzel kapaszkodj meg a pad felső végében.","Kilégzés közben húzd a lábad a törzsed felé, miközben a medencéd hátrabillented, és a csípőd elemeled a padról.","Tartsd meg a megfeszítést egy másodpercig, majd belégzés közben vidd vissza a lábad a kiinduló helyzetbe."],"en":["Lie on your back on a decline bench and hold on to the top of the bench with both hands.","While exhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the bench.","Hold the contraction for a second and move your legs back to the starting position while inhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Decline_Smith_Press":{"version":1,"steps":{"hu":["Állíts egy negatív padot a Smith-gép alá.","Rövid szünet után a könyököd nyújtásával nyomd vissza a rudat a kiinduló helyzetbe, közben fújd ki a levegőt.","Amikor a sorozat végére értél, akaszd vissza a rudat az állványba."],"en":["Place a decline bench underneath the Smith machine.","After a brief pause, bring the bar back to the starting position by extending the elbows, exhaling as you do so.","When the set is complete, lock the bar back in the rack."]},"reviewed":false,"summaryMethod":"source-extract"},"Deficit_Deadlift":{"version":1,"steps":{"hu":["Készíts elő egy emelvényt vagy súlytárcsákat, amelyekre ráállhatsz; ezek általában kb.","Ha a lábad és a fogásod a helyén van, vegyél egy nagy levegőt, majd engedd le a csípőd, és hajlítsd a térded, amíg a sípcsontod a rúdhoz nem ér.","Engedd le a rudat csípőből hajolva, és vezesd a padlóig."],"en":["Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height.","With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar.","Lower the bar by bending at the hips and guiding it to the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Depth_Jump_Leap":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz két dobozra vagy padra lesz szükséged: az egyik kb.","Kezdésként lépj le az első dobozról, érkezz páros lábra, és ugyanazzal a mozdulattal rugaszkodj is el mindkét lábbal.","Rugaszkodj el a lehető legintenzívebben felfelé és előre, és a karod lendítésével, a tested teljes kinyújtásával ugorj fel a magasabb dobozra."],"en":["For this drill you will need two boxes or benches, one 12 to 16 inches high and the other 22 to 26 inches high.","Begin by dropping off the initial box, landing and simultaneously taking off with both feet.","Rebound by driving upward and outward as intensely as possible, using the arms and full extension of the body to jump onto the higher box."]},"reviewed":false,"summaryMethod":"source-extract"},"Dip_Machine":{"version":1,"steps":{"hu":["Ülj be stabilan a tolódzkodó gépbe, állítsd be a súlyt, és fogd meg erősen a fogantyúkat.","A tricepszed megfeszítésével, kilégzés közben nyújtsd ki a karod lefelé.","Most belégzés közben lassan engedd vissza a karod a kiinduló helyzetbe."],"en":["Sit securely in a dip machine, select the weight and firmly grasp the handles.","As you contract the triceps, extend your arms downwards as you exhale.","Now slowly let your arms come back up to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Dips_-_Chest_Version":{"version":1,"steps":{"hu":["Támaszkodj a párhuzamos korlátra, és enyhén dőlj előre.","Hajlítsd a könyököd, engedd le a tested kontrolláltan.","Nyomd vissza magad; ne lendülj, és ne erőltesd a vállad mozgástartományát."],"en":["Support yourself on parallel bars with a slight forward lean.","Bend your elbows to lower your body with control.","Press back up; avoid swinging or forcing your shoulder range."]},"reviewed":true,"summaryMethod":"curated"},"Dips_-_Triceps_Version":{"version":1,"steps":{"hu":["A kiinduló helyzethez tartsd meg a tested majdnem teljesen nyújtott karral a korlátok fölött.","Most lélegezz be, és lassan ereszkedj le.","Ezután fújd ki a levegőt, és a tricepszed erejével told vissza a törzsed felfelé, a kiinduló helyzetbe."],"en":["To get into the starting position, hold your body at arm's length with your arms nearly locked above the bars.","Now, inhale and slowly lower yourself downward.","Then, exhale and push your torso back up using your triceps to bring your body back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Donkey_Calf_Raises":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz szamár vádliemelő gépre lesz szükséged.","Kilégzés közben emeld a sarkad: nyújtsd a bokád, amilyen magasra csak tudod, és feszítsd meg a vádlid.","Belégzés közben lassan térj vissza a kiinduló helyzetbe: engedd le a sarkad a bokád hajlításával, amíg a vádlid meg nem nyúlik."],"en":["For this exercise you will need access to a donkey calf raise machine.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched."]},"reviewed":false,"summaryMethod":"source-extract"},"Double_Kettlebell_Alternating_Hang_Clean":{"version":1,"steps":{"hu":["Tegyél két kettlebellt a lábfejed közé.","Vedd fel az egyik kettlebellt a válladra, a másikat pedig tartsd továbbra is a kezedben.","Egy folyamatos mozdulattal engedd le a fent lévő kettlebellt, miközben az alul lévőt felfelé lendíted."],"en":["Place two kettlebells between your feet.","Clean one kettlebell to your shoulder and hold on to the other kettlebell.","With a fluid motion, lower the top kettlebell while driving the bottom kettlebell up."]},"reviewed":false,"summaryMethod":"source-extract"},"Double_Kettlebell_Jerk":{"version":1,"steps":{"hu":["Fogj mindkét kezedbe egy-egy kettlebellt a fülénél.","Azonnal válts irányt: told el magad a sarkadból, lényegében ugorj, hogy lendületet szerezz.","A súlyokat a fejed fölött tartva térj vissza álló helyzetbe, és zárd össze a lábad."],"en":["Hold a kettlebell by the handle in each hand.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum.","Keeping the weights overhead, return to a standing position, bringing your feet together."]},"reviewed":false,"summaryMethod":"source-extract"},"Double_Kettlebell_Push_Press":{"version":1,"steps":{"hu":["Vegyél fel két kettlebellt a válladra.","Guggolj le néhány centimétert, majd gyorsan válts irányt.","Amikor a karod teljesen kinyúlt, engedd vissza a kettlebelleket a válladra, és ismételd."],"en":["Clean two kettlebells to your shoulders.","Squat down a few inches and reverse the motion rapidly.","Once the kettlebells are locked out, lower the kettlebells to your shoulders and repeat."]},"reviewed":false,"summaryMethod":"source-extract"},"Double_Kettlebell_Snatch":{"version":1,"steps":{"hu":["Tegyél két kettlebellt a lábfejed mögé.","Lendítsd a kettlebelleket erőteljesen a lábad közé, majd válts irányt.","Told előre a csípőd, és egyetlen megszakítás nélküli mozdulattal vidd a kettlebelleket a fejed fölé, teljesen nyújtott karba."],"en":["Place two kettlebells behind your feet.","Swing the kettlebells between your legs forcefully and reverse the direction.","Drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion."]},"reviewed":false,"summaryMethod":"source-extract"},"Double_Kettlebell_Windmill":{"version":1,"steps":{"hu":["Tegyél egy kettlebellt az elöl lévő lábad elé, egy másikat pedig az ellentétes karoddal vegyél fel, és nyomj ki a fejed fölé.","Csípőből oldalra hajolva, a feneked kitolva lassan dőlj, amíg el nem éred a padlón lévő kettlebellt.","Miután felvetted a kettlebellt a talajról, tarts egy másodperc szünetet, majd a mozdulatot megfordítva térj vissza a kiinduló helyzetbe."],"en":["Place a kettlebell in front of your front foot and clean and press a kettlebell overhead with your opposite arm.","Bending at the hip to one side, sticking your butt out, slowly lean until you can retrieve the kettlebell from the floor.","Pause for a second after retrieving the kettlebell from the ground and reverse the motion back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Double_Leg_Butt_Kick":{"version":1,"steps":{"hu":["Állj enyhén hajlított térddel.","Felfelé haladva húzd fel a sarkad a térded hajlításával, és próbáld megérinteni vele a feneked.","Fejezd be a mozdulatot úgy, hogy csak enyhén hajlított térddel érkezel, és a lábaddal tompítod az ütközést."],"en":["Begin standing with your knees slightly bent.","As you go up, tuck your heels by flexing the knees, attempting to touch the buttocks.","Finish the motion by landing with the knees only partially bent, using your legs to absorb the impact."]},"reviewed":false,"summaryMethod":"source-extract"},"Downward_Facing_Balance":{"version":1,"steps":{"hu":["Feküdj hasra egy fitlabda tetején.","A labdán a hasadon támaszkodva lépkedj előre a kezeddel a padlón, és emeld fel a lábad, közben nyújtsd ki a könyököd és a térded."],"en":["Lie facedown on top of an exercise ball.","While resting on your stomach on the ball, walk your hands forward along the floor and lift your legs, extending your elbows and knees."]},"reviewed":false,"summaryMethod":"source-extract"},"Drag_Curl":{"version":1,"steps":{"hu":["Fogd meg a rudat alsó fogással (előre néző tenyérrel), a könyököd húzd közel a törzsedhez és hátra.","Kilégzés közben hajlítsd fel a rudat úgy, hogy a könyököd hátul marad, és a rudat a törzsedhez érintve „húzod” felfelé.","Lassan térj vissza a kiinduló helyzetbe úgy, hogy a rúd végig a törzsedhez ér."],"en":["Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back.","As you exhale, curl the bar up while keeping the elbows to the back as you \"Drag\" the bar up by keeping it in contact with your torso.","Slowly go back to the starting position as you keep the bar in contact with the torso at all times."]},"reviewed":false,"summaryMethod":"source-extract"},"Drop_Push":{"version":1,"steps":{"hu":["Helyezz el két alacsony dobozt vagy más emelvényt egymástól kb.","Helyezkedj el közöttük fekvőtámaszhelyzetben úgy, hogy a kezeddel a dobozokon támaszkodsz.","Jó testtartással ugorj le az emelvényekről: nyomd ki magad, és vidd a kezed vállszélességbe; az érkezést a karoddal tompítsd, azzal nyeld el az ütközés erejét."],"en":["Position low boxes or other platforms 2-3 feet apart.","Move to a pushup position between them, supporting yourself by placing your hands on the boxes.","With good posture, drop from the platforms by pressing up and moving your hands to shoulder width, cushioning your landing by absorbing the impact through the arm."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Alternate_Bicep_Curl":{"version":1,"steps":{"hu":["Állj egyenes törzzsel, mindkét kezedben egy-egy kézisúlyzóval, nyújtott karral.","Lassan kezdd el visszaengedni a súlyzót a kiinduló helyzetbe, közben lélegezz be.","Folytasd így, váltott karral, az előírt ismétlésszámban."],"en":["Stand (torso upright) with a dumbbell in each hand held at arms length.","Slowly begin to bring the dumbbell back to the starting position as your breathe in.","Continue alternating in this manner for the recommended amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Bench_Press":{"version":1,"steps":{"hu":["Feküdj le egy sík padra, mindkét kezedben egy-egy kézisúlyzóval, amelyek a combodon pihennek.","Ha megvan a vállszélesség, fordítsd előre a csuklód, hogy a tenyered tőled elfelé nézzen.","Ezután fújd ki a levegőt, és közben a mellizmod erejével nyomd fel a súlyzókat."],"en":["Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you.","Then, as you breathe out, use your chest to push the dumbbells up."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Bench_Press_with_Neutral_Grip":{"version":1,"steps":{"hu":["Fogj mindkét kezedbe egy-egy kézisúlyzót, és feküdj hanyatt egy sík padra.","Kezdd a mozdulatot a könyököd hajlításával, a felkarodat oldalra engedve.","Tarts egy pillanatnyi szünetet, majd nyújtsd ki a könyököd, és térj vissza a kiinduló helyzetbe."],"en":["Take a dumbbell in each hand and lay back onto a flat bench.","Begin the movement by flexing the elbow, lowering the upper arms to the side.","Pause, then extend the elbow and return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Bicep_Curl":{"version":1,"steps":{"hu":["Állj egyenesen, mindkét kezedben egy-egy kézisúlyzóval, nyújtott karral.","Most a felkarodat mozdulatlanul tartva fújd ki a levegőt, és hajlítsd fel a súlyzókat a bicepszed megfeszítésével.","Ezután lélegezz be, és lassan kezdd el visszaengedni a súlyzókat a kiinduló helyzetbe."],"en":["Stand up straight with a dumbbell in each hand at arm's length.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Clean":{"version":1,"steps":{"hu":["Állj fel, mindkét kezedben egy-egy kézisúlyzóval, vállszéles terpeszben.","A mozdulat indításához ugorj fel robbanékonyan: nyújtsd ki a csípőd, a térded és a bokád, hogy felfelé gyorsítsd a súlyokat.","Miután guggolásban fogadtad a súlyt, nyújtsd ki a csípőd és a térded, és fejezd be a mozdulatot állásban, a súlyzókkal a válladon."],"en":["Begin standing with a dumbbell in each hand with your feet shoulder width apart.","To initiate the movement, violently jump upward by extending the hips, knees, and ankles to acclerate the weights upward.","Upon receiving the weight in the squat position, extend the hips and knees to finish in a standing position with the weights on your shoulders."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Floor_Press":{"version":1,"steps":{"hu":["Feküdj a földre, kezedben kézisúlyzókkal.","Engedd le a súlyokat, amíg a felkarod a talajhoz nem ér.","Lent tarts egy pillanatnyi szünetet, majd a könyököd nyújtásával vidd össze a súlyokat fent."],"en":["Lay on the floor holding dumbbells in your hands.","Lower the weights until your upper arm comes in contact with the floor.","Pause at the bottom, and then bring the weight together at the top by extending through the elbows."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Flyes":{"version":1,"steps":{"hu":["Feküdj le egy sík padra, mindkét kezedben egy-egy kézisúlyzóval, amelyek a combodon pihennek.","Enyhén hajlított könyökkel – hogy ne terheld a bicepszínt – engedd le a karod két oldalra széles ívben, amíg nyúlást nem érzel a mellizmodban.","Tartsd meg egy másodpercig a megfeszített helyzetet, majd ismételd a mozdulatot az előírt ismétlésszámban."],"en":["Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest.","Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Incline_Row":{"version":1,"steps":{"hu":["Kalapácsfogást alkalmazva dőlj rá mellkassal egy ferde padra.","Húzd hátra a lapockáidat, és a könyököd hajlításával evezd a súlyzókat a törzsed mellé.","A mozdulat tetején tarts egy pillanatnyi szünetet, majd térj vissza a kiinduló helyzetbe."],"en":["Using a neutral grip, lean into an incline bench.","Retract the shoulder blades and flex the elbows to row the dumbbells to your side.","Pause at the top of the motion, and then return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Incline_Shoulder_Raise":{"version":1,"steps":{"hu":["Ülj le egy ferde padra, mindkét kezedben egy-egy kézisúlyzóval, amelyeket a combodon tartasz.","A karodat végig nyújtva és zárva tartva emeld meg a súlyzókat úgy, hogy a válladat elemeled a padról, közben fújd ki a levegőt.","Engedd vissza a súlyzókat a kiinduló helyzetbe, közben lélegezz be."],"en":["Sit on an Incline Bench while holding a dumbbell on each hand on top of your thighs.","While keeping the arms straight and locked, lift the dumbbells by raising the shoulders from the bench as you breathe out.","Bring back the dumbbells to the starting position as you breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Lunges":{"version":1,"steps":{"hu":["Állj egyenes törzzsel, két kézisúlyzóval a kezedben, a tested mellett.","Lépj előre a jobb lábaddal kb.","Főleg a sarkadról elrugaszkodva told fel magad, és térj vissza a kiinduló helyzetbe, közben fújd ki a levegőt."],"en":["Stand with your torso upright holding two dumbbells in your hands by your sides.","Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance.","Using mainly the heel of your foot, push up and go back to the starting position as you exhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Lying_One-Arm_Rear_Lateral_Raise":{"version":1,"steps":{"hu":["Egyik kezedben egy kézisúlyzóval feküdj mellkassal lefelé egy enyhén megdöntött (a talajtól mérve kb.","Most emeld a súlyzót tartó karod oldalra, amíg a könyököd vállmagasságba nem kerül, és a karod nagyjából párhuzamos nem lesz a talajjal; közben fújd ki a levegőt.","Lassan engedd vissza a súlyzót a kiinduló helyzetbe, közben lélegezz be."],"en":["While holding a dumbbell in one hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench.","Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale.","Slowly lower the dumbbell to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Lying_Pronation":{"version":1,"steps":{"hu":["Feküdj hasra egy sík padon, az egyik kezedben egy kézisúlyzóval; a másik karodat hajlítsd be a padon úgy, hogy rá tudd fektetni a fejed.","Most emeld meg a felkarod úgy, hogy az alkarod merőleges legyen a talajra, a felkarod pedig merőleges a törzsedre.","Lélegezz be, és közben lassan térj vissza a kiinduló helyzetbe."],"en":["Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.","Now raise the upper arm so that the forearm is perpendicular to the floor and the upper arm is perpendicular to your torso.","As you breathe in, slowly go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Lying_Rear_Lateral_Raise":{"version":1,"steps":{"hu":["Mindkét kezedben egy-egy kézisúlyzóval feküdj mellkassal lefelé egy enyhén megdöntött (a talajtól mérve kb.","Most emeld a karod oldalra, amíg a könyököd vállmagasságba nem kerül, és a karod nagyjából párhuzamos nem lesz a talajjal; közben fújd ki a levegőt.","Lassan engedd vissza a súlyzókat a kiinduló helyzetbe, közben lélegezz be."],"en":["While holding a dumbbell in each hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench.","Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale.","Slowly lower the dumbbells to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Lying_Supination":{"version":1,"steps":{"hu":["Feküdj az oldaladra egy sík padon, az egyik kezedben egy kézisúlyzóval; a másik karodat hajlítsd be a padon úgy, hogy rá tudd fektetni a fejed.","Most emeld meg a felkarod úgy, hogy az alkarod párhuzamos legyen a talajjal és merőleges a törzsedre (Tipp: az alkarod így közvetlenül előtted lesz).","Lélegezz be, és közben lassan térj vissza a kiinduló helyzetbe."],"en":["Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.","Now raise the upper arm so that the forearm is parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you).","As you breathe in, slowly go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_One-Arm_Shoulder_Press":{"version":1,"steps":{"hu":["Fogj egy kézisúlyzót, és ülj le egy vállból nyomó padra vagy háttámlás, állítható padra, a súlyzót függőlegesen a combodra állítva, vagy állj egyenesen.","Fordítsd a csuklód úgy, hogy a tenyered előre nézzen.","Egy másodperc szünet után lassan engedd vissza a súlyzót a kiinduló helyzetbe, közben lélegezz be."],"en":["Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.","Rotate the wrist so that the palm of your hand is facing forward.","After a second pause, slowly come down back to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_One-Arm_Triceps_Extension":{"version":1,"steps":{"hu":["Fogj egy kézisúlyzót, és ülj le egy vállból nyomó padra vagy háttámlás, állítható padra, a súlyzót függőlegesen a combodra állítva, vagy állj egyenesen.","Fordítsd a csuklód úgy, hogy a tenyered előre, a kisujjad pedig a mennyezet felé nézzen.","Térj vissza a kiinduló helyzetbe a tricepszed megfeszítésével, közben fújd ki a levegőt."],"en":["Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.","Rotate the wrist so that the palm of your hand is facing forward and the pinkie is facing the ceiling.","Return to the starting position by flexing your triceps as you breathe out."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_One-Arm_Upright_Row":{"version":1,"steps":{"hu":["Fogj egy kézisúlyzót, és állj egyenesen, a karodat nyújtsd le magad előtt enyhén hajlított könyökkel, a hátad legyen egyenes.","A deltaizmod oldalsó részével emeld fel a súlyzót, közben fújd ki a levegőt.","Lassan engedd vissza a súlyzót a kiinduló helyzetbe."],"en":["Grab a dumbbell and stand up straight with your arm extended in front of you with a slight bend at the elbows and your back straight.","Use your side shoulders to lift the dumbbell as you exhale.","Lower the dumbbell back down slowly to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Prone_Incline_Curl":{"version":1,"steps":{"hu":["Fogj mindkét kezedbe egy-egy kézisúlyzót, és feküdj hasra egy ferde padon úgy, hogy a vállad a döntött támla tetejének közelében legyen.","Most tartsd a könyököd szorosan a tested mellett, a tenyered pedig nézzen előre.","Engedd le a súlyzókat, amíg a karod teljesen ki nem nyúlik."],"en":["Grab a dumbbell on each hand and lie face down on an incline bench with your shoulders near top of the incline.","Now keep your elbows in by your side and face the palms forward.","Lower the dumbbells until your arms are fully extended."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Raise":{"version":1,"steps":{"hu":["Fogj mindkét kezedbe egy-egy kézisúlyzót, és állj egyenesen, a karodat nyújtsd le a tested mellett enyhén hajlított könyökkel, a hátad legyen egyenes.","A deltaizmod oldalsó részével emeld fel a súlyzókat, közben fújd ki a levegőt.","Lassan engedd vissza a súlyzókat a kiinduló helyzetbe."],"en":["Grab a dumbbell in each arm and stand up straight with your arms extended by your sides with a slight bend at the elbows and your back straight.","Use your side shoulders to lift the dumbbells as you exhale.","Lower the dumbbells back down slowly to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Rear_Lunge":{"version":1,"steps":{"hu":["Állj egyenes törzzsel, két kézisúlyzóval a kezedben, a tested mellett.","Told fel magad, és térj vissza a kiinduló helyzetbe, közben fújd ki a levegőt.","Most ismételd meg a másik lábbal."],"en":["Stand with your torso upright holding two dumbbells in your hands by your sides.","Push up and go back to the starting position as you exhale.","Now repeat with the opposite leg."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Scaption":{"version":1,"steps":{"hu":["Ez a korrekciós gyakorlat a lapockát stabilizáló izmokat erősíti.","Kezdd a mozdulatot úgy, hogy a karodat magad elé emeled, a középvonaltól kb.","Folytasd, amíg a karod párhuzamos nem lesz a talajjal, majd térj vissza a kiinduló helyzetbe."],"en":["This corrective exercise strengthens the muscles that stabilize your shoulder blade.","Begin the movement raising your arms out in front of you, about 30 degrees off center.","Continue until your arms are parallel to the ground, and then return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Seated_Box_Jump":{"version":1,"steps":{"hu":["Helyezz egy dobozt egy pad mellé, tőle kb.","Érkezz a dobozra mindkét lábbal, és a csípőd és a térded behajlításával nyeld el az érkezés erejét.","Lépj le, és térj vissza a kiinduló helyzetbe."],"en":["Position a box a couple feet to the side of a bench.","Land on the box with both feet, absorbing the impact by allowing the hips and knees to bend.","Step down and return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Seated_One-Leg_Calf_Raise":{"version":1,"steps":{"hu":["Tegyél egy emelvényt a földre, kb.","Most tedd a bal lábfejed elülső részét (a talppárnát) az emelvényre.","Lassan térj vissza a kiinduló helyzetbe, és engedd a sarkad olyan mélyre, amennyire csak tudod, hogy megnyújtsd a vádlid."],"en":["Place a block on the floor about 12 inches from a flat bench.","Now place the ball of your left foot on the block.","Slowly return to the starting position, stretching as far down as possible."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Shoulder_Press":{"version":1,"steps":{"hu":["Mindkét kezedben egy-egy kézisúlyzóval ülj le egy vállból nyomó padra vagy háttámlás, állítható padra.","Fordítsd a csuklód úgy, hogy a tenyered előre nézzen.","Ezután a felső, megfeszített helyzetben tartott rövid szünet után lassan engedd vissza a súlyokat a kiinduló helyzetbe, közben lélegezz be."],"en":["While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support.","Make sure to rotate your wrists so that the palms of your hands are facing forward.","Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Shrug":{"version":1,"steps":{"hu":["Állj egyenesen, mindkét kezedben egy-egy kézisúlyzóval (a tenyered a törzsed felé néz), a karod nyújtva a tested mellett.","Emeld meg a súlyzókat úgy, hogy a válladat a lehető legmagasabbra húzod, közben fújd ki a levegőt.","Engedd vissza a súlyzókat a kiinduló helyzetbe."],"en":["Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.","Lift the dumbbells by elevating the shoulders as high as possible while you exhale.","Lower the dumbbells back to the original position."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Side_Bend":{"version":1,"steps":{"hu":["Állj egyenesen, a bal kezedben egy kézisúlyzóval (a tenyered a törzsed felé néz), a jobb kezedet pedig tedd a derekadra.","Egyenes háttal és felemelt fejjel hajolj el – csak derékból – jobbra, amennyire csak tudsz.","Most ismételd meg a mozdulatot, de ezúttal balra hajolva."],"en":["Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist.","While keeping your back straight and your head up, bend only at the waist to the right as far as possible.","Now repeat the movement but bending to the left instead."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Squat":{"version":1,"steps":{"hu":["Állj egyenesen, mindkét kezedben egy-egy kézisúlyzóval (a tenyered a lábad oldala felé néz).","Kezdd el lassan leengedni a törzsed a térded hajlításával, közben tartsd meg az egyenes testtartást és a felemelt fejet.","Kezdd el felemelni a törzsed, közben fújd ki a levegőt: főleg a sarkaddal told el magad a talajtól, nyújtsd ki újra a lábad, és térj vissza a kiinduló helyzetbe."],"en":["Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).","Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up.","Begin to raise your torso as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Squat_To_A_Bench":{"version":1,"steps":{"hu":["Állj egyenesen úgy, hogy egy sík pad van mögötted, mindkét kezedben egy-egy kézisúlyzóval (a tenyered a lábad oldala felé néz).","Kezdd el lassan leengedni a törzsed a térded hajlításával, közben tartsd meg az egyenes testtartást és a felemelt fejet.","Kezdj el felemelkedni, közben fújd ki a levegőt: főleg a sarkaddal told el magad a talajtól, nyújtsd ki újra a lábad, és térj vissza a kiinduló helyzetbe."],"en":["Stand up straight with a flat bench behind you while holding a dumbbell on each hand (palms facing the side of your legs).","Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Step_Ups":{"version":1,"steps":{"hu":["Állj egyenesen, mindkét kezedben egy-egy kézisúlyzóval (a tenyered a lábad oldala felé néz).","Tedd a jobb lábad az emelvényre.","Lépj le a bal lábbal úgy, hogy a jobb lábad csípőjét és térdét hajlítod, közben lélegezz be."],"en":["Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).","Place the right foot on the elevated platform.","Step down with the left leg by flexing the hip and knee of the right leg as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Dumbbell_Tricep_Extension_-Pronated_Grip":{"version":1,"steps":{"hu":["Feküdj le egy sík padra, és tarts két kézisúlyzót közvetlenül a vállad fölött.","Most lélegezz be, és lassan engedd le a súlyzókat, amíg a füled közelébe nem érnek.","Ezután fújd ki a levegőt, és a tricepszed erejével vidd vissza a súlyt a kiinduló helyzetbe."],"en":["Lie down on a flat bench holding two dumbbells directly above your shoulders.","Now, inhale and slowly lower the dumbbells until they are near your ears.","Then, exhale and use your triceps to return the weight to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Dynamic_Back_Stretch":{"version":1,"steps":{"hu":["Állj vállszéles terpeszbe.","Nyújtott karral lendítsd a karod egyenesen előre-fel 5–10 alkalommal, minden lendítéssel növelve a mozgástartományt, amíg a karod a fejed fölé nem kerül."],"en":["Stand with your feet shoulder width apart.","Keeping your arms straight, swing them straight up in front of you 5-10 times, increasing the range of motion each time until your arms are above your head."]},"reviewed":false,"summaryMethod":"source-extract"},"Dynamic_Chest_Stretch":{"version":1,"steps":{"hu":["Állj úgy, hogy a tenyereid összeérnek, a karod pedig egyenesen előtted nyújtva van.","Nyújtott karral gyorsan vidd hátra a karod, amennyire csak tudod, majd vissza előre, mintha eltúlzott tapsoló mozdulatot végeznél."],"en":["Stand with your hands together, arms extended directly in front of you.","Keeping your arms straight, quickly move your arms back as far as possible and back in again, similar to an exaggerated clapping motion."]},"reviewed":false,"summaryMethod":"source-extract"},"EZ-Bar_Curl":{"version":1,"steps":{"hu":["Állj egyenesen, és fogd meg az EZ-rudat a külső, széles fogásnál.","Emeld tovább a súlyt, amíg a bicepszed teljesen meg nem feszül, és a rúd vállmagasságba nem kerül.","Ezután lélegezz be, és lassan engedd vissza a rudat a kiinduló helyzetbe."],"en":["Stand up straight while holding an EZ curl bar at the wide outer handle.","Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level.","Then inhale and slowly lower the bar back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"EZ-Bar_Skullcrusher":{"version":1,"steps":{"hu":["Szűk fogással emeld fel az EZ-rudat, és tartsd behúzott könyökkel, miközben a padon fekszel.","A felkarodat mozdulatlanul tartva engedd le a rudat a könyököd hajlításával.","Emeld vissza a rudat a kiinduló helyzetbe a könyököd nyújtásával, közben fújd ki a levegőt."],"en":["Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench.","Keeping the upper arms stationary, lower the bar by allowing the elbows to flex.","Lift the bar back to the starting position by extending the elbow and exhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Elbow_Circles":{"version":1,"steps":{"hu":["Ülj vagy állj kis terpeszben.","Tedd a kezed a válladra úgy, hogy a könyököd vállmagasságban legyen, és kifelé mutasson.","Lassan írj le egy kört a könyököddel."],"en":["Sit or stand with your feet slightly apart.","Place your hands on your shoulders with your elbows at shoulder level and pointing out.","Slowly make a circle with your elbows."]},"reviewed":false,"summaryMethod":"source-extract"},"Elbow_to_Knee":{"version":1,"steps":{"hu":["Feküdj a földre, és tedd keresztbe a jobb lábad a behajlított bal térdeden.","A mozdulatot a gerinced hajlításával és a törzsed elfordításával végezd úgy, hogy a bal könyöködet a jobb térdedhez viszed.","Térj vissza a kiinduló helyzetbe, és ismételd a mozdulatot a kívánt ismétlésszámban, mielőtt oldalt cserélsz."],"en":["Lie on the floor, crossing your right leg across your bent left knee.","Perform the motion by flexing the spine and rotating your torso to bring the left elbow to the right knee.","Return to the starting position and repeat the movement for the desired number of repetitions before switching sides."]},"reviewed":false,"summaryMethod":"source-extract"},"Elbows_Back":{"version":1,"steps":{"hu":["Állj egyenesen.","Tedd mindkét kezed a derekadra úgy, hogy az ujjaid lefelé, a könyököd pedig kifelé mutasson.","Ezután óvatosan húzd hátra a könyököd, és próbáld összeérinteni őket."],"en":["Stand up straight.","Place both hands on your lower back, fingers pointing downward and elbows out.","Then gently pull your elbows back aiming to touch them together."]},"reviewed":false,"summaryMethod":"source-extract"},"Elevated_Back_Lunge":{"version":1,"steps":{"hu":["Helyezz egy megfelelő súllyal megpakolt rudat az állványra vállmagasságban.","Kezdd azzal, hogy az egyik lábaddal hátralépsz.","Tarts egy pillanatnyi szünetet, majd a csípőd és a térded nyújtásával emelkedj fel, és térj vissza teljesen a kiinduló helyzetbe, mielőtt lábat váltasz."],"en":["Position a bar onto a rack at shoulder height loaded to an appropriate weight.","Begin by stepping backwards with one leg.","Pause, and extend through the hips and knees to rise up, returning all the way to the starting position before alternating."]},"reviewed":false,"summaryMethod":"source-extract"},"Elevated_Cable_Rows":{"version":1,"steps":{"hu":["Szerezz valamilyen emelvényt (lehet aerobiklépcső vagy vádliemelő dobogó), amely kb.","Hajolj előre, megtartva a hátad természetes ívét, és fogd meg a V-fogantyút.","A törzsedet mozdulatlanul tartva húzd a fogantyút a törzsed felé, a karodat közel tartva hozzá, amíg el nem éred a hasad."],"en":["Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height.","Lean over as you keep the natural alignment of your back and grab the V-bar handles.","Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals."]},"reviewed":false,"summaryMethod":"source-extract"},"Elliptical_Trainer":{"version":1,"steps":{"hu":["Kezdésként lépj fel az elliptikus trénerre, és válaszd ki a kívánt opciót a menüből.","A fogantyúkkal mérheted a pulzusod, ami segít a megfelelő intenzitáson maradni."],"en":["To begin, step onto the elliptical and select the desired option from the menu.","The handles can be used to monitor your heart rate to help you stay at an appropriate intensity."]},"reviewed":false,"summaryMethod":"source-extract"},"Exercise_Ball_Crunch":{"version":1,"steps":{"hu":["Feküdj egy fitlabdára úgy, hogy a derekad íve a labda gömbölyű felületéhez simuljon.","Mozdulatlan csípővel hajlíts derékból a hasizmod megfeszítésével, és gördítsd felfelé a vállad és a törzsed, amíg erős feszülést nem érzel a hasizmodban.","Lélegezz be, és közben térj vissza a kiinduló helyzetbe."],"en":["Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball.","With the hips stationary, flex the waist by contracting the abdominals and curl the shoulders and trunk upward until you feel a nice contraction on your abdominals.","As you inhale, go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Exercise_Ball_Pull-In":{"version":1,"steps":{"hu":["Tegyél a közeledbe egy fitlabdát, és helyezkedj el előtte a földön fekvőtámaszhelyzetben, a kezed vállszélességben a talajon.","A hátadat teljesen egyenesen, a felsőtestedet mozdulatlanul tartva húzd a térded a mellkasod felé, közben fújd ki a levegőt, és engedd, hogy a labda előregördüljön a bokád alá.","Most lassan nyújtsd ki a lábad, visszagörgetve a labdát a kiinduló helyzetbe, közben lélegezz be."],"en":["Place an exercise ball nearby and lay on the floor in front of it with your hands on the floor shoulder width apart in a push-up position.","While keeping your back completely straight and the upper body stationary, pull your knees in towards your chest as you exhale, allowing the ball to roll forward under your ankles.","Now slowly straighten your legs, rolling the ball back to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Extended_Range_One-Arm_Kettlebell_Floor_Press":{"version":1,"steps":{"hu":["Feküdj a földre, és készíts oda egy kettlebellt az egykezes nyomáshoz.","Nyomd ki a kettlebellt a könyököd nyújtásával és a karod közelítésével, a tested fölé nyomva."],"en":["Lie on the floor and position a kettlebell for one arm to press.","Press the kettlebell by extending the elbow and adducting the arm, pressing it above your body."]},"reviewed":false,"summaryMethod":"source-extract"},"External_Rotation":{"version":1,"steps":{"hu":["Feküdj az oldaladra egy sík padon, az egyik kezedben egy kézisúlyzóval; a másik karodat hajlítsd be a padon úgy, hogy rá tudd fektetni a fejed.","Most hajlítsd be a könyököd, a felkarodat mozdulatlanul tartva.","Lélegezz be, és közben lassan térj vissza a kiinduló helyzetbe."],"en":["Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.","Now bend the elbow while keeping the upper arm stationary.","As you breathe in, slowly go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"External_Rotation_with_Band":{"version":1,"steps":{"hu":["Hurkold a gumiszalagot egy oszlop köré.","Ha a felkarod a helyén van, a könyököd legyen 90 fokban behajlítva, a kezed pedig nyúljon keresztbe a törzsed előtt.","Menj el addig, ameddig csak tudsz, tarts egy pillanatnyi szünetet, majd térj vissza a kiinduló helyzetbe."],"en":["Choke the band around a post.","With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso.","Continue as far as you are able, pause, and then return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"External_Rotation_with_Cable":{"version":1,"steps":{"hu":["Állítsd a kábelt a könyököddel egy magasságba.","Ha a felkarod a helyén van, a könyököd legyen 90 fokban behajlítva, a kezed pedig nyúljon keresztbe a törzsed előtt.","Végezd a mozdulatot úgy, hogy a karodat fonák ütéshez hasonló mozdulattal kifelé forgatod, a könyöködet a helyén tartva."],"en":["Adjust the cable to the same height as your elbow.","With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso.","Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place."]},"reviewed":false,"summaryMethod":"source-extract"},"Face_Pull":{"version":1,"steps":{"hu":["Állj szemben egy felső csigával, amelyre kötél vagy két fogantyú van rögzítve, és húzd a súlyt egyenesen az arcod felé, közben távolítsd el egymástól a két kezed."],"en":["Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so."]},"reviewed":false,"summaryMethod":"source-extract"},"Farmers_Walk":{"version":1,"steps":{"hu":["A farmersétához többféle eszköz használható.","Miután megfogtad a fogantyúkat, emeld fel őket a sarkadból tolva, egyenes háttal és felemelt fejjel.","Sétálj rövid, gyors léptekkel, és ne felejts el lélegezni."],"en":["There are various implements that can be used for the farmers walk.","After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.","Walk taking short, quick steps, and don't forget to breathe."]},"reviewed":false,"summaryMethod":"source-extract"},"Fast_Skipping":{"version":1,"steps":{"hu":["Indulj laza testhelyzetből, az egyik lábaddal kissé előrébb.","Szökdelj lépés–szökkenés ritmusban: jobb-jobb, lépés, majd bal-bal, lépés, és így tovább, felváltva.","A gyors szökdelésnél maradj közel a talajhoz, csökkentsd a levegőben töltött időt, és haladj a lehető leggyorsabban."],"en":["Start in a relaxed position with one leg slightly forward.","Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth.","Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible."]},"reviewed":false,"summaryMethod":"source-extract"},"Finger_Curls":{"version":1,"steps":{"hu":["Fogj meg egy rudat mindkét kezeddel, felfelé néző tenyérrel; a kezeid kb.","Engedd le a rudat, amennyire csak lehet, az ujjaid kinyújtásával.","Most hajlítsd fel a rudat, amilyen magasra csak tudod, a kezed összezárásával, közben fújd ki a levegőt."],"en":["Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.","Lower the bar as far as possible by extending the fingers.","Now curl bar up as high as possible by closing your hands while exhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Flat_Bench_Cable_Flyes":{"version":1,"steps":{"hu":["Állíts egy sík padot két alsó csiga közé úgy, hogy amikor ráfekszel, a mellkasod egy vonalban legyen a csigákkal.","Nyújtsd ki a karod oldalra, enyhén hajlított könyökkel.","Lassan térj vissza a kiinduló helyzetbe."],"en":["Position a flat bench between two low pulleys so that when you are laying on it, your chest will be lined up with the cable pulleys.","Extend your arms by your side with a slight bend on your elbows.","Slowly come back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Flat_Bench_Leg_Pull-In":{"version":1,"steps":{"hu":["Feküdj egy tornaszőnyegre vagy egy sík padra úgy, hogy a lábad lelógjon a pad végéről.","Hajlítsd be a térded, és húzd a combod a törzsed felé, közben fújd ki a levegőt.","Lélegezz be, és közben lassan térj vissza a kiinduló helyzetbe."],"en":["Lie on an exercise mat or a flat bench with your legs off the end.","Bend your knees and pull your upper thighs into your midsection as you breathe out.","As you breathe in, slowly return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Flat_Bench_Lying_Leg_Raise":{"version":1,"steps":{"hu":["Feküdj hanyatt egy padra úgy, hogy a nyújtott lábad lelógjon a pad végéről.","A lábadat nyújtva, a lehető legegyenesebben tartva – a térded enyhén hajlítva, de rögzítve – emeld fel a lábad, amíg 90 fokos szöget nem zár be a talajjal.","Most lélegezz be, és közben lassan engedd vissza a lábad a kiinduló helyzetbe."],"en":["Lie with your back flat on a bench and your legs extended in front of you off the end.","As you keep your legs extended, straight as possible with your knees slightly bent but locked raise your legs until they make a 90-degree angle with the floor.","Now, as you inhale, slowly lower your legs back down to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Flexor_Incline_Dumbbell_Curls":{"version":1,"steps":{"hu":["Fogd a kézisúlyzót a tőled távolabbi vége felé, hogy a hozzád közelebbi oldalon legyen több súly.","Hagyd a karod lelógni a tested mellett, behúzott könyökkel, és fordítsd a tenyered előre úgy, hogy a hüvelykujjad a testedtől elfelé mutasson.","Lélegezz be, és közben lassan térj vissza a kiinduló helyzetbe."],"en":["Hold the dumbbell towards the side farther from you so that you have more weight on the side closest to you.","Let your arms hang down on your sides, with the elbows in, and turn the palms of your hands forward with the thumbs pointing away from the body.","As you inhale, slowly go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Floor_Glute-Ham_Raise":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz kérhetsz segítséget egy társtól, vagy beakaszthatod a lábfejed valami stabil tárgy alá.","Ereszkedj előre a térded nyújtásával, és ügyelj rá, hogy előredőlés közben NE hajlíts csípőből.","Amikor eléred a talajt, tedd magad elé a kezed."],"en":["You can use a partner for this exercise or brace your feet under something stable.","Lower yourself by extending at the knee, taking care to NOT flex the hips as you go forward.","Place your hands in front of you as you reach the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Floor_Press":{"version":1,"steps":{"hu":["Állítsd be a J-kampókat olyan magasságba, ahonnan kényelmesen ki tudod emelni és vissza tudod tenni a rudat.","Engedd le a rudat a mellkasod alsó része vagy a hasad felső része felé, közben szorítsd a rudat, és próbáld széthúzni.","Nyomd vissza a rudat, amilyen gyorsan csak tudod, úgy, hogy a rúd, a csuklód és a könyököd közben egy vonalban maradjon."],"en":["Adjust the j-hooks so they are at the appropriate height to rack the bar.","Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so.","Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so."]},"reviewed":false,"summaryMethod":"source-extract"},"Floor_Press_with_Chains":{"version":1,"steps":{"hu":["Állítsd be a J-kampókat olyan magasságba, ahonnan kényelmesen ki tudod emelni és vissza tudod tenni a rudat.","Engedd le a rudat a mellkasod alsó része vagy a hasad felső része felé, közben szorítsd a rudat, és próbáld széthúzni.","Nyomd vissza a rudat, amilyen gyorsan csak tudod, úgy, hogy a rúd, a csuklód és a könyököd közben egy vonalban maradjon."],"en":["Adjust the j-hooks so they are at the appropriate height to rack the bar.","Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so.","Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so."]},"reviewed":false,"summaryMethod":"source-extract"},"Flutter_Kicks":{"version":1,"steps":{"hu":["Feküdj hasra egy sík padon úgy, hogy a csípőd a pad szélén legyen, a lábad nyújtva, a lábujjaid magasan a talaj fölött, a karod pedig a padon, a pad elülső szélébe kapaszkodva.","Kezdd a mozdulatot úgy, hogy a bal lábad magasabbra emeled, mint a jobbat.","Folytasd így váltogatva (mintha gyorsúszó lábtempót végeznél a vízben), amíg mindkét lábbal el nem végezted az előírt ismétlésszámot."],"en":["On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge.","Start the movement by lifting the left leg higher than the right leg.","Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg."]},"reviewed":false,"summaryMethod":"source-extract"},"Foot-SMR":{"version":1,"steps":{"hu":["Ez a gyakorlat a talp izmainak fasciáját (izompólyáját) nyújtja.","Nyomd rá erősen a talpad, és görgesd végig a talpboltozatodon."],"en":["This exercise stretches the fascia of the muscles in the feet.","Press down firmly, rolling across the arch of your foot."]},"reviewed":false,"summaryMethod":"source-extract"},"Forward_Drag_with_Press":{"version":1,"steps":{"hu":["Rögzíts a szánhoz egy kétfogantyús láncot vagy kötelet.","Kezdd a mozdulatot egy lépéssel előre."],"en":["Attach a dual handled chain or rope attachment to the sled.","Begin the movement by moving forward for one step."]},"reviewed":false,"summaryMethod":"source-extract"},"Frankenstein_Squat":{"version":1,"steps":{"hu":["Ez a gyakorlat megtanítja a rúd és a tested helyes helyzetét a felvételhez és az első guggoláshoz.","Guggolj le a térded és a csípőd hajlításával, a lábaid közé ülve.","Térj vissza álló helyzetbe úgy, hogy a sarkad elülső részéből tolod el magad, és kinyújtod a térded és a csípőd."],"en":["This drill teaches you the proper positioning of both the bar and your body during the clean and front squat.","Squat by flexing the knees and hips, sitting in between your legs.","Return to the upright position by driving through the front of the heel and extending the knees and hips."]},"reviewed":false,"summaryMethod":"source-extract"},"Freehand_Jump_Squat":{"version":1,"steps":{"hu":["Fond keresztbe a karod a mellkasod előtt.","Egyenes háttal és kiemelt mellkassal guggolj le, közben lélegezz be, amíg a combod párhuzamos nem lesz a talajjal, vagy annál is mélyebbre.","Amikor újra talajt érsz, azonnal guggolj le, és ugorj újra."],"en":["Cross your arms over your chest.","Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.","When you touch the floor again, immediately squat down and jump again."]},"reviewed":false,"summaryMethod":"source-extract"},"Frog_Hops":{"version":1,"steps":{"hu":["Állj fel, tedd a kezed a fejed mögé, és guggolj le egyenes törzzsel, felemelt fejjel.","Ugorj előre egy-két métert, de ne ugorj fölöslegesen magasra."],"en":["Stand with your hands behind your head, and squat down keeping your torso upright and your head up.","Jump forward several feet, avoiding jumping unnecessarily high."]},"reviewed":false,"summaryMethod":"source-extract"},"Frog_Sit-Ups":{"version":1,"steps":{"hu":["Feküdj hanyatt a földön (vagy tornaszőnyegen), nyújtott lábbal.","Most fond keresztbe a karod magad előtt úgy, hogy a kezed az ellentétes válladat érintse.","Lélegezz be, és közben lassan ereszkedj vissza a kiinduló helyzetbe."],"en":["Lie with your back flat on the floor (or exercise mat) and your legs extended in front of you.","Now, cross your arms in front of you by touching the opposite shoulders.","As you inhale, slowly lower back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Front_Barbell_Squat":{"version":1,"steps":{"hu":["Tartsd a rudat az elülső válladon, könyököd emeld fel. Feszítsd meg a törzsed.","Hajlítsd a csípőd és térded, guggolj le.","Tartsd a törzsed stabilan, és teljes talppal nyomd fel magad."],"en":["Support the bar on your front shoulders, elbows raised. Brace your trunk.","Bend at your hips and knees to squat down.","Keep your trunk steady and drive up through your whole foot."]},"reviewed":true,"summaryMethod":"curated"},"Front_Barbell_Squat_To_A_Bench":{"version":1,"steps":{"hu":["A gyakorlatot biztonsági okokból a legjobb guggolóállványban végezni.","Lépj el az állványtól, és állj közepes, vállszéles terpeszbe, a lábujjaid nézzenek enyhén kifelé.","Kezdd el felemelni a rudat, közben fújd ki a levegőt: főleg a sarkaddal told el magad a talajtól, nyújtsd ki újra a lábad, és térj vissza a kiinduló helyzetbe."],"en":["This exercise is best performed inside a squat rack for safety purposes.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out.","Begin to raise the bar as you exhale by pushing the floor mainly with the heel of your foot as you straighten the legs again and go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Front_Box_Jump":{"version":1,"steps":{"hu":["Tegyél magad elé kb.","Rugaszkodj el ebből a helyzetből: nyújtsd ki a csípőd, a térded és a bokád, és ugorj a lehető legmagasabbra.","Érkezz a dobozra hajlított térddel, a lábaddal elnyelve az érkezés erejét."],"en":["Begin with a box of an appropriate height 1-2 feet in front of you.","Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible.","Land on the box with the knees bent, absorbing the impact through the legs."]},"reviewed":false,"summaryMethod":"source-extract"},"Front_Cable_Raise":{"version":1,"steps":{"hu":["Állítsd be a súlyt egy alsó csigás gépen, és fogd meg a bal kezeddel az alsó csigára rögzített egykezes fogantyút.","A törzsedet mozdulatlanul tartva (lendítés nélkül) emeld előre a bal karod enyhén hajlított könyökkel, úgy, hogy a tenyered végig lefelé nézzen.","Ha ezzel a karral elvégezted az összes előírt ismétlést, cserélj kart, és végezd el a gyakorlatot a jobb karoddal is."],"en":["Select the weight on a low pulley machine and grasp the single hand cable attachment that is attached to the low pulley with your left hand.","While maintaining the torso stationary (no swinging), lift the left arm to the front with a slight bend on the elbow and the palms of the hand always faces down.","Once all of the recommended amount of repetitions have been performed for this arm, switch arms and perform the exercise with the right one."]},"reviewed":false,"summaryMethod":"source-extract"},"Front_Cone_Hops_or_hurdle_hops":{"version":1,"steps":{"hu":["Állíts fel egy sor bóját vagy más kisebb akadályt, egymástól kb.","Kezdd azzal, hogy páros lábbal átugrod az első bóját, ugrás közben mindkét karodat lendítve.","Folytasd, amíg az összes bóját át nem ugrottad."],"en":["Set up a row of cones or other small barriers, placing them a few feet apart.","Begin by jumping with both feet over the first cone, swinging both arms as you jump.","Continue until you have jumped over all of the cones."]},"reviewed":false,"summaryMethod":"source-extract"},"Front_Dumbbell_Raise":{"version":1,"steps":{"hu":["Fogj két kézisúlyzót, és állj egyenes törzzsel úgy, hogy a súlyzók nyújtott karral a combod előtt legyenek, a tenyered pedig a combod felé nézzen.","Most lassan engedd vissza a súlyzót a kiinduló helyzetbe, és ezzel egy időben emeld a jobb oldali súlyzót.","Folytasd így, váltott karral, amíg mindkét karral el nem végezted az összes előírt ismétlést."],"en":["Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs.","Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.","Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm."]},"reviewed":false,"summaryMethod":"source-extract"},"Front_Incline_Dumbbell_Raise":{"version":1,"steps":{"hu":["Ülj le egy ferde padra, amelynek a dőlésszöge 30 és 60 fok között van, mindkét kezedben egy-egy kézisúlyzóval.","Lassan emeld a súlyzókat egyenesen felfelé, amíg kicsivel a vállad fölé nem kerülnek, a könyöködet végig zárva tartva.","Engedd vissza a karod a kiinduló helyzetbe, közben lélegezz be."],"en":["Sit down on an incline bench with the incline set anywhere between 30 to 60 degrees while holding a dumbbell on each hand.","Slowly raise the dumbbells straight up until they are slightly above your shoulders, while keeping your elbows locked.","Lower the arms back to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Front_Leg_Raises":{"version":1,"steps":{"hu":["Állj egy szék vagy más támasz mellé, és kapaszkodj meg benne az egyik kezeddel.","Lendítsd előre a lábad, nyújtva tartva."],"en":["Stand next to a chair or other support, holding on with one hand.","Swing your leg forward, keeping the leg straight."]},"reviewed":false,"summaryMethod":"source-extract"},"Front_Plate_Raise":{"version":1,"steps":{"hu":["Állj egyenesen, és fogj meg egy súlytárcsát két kézzel, 3 és 9 óránál.","Fújd ki a levegőt, és közben lassan emeld a tárcsát kicsivel vállmagasság fölé.","Lélegezz be, és közben lassan engedd vissza a tárcsát a kiinduló helyzetbe."],"en":["While standing straight, hold a barbell plate in both hands at the 3 and 9 o'clock positions.","Slowly raise the plate as you exhale until it is a little above shoulder level.","As you inhale, slowly lower the plate back down to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Front_Raise_And_Pullover":{"version":1,"steps":{"hu":["Feküdj egy sík padra, és fogd meg a rudat felső fogással (tenyér lefelé), a kezeid kb.","Most lélegezz be, és nyújtott karral, félkörívben emeld fel a súlyt.","Most fújd ki a levegőt, és a mozdulatot megfordítva vidd vissza a rudat a kiinduló helyzetbe."],"en":["Lie on a flat bench while holding a barbell using a palms down grip that is about 15 inches apart.","Now raise the weight using a semicircular motion and keeping your arms straight as you inhale.","Now return the barbell to the starting position by reversing the motion as you exhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Front_Squat_Clean_Grip":{"version":1,"steps":{"hu":["Először állítsd be a rudat az állványon kicsivel vállmagasság alá.","Hajlítsd be a térdedet, és ülj le a két lábad közé.","Fújd ki a levegőt, és kezdd el felfelé emelni a rudat úgy, hogy főleg a sarkaddal vagy a talpad közepével tolod el magad a talajtól, miközben újra kinyújtod a lábadat, és visszatérsz a kiinduló helyzetbe."],"en":["To begin, first set the bar in a rack slightly below shoulder level.","Bend at the knees, sitting down between your legs.","Begin to raise the bar as you exhale by pushing the floor mainly with the heel or middle of your foot as you straighten the legs again and return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Front_Squats_With_Two_Kettlebells":{"version":1,"steps":{"hu":["Vedd fel a két kettlebellt a válladhoz.","Végig egyenesen előre nézve guggolj le olyan mélyre, amennyire csak tudsz, és lent tarts szünetet.","Emelkedj fel úgy, hogy a sarkaddal tolod el magad, majd ismételd."],"en":["Clean two kettlebells to your shoulders.","Looking straight ahead at all times, squat as low as you can and pause at the bottom.","Rise back up by driving through your heels and repeat."]},"reviewed":false,"summaryMethod":"source-extract"},"Front_Two-Dumbbell_Raise":{"version":1,"steps":{"hu":["Fogj meg két kézisúlyzót, állj egyenes törzzsel, a súlyzókat tartsd nyújtott karral a combod előtt, a tenyered a combod felé nézzen.","A törzsedet mozdulatlanul tartva (lendítés nélkül) emeld előre a súlyzókat enyhén hajlított könyökkel, a tenyered végig lefelé nézzen.","Lélegezz be, és közben lassan engedd vissza a súlyzókat a kiinduló helyzetbe."],"en":["Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs.","While maintaining the torso stationary (no swinging), lift the dumbbells to the front with a slight bend on the elbow and the palms of the hands always facing down.","As you inhale, lower the dumbbells back down slowly to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Full_Range-Of-Motion_Lat_Pulldown":{"version":1,"steps":{"hu":["Állva vagy egy magas padon ülve fogd meg a felső csigákra akasztott két kengyelfogantyút.","Tartsd kiemelve a mellkasodat és enyhén homorítva a derekadat, majd húzd le a fogantyúkat, mintha hagyományos lehúzást végeznél."],"en":["Either standing or seated on a high bench, grasp two stirrup cables that are attached to the high pulleys.","Keeping your chest up and maintaining a slight arch in your lower back, pull the handles down as if you were doing a regular pulldown."]},"reviewed":false,"summaryMethod":"source-extract"},"Gironda_Sternum_Chins":{"version":1,"steps":{"hu":["Fogd meg a húzódzkodó rudat vállszéles alsó fogással.","Kezdd el magad a rúd felé húzni úgy, hogy a gerinced végig homorít, a fejedet pedig a lehető legtávolabb döntöd hátra a rúdtól.","Lélegezz be, és közben lassan ereszkedj vissza a kiinduló helyzetbe."],"en":["Grasp the pull-up bar with a shoulder width underhand grip.","Start pulling yourself towards the bar with your spine arched throughout the movement and your head leaning back as far away from the bar as possible.","Slowly start going back to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Glute_Ham_Raise":{"version":1,"steps":{"hu":["Először állítsd be a gépet a testméretedhez.","A mozdulat alsó pontjáról indulj.","Térj vissza a kiinduló helyzetbe úgy, hogy az ereszkedést végig kontroll alatt tartod."],"en":["Begin by adjusting the equipment to fit your body.","Start from the bottom of the movement.","Return to the starting position, keeping your descent under control."]},"reviewed":false,"summaryMethod":"source-extract"},"Glute_Kickback":{"version":1,"steps":{"hu":["Térdelj le a talajra vagy egy tornaszőnyegre, hajolj előre csípőből, és nyújtsd ki magad előtt a karodat (a törzsedre merőlegesen), így térdelő fekvőtámasz helyzetbe kerülsz, de a kezeid vállszélességben legyenek.","Lélegezz be, és közben térj vissza a kiinduló helyzetbe, majd ismételd meg a bal lábaddal.","Váltogasd a lábaidat, amíg az összes előírt ismétlést el nem végezted."],"en":["Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width.","Go back to the initial position as you inhale and now repeat with the left leg.","Continue to alternate legs until all of the recommended repetitions have been performed."]},"reviewed":false,"summaryMethod":"source-extract"},"Goblet_Squat":{"version":1,"steps":{"hu":["Állj fel, és tarts egy könnyű kettlebellt a fogantyú két száránál (a „szarvainál”) fogva, közel a mellkasodhoz.","Guggolj le a két lábad közé, amíg a combhajlítód a vádlidhoz nem ér.","Az alsó helyzetben tarts szünetet, és a könyököddel told kifelé a térdedet."],"en":["Stand holding a light kettlebell by the horns close to your chest.","Squat down between your legs until your hamstrings are on your calves.","At the bottom position, pause and use your elbows to push your knees out."]},"reviewed":false,"summaryMethod":"source-extract"},"Good_Morning":{"version":1,"steps":{"hu":["Kezdd úgy, hogy a rúd vállmagasságban van az állványon.","Kezdd a mozdulatot csípőből: told hátra a csípődet, és dőlj előre, amíg a törzsed majdnem párhuzamos nem lesz a talajjal.","Fordítsd meg a mozdulatot: a farizmod és a combhajlítód erejével nyújtsd ki a csípődet."],"en":["Begin with a bar on a rack at shoulder height.","Begin by bending at the hips, moving them back as you bend over to near parallel.","Reverse the motion by extending through the hips with your glutes and hamstrings."]},"reviewed":false,"summaryMethod":"source-extract"},"Good_Morning_off_Pins":{"version":1,"steps":{"hu":["Kezdd úgy, hogy a rúd nagyjából a hasad magasságában van az állványon.","Kezdd a mozdulatot úgy, hogy a farizmod és a combhajlítód erejével kinyújtod a csípődet, amíg fel nem állsz a súllyal."],"en":["Begin with a bar on a rack at about the same height as your stomach.","Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight."]},"reviewed":false,"summaryMethod":"source-extract"},"Gorilla_Chin_Crunch":{"version":1,"steps":{"hu":["Függeszkedj a húzódzkodó rúdon alsó fogással (a tenyered feléd néz), vállszélességnél kicsit szélesebben.","Fújd ki a levegőt, és húzd fel magad, közben a térdedet is húzd fel hasprés-mozdulattal, amíg mellmagasságba nem kerül.","Lassan kezdj el belélegezni, miközben visszatérsz a kiinduló helyzetbe."],"en":["Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width.","As you exhale, pull yourself up while crunching your knees up at the same time until your knees are at chest level.","Slowly start to inhale as you return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Groin_and_Back_Stretch":{"version":1,"steps":{"hu":["Ülj a talajra hajlított térddel, a lábfejeidet zárd össze.","Kulcsold össze az ujjaidat a fejed mögött.","Gördülj előre-lefelé, és vidd a könyöködet a combod belső oldalához."],"en":["Sit on the floor with your knees bent and feet together.","Interlock your fingers behind your head.","Curl downwards, bringing your elbows to the inside of your thighs."]},"reviewed":false,"summaryMethod":"source-extract"},"Groiners":{"version":1,"steps":{"hu":["Helyezkedj el fekvőtámasz helyzetben a talajon.","Mindkét lábbal ugorj előre, és érkezz úgy, hogy a lábfejeid a kezeid mellé kerülnek.","Térj vissza a kiinduló helyzetbe, és azonnal ismételd meg a mozdulatot; végezz így 10–20 ismétlést."],"en":["Begin in a pushup position on the floor.","Using both legs, jump forward landing with your feet next to your hands.","Return to the starting position and immediately repeat the movement, continuing for 10-20 repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Hack_Squat":{"version":1,"steps":{"hu":["Támaszd a hátadat a gép háttámlájának, és akaszd a válladat a vállpárnák alá.","Most nyújtsd ki a lábadat anélkül, hogy a térdedet kiakasztanád.","Fújd ki a levegőt, és kezdd el felfelé tolni a szánt úgy, hogy főleg a sarkaddal tolod el a talplemezt, miközben újra kinyújtod a lábadat, és visszatérsz a kiinduló helyzetbe."],"en":["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.","Now straighten your legs without locking the knees.","Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Hammer_Curls":{"version":1,"steps":{"hu":["Állj stabilan, a súlyzókat tenyérrel a tested felé tartsd.","Könyökhajlítással emeld a súlyokat a vállad felé.","Felkarod maradjon a törzsed mellett; lassan engedd le."],"en":["Stand steady holding dumbbells with palms facing your body.","Bend your elbows to curl the weights toward your shoulders.","Keep your upper arms beside your torso; lower slowly."]},"reviewed":true,"summaryMethod":"curated"},"Hammer_Grip_Incline_DB_Bench_Press":{"version":1,"steps":{"hu":["Feküdj hanyatt egy ferde padra, mindkét kezedben egy-egy kézisúlyzóval, amelyek a combodon nyugszanak.","Most lélegezz be, és lassan engedd le a súlyzókat a tested mellé.","Ha végeztél, tedd vissza a súlyzókat a combodra, majd a talajra."],"en":["Lie back on an incline bench with a dumbbell on each hand on top of your thighs.","Now bring down the weights slowly to your side as you breathe in.","When you are done, place the dumbbells back in your thighs and then on the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Hamstring-SMR":{"version":1,"steps":{"hu":["Ülő helyzetben nyújtsd ki a lábadat a henger fölött úgy, hogy a henger a combod hátsó része alá kerüljön.","A kezedre támaszkodva emeld el a csípődet a talajról, és helyezd át a testsúlyodat a hengeren az egyik lábadra.","Gördülj végig a hengeren a csípő alatti résztől a térdhajlat fölötti részig, a feszes pontokon állj meg 10–30 másodpercre."],"en":["In a seated position, extend your legs over a foam roll so that it is position on the back of the upper legs.","Using your hands, lift your hips off of the floor and shift your weight on the foam roll to one leg.","Roll over the foam from below the hip to above the back of the knee, pausing at points of tension for 10-30 seconds."]},"reviewed":false,"summaryMethod":"source-extract"},"Hamstring_Stretch":{"version":1,"steps":{"hu":["Feküdj hanyatt, az egyik lábadat nyújtsd fel magad fölé úgy, hogy a csípőd 90 fokos szögben legyen.","Vess át egy övet, gumiszalagot vagy kötelet a talpad elülső részén (a lábujjpárnákon).","Húzd meg az övet, hogy feszülést érezz a vádlidban és a combhajlítódban."],"en":["Lie on your back with one leg extended above you, with the hip at ninety degrees.","Loop a belt, band, or rope over the ball of your foot.","Pull on the belt to create tension in the calves and hamstrings."]},"reviewed":false,"summaryMethod":"source-extract"},"Handstand_Push-Ups":{"version":1,"steps":{"hu":["Állj háttal a falnak, hajolj előre csípőből, és tedd mindkét kezedet a talajra vállszélességben.","Lélegezz be, és közben lassan ereszkedj le a talaj felé, amíg a fejed majdnem a talajhoz nem ér.","Fújd ki a levegőt, és közben lassan nyomd vissza magad, amíg a könyököd majdnem teljesen ki nem nyúlik."],"en":["With your back to the wall bend at the waist and place both hands on the floor at shoulder width.","Slowly lower yourself to the ground as you inhale until your head almost touches the floor.","Push yourself back up slowly as you exhale until your elbows are nearly locked."]},"reviewed":false,"summaryMethod":"source-extract"},"Hang_Clean":{"version":1,"steps":{"hu":["Kezdd vállszéles fogással, mindkét kézzel felső fogással vagy kampófogással (hook grip), a rúd a combközép magasságában lógjon.","Kezdd azzal, hogy robbanékonyan kinyújtod a csípődet, a térdedet és a bokádat, és ezzel felfelé hajtod a súlyt.","Azonnal állj fel úgy, hogy a sarkaddal tolod el magad, a törzsedet függőlegesen, a könyöködet pedig fent tartod."],"en":["Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position.","Begin by aggressively extending through the hips, knees and ankles, driving the weight upward.","Immediately recover by driving through the heels, keeping the torso upright and elbows up."]},"reviewed":false,"summaryMethod":"source-extract"},"Hang_Clean_-_Below_the_Knees":{"version":1,"steps":{"hu":["Kezdd vállszéles fogással, mindkét kézzel felső fogással vagy kampófogással (hook grip), a rúd közvetlenül a térded alatt lógjon.","A nyújtás csúcspontján robbanékonyan húzd magad lefelé, és közben fordítsd a könyöködet a rúd alá.","Azonnal állj fel úgy, hogy a sarkaddal tolod el magad, a törzsedet függőlegesen, a könyöködet pedig fent tartod."],"en":["Begin with a shoulder width, double overhand or hook grip, with the bar hanging just below the knees.","At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so.","Immediately recover by driving through the heels, keeping the torso upright and elbows up."]},"reviewed":false,"summaryMethod":"source-extract"},"Hang_Snatch":{"version":1,"steps":{"hu":["Kezdd széles fogással a rúdon, felső fogással vagy kampófogással (hook grip).","Miközben a lábadat a fogadóhelyzetbe viszed, erőteljesen húzd magad a rúd alá, és emeld a rudat a fejed fölé.","Állj fel a súllyal a fejed fölött."],"en":["Begin with a wide grip on the bar, with an overhand or hook grip.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead.","Return to a standing position with the weight overhead."]},"reviewed":false,"summaryMethod":"source-extract"},"Hang_Snatch_-_Below_Knees":{"version":1,"steps":{"hu":["Kezdd széles fogással a rúdon, felső fogással vagy kampófogással (hook grip).","Miközben a lábadat a fogadóhelyzetbe viszed, erőteljesen húzd magad a rúd alá, és emeld a rudat a fejed fölé.","Állj fel a súllyal a fejed fölött, majd kontrolláltan engedd vissza a súlyt a talajra."],"en":["Begin with a wide grip on the bar, with an overhand or hook grip.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead.","Return to a standing position with the weight overhead, and then return the weight to the floor under control."]},"reviewed":false,"summaryMethod":"source-extract"},"Hanging_Bar_Good_Morning":{"version":1,"steps":{"hu":["Kezdd úgy, hogy a rúd nagyjából a hasad magasságában van az állványon.","Kezdd a mozdulatot úgy, hogy a farizmod és a combhajlítód erejével kinyújtod a csípődet, amíg fel nem állsz a súllyal.","Lassan engedd vissza a súlyt a kiinduló helyzetbe, ahol a láncok tartják."],"en":["Begin with a bar on a rack at about the same height as your stomach.","Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight.","Slowly lower the weight back to the starting position, where it is supported by the chains."]},"reviewed":false,"summaryMethod":"source-extract"},"Hanging_Leg_Raise":{"version":1,"steps":{"hu":["Függeszkedj a húzódzkodó rúdon, mindkét karod legyen teljesen kinyújtva a fejed fölött, széles vagy közepes fogással.","Emeld a lábadat addig, amíg a törzsed 90 fokos szöget nem zár be a lábaddal.","Lélegezz be, és közben lassan térj vissza a kiinduló helyzetbe."],"en":["Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip.","Raise your legs until the torso makes a 90-degree angle with the legs.","Go back slowly to the starting position as you breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Hanging_Pike":{"version":1,"steps":{"hu":["Függeszkedj a húzódzkodó rúdon zárt lábbal és lábfejjel, felső fogással (a tenyered tőled elfelé néz), vállszélességnél kicsit szélesebben.","Fújd ki a levegőt, és húzd fel a lábadat, amíg a sípcsontod majdnem hozzá nem ér a fölötted lévő rúdhoz.","Engedd le a lábadat a lehető leglassabban, amíg vissza nem érsz a kiinduló helyzetbe."],"en":["Hang from a chin-up bar with your legs and feet together using an overhand grip (palms facing away from you) that is slightly wider than shoulder width.","Pull your legs up as you exhale until you almost touch your shins with the bar above you.","Lower your legs as slowly as possible until you reach the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Heaving_Snatch_Balance":{"version":1,"steps":{"hu":["Ez a gyakorlat segít megtanulni a szakítást.","Kezdd azzal, hogy enyhén berogyasztod a térdedet, majd visszapattansz, így egy pillanatra tehermentesíted a rudat.","Térj vissza álló helyzetbe."],"en":["This drill helps you learn the snatch.","Begin by dipping with the knees slightly, and popping back up to briefly unload the bar.","Return to a standing position."]},"reviewed":false,"summaryMethod":"source-extract"},"Heavy_Bag_Thrust":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz használj nehéz bokszzsákot.","Kezdd a mozdulatot derékból elfordulva, és told előre a zsákot, amilyen erősen csak tudod.","Amikor a zsák visszaleng, fogadd úgy, hogy fordított sorrendben végzed el ugyanezeket a lépéseket."],"en":["Utilize a heavy bag for this exercise.","Begin by twisting at the waist, pushing the bag forward as hard as possible.","Receive the bag as it swings back by reversing these steps."]},"reviewed":false,"summaryMethod":"source-extract"},"High_Cable_Curls":{"version":1,"steps":{"hu":["Állj két felső csiga közé, és fogj meg egy-egy fogantyút mindkét kezeddel.","Hajlítsd a fogantyúkat magad felé, amíg a füled mellé nem kerülnek.","Lassan engedd vissza a karodat a kiinduló helyzetbe."],"en":["Stand between a couple of high pulleys and grab a handle in each arm.","Curl the handles towards you until they are next to your ears.","Slowly bring back the arms to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Hip_Circles_prone":{"version":1,"steps":{"hu":["Helyezkedj négykézlábra a talajon.","A térdedet hajlítva tartva forgasd a combcsontodat körívben, és próbálj minél nagyobb kört leírni a térdeddel.","Végezd lassan, több ismétléssel, majd ismételd meg a másik oldalon."],"en":["Position yourself on your hands and knees on the ground.","Keeping the knee in a bent position, rotate the femur in an arc, attempting to make a big circle with your knee.","Perform this slowly for a number of repetitions, and repeat on the other side."]},"reviewed":false,"summaryMethod":"source-extract"},"Hip_Extension_with_Bands":{"version":1,"steps":{"hu":["Rögzítsd a gumiszalag egyik végét egy oszlop alsó részéhez, a másikat pedig erősítsd az egyik bokádra.","A fejedet és a mellkasodat fent tartva vidd hátra a szalaggal terhelt lábadat, amennyire csak tudod, a térdedet közben tartsd nyújtva.","Vidd vissza a lábadat a kiinduló helyzetbe."],"en":["Secure one end of the band to the lower portion of a post and attach the other to one ankle.","Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight.","Return the leg to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Hip_Flexion_with_Band":{"version":1,"steps":{"hu":["Rögzítsd a gumiszalag egyik végét egy oszlop alsó részéhez, a másikat pedig erősítsd az egyik bokádra.","A fejedet és a mellkasodat fent tartva emeld fel a térdedet 90 fokig, és tarts szünetet.","Vidd vissza a lábadat a kiinduló helyzetbe."],"en":["Secure one end of the band to the lower portion of a post and attach the other to one ankle.","Keeping your head and your chest up, raise your knee up to 90 degrees and pause.","Return the leg to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Hip_Lift_with_Band":{"version":1,"steps":{"hu":["Válassz megfelelő gumiszalagot, rögzítsd az állvány két oldalán, majd feküdj le az állvány közepére.","A válladat a talajon tartva told el magad a sarkaddal, emeld meg a csípődet, és nyomd bele a szalagba, amilyen magasra csak tudod.","A mozdulat tetején tarts szünetet, majd térj vissza a kiinduló helyzetbe."],"en":["After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you.","Keeping your shoulders on the ground, drive through your heels to raise your hips, pushing into the band as high as you can.","Pause at the top of the motion, and return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Hug_A_Ball":{"version":1,"steps":{"hu":["Ülj le a talajra.","Fogj közre egy fitlabdát a két lábaddal, és engedd le a csípődet a talaj felé.","Öleld át a labdát a karoddal, hogy megtámaszd a testedet."],"en":["Seat yourself on the floor.","Straddle an exercise ball between both legs and lower your hips down toward the floor.","Hug your arms around the ball to support your body."]},"reviewed":false,"summaryMethod":"source-extract"},"Hug_Knees_To_Chest":{"version":1,"steps":{"hu":["Feküdj hanyatt, és húzd fel mindkét térdedet a mellkasodhoz.","A karoddal a térded alatt fogd át a lábadat, ne fölötte (az túl nagy nyomást gyakorolna a térdízületeidre).","Lassan húzd a térdedet a vállad felé."],"en":["Lie down on your back and pull both knees up to your chest.","Hold your arms under the knees, not over (that would put to much pressure on your knee joints).","Slowly pull the knees toward your shoulders."]},"reviewed":false,"summaryMethod":"source-extract"},"Hurdle_Hops":{"version":1,"steps":{"hu":["Állíts fel egy sor gátat vagy más alacsony akadályt, egymástól kb.","Kezdd azzal, hogy páros lábbal átugrod az első gátat, ugrás közben lendíts mindkét karoddal.","A térded hajlításával tompítsd az érkezést, majd az első ugrásból visszapattanva ugord át a következő gátat."],"en":["Set up a row of hurdles or other small barriers, placing them a few feet apart.","Begin by jumping with both feet over the first hurdle, swinging both arms as you jump.","Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next hurdle."]},"reviewed":false,"summaryMethod":"source-extract"},"Hyperextensions_Back_Extensions":{"version":1,"steps":{"hu":["Feküdj hasra a hiperextenziós padra, és akaszd a bokádat biztosan a lábtámaszok alá.","Egyenes testtel fond keresztbe a karodat magad előtt (én ezt javaslom) vagy tedd a fejed mögé.","Lélegezz be, és közben lassan emeld vissza a törzsedet a kiinduló helyzetbe."],"en":["Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.","With your body straight, cross your arms in front of you (my preference) or behind your head.","Slowly raise your torso back to the initial position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Hyperextensions_With_No_Hyperextension_Bench":{"version":1,"steps":{"hu":["Kérj meg valakit, hogy fogja le a lábadat, és csússz előre a sík pad széléig, amíg a csípőd le nem lóg a pad végéről.","Kezdj el lassan előrehajolni derékból, amennyire csak tudsz, közben a hátad maradjon egyenes.","Fújd ki a levegőt, és közben lassan emeld vissza a törzsedet a kiinduló helyzetbe."],"en":["With someone holding down your legs, slide yourself down to the edge a flat bench until your hips hang off the end of the bench.","Start bending forward slowly at the waist as far as you can while keeping your back flat.","Slowly raise your torso back to the initial position as you exhale."]},"reviewed":false,"summaryMethod":"source-extract"},"IT_Band_and_Glute_Stretch":{"version":1,"steps":{"hu":["Hurkolj egy övet, kötelet vagy gumiszalagot az egyik lábfejed köré, és a talajon fekve lendítsd át ezt a lábadat a tested előtt az ellenkező oldalra, közben tartsd nyújtva.","A lábfejedet a talajtól elemelve húzd meg az övet, és a feszítés segítségével húzd felfelé a lábujjaidat."],"en":["Loop a belt, rope, or band around one of your feet, and swing that leg across your body to the opposite side, keeping the leg extended as you lay on the ground.","Keeping your foot off of the floor, pull on the belt, using the tension to pull the toes up."]},"reviewed":false,"summaryMethod":"source-extract"},"Iliotibial_Tract-SMR":{"version":1,"steps":{"hu":["Feküdj az oldaladra úgy, hogy az alul lévő lábad a hengeren legyen, a csípő és a térd közötti részen.","Helyezz annyi testsúlyt az alul lévő lábadra, amennyit még el tudsz viselni; az alsó lábadnak nem kell érintenie a talajt.","Görgesd a lábadat a hengeren a csípődtől a térdedig, a feszes pontokon állj meg 10–30 másodpercre."],"en":["Lay on your side, with the bottom leg placed onto a foam roller between the hip and the knee.","Place as much of your weight as is tolerable onto your bottom leg; there is no need to keep your bottom leg in contact with the ground.","Roll your leg over the foam from you hip to your knee, pausing for 10-30 seconds at points of tension."]},"reviewed":false,"summaryMethod":"source-extract"},"Inchworm":{"version":1,"steps":{"hu":["Állj közel zárt lábbal.","Folytasd, amíg a tested fekvőtámasz helyzetben párhuzamos nem lesz a talajjal.","Lépkedj tovább, amíg a lábfejed a kezed mellé nem ér, közben tartsd nyújtva a lábadat."],"en":["Stand with your feet close together.","Keep going until your body is parallel to the ground in a pushup position.","Continue walking until your feet are by hour hands, keeping your legs straight as you do so."]},"reviewed":false,"summaryMethod":"source-extract"},"Incline_Barbell_Triceps_Extension":{"version":1,"steps":{"hu":["Feküdj ferde padra, a rudat felső fogással tartsd a fejed fölött.","Könyökhajlítással engedd a rudat a fejed mögé.","Felkarod maradjon stabil; nyújtsd vissza a könyököd."],"en":["Lie on an incline bench holding the bar overhead with an overhand grip.","Bend your elbows to lower the bar behind your head.","Keep your upper arms steady; extend your elbows again."]},"reviewed":true,"summaryMethod":"curated"},"Incline_Bench_Pull":{"version":1,"steps":{"hu":["Fogj egy-egy kézisúlyzót a kezedbe, és feküdj hasra egy kb.","Most nyisd kifelé a könyöködet.","Lélegezz be, és közben lassan ereszkedj vissza a kiinduló helyzetbe."],"en":["Grab a dumbbell in each hand and lie face down on an incline bench that is set to an incline that is approximately 30 degrees.","Now flare the elbows out.","Slowly go back down to the starting position as you breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Incline_Cable_Chest_Press":{"version":1,"steps":{"hu":["Állítsd be a megfelelő súlyt, ülj le, és fogd meg a fogantyúkat.","Kezdd a mozdulatot a könyököd nyújtásával, és nyomd a fogantyúkat egyenesen magad elé, egymás felé.","A teljes nyújtásnál tarts szünetet, majd térj vissza a kiinduló helyzetbe úgy, hogy a kábelek végig feszesek maradnak."],"en":["Adjust the weight to an appropriate amount and be seated, grasping the handles.","Begin by extending through the elbow, pressing the handles together straight in front of you.","After pausing at full extension, return to the starting position, keeping tension on the cables."]},"reviewed":false,"summaryMethod":"source-extract"},"Incline_Cable_Flye":{"version":1,"steps":{"hu":["A kiinduló helyzet felvételéhez állítsd a csigákat a talaj szintjére (a gépen a lehető legalacsonyabb fokozatra, amely a törzsed alatt van).","Mindkét kezedben egy-egy fogantyúval feküdj a ferde padra, és nyújtott karral zárd össze a kezedet az arcod előtt.","Fújd ki a levegőt, és a mellizmodat megfeszítve vidd vissza a karodat a kiinduló helyzetbe."],"en":["To get yourself into the starting position, set the pulleys at the floor level (lowest level possible on the machine that is below your torso).","With a handle on each hand, lie on the incline bench and bring your hands together at arms length in front of your face.","Return your arms back to the starting position as you squeeze your chest muscles and exhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Incline_Dumbbell_Bench_With_Palms_Facing_In":{"version":1,"steps":{"hu":["Feküdj hanyatt egy ferde padra, mindkét kezedben egy-egy kézisúlyzóval, amelyek a combodon nyugszanak.","Most lélegezz be, és lassan engedd le a súlyzókat a tested mellé.","Ha végeztél, tedd vissza a súlyzókat a combodra, majd a talajra."],"en":["Lie back on an incline bench with a dumbbell on each hand on top of your thighs.","Now bring down the weights slowly to your side as you breathe in.","When you are done, place the dumbbells back in your thighs and then on the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Incline_Dumbbell_Curl":{"version":1,"steps":{"hu":["Támaszkodj a ferde padnak, a súlyzók lógjanak a tested mellett, tenyérrel előre.","Hajlítsd a könyököd, emeld a súlyokat a vállad felé.","Ne vidd előre a felkarod; lassan engedd le."],"en":["Lean against an incline bench, dumbbells hanging beside you with palms forward.","Bend your elbows to curl toward your shoulders.","Keep your upper arms still; lower slowly."]},"reviewed":true,"summaryMethod":"curated"},"Incline_Dumbbell_Flyes":{"version":1,"steps":{"hu":["Fogj egy-egy kézisúlyzót a kezedbe, és feküdj egy legfeljebb 30 fokos dőlésszögre állított ferde padra.","Most fordítsd el a csuklódat úgy, hogy a tenyered feléd nézzen.","Fújd ki a levegőt, és a mozdulatot megfordítva kezdd el visszaemelni a súlyzókat a kiinduló helyzetbe, közben fordítsd a kezedet úgy, hogy a kisujjaid ismét egymás mellé kerüljenek."],"en":["Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.","Now rotate the wrists so that the palms of your hands are facing you.","As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again."]},"reviewed":false,"summaryMethod":"source-extract"},"Incline_Dumbbell_Flyes_-_With_A_Twist":{"version":1,"steps":{"hu":["Fogj egy-egy kézisúlyzót a kezedbe, és feküdj egy legfeljebb 30 fokos dőlésszögre állított ferde padra.","Most fordítsd el a csuklódat úgy, hogy a tenyered feléd nézzen.","Fújd ki a levegőt, és a mozdulatot megfordítva kezdd el visszaemelni a súlyzókat a kiinduló helyzetbe, közben fordítsd a kezedet úgy, hogy a kisujjaid ismét egymás mellé kerüljenek."],"en":["Hold a dumbbell in each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.","Now rotate the wrists so that the palms of your hands are facing you.","As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again."]},"reviewed":false,"summaryMethod":"source-extract"},"Incline_Dumbbell_Press":{"version":1,"steps":{"hu":["Feküdj ferde padra, a súlyzók a vállad mellett legyenek, tenyérrel előre.","Nyomd a súlyokat a mellkasod fölé.","Lapockád maradjon támaszon; kontrolláltan engedd vissza."],"en":["Lie on an incline bench with dumbbells beside your shoulders, palms forward.","Press the weights above your chest.","Keep your shoulder blades supported; lower with control."]},"reviewed":true,"summaryMethod":"curated"},"Incline_Hammer_Curls":{"version":1,"steps":{"hu":["Ülj egy ferde padra, mindkét kezedben egy-egy kézisúlyzóval.","Indítsd a mozdulatot a könyököd hajlításával, és igyekezz a felkarodat mozdulatlanul tartani.","Folytasd a mozdulat tetejéig, tarts szünetet, majd lassan térj vissza a kiinduló helyzetbe."],"en":["Seat yourself on an incline bench with a dumbbell in each hand.","Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary.","Continue to the top of the movement and pause, then slowly return to the start position."]},"reviewed":false,"summaryMethod":"source-extract"},"Incline_Inner_Biceps_Curl":{"version":1,"steps":{"hu":["Fogj egy-egy kézisúlyzót a kezedbe, és feküdj hátra egy ferde padra.","Most fújd ki a levegőt, és hajlítsd a súlyt kifelé és felfelé úgy, hogy az alkarod az oldalsó deltaizmaid vonalában marad.","A mozdulat tetején tartsd meg egy másodpercig a megfeszítést, majd kezdj el belélegezni, és lassan engedd vissza a súlyzókat a kiinduló helyzetbe ugyanazon az úton, amelyen felemelted őket."],"en":["Hold a dumbbell in each hand and lie back on an incline bench.","Now as you exhale curl the weight outward and up while keeping your forearms in line with your side deltoids.","After a second contraction at the top of the movement, start to inhale and slowly lower the weights back to the starting position using the same path used to bring them up."]},"reviewed":false,"summaryMethod":"source-extract"},"Incline_Push-Up":{"version":1,"steps":{"hu":["Állj szembe egy paddal vagy egy stabil, megemelt felülettel.","Lépj hátra a padtól vagy a felülettől, és támaszkodj a lábfejed elülső részén, a karod és a tested legyen egyenes.","Nyomd fel magad, amíg a karod ki nem nyúlik."],"en":["Stand facing bench or sturdy elevated platform.","Position forefoot back from bench or platform with arms and body straight.","Push body up until arms are extended."]},"reviewed":false,"summaryMethod":"source-extract"},"Incline_Push-Up_Close-Grip":{"version":1,"steps":{"hu":["Állj szembe egy megfelelő magasságra állított Smith-gép rúdjával vagy egy megfelelő magasságú, stabil, megemelt felülettel.","Lépj hátra a lábaddal a rúdtól, a karod és a tested legyen egyenes.","A könyöködet kinyújtva nyomd vissza magad, és térj vissza a kiinduló helyzetbe."],"en":["Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.","Position your feet back from the bar with arms and body straight.","Return to the starting position by extending the elbows, pressing yourself back up."]},"reviewed":false,"summaryMethod":"source-extract"},"Incline_Push-Up_Depth_Jump":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz egy kb.","Helyezd a szteppadokat közvetlenül a vállad vonalán kívülre, a lábfejedet pedig tedd a dobozra, így döntött fekvőtámasz helyzetbe kerülsz, a kezed közvetlenül a szteppadokon belül legyen.","Kezdd a könyököd hajlításával, engedd le a testedet, majd gyorsan válts irányt, és lökd el magad a talajtól."],"en":["For this drill you will need a box about 12 inches high, and two thick mats or aerobics steps.","Place the steps just outside of your shoulders, and place your feet on top of the box so that you are in an incline pushup position, your hands just inside the steps.","Begin by bending at the elbows to lower your body, quickly reversing position to push your body off of the ground."]},"reviewed":false,"summaryMethod":"source-extract"},"Incline_Push-Up_Medium":{"version":1,"steps":{"hu":["Állj szembe egy megfelelő magasságra állított Smith-gép rúdjával vagy egy megfelelő magasságú, stabil, megemelt felülettel.","Lépj hátra a lábaddal a rúdtól, a karod és a tested legyen egyenes.","A könyöködet kinyújtva nyomd vissza magad, és térj vissza a kiinduló helyzetbe."],"en":["Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.","Position your feet back from the bar with arms and body straight.","Return to the starting position by extending the elbows, pressing yourself back up."]},"reviewed":false,"summaryMethod":"source-extract"},"Incline_Push-Up_Reverse_Grip":{"version":1,"steps":{"hu":["Állj szembe egy megfelelő magasságra állított Smith-gép rúdjával vagy egy megfelelő magasságú, stabil, megemelt felülettel.","Lépj hátra a lábaddal a rúdtól, a karod és a tested legyen egyenes.","A könyöködet kinyújtva nyomd vissza magad, és térj vissza a kiinduló helyzetbe."],"en":["Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.","Position your feet back from the bar with arms and body straight.","Return to the starting position by extending the elbows, pressing yourself back up."]},"reviewed":false,"summaryMethod":"source-extract"},"Incline_Push-Up_Wide":{"version":1,"steps":{"hu":["Állj szembe egy megfelelő magasságra állított Smith-gép rúdjával vagy egy megfelelő magasságú, stabil, megemelt felülettel.","Lépj hátra a lábaddal a rúdtól, a karod és a tested legyen egyenes.","A könyöködet kinyújtva nyomd vissza magad, és térj vissza a kiinduló helyzetbe."],"en":["Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.","Position your feet back from the bar with arms and body straight.","Return to the starting position by extending the elbows, pressing yourself back up."]},"reviewed":false,"summaryMethod":"source-extract"},"Intermediate_Groin_Stretch":{"version":1,"steps":{"hu":["Feküdj hanyatt nyújtott lábbal.","Húzd meg finoman az övet, hogy feszülést érezz az ágyékodban és a combhajlítódban."],"en":["Lie on your back with your legs extended.","Pull gently on the belt to create tension in your groin and hamstring muscles."]},"reviewed":false,"summaryMethod":"source-extract"},"Intermediate_Hip_Flexor_and_Quad_Stretch":{"version":1,"steps":{"hu":["Feküdj hasra a talajon úgy, hogy az egyik lábfejed köré egy kötél, öv vagy gumiszalag van hurkolva.","Hajlítsd be a nyújtani kívánt lábad térdét, és nyújtsd ki a csípőjét, miközben két kézzel húzod az övet."],"en":["Lie face down on the floor, with a rope, belt, or band looped around one foot.","Flex the knee and extend the hip of the leg to be stretched, using both hands to pull on the belt."]},"reviewed":false,"summaryMethod":"source-extract"},"Internal_Rotation_with_Band":{"version":1,"steps":{"hu":["Hurkold a gumiszalagot egy oszlop köré.","A felkarod a helyén van, a könyököd legyen 90 fokban hajlítva, a kezed pedig mutasson a törzsedtől elfelé.","Folytasd, ameddig csak tudod, tarts szünetet, majd térj vissza a kiinduló helyzetbe."],"en":["Choke the band around a post.","With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching away from your torso.","Continue as far as you are able, pause, and then return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Inverted_Row":{"version":1,"steps":{"hu":["Állíts be egy rudat az állványon nagyjából derékmagasságba.","Kezdd a könyököd hajlításával, és húzd a mellkasodat a rúd felé.","A mozdulat tetején tarts szünetet, majd ereszkedj vissza a kiinduló helyzetbe."],"en":["Position a bar in a rack to about waist height.","Begin by flexing the elbow, pulling your chest towards the bar.","Pause at the top of the motion, and return yourself to the start position."]},"reviewed":false,"summaryMethod":"source-extract"},"Inverted_Row_with_Straps":{"version":1,"steps":{"hu":["Akassz egy kötelet vagy függesztőhevedert egy állványra vagy más stabil tárgyra.","Kezdd a könyököd hajlításával, és húzd a mellkasodat a kezedhez.","A mozdulat tetején tarts szünetet, majd ereszkedj vissza a kiinduló helyzetbe."],"en":["Hang a rope or suspension straps from a rack or other stable object.","Begin by flexing the elbow, pulling your chest to your hands.","Pause at the top of the motion, and return yourself to the start position."]},"reviewed":false,"summaryMethod":"source-extract"},"Iron_Cross":{"version":1,"steps":{"hu":["Guggoló helyzetben tarts két kézisúlyzót magad előtt vállmagasságban.","Állj fel, közben nyisd a karjaidat oldalra vállmagasságban.","Kontrolláltan zárd vissza a karod, és térj vissza guggolásba."],"en":["Hold two dumbbells in front at shoulder height while squatting.","Stand up as you open your arms out to shoulder height.","Bring your arms together with control and return to the squat."]},"reviewed":true,"summaryMethod":"curated"},"Iron_Crosses_stretch":{"version":1,"steps":{"hu":["Feküdj hasra a talajon, a karod legyen oldalra nyújtva, a tenyered a talajhoz szorítva.","Kezdésként hajlítsd be az egyik térdedet, és vidd át ezt a lábadat a tested mögött keresztben, megpróbálva megérinteni vele a talajt az ellenkező oldali kezed közelében.","Azonnal vidd vissza a lábadat a kiinduló helyzetbe, és gyorsan ismételd meg a másik lábaddal."],"en":["Lie face down on the floor, with your arms extended out to your side, palms pressed to the floor.","To begin, flex one knee and bring that leg across the back of your body, attempting to touch it to the ground near the opposite hand.","Promptly return the leg to the starting postion, and quickly repeat with the other leg."]},"reviewed":false,"summaryMethod":"source-extract"},"Isometric_Chest_Squeezes":{"version":1,"steps":{"hu":["Ülve vagy állva hajlítsd be a karodat 90 fokos szögben, és illeszd össze a tenyereidet a mellkasod előtt.","Tartsd meg az előírt számú másodpercig.","Pihenj az előírt ideig, majd ismételd."],"en":["While either seating or standing, bend your arms at a 90-degree angle and place the palms of your hands together in front of your chest.","Hold for the recommended number of seconds.","Rest for the recommended amount of time and repeat."]},"reviewed":false,"summaryMethod":"source-extract"},"Isometric_Neck_Exercise_-_Front_And_Back":{"version":1,"steps":{"hu":["A fejed és a nyakad legyen semleges helyzetben (normál tartás, egyenesen tartott fejjel előre nézve), és tedd mindkét kezedet a fejed elülső oldalára.","Tartsd meg az előírt számú másodpercig.","Pihenj az előírt ideig, majd ismételd meg úgy, hogy a kezedet a fejed hátsó oldalára teszed."],"en":["With your head and neck in a neutral position (normal position with head erect facing forward), place both of your hands on the front side of your head.","Hold for the recommended number of seconds.","Rest for the recommended amount of time and repeat with your hands placed on the back side of your head."]},"reviewed":false,"summaryMethod":"source-extract"},"Isometric_Neck_Exercise_-_Sides":{"version":1,"steps":{"hu":["A fejed és a nyakad legyen semleges helyzetben (normál tartás, egyenesen tartott fejjel előre nézve), és tedd a bal kezedet a fejed bal oldalára.","Tartsd meg az előírt számú másodpercig.","Pihenj az előírt ideig, majd ismételd meg úgy, hogy a jobb kezedet a fejed jobb oldalára teszed."],"en":["With your head and neck in a neutral position (normal position with head erect facing forward), place your left hand on the left side of your head.","Hold for the recommended number of seconds.","Rest for the recommended amount of time and repeat with your right hand placed on the right side of your head."]},"reviewed":false,"summaryMethod":"source-extract"},"Isometric_Wipers":{"version":1,"steps":{"hu":["Vegyél fel fekvőtámasz helyzetet: a testsúlyodat a kezeden és a lábujjaidon tartod, a tested egyenes.","Kezdd azzal, hogy a testsúlyodat a lehető legmesszebb áthelyezed az egyik oldalra, és engeded, hogy az azon az oldalon lévő könyököd behajoljon, miközben leereszkedsz.","Fordítsd meg a mozdulatot: nyújtsd ki a behajlított karodat, nyomd fel magad, majd ereszkedj le a másik oldalra."],"en":["Assume a push-up position, supporting your weight on your hands and toes while keeping your body straight.","Begin by shifting your body weight as far to one side as possible, allowing the elbow on that side to flex as you lower your body.","Reverse the motion by extending the flexed arm, pushing yourself up and then dropping to the other side."]},"reviewed":false,"summaryMethod":"source-extract"},"JM_Press":{"version":1,"steps":{"hu":["Kezdd a gyakorlatot ugyanúgy, mint a szűk fogású fekvenyomást.","Fújd ki a levegőt, és a tricepszed erejével, szűk fogású fekvenyomás mozdulattal nyomd vissza a rudat.","Most térj vissza a kiinduló helyzetbe, és kezdd elölről."],"en":["Start the exercise the same way you would a close grip bench press.","As you exhale, press the bar back up by using the triceps to perform a close grip bench press.","Now go back to the starting position and start over."]},"reviewed":false,"summaryMethod":"source-extract"},"Jackknife_Sit-Up":{"version":1,"steps":{"hu":["Feküdj hanyatt a talajon (vagy tornaszőnyegen), a karod legyen egyenesen hátranyújtva a fejed mögé, és a lábad is legyen nyújtva.","Fújd ki a levegőt, és hajolj be derékból, közben egyszerre emeld a lábadat és a karodat, hogy bicska helyzetben találkozzanak.","Lélegezz be, és közben engedd vissza a karodat és a lábadat a kiinduló helyzetbe."],"en":["Lie flat on the floor (or exercise mat) on your back with your arms extended straight back behind your head and your legs extended also.","As you exhale, bend at the waist while simultaneously raising your legs and arms to meet in a jackknife position.","While inhaling, lower your arms and legs back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Janda_Sit-Up":{"version":1,"steps":{"hu":["Helyezkedj el a talajon a szokásos felülés kiinduló pozíciójában: a térded 90 fokban hajlítva, a talpad a talajon, a karod pedig a mellkasod előtt keresztezve vagy a tested mellett.","Feszítsd meg erősen a farizmod és a combhajlítód, szívd tele a tüdőd levegővel, majd lassan (három-hat másodpercig számolva) emelkedj fel, közben lassan fújd ki a levegőt.","Belégzés közben lassan, kontrolláltan ereszkedj vissza a kiinduló helyzetbe."],"en":["Position your body on the floor in the basic sit-up position; knees to a ninety degree angle with feet flat on the floor and arms either crossed over your chest or to the sides.","As you strongly tighten your glutes and hamstrings, fill your lungs with air and in a slow (three to six second count) ascent, slowly exhale.","As you inhale, slowly go back in a controlled manner to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Jefferson_Squats":{"version":1,"steps":{"hu":["Tegyél egy rudat a talajra.","A bal kezeddel fogd meg a rudat hátul.","Most a talpaddal a talajt tolva nyomd fel magad a kiinduló helyzetbe."],"en":["Place a barbell on the floor.","Grasp the rear of the bar with your left hand.","Now drive yourself back up to the starting position by pushing with the feet ."]},"reviewed":false,"summaryMethod":"source-extract"},"Jerk_Balance":{"version":1,"steps":{"hu":["Ez a gyakorlat segít megtanulni, hogy a lökésnél elég mélyre vidd magad a súly alá, és kijavítja azokat, akik a mozdulat közben hátrafelé mozdulnak.","Indítsd a mozdulatot ugyanúgy, mint egy normál lökést: rogyassz be térdből úgy, hogy a törzsed függőleges marad, majd erőteljesen lökd fel magad, és a lendülettel, ne a karoddal emeld a súlyt.","A hátsó lábad maradjon a helyén, és azzal told előre a tested teljes ollóba, miközben kilököd a súlyt."],"en":["This drill helps you learn to drive yourself low enough during the jerk and corrects those who move backward during the movement.","Initiate the movement as you would a normal jerk, dipping at the knees while keeping your torso vertical, and driving back up forcefully, using momentum and not your arms to elevate the weight.","Keep the rear foot in place, using it to drive your body forward into a full split as you jerk the weight."]},"reviewed":false,"summaryMethod":"source-extract"},"Jerk_Dip_Squat":{"version":1,"steps":{"hu":["Ez a mozdulat a lökés berogyasztási szakaszát erősíti.","A törzsed függőlegesen tartva rogyassz be térdhajlítással: a térded mozdulhat előre, de a csípőd ne told hátra."],"en":["This movement strengthens the dip portion of the jerk.","Keeping the torso vertical, dip by flexing the knees, allowing them to travel forward and without moving the hips to the rear."]},"reviewed":false,"summaryMethod":"source-extract"},"Jogging_Treadmill":{"version":1,"steps":{"hu":["Kezdésként lépj fel a futópadra, és válaszd ki a kívánt lehetőséget a menüből.","A futópad kényelmes, jót tesz a szív- és érrendszernek, és általában kevésbé terheli az ízületeket, mint a szabadtéri kocogás."],"en":["To begin, step onto the treadmill and select the desired option from the menu.","Treadmills offer convenience, cardiovascular benefits, and usually have less impact than jogging outside."]},"reviewed":false,"summaryMethod":"source-extract"},"Keg_Load":{"version":1,"steps":{"hu":["A hordópakoláshoz helyezd el a kívánt számú hordót a rakodóemelvénytől bizonyos távolságra, jellemzően kb.","Minél magasabbra tudod venni a hordót, annál gyorsabban tudsz az emelvényhez haladni.","Menj vissza a kiinduló helyre a következő hordóért, és ismételd, amíg a versenyszám véget nem ér."],"en":["To load kegs, place the desired number a distance from the loading platform, typically 30-50 feet.","The higher you can place the keg, the faster you should be able to move to the platform.","Return to the starting position to retrieve the next keg, and repeat until the event is completed."]},"reviewed":false,"summaryMethod":"source-extract"},"Kettlebell_Arnold_Press":{"version":1,"steps":{"hu":["Vedd fel a kettlebellt a válladhoz.","Egyenesen előre nézve nyomd ki a kettlebellt a fejed fölé, közben fordítsd a csuklód úgy, hogy a mozdulat tetején a tenyered előre nézzen.","Engedd vissza a kettlebellt a kiinduló helyzetbe úgy, hogy a tenyered ismét befelé néz."],"en":["Clean a kettlebell to your shoulder.","Looking straight ahead, press the kettlebell out and overhead, rotating your wrist so that your palm faces forward at the top of the motion.","Return the kettlebell to the starting position, with the palm facing in."]},"reviewed":false,"summaryMethod":"source-extract"},"Kettlebell_Dead_Clean":{"version":1,"steps":{"hu":["Tedd a kettlebellt a két lábfejed közé.","Vedd fel a kettlebellt a válladhoz.","Engedd le a kettlebellt úgy, hogy a combhajlítód terhelés alatt marad: tartsd egyenesen a hátad, a feneked pedig told hátra."],"en":["Place kettlebell between your feet.","Clean the kettlebell to your shoulder.","Lower the kettlebell, keeping the hamstrings loaded by keeping your back straight and your butt out."]},"reviewed":false,"summaryMethod":"source-extract"},"Kettlebell_Figure_8":{"version":1,"steps":{"hu":["Tegyél egy kettlebellt a lábad közé, és állj vállszélesnél nagyobb terpeszbe.","Vedd fel a kettlebellt, és add át a lábad között a másik kezedbe."],"en":["Place one kettlebell between your legs and take a wider than shoulder width stance.","Pick up a kettlebell and pass it to your other hand between your legs."]},"reviewed":false,"summaryMethod":"source-extract"},"Kettlebell_Halo":{"version":1,"steps":{"hu":["Állj egyenesen, csípőszéles terpeszben.","Folytasd a kört a másik füled mellett, majd vissza le a mellkasod elé, a kiinduló helyzetbe; a kettlebell végig a testedhez közel haladjon.","Mozogj lassan, a fejed, a csípőd és a derekad maradjon mozdulatlan."],"en":["Stand tall with your feet hip-width apart.","Continue the circle past the opposite ear and back down to the starting position in front of your chest, letting the bell pass close to your body throughout.","Move slowly and keep your head, hips and lower back still."]},"reviewed":false,"summaryMethod":"source-extract"},"Kettlebell_Halo_With_Overhead_Extension":{"version":1,"steps":{"hu":["Állj egyenesen, csípőszéles terpeszben.","Hajlítsd be a könyököd, és kontrolláltan engedd vissza a kettlebellt a fejed mögé, a megállási pozícióba.","Minden ismétlésnél válts körirányt."],"en":["Stand tall with your feet hip-width apart.","Bend your elbows to lower the kettlebell back to the pause position behind your head, under control.","Alternate the direction of the circle on each repetition."]},"reviewed":false,"summaryMethod":"source-extract"},"Kettlebell_Hang_Clean":{"version":1,"steps":{"hu":["Tedd a kettlebellt a két lábfejed közé.","Vedd fel a kettlebellt a válladhoz.","Engedd le a kettlebellt függő helyzetbe a lábad közé úgy, hogy a combhajlítód terhelés alatt marad."],"en":["Place kettlebell between your feet.","Clean kettlebell to your shoulder.","Lower kettlebell to a hanging position between your legs while keeping the hamstrings loaded."]},"reviewed":false,"summaryMethod":"source-extract"},"Kettlebell_One-Legged_Deadlift":{"version":1,"steps":{"hu":["Fogd meg egy kézzel a kettlebell fogantyúját.","A támaszlábad térdét enyhén hajlítva tartva végezz nyújtott lábas felhúzást: dőlj előre csípőből, a szabad lábad pedig nyújtsd hátra az egyensúly érdekében.","Engedd tovább a kettlebellt, amíg a törzsed párhuzamos nem lesz a talajjal, majd egyenesedj vissza álló helyzetbe."],"en":["Hold a kettlebell by the handle in one hand.","Keeping that knee slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance.","Continue lowering the kettlebell until you are parallel to the ground, and then return to the upright position."]},"reviewed":false,"summaryMethod":"source-extract"},"Kettlebell_Overhead_Triceps_Extension":{"version":1,"steps":{"hu":["Állj csípőszéles terpeszben, és fogd a kettlebellt két kézzel a fogantyú két oldalánál (a „szarvaknál”).","Könyökből hajlítva engedd le a kettlebellt a fejed mögé, olyan mélyre, amennyire a vállad mobilitása engedi anélkül, hogy a könyököd kifelé nyílna.","Tartsd lent a bordakosarad, és nyújtás közben ne homoríts a derekadból."],"en":["Stand with your feet hip-width apart, holding a kettlebell by the horns with both hands.","Bend at the elbows to lower the kettlebell behind your head, going as far as your shoulder mobility allows without your elbows flaring outward.","Keep your ribcage down and avoid arching your lower back as you extend."]},"reviewed":false,"summaryMethod":"source-extract"},"Kettlebell_Pass_Between_The_Legs":{"version":1,"steps":{"hu":["Tegyél egy kettlebellt a lábad közé, és vegyél fel kényelmes terpeszt.","Vedd fel a kettlebellt, és add át a lábad között a másik kezedbe, „W” alakot leírva."],"en":["Place one kettlebell between your legs and take a comfortable stance.","Pick up a kettlebell and pass it to your other hand between your legs, in the fashion of a \"W\"."]},"reviewed":false,"summaryMethod":"source-extract"},"Kettlebell_Pirate_Ships":{"version":1,"steps":{"hu":["Állj széles terpeszbe, és fogd a kettlebellt két kézzel.","Indítsd a mozdulatot úgy, hogy az egyik oldalra fordulsz, és a kettlebellt fejmagasságig lendíted.","Hagyd, hogy a kettlebell lesüllyedjen, miközben a másik oldalra fordulsz, és ott is emeld fejmagasságig."],"en":["With a wide stance, hold a kettlebell with both hands.","Initiate the movement by turning to one side, swinging the kettlebell to head height.","Allow the bell to drop as you rotate to the opposite side, again raising the kettlebell to head height."]},"reviewed":false,"summaryMethod":"source-extract"},"Kettlebell_Pistol_Squat":{"version":1,"steps":{"hu":["Vedd fel a kettlebellt két kézzel, és fogd a fogantyú két oldalánál (a „szarvaknál”).","Tartsd meg az alsó helyzetet egy másodpercig, majd fordítsd meg a mozdulatot: a sarkadból told fel magad, a fejed és a mellkasod maradjon fent.","Ereszkedj le újra, és ismételd."],"en":["Pick up a kettlebell with two hands and hold it by the horns.","Hold the bottom position for a second and then reverse the motion, driving through the heel and keeping your head and chest up.","Lower yourself again and repeat."]},"reviewed":false,"summaryMethod":"source-extract"},"Kettlebell_Seated_Press":{"version":1,"steps":{"hu":["Ülj le a talajra, és nyisd szét a lábad kényelmes terpeszbe.","Vegyél fel egy kettlebellt a válladhoz.","Nyomd a kettlebellt felfelé és kifelé, amíg a karod a fejed fölött teljesen ki nem nyúlik."],"en":["Sit on the floor and spread your legs out comfortably.","Clean one kettlebell to your shoulder.","Press the kettlebell up and out until it is locked out overhead."]},"reviewed":false,"summaryMethod":"source-extract"},"Kettlebell_Seesaw_Press":{"version":1,"steps":{"hu":["Vegyél fel két kettlebellt a válladhoz.","Nyomd ki az egyik kettlebellt.","Engedd le a kettlebellt, és azonnal nyomd ki a másikat."],"en":["Clean two kettlebells two your shoulders.","Press one kettlebell.","Lower the kettlebell and immediately press the other kettlebell."]},"reviewed":false,"summaryMethod":"source-extract"},"Kettlebell_Sumo_High_Pull":{"version":1,"steps":{"hu":["Tegyél egy kettlebellt a talajra a két lábfejed közé.","Nyújtsd ki a csípőd és a térded, és ezzel egy időben húzd a kettlebellt a válladhoz, közben emeld a könyököd."],"en":["Place a kettlebell on the ground between your feet.","Begin by extending the hips and knees, simultaneously pulling the kettlebell to your shoulders, raising your elbows as you do so."]},"reviewed":false,"summaryMethod":"source-extract"},"Kettlebell_Thruster":{"version":1,"steps":{"hu":["Vegyél fel két kettlebellt a válladhoz.","Az alsó ponton fordíts irányt, és állj fel a térded és a csípőd kinyújtásával, a sarkadból tolva magad.","A következő ismétlés kezdetén engedd vissza a súlyokat a válladhoz."],"en":["Clean two kettlebells to your shoulders.","At the bottom, reverse direction and squat by extending your knees and hips, driving through your heels.","As you begin the next repetition, return the weights to the shoulders."]},"reviewed":false,"summaryMethod":"source-extract"},"Kettlebell_Turkish_Get-Up_Lunge_style":{"version":1,"steps":{"hu":["Feküdj hanyatt a talajra, és a könyököd kinyújtásával nyomd ki a kettlebellt a felső helyzetbe.","A kettlebellt végig nyújtott karral tartva fordulj az ellenkező oldalra, és a nem dolgozó karoddal segítsd magad előre a kitöréses helyzetbe.","A kettlebellre felnézve lassan állj fel."],"en":["Lie on your back on the floor and press a kettlebell to the top position by extending the elbow.","Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position.","While looking up at the kettlebell, slowly stand up."]},"reviewed":false,"summaryMethod":"source-extract"},"Kettlebell_Turkish_Get-Up_Squat_style":{"version":1,"steps":{"hu":["Feküdj hanyatt a talajra, és a könyököd kinyújtásával nyomd ki a kettlebellt a felső helyzetbe.","A kettlebellt végig nyújtott karral tartva fordulj az ellenkező oldalra, és a nem dolgozó karoddal segítsd magad előre a kitöréses helyzetbe.","A szabad kezeddel told fel magad ülésbe, majd onnan a talpadra."],"en":["Lie on your back on the floor and press a kettlebell to the top position by extending the elbow.","Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position.","Using your free hand, push yourself to a seated position, then progressing to your feet."]},"reviewed":false,"summaryMethod":"source-extract"},"Kettlebell_Windmill":{"version":1,"steps":{"hu":["Tegyél egy kettlebellt az elöl lévő lábad elé, majd az ellenkező oldali karoddal vedd fel, és nyomd a fejed fölé.","A kettlebellt végig nyújtott karral tartva told ki a feneked a kinyomott kettlebell irányába.","A talaj elérése után tarts egy másodperc szünetet, majd a mozdulatot megfordítva térj vissza a kiinduló helyzetbe."],"en":["Place a kettlebell in front of your lead foot and clean and press it overhead with your opposite arm.","Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell.","Pause for a second after reaching the ground and reverse the motion back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Kipping_Muscle_Up":{"version":1,"steps":{"hu":["Fogd meg a gyűrűket hamis fogással (false grip), úgy, hogy a tenyered töve a gyűrűk tetején legyen.","Ellensúlyozd ezt úgy, hogy a lábad előre és felfelé lendíted, az állad és a mellkasod hátrarántod, közben pedig mindkét karoddal felhúzod magad.","Óvatosan ereszkedj vissza a talajra."],"en":["Grip the rings using a false grip, with the base of your palms on top of the rings.","Counter that movement by swinging your legs forward and up, jerking your chin and chest back, pulling yourself up with both arms as you do so.","Use care when lowering yourself to the ground."]},"reviewed":false,"summaryMethod":"source-extract"},"Knee_Across_The_Body":{"version":1,"steps":{"hu":["Feküdj a talajra, a jobb lábad legyen nyújtva.","A bal karod tedd kényelmesen magad mellé, a fejed pedig fordítsd balra."],"en":["Lie down on the floor with your right leg straight.","Place your left arm comfortably beside you and turn your head to the left."]},"reviewed":false,"summaryMethod":"source-extract"},"Knee_Circles":{"version":1,"steps":{"hu":["Állj zárt lábbal, a kezed legyen a derekadnál.","Most körözz a térdeddel, közben lélegezz normálisan."],"en":["Stand with your legs together and hands by your waist.","Now move your knees in a circular motion as you breathe normally."]},"reviewed":false,"summaryMethod":"source-extract"},"Knee_Hip_Raise_On_Parallel_Bars":{"version":1,"steps":{"hu":["Helyezkedj el a függőleges lábemelő állványon úgy, hogy az alkarod a törzsed melletti párnákon nyugodjon, a kezed pedig a fogantyúkat fogja.","Most fújd ki a levegőt, és emeld fel a lábad nyújtva.","Belégzés közben lassan térj vissza a kiinduló helyzetbe."],"en":["Position your body on the vertical leg raise bench so that your forearms are resting on the pads next to the torso and holding on to the handles.","Now as you breathe out, lift your legs up as you keep them extended.","Slowly go back to the starting position as you breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Knee_Tuck_Jump":{"version":1,"steps":{"hu":["Állj kényelmesen, enyhén hajlított térddel.","Rogyassz be gyorsan negyedguggolásba, majd azonnal robbanj felfelé.","Ugorj olyan magasra, amennyire csak tudsz, a térded felhúzva, majd érkezz biztonságosan: nyújtsd ki újra a lábad, és a térded behajlításával csillapítsd a becsapódást."],"en":["Begin in a comfortable standing position with your knees slightly bent.","Rapidly dip down into a quarter squat and immediately explode upward.","Jump as high as you can, raising your knees up, and then ensure a good land be re-extending your legs, absorbing impact through be allowing the knees to rebend."]},"reviewed":false,"summaryMethod":"source-extract"},"Kneeling_Arm_Drill":{"version":1,"steps":{"hu":["Ez a gyakorlat a futás közbeni karmunka hatékonyságát javítja.","Amint a kezed elhalad a csípőd mellett, a sprintmozdulat közben gyorsítsd előre, hogy a lehető leggyorsabban mozogjon.","Cserélj térdet, és ismételd."],"en":["This drill helps increase arm efficiency during the run.","As soon as your hands pass the hip, accelerate them forward during the sprinting motion to move them as quickly as possible.","Switch knees and repeat."]},"reviewed":false,"summaryMethod":"source-extract"},"Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists":{"version":1,"steps":{"hu":["Csatlakoztass kötelet a felső csigához, és tegyél elé egy matracot a talajra.","A kezed tartsd ugyanott, feszítsd meg a hasizmod, és hasprés-mozdulattal húzd lefelé a kötelet, amíg a könyököd el nem éri a térded.","Folytasd ezt a mozdulatsort kifáradásig."],"en":["Connect a rope attachment to a high pulley cable and position a mat on the floor in front of it.","Keep your hands in the same place, contract your abs and pull downward on the rope in a crunching movement until your elbows reach your knees.","Continue this series of movements to failure."]},"reviewed":false,"summaryMethod":"source-extract"},"Kneeling_Cable_Triceps_Extension":{"version":1,"steps":{"hu":["Állíts egy padot keresztben a felső csigás gép elé.","Tedd a fejed és a felkarod hátsó részét a padra.","Belégzés közben lassan térj vissza a kiinduló helyzetbe."],"en":["Place a bench sideways in front of a high pulley machine.","Place your head and the back of your upper arms on the bench.","Slowly return to the starting position as you breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Kneeling_Forearm_Stretch":{"version":1,"steps":{"hu":["Térdelj egy matracra, a tenyered tedd le laposan úgy, hogy az ujjaid hátrafelé, a térded felé mutassanak.","Lassan dőlj hátra, a tenyered maradjon laposan a talajon, amíg nyújtást nem érzel a csuklódban és az alkarodban."],"en":["Start by kneeling on a mat with your palms flat and your fingers pointing back toward your knees.","Slowly lean back keeping your palms flat on the floor until you feel a stretch in your wrists and forearms."]},"reviewed":false,"summaryMethod":"source-extract"},"Kneeling_High_Pulley_Row":{"version":1,"steps":{"hu":["Válaszd ki a megfelelő súlyt egy olyan csigán, amely a fejed fölött van.","Indítsd a mozdulatot a könyököd hajlításával és a vállad teljes hátrahúzásával: húzd a kötelet a mellkasod felső része felé, a könyököd kifelé nézzen.","Rövid szünet után lassan térj vissza a kiinduló helyzetbe."],"en":["Select the appropriate weight using a pulley that is above your head.","Initiate the movement by flexing the elbows and fully retracting your shoulders, pulling the rope toward your upper chest with your elbows out.","After pausing briefly, slowly return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Kneeling_Hip_Flexor":{"version":1,"steps":{"hu":["Térdelj egy matracra, és emeld fel a jobb térded úgy, hogy a talpad a talajra kerüljön, a bal lábad pedig nyújtsd hátra úgy, hogy a lábfejed felső része feküdjön a talajon.","Helyezd előre a testsúlyod, amíg nyújtást nem érzel a csípődben."],"en":["Kneel on a mat and bring your right knee up so the bottom of your foot is on the floor and extend your left leg out behind you so the top of your foot is on the floor.","Shift your weight forward until you feel a stretch in your hip."]},"reviewed":false,"summaryMethod":"source-extract"},"Kneeling_Jump_Squat":{"version":1,"steps":{"hu":["Kezdd a talajon térdelve, a rúddal a vállad hátsó részén; a gyakorlatot saját testsúllyal is végezheted.","Robbanj fel a csípődből, és fejts ki akkora erőt, hogy teli talppal a talajra érkezz.","Folytasd a guggolással: a sarkadból tolva magad és a térded kinyújtva állj fel."],"en":["Begin kneeling on the floor with a barbell racked across the back of your shoulders, or you can use your body weight for this exercise.","Explode up with your hips, generating enough power to land with your feet flat on the floor.","Continue with the squat by driving through your heels and extending the knees to come to a standing position."]},"reviewed":false,"summaryMethod":"source-extract"},"Kneeling_Single-Arm_High_Pulley_Row":{"version":1,"steps":{"hu":["Csatlakoztass egy egykezes fogantyút a felső csigához, és állítsd be a súlyt.","Előre néző tenyérrel indulva húzd le a súlyt a törzsedhez a könyököd hajlításával és a lapockád hátrahúzásával.","Rövid szünet után térj vissza a kiinduló helyzetbe."],"en":["Attach a single handle to a high pulley and make your weight selection.","Starting with your palm facing forward, pull the weight down to your torso by flexing the elbow and retract the shoulder blade.","After a brief pause, return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Kneeling_Squat":{"version":1,"steps":{"hu":["Állítsd a rudat megfelelő magasságba az erőkeretben.","Előre nézve ülj hátra a fenekeddel, amíg a vádlidhoz nem érsz.","Fordítsd meg a mozdulatot, és emeld vissza a törzsed függőleges helyzetbe."],"en":["Set the bar to the proper height in a power rack.","With your head looking forward, sit back with your butt until you touch your calves.","Reverse the motion, returning the torso to an upright position."]},"reviewed":false,"summaryMethod":"source-extract"},"Landmine_180s":{"version":1,"steps":{"hu":["Helyezd a rudat landmine-talpba, vagy rögzítsd biztonságosan egy sarokban.","A törzsed és a csípőd elfordításával lendítsd a súlyt egészen le az egyik oldalra.","Folytasd váltakozva, amíg a sorozat véget nem ér."],"en":["Position a bar into a landmine or securely anchor it in a corner.","Perform the movement by rotating the trunk and hips as you swing the weight all the way down to one side.","Continue alternating the movement until the set is complete."]},"reviewed":false,"summaryMethod":"source-extract"},"Landmine_Linear_Jammer":{"version":1,"steps":{"hu":["Helyezd a rudat landmine-talpba, vagy ha nincs, rögzítsd biztonságosan egy sarokban.","Atlétikus alapállásban guggolj le: hajlíts csípőből, és told hátra a csípőd, a karod maradjon hajlítva.","Térj vissza a kiinduló helyzetbe."],"en":["Position a bar into landmine or, lacking one, securely anchor it in a corner.","In an athletic stance, squat by flexing your hips and setting your hips back, keeping your arms flexed.","Return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Lateral_Bound":{"version":1,"steps":{"hu":["Vegyél fel félguggolást úgy, hogy 90 fokban állsz a haladási irányhoz képest.","Azonnal rugaszkodj el és nyújtózz ki, és próbálj minél messzebbre szökkenni oldalra.","Folytasd oda-vissza több ismétlésen át."],"en":["Assume a half squat position facing 90 degrees from your direction of travel.","Immediately push off and extend, attempting to bound to the side as far as possible.","Continue back and forth for several repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Lateral_Box_Jump":{"version":1,"steps":{"hu":["Állj kényelmesen úgy, hogy egy alacsony doboz legyen melletted.","Húzd fel a térded elég magasra ahhoz, hogy a lábfejed biztosan átérjen a doboz pereme fölött.","Óvatosan ugorj le a doboz másik oldalára, és folytasd oda-vissza több ismétlésen át."],"en":["Assume a comfortable standing position, with a short box positioned next to you.","Bring your knees high enough to ensure your feet have good clearance over the box.","Carefully jump down to the other side of the box, and continue going back and forth for several repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Lateral_Cone_Hops":{"version":1,"steps":{"hu":["Állíts fel sorban néhány bóját, egymástól kb.","Kezdd az ugrást térdrogyasztással, hogy kiváltsd a nyújtási reflexet, majd azonnal válts irányt, rugaszkodj el a talajról, és ugorj fel oldalra, át a bója fölött.","Érkezéskor a lábaddal csillapítsd a becsapódást, és rögtön pattanj tovább a következő ugrásba; így haladj végig a bójasoron."],"en":["Position a number of cones in a row several feet apart.","Begin the jump by dipping with the knees to initiate a stretch reflex, and immediately reverse direction to push off the ground, jumping up and sideways over the cone.","Use your legs to absorb impact upon landing, and rebound into the next jump, continuing down the row of cones."]},"reviewed":false,"summaryMethod":"source-extract"},"Lateral_Raise_-_With_Bands":{"version":1,"steps":{"hu":["Kezdésként állj rá a gumiszalagra úgy, hogy nyújtott karnál már feszüljön.","Kilégzés közben a vállad oldalsó részével emeld a fogantyúkat oldalra.","Engedd vissza lassan a fogantyúkat a kiinduló helyzetbe."],"en":["To begin, stand on an exercise band so that tension begins at arm's length.","Use your side shoulders to lift the handles to the sides as you exhale.","Lower the handles back down slowly to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Latissimus_Dorsi-SMR":{"version":1,"steps":{"hu":["A talajon fekve tegyél egy hengert a hátad alá, az egyik oldalra, közvetlenül a hónaljad mögé.","A kezelt oldali karod tartsd magad mögött, oldalt, miközben a testsúlyod a széles hátizmodra helyezed; a felsőtested ne érjen a talajhoz."],"en":["While lying on the floor, place a foam roll under your back and to one side, just behind your arm pit.","Keep the arm of the side being stretched behind and to the side of you as you shift your weight onto your lats, keeping your upper body off of the ground."]},"reviewed":false,"summaryMethod":"source-extract"},"Leg-Over_Floor_Press":{"version":1,"steps":{"hu":["Feküdj a talajra, egy kettlebell legyen a mellkasodon, a fogantyújánál fogva.","Nyomd ki a kettlebellt teljesen nyújtott karig.","Engedd le a súlyt, amíg a könyököd a talajhoz nem ér; a kettlebell maradjon a könyököd fölött."],"en":["Lie on the floor with one kettlebell in place on your chest, holding it by the handle.","Press the kettlebll into a locked out position.","Lower the weight until the elbow touches the ground, keeping the kettlebell above the elbow."]},"reviewed":false,"summaryMethod":"source-extract"},"Leg-Up_Hamstring_Stretch":{"version":1,"steps":{"hu":["Feküdj hanyatt, hajlítsd be az egyik térded, és tedd a talpad a talajra, hogy stabilizáld a gerinced.","A másik lábad nyújtsd a levegőbe.","Lassan nyújtsd ki a lábad, amennyire csak lehet, majd húzd az orrod felé."],"en":["Lie flat on your back, bend one knee, and put that foot flat on the floor to stabilize your spine.","Extend the other leg in the air.","Slowly straighten the legs as much as possible and then pull the leg toward your nose."]},"reviewed":false,"summaryMethod":"source-extract"},"Leg_Extensions":{"version":1,"steps":{"hu":["Ülj be; térded a gép forgáspontjánál, a henger az alsó lábszáradon legyen.","Nyújtsd a térded, emeld fel a hengert.","Ne lendíts; lassan engedd vissza."],"en":["Sit with your knees aligned to the pivot and the roller on your lower legs.","Straighten your knees to lift the roller.","Avoid swinging; lower slowly."]},"reviewed":true,"summaryMethod":"curated"},"Leg_Lift":{"version":1,"steps":{"hu":["Állj stabilan, kapaszkodj meg egy támaszban.","Hajlítsd az egyik térded, emeld a lábfejed hátra.","Csípőd maradjon stabil; lassan tedd vissza a lábad."],"en":["Stand steady and hold a support.","Bend one knee to lift your foot behind you.","Keep your hips steady; return your foot slowly."]},"reviewed":true,"summaryMethod":"curated"},"Leg_Press":{"version":1,"steps":{"hu":["Támaszd a hátad és medencéd a géphez. Talpad teljesen legyen a lapon.","Engedd közel a térded a törzsedhez a kontrollált tartományban.","Nyomd el a lapot; medencéd ne billenjen el a támasztól."],"en":["Support your back and pelvis, feet fully on the platform.","Lower through a controlled range, bringing your knees toward your torso.","Press the platform away without lifting your pelvis from the support."]},"reviewed":true,"summaryMethod":"curated"},"Leg_Pull-In":{"version":1,"steps":{"hu":["Feküdj egy tornamatracra nyújtott lábbal, a kezed pedig tenyérrel lefelé legyen melletted vagy a farizmod alatt.","Hajlítsd be a térded, és húzd a combod a törzsed felé, közben fújd ki a levegőt.","Belégzés közben térj vissza a kiinduló helyzetbe."],"en":["Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes.","Bend your knees and pull your upper thighs into your midsection as you breathe out.","Return to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Leverage_Chest_Press":{"version":1,"steps":{"hu":["Tegyél megfelelő súlyt a tárcsatartó tüskékre, és állítsd az ülést a magasságodhoz.","A könyököd kinyújtásával nyomd előre a fogantyúkat.","A felső ponton tartott rövid szünet után engedd vissza a súlyt közvetlenül a kiinduló helyzet fölé, és tartsd feszesen az izmokat azzal, hogy a sorozat végéig nem engeded vissza a súlyt az ütközőkre."],"en":["Load an appropriate weight onto the pins and adjust the seat for your height.","Press the handles forward by extending through the elbow.","After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."]},"reviewed":false,"summaryMethod":"source-extract"},"Leverage_Deadlift":{"version":1,"steps":{"hu":["Tegyél megfelelő súlyt a tárcsatartó tüskékre.","Engedd vissza a súlyt a kiinduló helyzetbe."],"en":["Load the pins to an appropriate weight.","Return the weight to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Leverage_Decline_Chest_Press":{"version":1,"steps":{"hu":["Tegyél megfelelő súlyt a tárcsatartó tüskékre, és állítsd az ülést a magasságodhoz.","A könyököd kinyújtásával nyomd előre a fogantyúkat.","A felső ponton tartott rövid szünet után engedd vissza a súlyt közvetlenül a kiinduló helyzet fölé, és tartsd feszesen az izmokat azzal, hogy a sorozat végéig nem engeded vissza a súlyt az ütközőkre."],"en":["Load an appropriate weight onto the pins and adjust the seat for your height.","Press the handles forward by extending through the elbow.","After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."]},"reviewed":false,"summaryMethod":"source-extract"},"Leverage_High_Row":{"version":1,"steps":{"hu":["Tegyél megfelelő súlyt a tárcsatartó tüskékre, és állítsd be az ülés magasságát úgy, hogy éppen elérd a fölötted lévő fogantyúkat.","A mozdulat végpontján tarts szünetet, majd lassan engedd vissza a fogantyúkat a kiinduló helyzetbe.","Több ismétlésnél ne engedd vissza teljesen a súlyt az ütközőkre, hogy a dolgozó izmok feszesek maradjanak."],"en":["Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you.","Pause at the bottom of the motion, and then slowly return the handles to the starting position.","For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."]},"reviewed":false,"summaryMethod":"source-extract"},"Leverage_Incline_Chest_Press":{"version":1,"steps":{"hu":["Tegyél megfelelő súlyt a tárcsatartó tüskékre, és állítsd az ülést a magasságodhoz.","A könyököd kinyújtásával nyomd előre a fogantyúkat.","A felső ponton tartott rövid szünet után engedd vissza a súlyt közvetlenül a kiinduló helyzet fölé, és tartsd feszesen az izmokat azzal, hogy a sorozat végéig nem engeded vissza a súlyt az ütközőkre."],"en":["Load an appropriate weight onto the pins and adjust the seat for your height.","Press the handles forward by extending through the elbow.","After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."]},"reviewed":false,"summaryMethod":"source-extract"},"Leverage_Iso_Row":{"version":1,"steps":{"hu":["Állítsd az ülést úgy, hogy a fogantyúk mellmagasságban legyenek. Fogd meg őket.","Könyöködet hátravezetve húzd a fogantyúkat a törzsedhez.","Ne hintázz; lassan engedd vissza a karokat."],"en":["Adjust the seat so the handles are at chest height and hold them.","Drive your elbows back to row the handles toward your torso.","Avoid rocking; return the handles slowly."]},"reviewed":true,"summaryMethod":"curated"},"Leverage_Shoulder_Press":{"version":1,"steps":{"hu":["Tegyél megfelelő súlyt a tárcsatartó tüskékre, és állítsd az ülést a magasságodhoz.","A könyököd kinyújtásával nyomd felfelé a fogantyúkat.","A felső ponton tartott rövid szünet után engedd vissza a súlyt közvetlenül a kiinduló helyzet fölé, és tartsd feszesen az izmokat azzal, hogy a sorozat végéig nem engeded vissza a súlyt az ütközőkre."],"en":["Load an appropriate weight onto the pins and adjust the seat for your height.","Press the handles upward by extending through the elbow.","After a brief pause at the top, return the weight to just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."]},"reviewed":false,"summaryMethod":"source-extract"},"Leverage_Shrug":{"version":1,"steps":{"hu":["Tegyél megfelelő súlyt a tárcsatartó tüskékre.","A sarkaddal a talajt tolva nyújtsd ki a csípőd és a térded, és állj fel.","A mozdulat tetején tarts szünetet, majd engedd vissza a súlyt a kiinduló helyzetbe."],"en":["Load the pins to an appropriate weight.","Drive through the floor with your heels, extending your hips and knees as you rise to a standing position.","Pause at the top of the motion, and then return the weight to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Linear_3-Part_Start_Technique":{"version":1,"steps":{"hu":["Ez a gyakorlat abban segít, hogy álló helyzetből a lehető leggyorsabban gyorsíts fel sprintbe.","Guggolj le, miközben előredőlsz: a fejed legyen lejjebb, mint a csípőd, a testsúlyod pedig a bal lábadra terhelődjön.","Emeld a bal kezed úgy, hogy párhuzamos legyen a talajjal és hátrafelé mutasson, majd amikor készen állsz, robbanj ki."],"en":["This drill helps you accelerate as quickly as possible into a sprint from a dead stop.","Squat down as you lean foward, your head being lower than your hips and your weight loaded onto the left leg.","Take your left hand up so that it is parallel to the ground, pointing behind you, and explode out when ready."]},"reviewed":false,"summaryMethod":"source-extract"},"Linear_Acceleration_Wall_Drill":{"version":1,"steps":{"hu":["Dőlj kb.","Kezdésként emeld fel gyorsan a jobb térded, tarts szünetet, majd csapd egyenesen le a talajra.","Válts lábat: emeld a másik térded, majd azzal is támadd egyenesen lefelé a talajt."],"en":["Lean at around 45 degrees against a wall.","Begin by lifting your right knee quickly, pausing, and then driving it straight down into the ground.","Switch legs, raising the opposite knee, and then attacking the ground straight down."]},"reviewed":false,"summaryMethod":"source-extract"},"Linear_Depth_Jump":{"version":1,"steps":{"hu":["Két dobozra vagy padra lesz szükséged, egymástól kb.","Fordítsd meg a mozdulatot robbanékonyan: nyújtsd ki a csípőd, a térded és a bokád, és ugorj fel a másik emelvényre.","Érkezz puhán, a lábaddal csillapítva a becsapódást."],"en":["You will need two boxes or benches spaced a few feet away from each other.","Reverse the motion by exploding, extending through the hips, knees, and ankles to jump onto the other platform.","Land softly, asborbing the impact through the legs."]},"reviewed":false,"summaryMethod":"source-extract"},"Log_Lift":{"version":1,"steps":{"hu":["Állj úgy, hogy a rönk előtted legyen.","Told hátra a fejed, és nézz felfelé, így polcot képezel a mellkasodon, amelyen a rönk megpihenhet."],"en":["Begin standing with the log in front of you.","Push your head back and look up, creating a shelf on your chest to rest the log."]},"reviewed":false,"summaryMethod":"source-extract"},"London_Bridges":{"version":1,"steps":{"hu":["Rögzíts egy mászókötelet egy magas gerendához vagy kereszttartóhoz.","A tested egyenesen tartva dőlj hátra, és engedd le magad úgy, hogy lassan, kézről kézre haladsz a kötélen.","A tested egyenesen tartva fordítsd meg a mozdulatot, és kézről kézre haladva térj vissza a kiinduló helyzetbe."],"en":["Attach a climbing rope to a high beam or cross member.","Keeping your body straight, lean back and lower your body by slowly going hand over hand with the rope.","Keeping your body straight, reverse the motion, going hand over hand back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Looking_At_Ceiling":{"version":1,"steps":{"hu":["Térdelj a talajra, és fogd meg mindkét kezeddel a sarkad.","Emeld a feneked fel és előre, közben döntsd hátra a fejed, és nézz fel a plafonra, hogy a hátad ívbe hajoljon."],"en":["Kneel on the floor, holding your heels with both hands.","Lift your buttocks up and forward while bringing your head back to look up at the ceiling, to give an arch in your back."]},"reviewed":false,"summaryMethod":"source-extract"},"Low_Cable_Crossover":{"version":1,"steps":{"hu":["A kiinduló helyzethez állítsd a csigákat alsó állásba, válaszd ki az ellenállást, és fogj meg egy-egy fogantyút mindkét kezeddel.","Enyhén hajlított karral húzd a kezed felfelé és a tested középvonala felé.","Rövid szünet után engedd vissza a karod a kiinduló helyzetbe."],"en":["To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand.","With a slight bend in your arms, draw your hands upward and toward the midline of your body.","Return your arms back to the starting position after a brief pause."]},"reviewed":false,"summaryMethod":"source-extract"},"Low_Cable_Triceps_Extension":{"version":1,"steps":{"hu":["Válaszd ki a kívánt súlyt, és feküdj hanyatt egy olyan ülő evezőgép padjára, amelyre kötél van csatlakoztatva.","Állítsd be a könyököd úgy, hogy 90 fokban legyen hajlítva, a felkarod pedig merőleges legyen (90 fokos szögben) a törzsedre.","Belégzés közben lassan térj vissza a kiinduló helyzetbe."],"en":["Select the desired weight and lay down face up on the bench of a seated row machine that has a rope attached to it.","Position your elbows so that they are bent at a 90 degree angle and your upper arms are perpendicular (90 degree angle) to your torso.","As you breathe in slowly return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Low_Pulley_Row_To_Neck":{"version":1,"steps":{"hu":["Ülj le egy alsó csigás evezőgépre, amelyre kötél van csatlakoztatva.","A törzsed mozdulatlanul tartva emeld a könyököd, és kezdd el hajlítani, miközben a kötelet a nyakad felé húzod, és kifújod a levegőt.","A megfeszített helyzetet nagyjából egy másodpercig megtartva lassan térj vissza a kiinduló helyzetbe, közben lélegezz be."],"en":["Sit on a low pulley row machine with a rope attachment.","While keeping your torso stationary, lift your elbows and start bending them as you pull the rope towards your neck while exhaling.","After holding for a second or so at the contracted position, come back slowly to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Lower_Back-SMR":{"version":1,"steps":{"hu":["Ülő helyzetben tegyél egy hengert a derekad alá.","Emeld el a csípőd a talajtól, és dőlj hátra úgy, hogy a súlyod a derekadon legyen."],"en":["In a seated position, place a foam roll under your lower back.","Raise your hips off of the floor and lean back, keeping your weight on your lower back."]},"reviewed":false,"summaryMethod":"source-extract"},"Lower_Back_Curl":{"version":1,"steps":{"hu":["Feküdj hasra, a karod legyen oldalra nyújtva.","A derékizmaid erejével nyújtsd a gerinced, és emeld el a mellkasod a talajtól."],"en":["Lie on your stomach with your arms out to your sides.","Using your lower back muscles, extend your spine lifting your chest off of the ground."]},"reviewed":false,"summaryMethod":"source-extract"},"Lunge_Pass_Through":{"version":1,"steps":{"hu":["Állj egyenes törzzsel, a jobb kezedben egy kettlebell-lel.","Kitörés közben add át a kettlebellt az elöl lévő lábad alatt a másik kezedbe.","A sarkadból tolva magad térj vissza a kiinduló helyzetbe."],"en":["Stand with your torso upright holding a kettlebell in your right hand.","As you lunge, pass the kettlebell under your front leg to your opposite hand.","Pressing through the heel of your foot, return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Lunge_Sprint":{"version":1,"steps":{"hu":["Állítsd a Smith-gép rúdját megfelelő magasságba.","Engedd a hátsó térded majdnem a talajig, közben hajlítsd a térded, és süllyeszd a csípőd.","A leereszkedés alján azonnal válts irányt."],"en":["Adjust a bar in a Smith machine to an appropriate height.","Lower your back knee nearly to the ground, flexing the knees and lowering your hips as you do so.","At the bottom of the descent, immediately reverse direction."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_Bent_Leg_Groin":{"version":1,"steps":{"hu":["Feküdj hanyatt hajlított térddel, a talpaid szorítsd egymáshoz.","Próbáld összezárni a térded, miközben a társad megakadályoz minden elmozdulást.","10–20 másodperc után lazítsd el az izmaid, miközben a társad finoman a talaj felé nyomja a térded."],"en":["Lie on your back with your knees bent and the soles of the feet pressed together.","Attempt to squeeze your knees together, while your partner prevents any movement from occurring.","After 10-20 seconds, relax your muscles as your partner gently pushes your knees towards the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_Cable_Curl":{"version":1,"steps":{"hu":["Fogd meg két kézzel az alsó csigára rögzített egyenes rudat vagy EZ-rudat alsó fogással (tenyér felfelé), vállszéles fogásban.","Nyújtott karral, a könyöködet a testedhez közel tartva hajlítsd be enyhén a karod.","A mozdulat felső pontján tartsd meg egy másodpercig a megfeszítést, majd lassan engedd vissza a kiinduló helyzetbe."],"en":["Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) shoulder-width grip.","With your arms extended and your elbows close to your body slightly bend your arms.","After a second squeeze at the top of the movement, slowly return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_Cambered_Barbell_Row":{"version":1,"steps":{"hu":["Tegyél egy hajlított (cambered) rudat az edzőpad alá.","Fújd ki a levegőt, és húzd fel a rudat úgy, hogy a könyököd a tested közelében marad: a mellkasodhoz, ha a hát felső-középső részét akarod megdolgoztatni, vagy a hasadhoz, ha a széles hátizom a célod.","Tartsd meg fent egy másodpercig, majd lélegezz be, és lassan engedd vissza a kiinduló helyzetbe."],"en":["Place a cambered bar underneath an exercise bench.","As you exhale row the bar up as you keep the elbows close to your body to either your chest, in order to target the upper mid back, or to your stomach if targeting the lats is your goal.","After a second hold at the top, lower back down to the starting position slowly as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_Close-Grip_Bar_Curl_On_High_Pulley":{"version":1,"steps":{"hu":["Állíts egy sík padot a felső csiga vagy a lehúzógép elé.","Most nyújtsd ki a karod egyenesen a vállad fölé.","Lassan engedd vissza a kiinduló helyzetbe."],"en":["Place a flat bench in front of a high pulley or lat pulldown machine.","Now extend your arms straight above your shoulders.","Return to starting position slowly."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head":{"version":1,"steps":{"hu":["Fogj meg egy rudat vagy EZ-rudat felső fogással (tenyér előre), és feküdj hanyatt egy sík padra úgy, hogy a fejed közel legyen a pad végéhez.","Lélegezz be, és a könyököd hajlításával engedd le a rudat, a felkarod közben maradjon mozdulatlan.","Fújd ki a levegőt, és félköríves mozdulattal nyomd vissza a rudat a kiinduló helyzetbe, amíg az alkarod is párhuzamos nem lesz a padlóval."],"en":["While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head close to the end of the bench.","As you inhale, lower the bar by bending at the elbows and while keeping the upper arm stationary.","As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion until the lower arms are also parallel to the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_Close-Grip_Barbell_Triceps_Press_To_Chin":{"version":1,"steps":{"hu":["Fogj meg egy rudat vagy EZ-rudat felső fogással (tenyér előre), és feküdj hanyatt egy sík padra úgy, hogy a fejed lelógjon a pad végéről.","Lélegezz be, és a könyököd hajlításával, félköríves mozdulattal engedd le a rudat; a felkarod maradjon mozdulatlan, a könyököd befelé.","Fújd ki a levegőt, és félköríves mozdulattal nyomd vissza a rudat a kiinduló helyzetbe."],"en":["While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head off the end of the bench.","As you inhale, lower the bar in a semi-circular motion by bending at the elbows and while keeping the upper arm stationary and elbows in.","As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_Crossover":{"version":1,"steps":{"hu":["Feküdj hanyatt, nyújtott lábbal.","Próbáld felemelni a hajlított térded a talajról, miközben a társad megakadályozza a tényleges elmozdulást.","10–20 másodperc után lazítsd el a lábad, a társad pedig finoman nyomja a térded a padló felé."],"en":["Lie on your back with your legs extended.","Attempt to raise the bent knee off of the ground as your partner prevents any actual movement.","After 10-20 seconds, relax the leg as your partner gently presses the knee towards the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_Dumbbell_Tricep_Extension":{"version":1,"steps":{"hu":["Feküdj egy sík padra, és tarts két kézisúlyzót közvetlenül magad előtt.","Lélegezz be, és a felkarodat mozdulatlanul, a könyöködet befelé tartva lassan engedd le a súlyt, amíg a kézisúlyzók a füled közelébe nem kerülnek.","Innen – továbbra is behúzott könyökkel és mozdulatlan felkarral – a tricepszed erejével nyomd vissza a súlyt a kiinduló helyzetbe, közben fújd ki a levegőt."],"en":["Lie on a flat bench while holding two dumbbells directly in front of you.","As you breathe in and you keep the upper arms stationary with the elbows in, slowly lower the weight until the dumbbells are near your ears.","At that point, while keeping the elbows in and the upper arms stationary, use the triceps to bring the weight back up to the starting position as you breathe out."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_Face_Down_Plate_Neck_Resistance":{"version":1,"steps":{"hu":["Feküdj hasra egy sík padra úgy, hogy az egész tested egyenes legyen, és tarts egy súlytárcsát a tarkódon.","A tárcsát biztosan a tarkódon tartva lassan engedd le a fejed (mintha bólintva „igent” mondanál), közben lélegezz be.","Emeld vissza a fejed félköríves mozdulattal a kiinduló helyzetbe, közben fújd ki a levegőt."],"en":["Lie face down with your whole body straight on a flat bench while holding a weight plate behind your head.","While keeping the plate secure on the back of your head slowly lower your head (as in saying \"yes\") as you breathe in.","Raise your head back up to the starting position in a semi-circular motion as you breathe out."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_Face_Up_Plate_Neck_Resistance":{"version":1,"steps":{"hu":["Feküdj hanyatt egy sík padra úgy, hogy az egész tested egyenes legyen, és tarts egy súlytárcsát a homlokodon.","A tárcsát biztosan a homlokodon tartva lassan, félköríves mozdulattal engedd hátra a fejed, közben lélegezz be.","Emeld vissza a fejed félköríves mozdulattal a kiinduló helyzetbe, közben fújd ki a levegőt."],"en":["Lie face up with your whole body straight on a flat bench while holding a weight plate on top of your forehead.","While keeping the plate secure on your forehead slowly lower your head back in a semi-circular motion as you breathe in.","Raise your head back up to the starting position in a semi-circular motion as you breathe out."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_Glute":{"version":1,"steps":{"hu":["Feküdj hanyatt, a társad térdeljen melléd.","Próbáld a lábad a társad felé nyomni, ő pedig akadályozza meg, hogy a láb ténylegesen elmozduljon.","10–20 másodperc után lazíts el teljesen, a társad pedig finoman tolja a bokád és a térded a mellkasod felé."],"en":["Lie on your back with your partner kneeling beside you.","Attempt to push your leg towards your partner, who should be preventing any actual movement of the leg.","After 10-20 seconds, completely relax as your partner gently pushes the ankle and knee towards your chest."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_Hamstring":{"version":1,"steps":{"hu":["Feküdj hanyatt, nyújtott lábbal.","Miközben a társad a helyén tartja a lábad, próbáld behajlítani a térded, és feszítsd meg a combhajlítódat 10–20 másodpercig.","Ezután lazítsd el a lábad, és hagyd, hogy a társad finoman a fejed felé tolja."],"en":["Lie on your back with your legs extended.","With your partner holding your leg in place, attempt to flex the knee, contracting the hamstrings for 10-20 seconds.","Then relax your leg, allowing your partner to gently push the leg towards your head."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_High_Bench_Barbell_Curl":{"version":1,"steps":{"hu":["Feküdj hasra egy magas sík padra, és fogj egy rudat alsó fogással (tenyér felfelé).","A könyöködet befelé, a felkarodat mozdulatlanul tartva húzd fel a súlyt félköríves mozdulattal, közben feszítsd meg a bicepszed, és fújd ki a levegőt.","Lélegezz be, és lassan engedd vissza a kiinduló helyzetbe."],"en":["Lie face forward on a tall flat bench while holding a barbell with a supinated grip (palms facing up).","While keeping the elbows in and the upper arms stationary, curl the weight up in a semi-circular motion as you contract the biceps and exhale.","As you inhale, slowly go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_Leg_Curls":{"version":1,"steps":{"hu":["Feküdj hasra; a henger az alsó lábszáradon legyen.","Hajlítsd a térded, közelítsd a sarkad a faradhoz.","Csípőd maradjon lent; lassan engedd vissza."],"en":["Lie face down with the roller on your lower legs.","Bend your knees, bringing your heels toward your hips.","Keep your hips down; lower slowly."]},"reviewed":true,"summaryMethod":"curated"},"Lying_Machine_Squat":{"version":1,"steps":{"hu":["Állítsd be a gépet olyan magasságra, hogy hajlított térddel, a párhuzamosnál kicsit mélyebben lévő combbal be tudj helyezkedni.","Tedd a kezed a fogantyúkra, a lábad pedig vállszélességben, enyhén kifelé forduló lábfejjel helyezd el.","Lélegezz be, és lassan guggolj le, de ne menj le egészen a kiinduló helyzetig: állj meg, amikor a combod párhuzamos a talplemezzel."],"en":["Adjust the leg machine to a height that will allow you to get inside it with your knees bent and the thighs slightly below parallel.","Place your hands by the handles and position your feet slightly pointing out at a shoulder width position.","Slowly squat down as you inhale but instead of going all the way down to the starting position, just stop once your thighs are parallel to the platform."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_One-Arm_Lateral_Raise":{"version":1,"steps":{"hu":["Fogj egy kézisúlyzót az egyik kezedbe, és feküdj mellkassal lefelé egy sík padra.","Most fújd ki a levegőt, és emeld a súlyzót tartó karod oldalra, amíg a könyököd vállmagasságba nem kerül, és a karod nagyjából párhuzamos nem lesz a padlóval.","Lélegezz be, és lassan engedd vissza a kézisúlyzót a kiinduló helyzetbe."],"en":["While holding a dumbbell in one hand, lay with your chest down on a flat bench.","Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale.","Slowly lower the dumbbell to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_Prone_Quadriceps":{"version":1,"steps":{"hu":["Feküdj hasra a padlón, a társad térdeljen melléd.","10–20 másodperc után lazítsd el az izmaidat, a társad pedig finoman tolja a lábfejed a farizmod felé, így tovább nyújtva a combfeszítőt és a csípőhajlítót.","10–20 másodperc után cserélj oldalt."],"en":["Lay face down on the floor with your partner kneeling beside you.","After 10-20 seconds, relax your muscles as your partner gently pushes the foot towards your glutes, further stretching the quadriceps and hip flexors.","After 10-20 seconds, switch sides."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_Rear_Delt_Raise":{"version":1,"steps":{"hu":["Fogj mindkét kezedbe egy-egy kézisúlyzót, és feküdj mellkassal lefelé egy sík padra.","Most fújd ki a levegőt, és emeld a karod oldalra, amíg a könyököd vállmagasságba nem kerül, és a karod nagyjából párhuzamos nem lesz a padlóval.","Lélegezz be, és lassan engedd vissza a kézisúlyzókat a kiinduló helyzetbe."],"en":["While holding a dumbbell in each hand, lay with your chest down on a flat bench.","Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale.","Slowly lower the dumbbells to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_Supine_Dumbbell_Curl":{"version":1,"steps":{"hu":["Feküdj hanyatt egy sík padra, mindkét kezedben egy-egy kézisúlyzóval, amelyeket a combodon tartasz.","A karodat a törzsed közelében, a könyöködet befelé tartva lassan engedd le a karod (nyújtva, enyhén hajlított könyökkel) a padló felé, amilyen mélyre csak tudod.","Nagyon lassan engedd vissza a kiinduló helyzetbe."],"en":["Lie down on a flat bench face up while holding a dumbbell in each arm on top of your thighs.","While keeping the arms close to your torso and elbows in, slowly lower your arms (as you keep them extended with a slight bend at the elbows) as far down towards the floor as you can go.","Return back to the starting position very slowly."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_T-Bar_Row":{"version":1,"steps":{"hu":["Pakold fel a T-rudas evezőgépre a kívánt súlyt, és állítsd be a lábtámasz magasságát úgy, hogy a mellkasod felső része a párna tetejénél legyen.","Emeld ki a rudat a tartóból, és nyújtsd ki magad előtt a karod.","A felső ponton tartsd meg egy másodpercig a megfeszítést, majd lélegezz be, és lassan engedd vissza a kiinduló helyzetbe."],"en":["Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad.","Lift the bar off the rack and extend your arms in front of you.","After a second contraction at the top of the movement, as you inhale, slowly go back down to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Lying_Triceps_Press":{"version":1,"steps":{"hu":["Feküdj egy sík padra; a fejed mögött a padlón legyen egy EZ-rúd (én ezt ajánlom) vagy egy egyenes rúd, a talpad pedig legyen a padlón.","Lélegezz be, és lassan engedd le a súlyt, amíg a rúd finoman a homlokodhoz nem ér; a felkarod és a könyököd közben maradjon mozdulatlan.","Innen a tricepszed erejével nyomd vissza a súlyt a kiinduló helyzetbe, közben fújd ki a levegőt."],"en":["Lie on a flat bench with either an e-z bar (my preference) or a straight bar placed on the floor behind your head and your feet on the floor.","As you breathe in, slowly lower the weight until the bar lightly touches your forehead while keeping the upper arms and elbows stationary.","At that point, use the triceps to bring the weight back up to the starting position as you breathe out."]},"reviewed":false,"summaryMethod":"source-extract"},"Machine_Bench_Press":{"version":1,"steps":{"hu":["Ülj be a mellnyomó gépbe, és válaszd ki a súlyt.","Most lélegezz be, és engedd vissza a fogantyúkat magad felé.","Ha végeztél, lépj rá újra a lábkarra, és lassan engedd vissza a fogantyúkat az eredeti helyükre."],"en":["Sit down on the Chest Press Machine and select the weight.","Now bring the handles back towards you as you breathe in.","When finished step on the lever again and slowly get the handles back to their original place."]},"reviewed":false,"summaryMethod":"source-extract"},"Machine_Bicep_Curl":{"version":1,"steps":{"hu":["Állítsd az ülést a megfelelő magasságba, és válaszd ki a súlyt.","A mozdulat felső pontján tarts egy rövid szünetet, majd lassan engedd vissza a súlyt a kiinduló helyzetbe.","Amíg a sorozat tart, ne engedd vissza a súlyt egészen az ütközőig, hogy a dolgozó izmok végig feszülés alatt maradjanak."],"en":["Adjust the seat to the appropriate height and make your weight selection.","Pause at the top of the movement, and then slowly return the weight to the starting position.","Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked."]},"reviewed":false,"summaryMethod":"source-extract"},"Machine_Preacher_Curls":{"version":1,"steps":{"hu":["Ülj be a Scott-bicepszgépbe, és válaszd ki a súlyt.","Most fújd ki a levegőt, és emeld fel a fogantyúkat, közben feszítsd meg a bicepszed.","Lélegezz be, és lassan engedd vissza a fogantyúkat a kiinduló helyzetbe."],"en":["Sit down on the Preacher Curl Machine and select the weight.","Now lift the handles as you exhale and you contract the biceps.","Lower the handles slowly back to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Machine_Shoulder_Military_Press":{"version":1,"steps":{"hu":["Ülj be a vállnyomó gépbe, és válaszd ki a súlyt.","Most fújd ki a levegőt, és nyomd fel a fogantyúkat, amíg a karod teljesen ki nem nyúlik.","Lélegezz be, és lassan engedd vissza a fogantyúkat a kiinduló helyzetbe."],"en":["Sit down on the Shoulder Press Machine and select the weight.","Now lift the handles as you exhale and you extend the arms fully.","Lower the handles slowly back to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Machine_Triceps_Extension":{"version":1,"steps":{"hu":["Állítsd az ülést a megfelelő magasságba, és válaszd ki a súlyt.","A mozdulat végpontján tarts egy rövid szünetet, majd lassan engedd vissza a súlyt a kiinduló helyzetbe.","Amíg a sorozat tart, ne engedd vissza a súlyt egészen az ütközőig, hogy a dolgozó izmok végig feszülés alatt maradjanak."],"en":["Adjust the seat to the appropriate height and make your weight selection.","Pause at the completion of the movement, and then slowly return the weight to the starting position.","Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked."]},"reviewed":false,"summaryMethod":"source-extract"},"Medicine_Ball_Chest_Pass":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz társra lesz szükséged.","Húzd a labdát a mellkasodhoz, majd fordítsd meg a mozdulatot, és a könyököd kinyújtásával dobd el.","Két kézzel, mellmagasságban kapd el a labdát."],"en":["You will need a partner for this exercise.","Pull the ball to your chest, and reverse the motion by extending through the elbows.","Receive the throw with both hands at chest height."]},"reviewed":false,"summaryMethod":"source-extract"},"Medicine_Ball_Full_Twist":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz egy medicinlabdára és egy társra lesz szükséged.","A teljes forduláshoz a társaddal ugyanabba az irányba forduljatok, például az óramutató járásával ellentétesen.","Add át a labdát a társadnak, majd mindketten forduljatok az ellenkező irányba, és ismételjétek meg a folyamatot."],"en":["For this exercise you will need a medicine ball and a partner.","For full rotation, you and your partner should twist in the same direction, i.e.","Pass the ball to your partner, and both of you can now twist in the opposite direction to repeat the procedure."]},"reviewed":false,"summaryMethod":"source-extract"},"Medicine_Ball_Scoop_Throw":{"version":1,"steps":{"hu":["Vegyél fel félguggolást, medicinlabdával a kezedben.","Indításként told előre erőteljesen a csípőd, közben nyújtsd ki a lábad, és ugorj fel.","Közben lendítsd a karod nyújtva fel, a fejed fölé, és a mozdulat csúcspontján engedd el a labdát."],"en":["Assume a semisquat stance with a medicine ball in your hands.","Begin by thrusting the hips forward as you extend through the legs, jumping up.","As you do, swing your arms up and over your head, keeping them extended, releasing the ball at the peak of your movement."]},"reviewed":false,"summaryMethod":"source-extract"},"Middle_Back_Shrug":{"version":1,"steps":{"hu":["Feküdj hasra egy ferde padra, mindkét kezedben egy-egy kézisúlyzóval.","Fújd ki a levegőt, zárd össze a lapockáidat, és tartsd meg a megfeszítést egy teljes másodpercig.","Lélegezz be, és térj vissza a kiinduló helyzetbe."],"en":["Lie facedown on an incline bench while holding a dumbbell in each hand.","As you exhale, squeeze your shoulder blades together and hold the contraction for a full second.","As you inhale go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Middle_Back_Stretch":{"version":1,"steps":{"hu":["Állj vállszéles terpeszbe, és tedd a kezed a csípődre.","Fordulj el derékból, amíg nyújtást nem érzel."],"en":["Stand so your feet are shoulder width apart and your hands are on your hips.","Twist at your waist until you feel a stretch."]},"reviewed":false,"summaryMethod":"source-extract"},"Mixed_Grip_Chin":{"version":1,"steps":{"hu":["Fogd meg a húzódzkodó rudat a vállszélesnél csak kb.","A felső ponton tartsd meg egy másodpercig a megfeszítést, majd lélegezz be, és kezdj lassan leereszkedni.","A következő sorozatban cserélj fogást: ha eddig a jobb tenyered nézett feléd és a bal előre, akkor a következő sorozatban a jobb tenyered nézzen előre, a bal pedig feléd."],"en":["Using a spacing that is just about 1 inch wider than shoulder width, grab a pull-up bar with the palms of one hand facing forward and the palms of the other hand facing towards you.","After a second contraction at the top, start to slowly come down as you inhale.","On the following set, switch grips; so if you had the right hand with the palms facing you and the left one with the palms facing forward, on the next set you will have the palms facing forward for the right hand and facing you for the left."]},"reviewed":false,"summaryMethod":"source-extract"},"Monster_Walk":{"version":1,"steps":{"hu":["Tegyél egy gumiszalagot mindkét bokád köré, egy másikat pedig mindkét térded köré.","Kezdésként lépkedj előre rövid lépésekkel, felváltva a bal és a jobb lábaddal.","Néhány lépés után csináld fordítva: sétálj hátrafelé oda, ahonnan elindultál."],"en":["Place a band around both ankles and another around both knees.","To begin, take short steps forward alternating your left and right foot.","After several steps, do just the opposite and walk backward to where you started."]},"reviewed":false,"summaryMethod":"source-extract"},"Mountain_Climbers":{"version":1,"steps":{"hu":["Helyezkedj el fekvőtámaszban, a súlyod a tenyereden és a lábujjaidon legyen.","Robbanékonyan cseréld meg a lábaid helyzetét: a hajlított lábad nyújtsd ki, amíg egyenes nem lesz és a lábujjadon támaszkodik, a másik lábad pedig húzd előre hajlított csípővel és térddel."],"en":["Begin in a pushup position, with your weight supported by your hands and toes.","Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed."]},"reviewed":false,"summaryMethod":"source-extract"},"Moving_Claw_Series":{"version":1,"steps":{"hu":["Ez a gyakorlat a futótechnikádat készíti fel, hogy jobb legyél sprintben.","Ahogy a lábad újra előrelendül, feszítsd elő a combfeszítőt, és a következő lépésnél támadd a talajt.","Futás közben ügyelj a karmunkára is: gyors, egy-kettő ritmusú, ütésszerű mozdulattal lendítsd át a karod."],"en":["This move helps prepare your running form to help you excel at sprinting.","Reload the quad as the leg moves back forward, attacking the ground on the next step.","Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion."]},"reviewed":false,"summaryMethod":"source-extract"},"Muscle_Snatch":{"version":1,"steps":{"hu":["Kezdésként tarts egy megpakolt rudat széles fogással a combközép magasságában.","Kezdd a húzást úgy, hogy a sarkad elülső részéről tolod el magad, és emeled a rudat.","Emeld tovább a rudat a fej fölötti helyzetig úgy, hogy a térded közben nem hajlítod be újra."],"en":["Begin with a loaded barbell held at the mid thigh position with a wide grip.","Begin the pull by driving through the front of the heels, raising the bar.","Continue raising the bar to the overhead position, without rebending the knees."]},"reviewed":false,"summaryMethod":"source-extract"},"Muscle_Up":{"version":1,"steps":{"hu":["Fogd meg a gyűrűket hamis fogással (false grip), úgy, hogy a tenyered töve a gyűrűk tetején legyen.","A kontrollt és a stabilitást megőrizve nyújtsd ki a könyököd, és fejezd be a mozdulatot.","Óvatosan ereszkedj vissza a talajra."],"en":["Grip the rings using a false grip, with the base of your palms on top of the rings.","Maintaining control and stability, extend through the elbow to complete the motion.","Use care when lowering yourself to the ground."]},"reviewed":false,"summaryMethod":"source-extract"},"Narrow_Stance_Hack_Squats":{"version":1,"steps":{"hu":["Támaszd a hátad a gép háttámlájának, és akaszd be a vállad a vállpárnák alá.","Most nyújtsd ki a lábad, de ne feszítsd ki teljesen a térded.","Fújd ki a levegőt, és kezdd felfelé tolni a szánt úgy, hogy főként a sarkaddal nyomsz, közben újra kinyújtod a lábad, és visszatérsz a kiinduló helyzetbe."],"en":["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.","Now straighten your legs without locking the knees.","Begin to raise the unit as you exhale by pushing the floor with mainly with the heels of your feet as you straighten the legs again and go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Narrow_Stance_Leg_Press":{"version":1,"steps":{"hu":["Ülj be a lábtoló gépbe, és tedd a lábad közvetlenül magad elé a talplemezre, vállszélesnél szűkebb terpeszben, enyhén kifelé forduló lábujjakkal.","Lélegezz be, és lassan engedd le a talplemezt, amíg a combod és a lábszárad 90 fokos szöget nem zár be.","Főként a sarkaddal nyomva, a combfeszítőd erejével térj vissza a kiinduló helyzetbe, közben fújd ki a levegőt."],"en":["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out.","As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.","Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Narrow_Stance_Squats":{"version":1,"steps":{"hu":["Ezt a gyakorlatot biztonsági okokból guggolóállványban érdemes végezni.","Lépj el az állványtól, és állj vállszélesnél szűkebb terpeszbe, enyhén kifelé forduló lábujjakkal.","Fújd ki a levegőt, és kezdd felfelé nyomni a rudat úgy, hogy főként a sarkaddal tolod el magad a talajtól, közben újra kinyújtod a lábad, és visszatérsz a kiinduló helyzetbe."],"en":["This exercise is best performed inside a squat rack for safety purposes.","Step away from the rack and position your legs using a less-than-shoulder-width narrow stance with the toes slightly pointed out.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Natural_Glute_Ham_Raise":{"version":1,"steps":{"hu":["Használd a lehúzógép lábpárnáját vagy egy Scott-padot: helyezkedj el úgy, hogy a bokád a párnák alatt, a térded az ülésen legyen, és háttal legyél a gépnek.","Továbbra is kontrolláltan emelkedj vissza a kiinduló helyzetbe.","Ha nem tudsz végigcsinálni egy ismétlést, használj gumiszalagot, kérj segítséget egy társtól, vagy lökd el magad egy dobozról, hogy be tudd fejezni az ismétlést."],"en":["Using the leg pad of a lat pulldown machine or a preacher bench, position yourself so that your ankles are under the pads, knees on the seat, and you are facing away from the machine.","Remaining in control, raise yourself back up to the starting position.","If you are unable to complete a rep, use a band, a partner, or push off of a box to aid in completing a repetition."]},"reviewed":false,"summaryMethod":"source-extract"},"Neck-SMR":{"version":1,"steps":{"hu":["Fogj egy masszázsrudat vagy egy sodrófát, és tedd a fejed mögé, a nyakadhoz.","A nyakad tetejétől indulva lassan görgess lefelé a nyakizmokon, a feszes pontokon 10–30 másodpercre megállva."],"en":["Using a muscle roller or a rolling pin, place the roller behind your head and against your neck.","Starting at the top of your neck, slowly roll down the muscles of your neck, pausing at points of tension for 10-30 seconds."]},"reviewed":false,"summaryMethod":"source-extract"},"Neck_Press":{"version":1,"steps":{"hu":["Feküdj hanyatt egy sík padra.","Egy másodperc szünet után fújd ki a levegőt, és a mellizmaid erejével nyomd vissza a rudat a kiinduló helyzetbe.","Ha végeztél, tedd vissza a rudat az állványra."],"en":["Lie back on a flat bench.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles.","When you are done, place the bar back in the rack."]},"reviewed":false,"summaryMethod":"source-extract"},"Oblique_Crunches":{"version":1,"steps":{"hu":["Feküdj hanyatt a padlón, a derekad simuljon a talajra.","Egyszerűen emeld a vállad és a törzsed felfelé, amíg el nem éred a térded.","Folytasd így váltogatva, amíg mindkét oldalra el nem végezted az előírt ismétlésszámot."],"en":["Lie flat on the floor with your lower back pressed to the ground.","Simply elevate your shoulder and body upward until you touch your knee.","Continue alternating in this manner until all of the recommended repetitions for each side have been completed."]},"reviewed":false,"summaryMethod":"source-extract"},"Oblique_Crunches_-_On_The_Floor":{"version":1,"steps":{"hu":["Kezdésként feküdj a jobb oldaladra, a lábaid legyenek egymáson.","Ha felvetted ezt a helyzetet, kezdd el a bal könyöködet felfelé emelni, ahogy egy sima hasprésnél tennéd, csak most a fő hangsúly a ferde hasizmon van.","Ne feledd: a gyakorlat excentrikus (leengedő) szakaszában lélegezz be, a koncentrikus (emelkedő) szakaszában pedig fújd ki a levegőt."],"en":["Start out by lying on your right side with your legs lying on top of each other.","Once you are in this set position, begin by moving your left elbow up as you would perform a normal crunch except this time the main emphasis is on your obliques.","Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (elevation) part of the exercise."]},"reviewed":false,"summaryMethod":"source-extract"},"Olympic_Squat":{"version":1,"steps":{"hu":["Kezdésként a rúd a csuklyás izmod tetején nyugodjon.","Ereszkedj le a térded hajlításával, és amennyire lehet, kerüld a csípő hátratolását.","Abban a pillanatban, amikor a combod a vádlidhoz ér, fordítsd meg a mozdulatot, és told felfelé a súlyt."],"en":["Begin with a barbell supported on top of the traps.","Descend by flexing the knees, refraining from moving the hips back as much as possible.","At the moment the upper legs contact the lower, reverse the motion, driving the weight upward."]},"reviewed":false,"summaryMethod":"source-extract"},"On-Your-Back_Quad_Stretch":{"version":1,"steps":{"hu":["Feküdj egy sík padra vagy sztepp-padra, és az egyik lábad és karod lógasd le oldalt.","Húzd a köldököd a gerinced felé, hogy semleges helyzetben maradj.","Cserélj oldalt."],"en":["Lie on a flat bench or step, and hang one leg and arm over the side.","Pull the belly button to the spine to stay in neutral.","Switch sides."]},"reviewed":false,"summaryMethod":"source-extract"},"On_Your_Side_Quad_Stretch":{"version":1,"steps":{"hu":["Kezdésként feküdj a jobb oldaladra, a jobb térded 90 fokban behajlítva nyugodjon előtted a padlón (ez stabilizálja a törzset).","Hajlítsd hátra a bal térded, és fogd meg a bal lábfejed a bal kezeddel."],"en":["Start off by lying on your right side, with your right knee bent at a 90-degree angle resting on the floor in front of you (this stabilizes the torso).","Bend your left knee behind you and hold your left foot with your left hand."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Dumbbell_Row":{"version":1,"steps":{"hu":["Válassz egy sík padot, és tegyél mindkét oldalára egy-egy kézisúlyzót.","Húzd a súlyt egyenesen fel, a mellkasod oldalához; a felkarod maradjon közel az oldaladhoz, a törzsed pedig mozdulatlan.","Cserélj oldalt, és ismételd meg a másik karoddal."],"en":["Choose a flat bench and place a dumbbell on each side of it.","Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary.","Switch sides and repeat again with the other arm."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Flat_Bench_Dumbbell_Flye":{"version":1,"steps":{"hu":["Feküdj egy sík padra, az egyik kezedben egy kézisúlyzóval, amelyet a combodon nyugtatsz.","Vidd vissza a dolgozó karod a kiinduló helyzetbe, közben feszítsd meg a mellizmod, és fújd ki a levegőt.","Cserélj kart, és ismételd meg a gyakorlatot."],"en":["Lie down on a flat bench with a dumbbell in one hand resting on top of your thigh.","Return your lifting arm back to the starting position as you squeeze your chest muscles and breathe out.","Switch arms and repeat the exercise."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_High-Pulley_Cable_Side_Bends":{"version":1,"steps":{"hu":["Rögzíts egy hagyományos fogantyút a kábeltoronyra.","Állj csípőszéles terpeszbe.","Ezután állj át, és ismételd meg ugyanezt a mozdulatsort a másik oldalon."],"en":["Connect a standard handle to a tower.","Position feet hip-width apart.","Then, reposition and repeat the same series of movements on the opposite side."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Incline_Lateral_Raise":{"version":1,"steps":{"hu":["Feküdj oldalra egy ferde padra, kézisúlyzóval a kezedben.","A kézisúlyzót végig a padlóval párhuzamosan tartva végezz oldalemelést.","Cserélj kart, és ismételd meg a mozdulatot."],"en":["Lie down sideways on an incline bench press with a dumbbell in the hand.","While keeping the dumbbell parallel to the floor at all times, perform a lateral raise.","Switch arms and repeat the movement."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Kettlebell_Clean":{"version":1,"steps":{"hu":["Tegyél egy kettlebellt a két lábfejed közé.","Vedd fel a kettlebellt a válladhoz: nyújtsd ki a lábad és a csípőd, miközben a kettlebellt a vállad felé emeled.","Engedd vissza a súlyt a kiinduló helyzetbe."],"en":["Place a kettlebell between your feet.","Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder.","Return the weight to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Kettlebell_Clean_and_Jerk":{"version":1,"steps":{"hu":["Fogd meg a kettlebellt a fogantyújánál.","Azonnal válts irányt: told el magad a sarkadról, lényegében ugorj fel, hogy lendületet szerezz.","A súlyt a fejed fölött tartva állj fel."],"en":["Hold a kettlebell by the handle.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum.","Keeping the weight overhead, return to a standing position."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Kettlebell_Floor_Press":{"version":1,"steps":{"hu":["Feküdj a padlóra, egyik kezedben egy kettlebell-lel, a felkarod támaszkodjon a padlón.","Nyomd a kettlebellt egyenesen fel, a mennyezet felé, közben fordítsd el a csuklód.","Engedd vissza a kettlebellt a kiinduló helyzetbe, és ismételd."],"en":["Lie on the floor holding a kettlebell with one hand, with your upper arm supported by the floor.","Press the kettlebell straight up toward the ceiling, rotating your wrist.","Lower the kettlebell back to the starting position and repeat."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Kettlebell_Jerk":{"version":1,"steps":{"hu":["Fogd meg a kettlebellt a fogantyújánál.","Azonnal válts irányt: told el magad a sarkadról, lényegében ugorj fel, hogy lendületet szerezz.","Engedd le a súlyt, és jöhet a következő ismétlés."],"en":["Hold a kettlebell by the handle.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum.","Lower the weight to perform the next repetition."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Kettlebell_Military_Press_To_The_Side":{"version":1,"steps":{"hu":["Vegyél fel egy kettlebellt a válladhoz.","Nézz a kettlebellre, és nyomd felfelé és kifelé, amíg a karod teljesen ki nem nyúlik a fejed fölött.","Kontrolláltan engedd vissza a kettlebellt a válladhoz, és ismételd."],"en":["Clean a kettlebell to your shoulder.","Look at the kettlebell and press it up and out until it is locked out overhead.","Lower the kettlebell back to your shoulder under control and repeat."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Kettlebell_Para_Press":{"version":1,"steps":{"hu":["Vegyél fel egy kettlebellt a válladhoz.","Tartsd a kettlebellt oldalra kifelé mutató könyökkel, és nyomd felfelé és kifelé, amíg a karod teljesen ki nem nyúlik a fejed fölött.","Kontrolláltan engedd vissza a kettlebellt a válladhoz, és ismételd."],"en":["Clean a kettlebell to your shoulder.","Hold the kettlebell with the elbow out to the side, and press it up and out until it is locked out overhead.","Lower the kettlebell back to your shoulder under control and repeat."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Kettlebell_Push_Press":{"version":1,"steps":{"hu":["Fogd meg a kettlebellt a fogantyújánál.","Rogyassz a térded hajlításával, a törzsed maradjon függőleges.","Azonnal válts irányt: told el magad a sarkadról, lényegében ugorj fel, hogy lendületet szerezz."],"en":["Hold a kettlebell by the handle.","Dip your body by bending the knees, keeping your torso upright.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Kettlebell_Row":{"version":1,"steps":{"hu":["Tegyél egy kettlebellt a lábfejed elé."],"en":["Place a kettlebell in front of your feet."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Kettlebell_Snatch":{"version":1,"steps":{"hu":["Tegyél egy kettlebellt a két lábfejed közé.","Nézz egyenesen előre, és lendítsd hátra a kettlebellt a lábaid között.","Azonnal válts irányt, és a csípőd és a térded erőteljes kinyújtásával gyorsítsd felfelé a kettlebellt."],"en":["Place a kettlebell between your feet.","Look straight ahead and swing the kettlebell back between your legs.","Immediately reverse the direction and drive through with your hips and knees, accelerating the kettlebell upward."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Kettlebell_Split_Jerk":{"version":1,"steps":{"hu":["Fogd meg a kettlebellt a fogantyújánál.","Azonnal válts irányt: told el magad a sarkadról, lényegében ugorj fel, hogy lendületet szerezz.","A súlyt a fejed fölött tartva állj fel, és zárd össze a lábad."],"en":["Hold a kettlebell by the handle.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum.","Keeping the weight overhead, return to a standing position and bring your feet together."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Kettlebell_Split_Snatch":{"version":1,"steps":{"hu":["Fogj egy kettlebellt az egyik kezedbe a fogantyújánál.","Miután teljesen kinyújtottad a tested, ereszkedj kitörésbe, hogy a fejed fölött fogadd a súlyt – egyik láb elöl, a másik hátul.","Állj fel, a súlyt a fejed fölött tartva, és zárd össze a lábad."],"en":["Hold a kettlebell in one hand by the handle.","After fully extending the body, descend into a lunge position to receive the weights overhead, one leg forward and one leg back.","Return to a standing position, holding the weight overhead, and bring the feet together."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Kettlebell_Swings":{"version":1,"steps":{"hu":["Állj stabilan, fogd a kettlebellt egy kézzel. Csípőből hajolva engedd a lábad közé.","Csípőnyújtással lendítsd előre a súlyt; karod maradjon hosszú.","Ne vállból emeld; a visszalendülést csípőből kövesd."],"en":["Stand steady with a one-handed grip and hinge as the bell swings between your legs.","Extend your hips to swing the bell forward with a long arm.","Do not lift from your shoulder; hinge again as the bell returns."]},"reviewed":true,"summaryMethod":"curated"},"One-Arm_Long_Bar_Row":{"version":1,"steps":{"hu":["Rögzítsd a rúd egyik végét landmine-tartóba vagy egy sarokba, hogy ne mozduljon el.","Vegyél fel hajlított térdű állást, hátratolt csípővel és kiemelt mellkassal.","Rövid szünet után térj vissza a kiinduló helyzetbe."],"en":["Position a bar into a landmine or in a corner to keep it from moving.","Assume a bent-knee stance with your hips back and your chest up.","After a brief pause, return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Medicine_Ball_Slam":{"version":1,"steps":{"hu":["Állj harántterpeszbe, sportos alapállásba.","A nyújtás csúcspontján a vállad, a gerinced és a csípőd hajlításával vágd a labdát erősen a földhöz, közvetlenül magad elé.","Kapd el a visszapattanó labdát, és folytasd a kívánt ismétlésszámig."],"en":["Start in a standing position with a staggered, athletic stance.","At peak extension, flex the shoulders, spine, and hips to throw the ball hard into the ground directly in front of you.","Catch the ball on the bounce and continue for the desired number of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Open_Palm_Kettlebell_Clean":{"version":1,"steps":{"hu":["Tegyél egy kettlebellt a két lábfejed közé.","Dobd ki a kettlebellt magad elé, és kapd el egy kézzel a fogantyúját.","Vidd le a kettlebellt a padlóra, és ismételd."],"en":["Place one kettlebell between your feet.","Throw the kettlebell out in front of you and catch the handle with one hand.","Take the kettlebell to the floor and repeat."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Overhead_Kettlebell_Squats":{"version":1,"steps":{"hu":["Vegyél fel és nyomj ki egy kettlebellt egy kézzel.","Nézz egyenesen előre, tartsd a kettlebellt nyújtott karral a fejed fölött, hajlítsd be a térded és a csípőd, és engedd le a törzsed a lábaid közé; a fejed és a mellkasod maradjon emelve.","Az alsó ponton tarts egy másodperc szünetet, majd a sarkadról eltolva magad emelkedj vissza a felső helyzetbe."],"en":["Clean and press a kettlebell with one arm.","Looking straight ahead and keeping a kettlebell locked out above you, flex the knees and hips and lower your torso between your legs, keeping your head and chest up.","Pause at the bottom position for a second before rising back to the top, driving through the heels of your feet."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Side_Deadlift":{"version":1,"steps":{"hu":["Állj oldalt a rúd mellé, a közepéhez.","Fújd ki a levegőt, és a lábad erejével segítve emeld fel a rudat.","Cserélj kart, és ismételd meg a mozdulatot."],"en":["Stand to the side of a barbell next to its center.","Use your legs to help lift the barbell up while exhaling.","Switch arms and repeat the movement."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Arm_Side_Laterals":{"version":1,"steps":{"hu":["Válassz egy kézisúlyzót, és fogd az egyik kezedbe.","A törzsedet mozdulatlanul tartva (lendítés nélkül) emeld a kézisúlyzót oldalra, enyhén hajlított könyökkel és kissé előrebillentett kézzel, mintha vizet töltenél egy pohárba.","Cserélj kart, és ismételd meg a gyakorlatot."],"en":["Pick a dumbbell and place it in one of your hands.","While maintaining the torso stationary (no swinging), lift the dumbbell to your side with a slight bend on the elbow and your hand slightly tilted forward as if pouring water in a glass.","Switch arms and repeat the exercise."]},"reviewed":false,"summaryMethod":"source-extract"},"One-Legged_Cable_Kickback":{"version":1,"steps":{"hu":["Akassz egy bőr bokapántot az alsó csigára, majd csatold a pántot a bokádra.","A térdedet és a csípődet enyhén hajlítva, a hasadat feszesen tartva feszítsd meg a farizmod, és lassan „rúgd” hátra a dolgozó lábad félköríves ívben, olyan magasra, ameddig kényelmesen megy, közben fújd ki a levegőt.","Cserélj lábat, és ismételd meg a mozdulatot a másik oldalra."],"en":["Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.","While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly \"kick\" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out.","Switch legs and repeat the movement for the other side."]},"reviewed":false,"summaryMethod":"source-extract"},"One_Arm_Against_Wall":{"version":1,"steps":{"hu":["Álló helyzetből támaszd az egyik, behajlított karod egy falnak vagy ajtófélfának.","Lassan dőlj a karod felé, amíg nyújtást nem érzel a széles hátizmodban."],"en":["From a standing position, place a bent arm against a wall or doorway.","Slowly lean toward your arm until you feel a stretch in your lats."]},"reviewed":false,"summaryMethod":"source-extract"},"One_Arm_Chin-Up":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz először vess át egy törölközőt a húzódzkodó rúdon.","Húzd fel a törzsed, amíg a rúd a mellkasod felső részéhez nem ér; ehhez húzd a vállad és a felkarod lefelé és hátra.","Cserélj kart, és ismételd meg a mozdulatot."],"en":["For this exercise, start out by placing a towel around a chin up bar.","Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back.","Switch arms and repeat the movement."]},"reviewed":false,"summaryMethod":"source-extract"},"One_Arm_Dumbbell_Bench_Press":{"version":1,"steps":{"hu":["Feküdj egy sík padra, az egyik kezedben egy kézisúlyzóval, amelyet a combodon tartasz.","Lélegezz be, és lassan engedd le a súlyt az oldaladhoz.","Cserélj kart, és ismételd meg a mozdulatot."],"en":["Lie down on a flat bench with a dumbbell in one hand on top of your thigh.","Bring down the weights slowly to your side as you breathe in.","Switch arms and repeat the movement."]},"reviewed":false,"summaryMethod":"source-extract"},"One_Arm_Dumbbell_Preacher_Curl":{"version":1,"steps":{"hu":["Fogj egy kézisúlyzót a jobb kezedbe, és támaszd a felkarodat a Scott-pad vagy a ferde pad tetejére.","Kilégzés közben a bicepszed erejével hajlítsd fel a súlyt, amíg a bicepszed teljesen meg nem feszül, és a súlyzó vállmagasságba nem kerül.","Válts kart, és ismételd meg a mozdulatot."],"en":["Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench.","As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell is at shoulder height.","Switch arms and repeat the movement."]},"reviewed":false,"summaryMethod":"source-extract"},"One_Arm_Floor_Press":{"version":1,"steps":{"hu":["Feküdj hanyatt sík felületre úgy, hogy a hátad a padlóhoz vagy egy tornaszőnyeghez simuljon.","Kezdd a gyakorlatot azzal, hogy leengeded a rudat, amíg a könyököd a talajhoz nem ér.","Válts kart, és ismételd meg a mozdulatot."],"en":["Lie down on a flat surface with your back pressing against the floor or an exercise mat.","Begin the exercise by lowering the barbell until your elbow touches the ground.","Switch arms and repeat the movement."]},"reviewed":false,"summaryMethod":"source-extract"},"One_Arm_Lat_Pulldown":{"version":1,"steps":{"hu":["Válassz megfelelő súlyt, és állítsd be a térdpárnát úgy, hogy lent tartson.","A mozdulat alján tarts egy pillanatnyi szünetet, majd lassan engedd vissza a fogantyút a kiinduló helyzetbe.","Ha több ismétlést végzel, ne engedd vissza teljesen a súlyt, hogy a dolgozó izmok feszülés alatt maradjanak."],"en":["Select an appropriate weight and adjust the knee pad to help keep you down.","Pause at the bottom of the motion, and then slowly return the handle to the starting position.","For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked."]},"reviewed":false,"summaryMethod":"source-extract"},"One_Arm_Pronated_Dumbbell_Triceps_Extension":{"version":1,"steps":{"hu":["Feküdj hanyatt egy padra, és tarts egy kézisúlyzót nyújtott karral.","Belégzés közben lassan kezdd el leengedni a kézisúlyzót.","Válts kart, és ismételd meg a mozdulatot."],"en":["Lie flat on a bench while holding a dumbbell at arms length.","Slowly begin to lower the dumbbell down as you breathe in.","Switch arms and repeat the movement."]},"reviewed":false,"summaryMethod":"source-extract"},"One_Arm_Supinated_Dumbbell_Triceps_Extension":{"version":1,"steps":{"hu":["Feküdj hanyatt egy padra, és tarts egy kézisúlyzót nyújtott karral.","Ezután a tricepszedet megfeszítve emeld vissza a súlyzót.","Válts ismét kart, és ismételd meg a mozdulatot."],"en":["Lie flat on a bench while holding a dumbbell at arms length.","Then, begin lifting the dumbbell upward as you contract the triceps.","Switch arms again and repeat the movement."]},"reviewed":false,"summaryMethod":"source-extract"},"One_Half_Locust":{"version":1,"steps":{"hu":["Feküdj hasra a padlón.","Hajlítsd be a jobb térdedet, hogy a jobb kezeddel megfoghasd a lábfejedet.","Emeld a lábfejedet a levegőbe, és ezzel egy időben emeld el a válladat a padlóról."],"en":["Lie facedown on the floor.","Bend your right knee so you can hold the foot in your right hand.","Lift the foot in the air and simultaneously lift your shoulders off the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"One_Handed_Hang":{"version":1,"steps":{"hu":["Fogj meg egy húzódzkodó rudat egy kézzel, felső fogással."],"en":["Grab onto a chinup bar with one hand, using a pronated grip."]},"reviewed":false,"summaryMethod":"source-extract"},"One_Knee_To_Chest":{"version":1,"steps":{"hu":["Kezdésként feküdj le a padlóra.","Húzd finoman a térdedet az orrod felé.","Cserélj oldalt."],"en":["Start off by lying on the floor.","Gently tug that knee toward your nose.","Switch sides."]},"reviewed":false,"summaryMethod":"source-extract"},"One_Leg_Barbell_Squat":{"version":1,"steps":{"hu":["Állj kb.","Belégzés közben lassan ereszkedj le, amíg a combod párhuzamos nem lesz a padlóval.","Válts lábat, és ismételd meg a mozdulatot."],"en":["Start by standing about 2 to 3 feet in front of a flat bench with your back facing the bench.","As you inhale, slowly lower your leg until your thigh is parallel to the floor.","Switch legs and repeat the movement."]},"reviewed":false,"summaryMethod":"source-extract"},"Open_Palm_Kettlebell_Clean":{"version":1,"steps":{"hu":["Tegyél egy kettlebellt a két lábfejed közé.","Ahogy a kettlebell felfelé halad, engedd el, és hagyd átfordulni úgy, hogy a golyója a tenyeredbe érkezzen.","Engedd ki magad elé a kettlebellt, és kapd el a fülét mindkét kézzel."],"en":["Place one kettlebell between your feet.","Release the kettlebell as it comes up, and let it flip so that the ball of the kettlebell lands in the palms of your hands.","Release the kettlebell out in front of you and catch the handle with both hands."]},"reviewed":false,"summaryMethod":"source-extract"},"Otis-Up":{"version":1,"steps":{"hu":["Rögzítsd a lábfejedet, és feküdj hanyatt a padlóra.","Felfelé haladva nyomd ki a súlyt úgy, hogy a mozdulat tetején a fejed fölött legyen.","A felülést visszafelé végezve engedd vissza a súlyt a mellkasodhoz, de ügyelj rá, hogy ne ereszkedj le teljesen a padlóig."],"en":["Secure your feet and lay back on the floor.","As you move up, press the weight up so that it is above your head at the top of the movement.","Return the weight to your chest as you reverse the sit-up motion, ensuring not to go all the way down to the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Overhead_Cable_Curl":{"version":1,"steps":{"hu":["Kezdésként állíts be kényelmes súlyt a csigás gép mindkét oldalán.","Állj a két oldal közé középre, és fogd meg a fogantyúkat alsó fogással (a tenyered a mennyezet felé néz).","Belégzés közben vidd vissza az alkarodat a kiinduló helyzetbe."],"en":["To begin, set a weight that is comfortable on each side of the pulley machine.","Stand in the middle of both sides and use an underhand grip (palms facing towards the ceiling) to grab each handle.","While inhaling, move your forearms back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Overhead_Lat":{"version":1,"steps":{"hu":["Ülj egyenes háttal a padlón, az edzőtársad legyen mögötted.","Próbáld a felkarodat az oldaladhoz húzni, miközben a társad megakadályozza, hogy ezt valóban megtedd.","10–20 másodperc után lazítsd el a karodat, és hagyd, hogy a társad a tricepszre gyakorolt enyhe nyomással tovább nyújtsa a széles hátizmodat."],"en":["Sit upright on the floor with your partner behind you.","Attempt to pull your upper arm to your side as your partner prevents you from doing actually doing so.","After 10-20 seconds, relax the arm and allow your partner to further stretch the lat by applying gentle pressure to the tricep."]},"reviewed":false,"summaryMethod":"source-extract"},"Overhead_Slam":{"version":1,"steps":{"hu":["Fogj egy medicinlabdát mindkét kezedbe, és állj vállszéles terpeszbe.","Fordítsd meg a mozdulatot, és csapd a labdát közvetlenül magad elé a talajhoz, amilyen erősen csak tudod.","A visszapattanó labdát kapd el mindkét kézzel, és ismételd meg a mozdulatot."],"en":["Hold a medine ball with both hands and stand with your feet at shoulder width.","Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can.","Receive the ball with both hands on the bounce and repeat the movement."]},"reviewed":false,"summaryMethod":"source-extract"},"Overhead_Squat":{"version":1,"steps":{"hu":["Kezdésként a rúd legyen előtted a padlón.","Vidd a rudat a fejed fölé, kissé a fejed mögé, és ügyelj rá, hogy a karod teljesen nyújtva legyen.","Most kilégzés közben a lábfejed és a lábad erejével vidd vissza a súlyt a kiinduló helyzetbe."],"en":["Start out by having a barbell in front of you on the floor.","Move the barbell over and slightly behind your head and make sure your arms are fully extended.","Now use your feet and legs to help bring the weight back up to the starting position while exhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Overhead_Stretch":{"version":1,"steps":{"hu":["Állj egyenesen, kulcsold össze az ujjaidat, és fordítsd a tenyeredet a mennyezet felé.","A teljes törzs megnyújtásához közben húzd lefelé a farokcsontodat, és stabilizáld a törzsedet."],"en":["Standing straight up, lace your fingers together and open your palms to the ceiling.","To create a full torso stretch, pull your tailbone down and stabilize your torso as you do this."]},"reviewed":false,"summaryMethod":"source-extract"},"Overhead_Triceps":{"version":1,"steps":{"hu":["Ülj egyenes háttal a padlón, az edzőtársad legyen mögötted.","Próbáld a karodat egyenesen felfelé kinyújtani, miközben a társad megakadályozza, hogy ezt valóban megtedd.","10–20 másodperc után lazítsd el a karodat, és hagyd, hogy a társad a csuklóra gyakorolt enyhe nyomással tovább nyújtsa a tricepszedet."],"en":["Sit upright on the floor with your partner behind you.","Attempt to extend the arm straight into the air as your partner prevents you from doing actually doing so.","After 10-20 seconds, relax the arm and allow your partner to further stretch the tricep by applying gentle pressure to the wrist."]},"reviewed":false,"summaryMethod":"source-extract"},"Pallof_Press":{"version":1,"steps":{"hu":["Csatlakoztass egy hagyományos fogantyút a csigás toronyhoz, és – ha lehet – állítsd a kábelt vállmagasságba.","Nyomd el a fogantyút a mellkasodtól, és nyújtsd ki teljesen mindkét karodat.","A sorozat végén ismételd meg a másik irányba fordulva."],"en":["Connect a standard handle to a tower, and—if possible—position the cable to shoulder height.","Press the cable away from your chest, fully extending both arms.","At the conclusion of the set, repeat facing the other direction."]},"reviewed":false,"summaryMethod":"source-extract"},"Pallof_Press_With_Rotation":{"version":1,"steps":{"hu":["Csatlakoztass egy hagyományos fogantyút a csigás toronyhoz, és állítsd a kábelt vállmagasságba.","A csípődet egyenesen tartva fordítsd el a törzsedet a csigától, amíg egy teljes negyed fordulatot nem teszel.","Ezután állj át, és végezd el ugyanezt a mozdulatsort a másik oldalra is."],"en":["Connect a standard handle to a tower, and position the cable to shoulder height.","Keeping your hips straight, twist your torso away from the pulley until you get a full quarter rotation.","Then, reposition and repeat the same series of movements on the opposite side."]},"reviewed":false,"summaryMethod":"source-extract"},"Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench":{"version":1,"steps":{"hu":["Kezdésként tegyél két kézisúlyzót egy sík pad egyik oldalára.","Kezdésként kilégzés közben hajlítsd a csuklódat felfelé.","Az alkarod maradjon mozdulatlan, a gyakorlathoz csak a csuklód mozgására van szükség."],"en":["Start out by placing two dumbbells on one side of a flat bench.","Start out by curling your wrist upwards and exhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise."]},"reviewed":false,"summaryMethod":"source-extract"},"Palms-Down_Wrist_Curl_Over_A_Bench":{"version":1,"steps":{"hu":["Kezdésként tegyél egy rudat egy sík pad egyik oldalára.","Kezdésként kilégzés közben hajlítsd a csuklódat felfelé.","Az alkarod maradjon mozdulatlan, a gyakorlathoz csak a csuklód mozgására van szükség."],"en":["Start out by placing a barbell on one side of a flat bench.","Start out by curling your wrist upwards and exhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise."]},"reviewed":false,"summaryMethod":"source-extract"},"Palms-Up_Barbell_Wrist_Curl_Over_A_Bench":{"version":1,"steps":{"hu":["Kezdésként tegyél egy rudat egy sík pad egyik oldalára.","Kezdésként kilégzés közben hajlítsd a csuklódat felfelé.","Az alkarod maradjon mozdulatlan, a gyakorlathoz csak a csuklód mozgására van szükség."],"en":["Start out by placing a barbell on one side of a flat bench.","Start out by curling your wrist upwards and exhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise."]},"reviewed":false,"summaryMethod":"source-extract"},"Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench":{"version":1,"steps":{"hu":["Kezdésként tegyél két kézisúlyzót egy sík pad egyik oldalára.","Kezdésként kilégzés közben hajlítsd a csuklódat felfelé.","Az alkarod maradjon mozdulatlan, a gyakorlathoz csak a csuklód mozgására van szükség."],"en":["Start out by placing two dumbbells on one side of a flat bench.","Start out by curling your wrist upwards and exhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise."]},"reviewed":false,"summaryMethod":"source-extract"},"Parallel_Bar_Dip":{"version":1,"steps":{"hu":["Állj két párhuzamos korlát közé.","Kezdd a könyököd hajlításával, és ereszkedj le, amíg a karod 90 foknál jobban be nem hajlik.","Fordítsd meg a mozdulatot: a könyököd nyújtásával told vissza magad a kiinduló helyzetbe."],"en":["Stand between a set of parallel bars.","Begin by flexing the elbow, lowering your body until your arms break 90 degrees.","Reverse the motion by extending the elbow, pushing yourself back up into the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Pelvic_Tilt_Into_Bridge":{"version":1,"steps":{"hu":["Feküdj hanyatt, a talpad legyen a padlón, a sarkad pontosan a térded alatt.","Csak a farokcsontodat emeld a mennyezet felé, hogy megnyújtsd a derekadat.","A hídhoz emeld fel az egész gerincedet, a nyakad kivételével."],"en":["Lie down with your feet on the floor, heels directly under your knees.","Lift only your tailbone to the ceiling to stretch your lower back.","To go into a bridge, lift the entire spine except the neck."]},"reviewed":false,"summaryMethod":"source-extract"},"Peroneals-SMR":{"version":1,"steps":{"hu":["Feküdj az oldaladra, a súlyodat az alkarodon és az alul lévő lábszárad külső oldala alá helyezett hengeren támaszd meg.","Emeld el a csípődet a talajról, és kezdj el görgetni a lábszárad oldalán a térd alatti résztől a boka fölötti részig; a feszes pontokon állj meg 10–30 másodpercre."],"en":["Lay on your side, supporting your weight on your forearm and on a foam roller placed on the outside of your lower leg.","Raise your hips off of the ground and begin to roll from below the knee to above the ankle on the side of your leg, pausing at points of tension for 10-30 seconds."]},"reviewed":false,"summaryMethod":"source-extract"},"Peroneals_Stretch":{"version":1,"steps":{"hu":["Ülő helyzetben vess át egy övet, kötelet vagy gumiszalagot az egyik lábfejeden.","Nyújtott lábbal, a sarkadat a talajról elemelve húzd az övet úgy, hogy a lábfejed befelé forduljon, vagyis a lábfej belső éle húzódjon feléd."],"en":["In a seated position, loop a belt, rope, or band around one foot.","With the leg extended and the heel off of the ground, pull on the belt so that the foot is inverted, with the inside of the foot being pulled towards you."]},"reviewed":false,"summaryMethod":"source-extract"},"Physioball_Hip_Bridge":{"version":1,"steps":{"hu":["Feküdj egy fitlabdára úgy, hogy a hátad felső része legyen a labdán, a csípőd pedig megtámasztás nélkül maradjon.","Kezdd a csípőd nyújtásával: a farizmod és a combhajlítód erejével emeld felfelé a csípődet hídba.","A mozdulat tetején tarts egy pillanatnyi szünetet, majd térj vissza a kiinduló helyzetbe."],"en":["Lay on a ball so that your upper back is on the ball with your hips unsupported.","Begin by extending the hips using your glutes and hamstrings, raising your hips upward as you bridge.","Pause at the top of the motion and return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Pin_Presses":{"version":1,"steps":{"hu":["A tüskékről végzett fekvenyomás kiiktatja a fekvenyomás excentrikus szakaszát, így az indítóerőt fejleszti.","Foghatod a rudat a szokásos fekvenyomó fogással, vagy vállszéles fogással, ha a tricepszre akarsz összpontosítani.","Engedd vissza a rudat a tüskékre, és tarts szünetet a következő ismétlés előtt."],"en":["Pin presses remove the eccentric phase of the bench press, developing starting strength.","You can take a standard bench grip, or shoulder width to focus on the triceps.","Return the bar to the pins, pausing before beginning the next repetition."]},"reviewed":false,"summaryMethod":"source-extract"},"Piriformis-SMR":{"version":1,"steps":{"hu":["Ülj a fenekeddel egy hengerre.","Helyezd át a testsúlyodat a keresztbe tett láb oldalára, és görgess a fenekeden, amíg feszülést nem érzel a farizmod felső részén."],"en":["Sit with your buttocks on top of a foam roll.","Shift your weight to the side of the crossed leg, rolling over the buttocks until you feel tension in your upper glute."]},"reviewed":false,"summaryMethod":"source-extract"},"Plank":{"version":1,"steps":{"hu":["Helyezkedj el hason a padlón úgy, hogy a súlyodat a lábujjaidon és az alkarodon tartod.","Tartsd a testedet végig egyenesen, és maradj ebben a helyzetben, ameddig csak bírod."],"en":["Get into a prone position on the floor, supporting your weight on your toes and your forearms.","Keep your body straight at all times, and hold this position as long as possible."]},"reviewed":false,"summaryMethod":"source-extract"},"Plate_Pinch":{"version":1,"steps":{"hu":["Fogj két széles peremű súlytárcsát, és illeszd össze őket úgy, hogy a sima oldaluk kifelé nézzen.","Szorítsd össze a tárcsákat az ujjaiddal és a hüvelykujjaddal.","Válts kezet, és ismételd meg a gyakorlatot."],"en":["Grab two wide-rimmed plates and put them together with the smooth sides facing outward","Squeeze the plate with your fingers and thumb.","Switch arms and repeat the movements."]},"reviewed":false,"summaryMethod":"source-extract"},"Plate_Twist":{"version":1,"steps":{"hu":["Helyezkedj el a padlón vagy egy tornaszőnyegen teljesen nyújtott lábbal, függőleges felsőtesttel.","Vidd a tárcsát a bal oldaladra, és érintsd meg vele a padlót.","Belégzés közben térj vissza a kiinduló helyzetbe, majd ismételd meg a mozdulatot, ezúttal a tested jobb oldalára."],"en":["Lie down on the floor or an exercise mat with your legs fully extended and your upper body upright.","Move the plate to the left side and touch the floor with it.","Come back to the starting position as you breathe in and then repeat the movement but this time to the right side of the body."]},"reviewed":false,"summaryMethod":"source-extract"},"Platform_Hamstring_Slides":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz fapadlóra vagy hasonló felületre van szükség.","Húzd tovább a sarkadat magad felé, a padlón csúsztatva.","Amikor a térded teljesen be van hajlítva, fordítsd meg a mozdulatot, és térj vissza a kiinduló helyzetbe."],"en":["For this movement a wooden floor or similar is needed.","Continue bringing the heel closer to you, sliding it on the floor.","At full knee flexion, reverse the movement to return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Plie_Dumbbell_Squat":{"version":1,"steps":{"hu":["Fogj egy kézisúlyzót az egyik végénél mindkét kézzel, és állj egyenesen.","Lassan hajlítsd be a térdedet, és ereszkedj le, amíg a combod párhuzamos nem lesz a padlóval.","Főként a sarkadra támaszkodva told vissza a testedet a kiinduló helyzetbe, közben fújd ki a levegőt."],"en":["Hold a dumbbell at the base with both hands and stand straight up.","Slowly bend the knees and lower your legs until your thighs are parallel to the floor.","Press mainly with the heel of the foot to bring the body back to the starting position while exhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Plyo_Kettlebell_Pushups":{"version":1,"steps":{"hu":["Tegyél egy kettlebellt a padlóra.","Kezdésként ereszkedj le olyan mélyre, amennyire csak tudsz, a hátadat egyenesen tartva.","Gyorsan és erőteljesen fordítsd meg az irányt, és lökd át magad a kettlebell másik oldalára, közben válts kezet."],"en":["Place a kettlebell on the floor.","Begin by lowering yourself as low as you can, keeping your back straight.","Quickly and forcefully reverse direction, pushing yourself up to the other side of the kettlebell, switching hands as you do so."]},"reviewed":false,"summaryMethod":"source-extract"},"Plyo_Push-up":{"version":1,"steps":{"hu":["Helyezkedj el hason a padlón, és támaszkodj a kezedre és a lábujjaidra.","Lent fordítsd meg a mozdulatot: a könyököd nyújtásával told fel magad, amilyen gyorsan csak tudod.","A nehezítéshez tapsolj, amíg a levegőben vagy."],"en":["Move into a prone position on the floor, supporting your weight on your hands and toes.","At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible.","For added difficulty, add claps into the movement while you are air borne."]},"reviewed":false,"summaryMethod":"source-extract"},"Posterior_Tibialis_Stretch":{"version":1,"steps":{"hu":["Ülő helyzetben vess át egy övet, kötelet vagy gumiszalagot az egyik lábfejeden.","Nyújtott lábbal, a sarkadat a talajról elemelve húzd az övet úgy, hogy a lábfejed kifelé forduljon, vagyis a lábfej külső éle húzódjon feléd."],"en":["In a seated position, loop a belt, rope, or band around one foot.","With the leg extended and the heel off of the ground, pull on the belt so that the foot is everted, with the outside of the foot being pulled towards you."]},"reviewed":false,"summaryMethod":"source-extract"},"Power_Clean":{"version":1,"steps":{"hu":["Állj vállszélesnél kissé szélesebb terpeszbe, enyhén kifelé fordított lábujjakkal.","Amikor az alsótested ízületei teljesen kinyúltak, húzd fel gyorsan a válladat, de a könyöködet még ne hajlítsd be.","Kezdd újra az első fázistól, és ismételd az előírt ismétlésszámban."],"en":["Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly.","When your lower body joints are fully extended, shrug the shoulders upward rapidly without letting the elbows flex yet.","Start over at Phase 1 and repeat for the recommended amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Power_Clean_from_Blocks":{"version":1,"steps":{"hu":["A rúd legyen a kívánt magasságú bakokon; fogd meg közvetlenül a lábadon kívül.","Ugró mozdulattal gyorsíts: nyújtsd ki a csípődet, a térdedet és a bokádat, és a sebességgel vidd felfelé a rudat.","Azonnal állj fel: nyomd a sarkadat a talajba, a törzsedet tartsd függőlegesen, a könyöködet fent."],"en":["With a barbell on boxes of the desired height, take a grip just outside the legs.","In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward.","Immediately recover by driving through the heels, keeping the torso upright and elbows up."]},"reviewed":false,"summaryMethod":"source-extract"},"Power_Jerk":{"version":1,"steps":{"hu":["Állj úgy, hogy a súly a vállad elülső részén fekszik, és kezdd a berugózással.","Abban a pillanatban, amikor a lábad elhagyja a talajt, a lehető leggyorsabban a fogadó helyzetbe kell tenned.","Állj vissza egyenes állásba."],"en":["Standing with the weight racked on the front of the shoulders, begin with the dip.","At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible.","Return to a standing position."]},"reviewed":false,"summaryMethod":"source-extract"},"Power_Partials":{"version":1,"steps":{"hu":["Állj egyenes törzzsel, mindkét kezedben egy-egy kézisúlyzóval, nyújtott karral.","A karodat nyújtva, a törzsedet mozdulatlanul tartva emeld a súlyokat oldalra körülbelül vállmagasságig, közben fújd ki a levegőt.","Egy másodpercig érezd a megfeszítést, majd belégzés közben kezdd el visszaengedni a súlyokat a kiinduló helyzetbe."],"en":["Stand up with your torso upright and a dumbbell on each hand being held at arms length.","Keeping your arms straight and the torso stationary, lift the weights out to your sides until they are about shoulder level height while exhaling.","Feel the contraction for a second and begin to lower the weights back down to the starting position while inhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Power_Snatch":{"version":1,"steps":{"hu":["Kezdésként a megpakolt rúd legyen a padlón.","Térj át a második húzásra: nyújtsd ki a csípődet, a térdedet és a bokádat, és vidd felfelé a rudat a lehető leggyorsabban.","Állj vissza egyenes állásba, a súlyt a fejed fölött tartva."],"en":["Begin with a loaded barbell on the floor.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible.","Return to a standing position with the weight over head."]},"reviewed":false,"summaryMethod":"source-extract"},"Power_Snatch_from_Blocks":{"version":1,"steps":{"hu":["Kezdésként a megpakolt rúd legyen a kívánt magasságú bakokon vagy állványokon.","Térj át a második húzásra: nyújtsd ki a csípődet, a térdedet és a bokádat, és vidd felfelé a rudat a lehető leggyorsabban.","A rudat a sarkad elülső része fölött tartva, emelt fejjel és mellkassal nyomd a sarkadat a talajba, és állj fel."],"en":["Begin with a loaded barbell on boxes or stands of the desired height.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible.","Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position."]},"reviewed":false,"summaryMethod":"source-extract"},"Power_Stairs":{"version":1,"steps":{"hu":["Az erőlépcső versenyszámban eszközöket kell felvinni egy lépcsőn.","Hátradőlve próbáld fellendíteni a súlyt a lépcsőfokra, amely általában kb.","Végezz 3–5 ismétlést, majd folytasd nehezebb súllyal, a lehető leggyorsabban haladva."],"en":["In the power stairs, implements are moved up a staircase.","Begin by taking the implement with both hands.","As you lean back, attempt to swing the weight onto the stairs, which are usually around 16-18\" high."]},"reviewed":false,"summaryMethod":"source-extract"},"Preacher_Curl":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz Scott-padra és EZ-rúdra lesz szükséged.","Belégzés közben lassan engedd le a rudat, amíg a karod ki nem nyúlik, és a bicepszed teljesen meg nem nyúlik.","Kilégzés közben a bicepszed erejével hajlítsd fel a súlyt, amíg a bicepszed teljesen meg nem feszül, és a rúd vállmagasságba nem kerül."],"en":["To perform this movement you will need a preacher bench and an E-Z bar.","As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.","As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height."]},"reviewed":false,"summaryMethod":"source-extract"},"Preacher_Hammer_Dumbbell_Curl":{"version":1,"steps":{"hu":["Támaszd mindkét felkarodat a Scott-pad tetejére, és tarts mindkét kezedben egy-egy kézisúlyzót úgy, hogy a tenyereid egymás felé néznek (kalapácsfogás).","Kilégzés közben a bicepszed erejével hajlítsd fel a súlyt, amíg a bicepszed teljesen meg nem feszül, és a súlyzók vállmagasságba nem kerülnek.","A megfeszített helyzetben egy másodpercig feszítsd meg erősen a bicepszedet, majd ismételd az előírt ismétlésszámban."],"en":["Place the upper part of both arms on top of the preacher bench as you hold a dumbbell in each hand with the palms facing each other (neutral grip).","As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbells are at shoulder height.","Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Press_Sit-Up":{"version":1,"steps":{"hu":["Kezdésként feküdj egy padra úgy, hogy a rúd a mellkasodon nyugszik.","Belégzés közben feszítsd meg a hasizmodat és a farizmodat.","Engedd vissza a felsőtestedet a kiinduló helyzetbe, közben a rudat is engedd vissza a törzsedhez."],"en":["To begin, lie down on a bench with a barbell resting on your chest.","While inhaling, tighten your abdominals and glutes.","Lower your upper body back down to the starting position while bringing the barbell back down to your torso."]},"reviewed":false,"summaryMethod":"source-extract"},"Prone_Manual_Hamstring":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz edzőtársra lesz szükséged.","Kezdésként hajlítsd be a térdedet, és húzd fel a lábszáradat.","Fent tarts egy pillanatnyi szünetet, majd engedd vissza a lábadat a kiinduló helyzetbe, miközben a társad a másik irányba fejt ki ellenállást."],"en":["You will need a partner for this exercise.","To begin, flex the knee to curl your leg up.","Pause at the top, returning the leg to the starting position as your partner provides resistance going the other direction."]},"reviewed":false,"summaryMethod":"source-extract"},"Prowler_Sprint":{"version":1,"steps":{"hu":["Tedd a szánt megfelelő felületre, megfelelő súllyal megpakolva.","A gyakorlathoz használhatod a magas vagy az alacsony fogantyúkat.","Helyes testtartással, váltott lábbal, rövid lépésekkel rugaszkodj el a talajtól."],"en":["Place your sled on an appropriate surface, loaded to a suitable weight.","You may use the upright or the low handles for this exercise.","With good posture, drive through the ground with alternating, short steps."]},"reviewed":false,"summaryMethod":"source-extract"},"Pull_Through":{"version":1,"steps":{"hu":["Állj kb.","Kezdd a mozdulatot úgy, hogy csípőből előrehajolva a lábad között a lehető leghátrébb nyúlsz."],"en":["Begin standing a few feet in front of a low pulley with a rope or handle attached.","Begin the movement by reaching through your legs as far as possible, bending at the hips."]},"reviewed":false,"summaryMethod":"source-extract"},"Pullups":{"version":1,"steps":{"hu":["Fogd a rudat felső fogással. Feszítsd meg a törzsed.","Húzd magad felfelé, könyöködet vezesd lefelé.","Ne lendülj; kontrolláltan ereszkedj vissza."],"en":["Take an overhand grip and brace your trunk.","Pull yourself up, driving your elbows down.","Avoid swinging; lower with control."]},"reviewed":true,"summaryMethod":"curated"},"Push-Up_Wide":{"version":1,"steps":{"hu":["Széles kéztartással támaszkodj a lábujjaidra és a kezedre plank helyzetben.","A mellizmod erejével, a könyököd nyújtásával nyomd vissza a felsőtestedet a kiinduló helyzetbe.","A megfeszített helyzetben tartott rövid szünet után ismételd a mozdulatot az előírt ismétlésszámban."],"en":["With your hands wide apart, support your body on your toes and hands in a plank position.","Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows.","After pausing at the contracted position, repeat the movement for the prescribed amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Push-Ups_-_Close_Triceps_Position":{"version":1,"steps":{"hu":["Feküdj hasra a padlón, és tedd a kezedet a vállszélességnél szűkebbre, szűk kéztartásba.","A tricepszed és részben a mellizmod erejével nyomd vissza a felsőtestedet a kiinduló helyzetbe, és feszítsd meg a mellizmodat.","A megfeszített helyzetben tarts egy másodperc szünetet, majd ismételd a mozdulatot az előírt ismétlésszámban."],"en":["Lie on the floor face down and place your hands closer than shoulder width for a close hand position.","Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Push-Ups_With_Feet_Elevated":{"version":1,"steps":{"hu":["Feküdj hasra a padlón, és tedd a kezedet kb.","Belégzés közben ereszkedj le, amíg a mellkasod majdnem a padlóhoz nem ér.","A megfeszített helyzetben tarts egy másodperc szünetet, majd ismételd a mozdulatot az előírt ismétlésszámban."],"en":["Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.","Lower yourself until your chest almost touches the floor as you inhale.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Push-Ups_With_Feet_On_An_Exercise_Ball":{"version":1,"steps":{"hu":["Feküdj hasra a padlón, és tedd a kezedet kb.","Belégzés közben ereszkedj le, amíg a mellkasod majdnem a padlóhoz nem ér.","A megfeszített helyzetben tarts egy másodperc szünetet, majd ismételd a mozdulatot az előírt ismétlésszámban."],"en":["Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.","Lower yourself until your chest almost touches the floor as you inhale.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Push_Press":{"version":1,"steps":{"hu":["A rúd az elülső válladon legyen, törzsed stabil.","Rövid térdhajlítás után lábbal indítva nyomd a rudat a fejed fölé.","Ne homoríts; kontrolláltan engedd vállhoz."],"en":["Support the bar on your front shoulders with your trunk braced.","Make a short knee dip, then drive through your legs and press overhead.","Avoid over-arching; lower the bar to your shoulders with control."]},"reviewed":true,"summaryMethod":"curated"},"Push_Press_-_Behind_the_Neck":{"version":1,"steps":{"hu":["Állj úgy, hogy a súly a vállad hátsó részén fekszik, és kezdd a berugózással.","A megszerzett lendületet kihasználva a karod nyújtásával fejezd be a súly kinyomását a fejed fölé.","Térj vissza a kiinduló helyzetbe, és a lábaddal tompítsd a rúd érkezését."],"en":["Standing with the weight racked on the back of the shoulders, begin with the dip.","Using the momentum generated, finish pressing the weight overhead be extending through the arms.","Return to the starting position, using your legs to absorb the impact."]},"reviewed":false,"summaryMethod":"source-extract"},"Push_Up_to_Side_Plank":{"version":1,"steps":{"hu":["Helyezkedj fekvőtámaszba a lábujjaidon, a kezed legyen a vállszélességnél éppen csak szélesebben.","Csinálj egy fekvőtámaszt, és ahogy feljössz, helyezd át a súlyodat a tested bal oldalára, fordulj oldalra, és emeld a jobb karodat a mennyezet felé oldalplankba.","Engedd vissza a karodat a padlóra egy újabb fekvőtámaszhoz, majd fordulj a másik oldalra."],"en":["Get into pushup position on the toes with your hands just outside of shoulder width.","Do one pushup and as you come up, shift your weight on the left side of the body, twist to the side while bringing the right arm up towards the ceiling in a side plank.","Lower the arm back to the floor for another pushup and then twist to the other side."]},"reviewed":false,"summaryMethod":"source-extract"},"Pushups":{"version":1,"steps":{"hu":["Feküdj hasra a padlón, és tedd a kezedet kb.","Most fújd ki a levegőt, és nyomd vissza a felsőtestedet a kiinduló helyzetbe, közben feszítsd meg a mellizmodat.","A felső, megfeszített helyzetben tartott rövid szünet után ismét elkezdhetsz leereszkedni; végezz annyi ismétlést, amennyi szükséges."],"en":["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.","Now breathe out and press your upper body back up to the starting position while squeezing your chest.","After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."]},"reviewed":false,"summaryMethod":"source-extract"},"Pushups_Close_and_Wide_Hand_Positions":{"version":1,"steps":{"hu":["Feküdj hasra a padlón egyenes testtel, a lábujjaid a padlón; széles kéztartásnál a kezed legyen a vállszélességnél szélesebben, szűk kéztartásnál pedig a vállszélességnél szűkebben.","A mellizmod erejével nyomd vissza a felsőtestedet a kiinduló helyzetbe, és feszítsd meg a mellizmodat.","A megfeszített helyzetben tarts egy másodperc szünetet, majd ismételd a mozdulatot az előírt ismétlésszámban."],"en":["Lie on the floor face down and body straight with your toes on the floor and the hands wider than shoulder width for a wide hand position and closer than shoulder width for a close hand position.","Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Pyramid":{"version":1,"steps":{"hu":["Kezdésként gördülj előre a törzseddel a labdára úgy, hogy a csípőd a labda tetején nyugodjon, és a tested legmagasabb pontja legyen.","Támaszd a kezedet és a lábfejedet a padlóra."],"en":["Start off by rolling your torso forward onto the ball so your hips rest on top of the ball and become the highest point of your body.","Rest your hands and feet on the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Quad_Stretch":{"version":1,"steps":{"hu":["Feküdj az oldaladra.","Az övet a vállad fölött vagy a fejed fölött tartva húzd finoman, hogy fokozd a combfeszítő nyújtását."],"en":["Lay on your side.","With the belt being held over the shoulder or overhead, gently pull to increase the stretch in the quadriceps."]},"reviewed":false,"summaryMethod":"source-extract"},"Quadriceps-SMR":{"version":1,"steps":{"hu":["Feküdj hasra a padlón, a súlyodat a kezeden vagy az alkarodon tartva.","Helyezz annyi súlyt a nyújtandó lábra, amennyi még elviselhető, és görgess a hengeren a térd fölötti résztől a csípő alatti részig; a feszes pontokon állj meg 10–30 másodpercre."],"en":["Lay facedown on the floor with your weight supported by your hands or forearms.","Shifting as much weight onto the leg to be stretched as is tolerable, roll over the foam from above the knee to below the hip, holding points of tension for 10-30 seconds."]},"reviewed":false,"summaryMethod":"source-extract"},"Quick_Leap":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz egy dobozra lesz szükséged.","A csípőd erejét használva szökkenj fel a dobozra, és érkezz mindkét lábadra.","Az érkezés után azonnal nyújtsd ki teljesen az egész testedet, és lendítsd a karodat a fejed fölé, hogy robbanékonyan elrugaszkodj a dobozról."],"en":["You will need a box for this exerise.","By utilizing your hips, hop onto the box, landing on both legs.","Immediately upon landing, fully extend through the entire body and swing your arms overhead to explode off of the box."]},"reviewed":false,"summaryMethod":"source-extract"},"Rack_Delivery":{"version":1,"steps":{"hu":["Ez a gyakorlat azt tanítja meg, hogyan juttasd a rudat a vállon lévő tartóhelyzetbe.","Kezdd azzal, hogy a könyöködet átfordítod a rúd körül, és a rudat a válladra juttatod.","Fontos, hogy a rúd mindvégig közel maradjon a testedhez, mert nehezebb súlynál bármekkora távolság nemkívánatos ütközéshez vezet."],"en":["This drill teaches the delivery of the barbell to the rack position on the shoulders.","Begin by rotating the elbows around the bar, delivering the bar to the shoulders.","It is important that the bar stay close to the body at all times, as with a heavier load any distance will result in an unwanted collision."]},"reviewed":false,"summaryMethod":"source-extract"},"Rack_Pull_with_Bands":{"version":1,"steps":{"hu":["Állj be egy erőkeretbe (power rackbe), a rúd legyen a tüskéken.","Állj a rúdhoz helyes felhúzó testhelyzetben.","Előre nézve nyújtsd ki a csípődet és a térdedet, és húzd a súlyt felfelé és hátra, amíg teljesen ki nem egyenesedsz."],"en":["Set up in a power rack with the bar on the pins.","Position yourself against the bar in proper deadlifting position.","With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout."]},"reviewed":false,"summaryMethod":"source-extract"},"Rack_Pulls":{"version":1,"steps":{"hu":["Állj be egy erőkeretbe (power rackbe), a rúd legyen a tüskéken.","Előre nézve nyújtsd ki a csípődet és a térdedet, és húzd a súlyt felfelé és hátra, amíg teljesen ki nem egyenesedsz.","Engedd vissza a súlyt a tüskékre, és ismételd."],"en":["Set up in a power rack with the bar on the pins.","With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout.","Return the weight to the pins and repeat."]},"reviewed":false,"summaryMethod":"source-extract"},"Rear_Leg_Raises":{"version":1,"steps":{"hu":["Helyezkedj négykézlábra egy tornaszőnyegen.","Nyújtsd ki az egyik lábadat felfelé és hátra."],"en":["Place yourself on your hands knees on an exercise mat.","Extend one leg up and behind you."]},"reviewed":false,"summaryMethod":"source-extract"},"Recumbent_Bike":{"version":1,"steps":{"hu":["Kezdésként ülj fel a kerékpárra, és állítsd be az ülést a magasságodhoz.","Válaszd ki a kívánt opciót a menüből.","A fekvő szobakerékpár kényelmes, jót tesz a szív- és érrendszernek, és kisebb terheléssel jár, mint más mozgásformák."],"en":["To begin, seat yourself on the bike and adjust the seat to your height.","Select the desired option from the menu.","Recumbent bikes offer convenience, cardiovascular benefits, and have less impact than other activities."]},"reviewed":false,"summaryMethod":"source-extract"},"Return_Push_from_Stance":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz társra lesz szükséged.","A jelre mozdulj olyan helyzetbe, hogy fogadni tudd a társad passzát.","A gyakorlatot különböző futási útvonalakkal variálhatod."],"en":["You will need a partner for this drill.","At the signal, move into a position to receive the pass from your partner.","You can modify this drill by running different routes."]},"reviewed":false,"summaryMethod":"source-extract"},"Reverse_Band_Bench_Press":{"version":1,"steps":{"hu":["Állíts egy padot az erőkeretbe (power rackbe), a rudat tedd a megfelelő magasságba.","Emeld ki a rudat az állványból anélkül, hogy a válladat előretolnád.","Tarts szünetet, amikor a rúd a törzsedhez ér, majd nyomd fel a lehető legnagyobb erővel."],"en":["Position a bench inside a power rack, with the bar set to the correct height.","Pull the bar out of the rack without protracting your shoulders.","Pause when the barbell touches your torso, and then drive the bar up with as much force as possible."]},"reviewed":false,"summaryMethod":"source-extract"},"Reverse_Band_Box_Squat":{"version":1,"steps":{"hu":["Állj be egy erőkeretbe (power rackbe), mögötted legyen egy megfelelő magasságú doboz.","Feszes háttal, vállal és törzzsel told kifelé a térdedet és hátra a fenekedet, ahogy elkezdesz leereszkedni.","A súlyt a sarkadon tartva, a lábfejedet és a térdedet kifelé nyomva told fel magad a dobozról úgy, hogy a mozdulatot a fejeddel vezeted."],"en":["Begin in a power rack with a box at the appropriate height behind you.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head."]},"reviewed":false,"summaryMethod":"source-extract"},"Reverse_Band_Deadlift":{"version":1,"steps":{"hu":["Állítsd be a rudat egy erőállványban.","Ha a lábad és a fogásod a helyén van, vegyél egy nagy levegőt, majd told le a csípődet és hajlítsd be a térdedet, amíg a sípcsontod hozzáér a rúdhoz.","Engedd vissza a rudat úgy, hogy a csípődből meghajolsz, és vezeted a rudat a talajra."],"en":["Set the bar up in a power rack.","With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar.","Lower the bar by bending at the hips and guiding it to the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Reverse_Band_Power_Squat":{"version":1,"steps":{"hu":["Kezdd egy erőállványban úgy, hogy a tartócsapok és a rúd megfelelő magasságban legyenek.","Tartsd a fejedet előre nézve.","A súlyt a sarkadon tartva, a lábadat és a térdedet kifelé nyomva told fel magad, miközben a fejeddel vezeted a mozdulatot."],"en":["Begin in a power rack with the pins and bar set at the appropriate height.","Keep your head facing forward.","Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head."]},"reviewed":false,"summaryMethod":"source-extract"},"Reverse_Band_Sumo_Deadlift":{"version":1,"steps":{"hu":["Kezdd egy erőállványon belül a földön lévő, megterhelt rúddal.","Vegyél egy nagy levegőt, majd told le a csípődet, nézz előre, és tartsd magasan a mellkasodat.","Tedd vissza a súlyt a talajra úgy, hogy a csípődből meghajolsz, és kontrollálod a súlyt lefelé."],"en":["Begin with a bar loaded on the floor inside of a power rack.","Take a breath, and then lower your hips, looking forward with your head with your chest up.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."]},"reviewed":false,"summaryMethod":"source-extract"},"Reverse_Barbell_Curl":{"version":1,"steps":{"hu":["Állj egyenesen, törzzsel felegyenesedve, és fogj egy rudat vállszéles fogással, könyökkel a törzs mellett.","A felkarodat mozdulatlanul tartva hajlítsd fel a súlyt, miközben megfeszíted a bicepszet, és kifújod a levegőt.","Lassan kezdd visszavinni a rudat a kiinduló helyzetbe, miközben belélegzel."],"en":["Stand up with your torso upright while holding a barbell at shoulder width with the elbows close to the torso.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out.","Slowly begin to bring the bar back to starting position as your breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Reverse_Barbell_Preacher_Curls":{"version":1,"steps":{"hu":["Fogj meg egy EZ-rudat vállszéles, felső fogással (tenyér lefelé).","Miközben kifújod a levegőt, a bicepsszel hajlítsd fel a súlyt, amíg a bicepszed teljesen megfeszül és a rúd vállmagasságba ér.","Belégzés közben lassan engedd le a rudat, amíg a felkarod ki nem nyúlik és a bicepsz teljesen meg nem nyúlik."],"en":["Grab an EZ-bar using a shoulder width and palms down (pronated) grip.","As you exhale, use the biceps to curl the weight up until your biceps are fully contracted and the barbell is at shoulder height.","As you breathe in, slowly lower the barbell until your upper arms are extended and the biceps is fully stretched."]},"reviewed":false,"summaryMethod":"source-extract"},"Reverse_Cable_Curl":{"version":1,"steps":{"hu":["Állj egyenesen, felegyenesedett törzzsel, és fogj meg egy alsó csigára rögzített rudat felső fogással (tenyér lefelé), vállszéles fogással.","A felkarodat mozdulatlanul tartva hajlítsd fel a súlyt, miközben megfeszíted a bicepszet, és kifújod a levegőt.","Lassan kezdd visszavinni a rudat a kiinduló helyzetbe, miközben belélegzel."],"en":["Stand up with your torso upright while holding a bar attachment that is attached to a low pulley using a pronated (palms down) and shoulder width grip.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out.","Slowly begin to bring the bar back to starting position as your breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Reverse_Crunch":{"version":1,"steps":{"hu":["Feküdj hanyatt a földön, nyújtott lábbal, a karod a törzsed mellett, a tenyered a földön.","Belégzés közben húzd a lábadat a törzsed felé, miközben hátrabillented a medencédet és felemeled a csípődet a földről.","Tartsd egy másodpercig a megfeszített helyzetet, majd kilégzés közben vidd vissza a lábadat a kiinduló helyzetbe."],"en":["Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor.","While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor.","Hold the contraction for a second and move your legs back to the starting position while exhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Reverse_Flyes":{"version":1,"steps":{"hu":["Kezdésként feküdj hasra egy ferde padon úgy, hogy a mellkasod és a hasad a háttámlának nyomódjon.","A könyököd enyhe hajlítását megtartva mozgasd a súlyokat kifelé, egymástól távolodva (oldalra) ívelő mozdulattal, miközben kifújod a levegőt.","Érezd a megfeszítést, majd lassan engedd vissza a súlyokat a kiinduló helyzetbe, miközben belélegzel."],"en":["To begin, lie down on an incline bench with the chest and stomach pressing against the incline.","Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling.","Feel the contraction and slowly lower the weights back down to the starting position while inhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Reverse_Flyes_With_External_Rotation":{"version":1,"steps":{"hu":["Kezdésként feküdj hasra egy 30 fokos szögre állított ferde padon úgy, hogy a mellkasod és a hasad a háttámlának nyomódjon.","Ahogy emeled a súlyt, a csuklód forduljon kifelé 90 fokkal, így a felső fogásból (tenyér lefelé) kalapácsfogásba (a tenyerek egymás felé néznek) jutsz.","Érezd a megfeszítést, majd lassan engedd vissza a súlyokat a kiinduló helyzetbe, miközben belélegzel."],"en":["To begin, lie down on an incline bench set at a 30-degree angle with the chest and stomach pressing against the incline.","As you lift the weight, your wrist should externally rotate by 90-degrees so that you go from a palms down (pronated) grip to a palms facing each other (neutral) grip.","Feel the contraction and slowly lower the weights back down to the starting position while inhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Reverse_Grip_Bent-Over_Rows":{"version":1,"steps":{"hu":["Állj egyenesen, és fogj egy rudat alsó fogással (tenyér felfelé).","A törzsedet mozdulatlanul tartva emeld a rudat, miközben kifújod a levegőt.","Lassan engedd vissza a súlyt a kiinduló helyzetbe, miközben belélegzel."],"en":["Stand erect while holding a barbell with a supinated grip (palms facing up).","While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights.","Slowly lower the weight again to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Reverse_Grip_Triceps_Pushdown":{"version":1,"steps":{"hu":["Kezdd azzal, hogy egy rudat (egyenes vagy EZ) a magas csigagépre rögzítesz.","Lassan emeld fel a rudat belégzés közben, amíg a mellkasod magasságába nem ér.","Ezután kezdd visszaengedni a kábelrudat az eredeti kiinduló helyzetbe, miközben kifújod a levegőt és erősen megfeszíted a tricepszet."],"en":["Start by setting a bar attachment (straight or e-z) on a high pulley machine.","Slowly elevate the bar attachment up as you inhale so it is aligned with your chest.","Then begin to lower the cable bar back down to the original staring position while exhaling and contracting the triceps hard."]},"reviewed":false,"summaryMethod":"source-extract"},"Reverse_Hyperextension":{"version":1,"steps":{"hu":["Helyezd a lábadat a párnák közé, miután megfelelő súlyt raktál fel.","Fordítsd meg a mozdulatot: nyújtsd ki a csípődet, és rúgd hátra a lábadat.","Térj vissza úgy, hogy ismét behajlítod a csípődet, és előrehúzod a kocsit, amennyire csak tudod."],"en":["Place your feet between the pads after loading an appropriate weight.","Reverse the motion by extending the hips, kicking the leg back.","Return by again flexing the hip, pulling the carriage forward as far as you can."]},"reviewed":false,"summaryMethod":"source-extract"},"Reverse_Machine_Flyes":{"version":1,"steps":{"hu":["Állítsd be a fogantyúkat úgy, hogy teljesen hátul legyenek.","Tartsd a karodat enyhén hajlítva a mozdulat során, az egész mozgás a vállízületben történjen.","Tarts szünetet a mozdulat hátsó végén, majd lassan vidd vissza a súlyt a kiinduló helyzetbe."],"en":["Adjust the handles so that they are fully to the rear.","Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint.","Pause at the rear of the movement, and slowly return the weight to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Reverse_Plate_Curls":{"version":1,"steps":{"hu":["Állj egyenesen, és fogj egy súlytárcsát mindkét kezeddel, kinyújtott karral.","Lassan emeld fel a tárcsát, miközben a könyököd bent marad és a felkarod mozdulatlan, amíg a bicepszed és az alkarod össze nem ér, és közben kifújod a levegőt.","Érezd a megfeszítést egy másodpercig, majd kezdd leengedni a súlyt a kiinduló helyzetbe, miközben belélegzel."],"en":["Start by standing straight with a weighted plate held by both hands and arms fully extended.","Slowly lift the plate up while keeping the elbows in and the upper arms stationary until your biceps and forearms touch while exhaling.","Feel the contraction for a second and begin to lower the weight back down to the starting position while inhaling"]},"reviewed":false,"summaryMethod":"source-extract"},"Reverse_Triceps_Bench_Press":{"version":1,"steps":{"hu":["Feküdj hanyatt egy sík padra.","Egy másodperces szünet után told vissza a rudat a kiinduló helyzetbe kilégzés közben, a tricepszed erejével.","Ha végeztél, tedd vissza a rudat az állványra."],"en":["Lie back on a flat bench.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles.","When you are done, place the bar back in the rack."]},"reviewed":false,"summaryMethod":"source-extract"},"Rhomboids-SMR":{"version":1,"steps":{"hu":["Feküdj hanyatt a földön.","Emeld fel a csípődet a talajról, és a súlyodat told a hengerre."],"en":["Lay down with your back on the floor.","Raise your hips off of the ground, placing your weight onto the foam roll."]},"reviewed":false,"summaryMethod":"source-extract"},"Rickshaw_Carry":{"version":1,"steps":{"hu":["Helyezd a keretet a kiindulási pontra, és terheld meg megfelelő súllyal.","Azonnal kezdj el gyorsan, rövid, kontrollált léptekkel járni."],"en":["Position the frame at the starting point, and load with the appropriate weight.","Immediately begin walking briskly with quick, controlled steps."]},"reviewed":false,"summaryMethod":"source-extract"},"Rickshaw_Deadlift":{"version":1,"steps":{"hu":["Terheld meg a keretet a kívánt súllyal.","Ha a lábad és a fogásod a helyén van, vegyél egy nagy levegőt, majd told le a csípődet és hajlítsd be a térdedet.","Engedd le a súlyt úgy, hogy a csípődből meghajolsz, és vezeted a talajra."],"en":["Load the frame with the desired weight.","With your feet and your grip set, take a big breath and then lower your hips and flex the knees.","Lower the weight by bending at the hips and guiding it to the ground."]},"reviewed":false,"summaryMethod":"source-extract"},"Ring_Dips":{"version":1,"steps":{"hu":["Fogj meg egy-egy gyűrűt mindkét kezeddel, majd egy kis ugrással told fel magad a kiinduló helyzetbe, kinyújtott, zárt karral.","Kezdd a mozdulatot a könyököd behajlításával, engedd le a tested, amíg a karod 90 foknál nagyobb szögbe nem kerül.","Fordítsd meg a mozdulatot: nyújtsd ki a könyöködet, és told vissza magad a kiinduló helyzetbe."],"en":["Grip a ring in each hand, and then take a small jump to help you get into the starting position with your arms locked out.","Begin by flexing the elbow, lowering your body until your arms break 90 degrees.","Reverse the motion by extending the elbow, pushing yourself back up into the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Rocket_Jump":{"version":1,"steps":{"hu":["Kezdj laza állásban, a lábad vállszélességben, a karod a test közelében.","A mozdulat megkezdéséhez guggolj le félig, majd robbanékonyan ugorj fel a lehető legmagasabbra.","Nyújtsd ki teljesen az egész testedet, és nyújtózz a fejed fölé, amennyire csak tudsz."],"en":["Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.","To initiate the move, squat down halfway and explode back up as high as possible.","Fully extend your entire body, reaching overhead as far as possible."]},"reviewed":false,"summaryMethod":"source-extract"},"Rocking_Standing_Calf_Raise":{"version":1,"steps":{"hu":["Ezt a gyakorlatot biztonsági okokból a legjobb guggolóállványban végezni.","Emeld fel a sarkadat kilégzés közben úgy, hogy a bokádat a lehető legmagasabbra nyújtod, és megfeszíted a vádlidat.","Tartsd egy másodpercig, majd engedd vissza őket, miközben belélegzel."],"en":["This exercise is best performed inside a squat rack for safety purposes.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf.","Hold for a second and bring them back down as you breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Rocky_Pull-Ups_Pulldowns":{"version":1,"steps":{"hu":["Fogd meg a húzódzkodó rudat előre néző tenyérrel, széles fogással.","Egy másodperc megtartás után a megfeszített helyzetben kezdj belélegezni, és lassan engedd vissza a törzsedet a kiinduló helyzetbe, amíg a karod teljesen ki nem nyúlik és a széles hátizom teljesen meg nem nyúlik.","Miután leereszkedtél a kiinduló helyzetbe, ismételd a gyakorlatot az edzésprogramodban előírt ismétlésszámban."],"en":["Grab the pull-up bar with the palms facing forward using a wide grip.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Once you have lowered yourself back down to the starting position, repeat the exercise for the prescribed amount of repetitions in your program."]},"reviewed":false,"summaryMethod":"source-extract"},"Romanian_Deadlift":{"version":1,"steps":{"hu":["Állj stabilan, a rudat tartsd a combod előtt. Térded enyhén hajlítsd.","Csípődet told hátra, a rudat vezesd a lábad közelében lefelé.","Tartsd stabilan a hátad, majd csípőből egyenesedj fel."],"en":["Stand with the bar in front of your thighs, knees slightly bent.","Push your hips back, lowering the bar close to your legs.","Keep your back steady, then extend at your hips to stand."]},"reviewed":true,"summaryMethod":"curated"},"Romanian_Deadlift_from_Deficit":{"version":1,"steps":{"hu":["Állj egyenesen, és tarts egy rudat kinyújtott karral magad előtt.","Kezdd a térded enyhe behajlításával, majd hajolj előre a csípődből, tolva a feneked a lehető legmesszebb hátra, és engedd le a törzsedet, amilyen mélyre a hajlékonyságod engedi.","Fordítsd meg a mozdulatot, hogy visszatérj a kiinduló helyzetbe."],"en":["Begin standing while holding a bar at arm's length in front of you.","Begin by flexing the knees slightly, and then flex at the hip, moving your butt back as far as possible, lowering the torso as far as flexibility allows.","Reverse the motion to return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Rope_Climb":{"version":1,"steps":{"hu":["Fogd meg a kötelet mindkét kezeddel a fejed fölött.","Engedd el a kötelet a lábaddal, miközben a karoddal felhúzod magad, a térdedet a mellkasod felé húzva.","A leereszkedéshez lazítsd a lábad szorítását a kötélen, és csúsztasd le magad kézről kézre fogva."],"en":["Grab the rope with both hands above your head.","Release the rope from your feet as you pull yourself up with your arms, bringing your knees towards your chest.","To lower yourself, loosen the grip of your feet on the rope as you slide down using a hand over hand motion."]},"reviewed":false,"summaryMethod":"source-extract"},"Rope_Crunch":{"version":1,"steps":{"hu":["Térdelj le kb.","A kezdéshez görbítsd a gerincedet, és próbáld a bordakosarad a lábad felé vinni, miközben lehúzod a kábelt.","Ezeket végezheted csavarással vagy oldalra döntéssel is, hogy a ferde hasizmokat dolgoztasd meg."],"en":["Kneel 1-2 feet in front of a cable system with a rope attached.","To begin, flex at the spine, attempting to bring your rib cage to your legs as you pull the cable down.","These can be done with twists or to the side to hit the obliques."]},"reviewed":false,"summaryMethod":"source-extract"},"Rope_Jumping":{"version":1,"steps":{"hu":["Fogd meg a kötél egyik végét mindkét kezedben.","Az ugrókötelezés izgalmas, próbára teszi a koordinációdat, és sok energiát igényel."],"en":["Hold an end of the rope in each hand.","Rope jumping is exciting, challenges your coordination, and requires a lot of energy."]},"reviewed":false,"summaryMethod":"source-extract"},"Rope_Straight-Arm_Pulldown":{"version":1,"steps":{"hu":["Rögzíts egy kötelet egy magas csigára, és válaszd ki a súlyt.","Tarts szünetet a mozdulat alján, és szorítsd meg a széles hátizmaidat.","Térj vissza a kiinduló helyzetbe úgy, hogy a súly ne nyugodjon teljesen a súlytömbön."],"en":["Attach a rope to a high pulley and make your weight selection.","Pause at the bottom of the motion, squeezing your lats.","Return to the starting position without allowing the weight to fully rest on the stack."]},"reviewed":false,"summaryMethod":"source-extract"},"Round_The_World_Shoulder_Stretch":{"version":1,"steps":{"hu":["Állj egyenesen összezárt lábbal, és tarts egy tornabotot vagy seprűnyelet.","Told a botot a csípőd mögé, a vállszélességnél szélesebb fogással.","Lassan emeld fel a karodat a fejed mögött."],"en":["Stand up straight with your legs together, holding a bodybar or broomstick.","Hold the pole behind your hips with a wider than shoulder width grip.","Slowly lift your arms up behind your head."]},"reviewed":false,"summaryMethod":"source-extract"},"Rowing_Stationary":{"version":1,"steps":{"hu":["Kezdésként ülj fel az evezőgépre.","Az evezés három mozgásfázisból áll.","A visszatérő fázis egyszerűen a karod kinyújtásából, a térded behajlításából, és a tested ismételt előrevitelből áll, ahogy átmész az első fázisba."],"en":["To begin, seat yourself on the rower.","There are three phases of movement when using a rower.","The recovery phase simply involves straightening your arms, bending the knees, and bringing your body forward again as you transition back into the first phase."]},"reviewed":false,"summaryMethod":"source-extract"},"Runners_Stretch":{"version":1,"steps":{"hu":["Ebbe a nyújtásba a legkönnyebb úgy beállni, hogy állva indulsz, az egyik lábadat hátrateszed, és lassan lesüllyeszted a törzsedet a föld felé.","Tartsd az elülső sarkadat a földön (ha felemelkedik, csúsztasd hátrébb a másik lábadat).","Helyezd a kezedet az elülső lábad két oldalára."],"en":["It's easiest to get into this stretch if you start standing up, put one leg behind you, and slowly lower your torso down to the floor.","Keep the front heel on the floor (if it lifts up, scoot your other leg further back).","Place your hands on either side of your front leg."]},"reviewed":false,"summaryMethod":"source-extract"},"Running_Treadmill":{"version":1,"steps":{"hu":["Kezdésként lépj fel a futópadra, és válaszd ki a kívánt opciót a menüből.","A futópadok kényelmet és kardiovaszkuláris előnyöket nyújtanak, és általában kisebb terheléssel járnak, mint a szabadtéri futás."],"en":["To begin, step onto the treadmill and select the desired option from the menu.","Treadmills offer convenience, cardiovascular benefits, and usually have less impact than running outside."]},"reviewed":false,"summaryMethod":"source-extract"},"Russian_Twist":{"version":1,"steps":{"hu":["Feküdj le a földre úgy, hogy a lábadat valami olyan alá teszed, ami nem mozdul, vagy egy társ tartja.","Csavard el a törzsedet jobbra, amíg a karod párhuzamos nem lesz a talajjal, miközben kifújod a levegőt.","Tartsd egy másodpercig a megfeszített helyzetet, majd térj vissza a kiinduló helyzetbe, miközben kifújod a levegőt."],"en":["Lie down on the floor placing your feet either under something that will not move or by having a partner hold them.","Twist your torso to the right side until your arms are parallel with the floor while breathing out.","Hold the contraction for a second and move back to the starting position while breathing out."]},"reviewed":false,"summaryMethod":"source-extract"},"Sandbag_Load":{"version":1,"steps":{"hu":["A homokzsákok vagy más tárgyak felrakásához kezdd úgy, hogy az eszközök a felrakó platformtól egy bizonyos távolságra vannak, jellemzően kb.","Mozogj a lehető leggyorsabban a platformhoz, és rakd fel, a csípődet, térdedet és bokádat kinyújtva, hogy a lehető legmagasabbra juttasd.","Térj vissza a kiindulási helyre, hogy elhozd a következő homokzsákot, és ismételd, amíg a feladat be nem fejeződik."],"en":["To load sandbags or other objects, begin with the implements placed a distance from the loading platform, typically 50 feet.","Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankles to get it as high as possible.","Return to the starting position to retrieve the next sandbag, and repeat until the event is completed."]},"reviewed":false,"summaryMethod":"source-extract"},"Scapular_Pull-Up":{"version":1,"steps":{"hu":["Fogd meg a húzódzkodó rudat felső fogással.","Lógó helyzetből emeld fel magad néhány centiméterre a karod használata nélkül.","Tarts szünetet a mozdulat végén, majd lassan térj vissza a kiinduló helyzetbe, mielőtt további ismétléseket végzel."],"en":["Take a pronated grip on a pull-up bar.","From a hanging position, raise yourself a few inches without using your arms.","Pause at the completion of the movement, and then slowly return to the starting position before performing more repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Scissor_Kick":{"version":1,"steps":{"hu":["Kezdésként feküdj hanyatt, a hátad a földhöz vagy egy tornaszőnyeghez nyomva (utóbbi nem kötelező).","Most emeld fel a bal lábadat kb.","Cserélj: emeld fel a jobb lábadat, és engedd le a balt."],"en":["To begin, lie down with your back pressed against the floor or on an exercise mat (optional).","Now lift your left leg up to about a 45 degree angle while your right leg is lowered until the heel is about 2-3 inches from the ground.","Switch movements by raising your right leg up and lowering your left leg."]},"reviewed":false,"summaryMethod":"source-extract"},"Scissors_Jump":{"version":1,"steps":{"hu":["Vedd fel a kitörés pozícióját: az egyik láb előre, behajlított térddel, a hátsó térded majdnem érintse a talajt.","Miközben a lehető legmagasabbra ugrasz, cseréld fel a lábad helyzetét: az elülső lábadat vidd hátra, a hátsót előre.","Leérkezéskor a lábaddal csillapítsd az ütközést úgy, hogy kitörés helyzetbe érkezel, és ismételd."],"en":["Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.","As you jump as high as you can, switch the position of your legs, moving your front leg to the back and the rear leg to the front.","As you land, absorb the impact through the legs by adopting the lunge position, and repeat."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Band_Hamstring_Curl":{"version":1,"steps":{"hu":["Rögzíts egy gumiszalagot a talaj közelében, és helyezz egy padot kb.","Hajlítsd be a térdedet, a lábfejedet a pad felé húzva.","Tarts szünetet a mozdulat végén, majd lassan térj vissza a kiinduló helyzetbe."],"en":["Secure a band close to the ground and place a bench a couple feet away from it.","Flex the knees, bringing your feet towards the bench.","Pause at the completion of the movement, and then slowly return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Barbell_Military_Press":{"version":1,"steps":{"hu":["Ülj egy vállnyomó padra úgy, hogy a rúd a fejed mögött legyen, és vagy kérj meg egy segítőt, hogy adja oda a rudat (így kíméletesebb a forgatóköpenynek), vagy óvatosan vedd fel magad felső fogással (tenyér előre).","Lassan engedd le a rudat a kulcscsontodig, miközben belélegzel.","Told vissza a rudat a kiinduló helyzetbe, miközben kifújod a levegőt."],"en":["Sit on a Military Press Bench with a bar behind your head and either have a spotter give you the bar (better on the rotator cuff this way) or pick it up yourself carefully with a pronated grip (palms facing forward).","Lower the bar down to the collarbone slowly as you inhale.","Lift the bar back up to the starting position as you exhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Barbell_Twist":{"version":1,"steps":{"hu":["Kezdd úgy, hogy egy sík pad szélén ülsz, a rúd a combodon fekszik.","Most engedd le a rudat a fejed mögé, amíg a nyakad tövén nem nyugszik.","Ne felejts el kifújni a levegőt, amikor oldalra csavarod a tested, és belélegezni, amikor visszamész a kiinduló helyzetbe."],"en":["Start out by sitting at the end of a flat bench with a barbell placed on top of your thighs.","Now lower the barbell behind your head until it is resting along the base of your neck.","Remember to breathe out while twisting your body to the side and in when moving back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension":{"version":1,"steps":{"hu":["Ülj le egy sík pad szélére, az egyik kezedben egy kézisúlyzóval, kalapácsfogással (a tenyered feléd néz).","A felkarodat mozdulatlanul tartva told fel a súlyt a tricepsszel, miközben kifújod a levegőt, amíg az alkarod párhuzamos nem lesz a talajjal, és az egész karod ki nem nyúlik.","Cserélj kart, és ismételd meg a gyakorlatot."],"en":["Sit down at the end of a flat bench with a dumbbell in one arm using a neutral grip (palms of the hand facing you).","Keeping the upper arm stationary, use the triceps to lift the weight as you exhale until the forearm is parallel to the floor and the whole arm is extended.","Switch arms and repeat the exercise."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Bent-Over_Rear_Delt_Raise":{"version":1,"steps":{"hu":["Helyezz két kézisúlyzót egy sík pad elé, előre nézve.","Hajolj előre a derékból, egyenes háttal, hogy felvedd a kézisúlyzókat.","Egy másodperces megfeszítés után fent, lassan engedd vissza a kézisúlyzókat a kiinduló helyzetbe."],"en":["Place a couple of dumbbells looking forward in front of a flat bench.","Bend at the waist while keeping the back straight in order to pick up the dumbbells.","After a one second contraction at the top, slowly lower the dumbbells back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension":{"version":1,"steps":{"hu":["Ülj le egy sík pad szélére, mindkét kezedben egy kézisúlyzóval, kalapácsfogással (a tenyered feléd néz).","A kézisúlyzókat tartó felkarok legyenek közel a törzshöz és egy vonalban vele (felemelve, amíg párhuzamosak nem lesznek a talajjal, az alkarok pedig a talaj felé mutatnak, miközben a kezek tartják a súlyokat).","Egy másodperces megfeszítés után fent, lassan engedd vissza a kézisúlyzókat a kiinduló helyzetbe, miközben belélegzel."],"en":["Sit down at the end of a flat bench with a dumbbell in both arms using a neutral grip (palms of the hand facing you).","The upper arms with the dumbbells should be close to the torso and aligned with it (lifted up until they are parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights).","After a second contraction at the top, slowly lower the dumbbells back to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Biceps":{"version":1,"steps":{"hu":["Ülj a földre behajlított térddel, a társad pedig álljon mögötted.","Próbáld behajlítani a könyöködet, miközben a társad megakadályozza a tényleges mozgást.","10–20 másodperc után lazítsd el a karodat, miközben a társad finoman felfelé húzza a csuklódat, hogy megnyújtsa a bicepszedet."],"en":["Sit on the floor with your knees bent and your partner standing behind you.","Attempt to flex your elbows, while your partner prevents any actual movement.","After 10-20 seconds, relax your arms while your partner gently pulls your wrists up to stretch your biceps."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Cable_Rows":{"version":1,"steps":{"hu":["Ülj stabilan, talpad támaszd meg, fogd a fogantyút.","Húzd a fogantyút a hasadhoz, könyöködet vezesd hátra.","Ne hintázz; lassan nyújtsd vissza a karod."],"en":["Sit steady with your feet supported and hold the handle.","Row the handle toward your abdomen, elbows moving back.","Avoid rocking; extend your arms slowly."]},"reviewed":true,"summaryMethod":"curated"},"Seated_Cable_Shoulder_Press":{"version":1,"steps":{"hu":["Állítsd a súlyt megfelelő mennyiségre, és ülj le, megfogva a fogantyúkat.","A tetején tartott szünet után vidd vissza a fogantyúkat a kiinduló helyzetbe.","Ezt a mozdulatot végezheted úgy is, hogy a hátad nem támaszkodik a párnának, és váltott karral nyomsz."],"en":["Adjust the weight to an appropriate amount and be seated, grasping the handles.","After pausing at the top, return the handles to the starting position.","You can also execute this movement with your back off the pad and alternate hands."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Calf_Raise":{"version":1,"steps":{"hu":["Ülj be, a párna a combodon legyen. Lábujjpárnád támaszd az emelvényre.","Emeld a sarkad a lábujjpárnádra támaszkodva.","Lassan engedd le, ne rugózz."],"en":["Sit with the pad on your thighs, balls of your feet on the platform.","Raise your heels while keeping the balls of your feet supported.","Lower slowly without bouncing."]},"reviewed":true,"summaryMethod":"curated"},"Seated_Calf_Stretch":{"version":1,"steps":{"hu":["Ülj egyenesen egy tornaszőnyegen.","Nyújtsd ki a másik lábadat, és hajlítsd meg a bokádat.","Egy gumiszalaggal, törölközővel vagy a kezeddel, ha eléred, húzd magad felé a lábujjaidat."],"en":["Sit up straight on an exercise mat.","Straighten your other leg and flex your ankle.","Using a band, towel, or your hand if you can reach, pull the toes toward you."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Close-Grip_Concentration_Barbell_Curl":{"version":1,"steps":{"hu":["Ülj le egy sík padra úgy, hogy egy rúd vagy EZ-rúd legyen előtted a lábad között.","A felkarodat mozdulatlanul tartva hajlítsd előre a súlyt, miközben megfeszíted a bicepszet, és kifújod a levegőt.","Lassan kezdd visszavinni a rudat a kiinduló helyzetbe, miközben belélegzel."],"en":["Sit down on a flat bench with a barbell or E-Z Bar in front of you in between your legs.","While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out.","Slowly begin to bring the barbell back to starting position as your breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Dumbbell_Curl":{"version":1,"steps":{"hu":["Ülj egy sík padra, mindkét kezedben egy-egy kézisúlyzóval, kinyújtott karral.","A felkarodat mozdulatlanul tartva hajlítsd fel a súlyokat, és kezdd el csavarni a csuklódat, amint a kézisúlyzók elhaladnak a combod mellett, hogy a tenyered a mozdulat végén előre nézzen.","Lassan kezdd visszavinni a kézisúlyzókat a kiinduló helyzetbe, miközben belélegzel, és közben fordítsd vissza a csuklódat kalapácsfogásba."],"en":["Sit on a flat bench with a dumbbell on each hand being held at arms length.","While holding the upper arm stationary, curl the weights and start twisting the wrists once the dumbbells pass your thighs so that the palms of your hands face forward at the end of the movement.","Slowly begin to bring the dumbbells back to the starting position as your breathe in and as you rotate the wrists back to a neutral grip."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Dumbbell_Inner_Biceps_Curl":{"version":1,"steps":{"hu":["Ülj egy sík pad szélére, mindkét kezedben egy-egy kézisúlyzóval, kinyújtott karral.","A felkarodat mozdulatlanul tartva hajlítsd a kézisúlyzókat kifelé és felfelé, miközben emeléskor kifelé fordítod a tenyered, és az alkarodat a külső deltaizmoddal egy vonalban tartod.","Lassan kezdd visszavinni a kézisúlyzókat a kiinduló helyzetbe, miközben belélegzel."],"en":["Sit on the end of a flat bench with a dumbbell in each hand being held at arms length.","While holding the upper arms stationary, curl the dumbbells out and up, turning the palms out as you lift and keeping your forearms in line with your outer deltoids.","Slowly begin to bring the dumbbells back to the starting position as your breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Dumbbell_Palms-Down_Wrist_Curl":{"version":1,"steps":{"hu":["Kezdd azzal, hogy két kézisúlyzót lerakod a földre egy sík pad elé.","Kezdd a csuklód felfelé hajlításával, miközben kifújod a levegőt.","Amikor végeztél, egyszerűen tedd le a kézisúlyzókat a földre."],"en":["Start out by placing two dumbbells on the floor in front of a flat bench.","Start out by curling your wrist upwards and exhaling.","When finished, simply lower the dumbbells to the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Dumbbell_Palms-Up_Wrist_Curl":{"version":1,"steps":{"hu":["Ülj a pad szélére. Alkarod támaszd a combodra, csuklód lógjon túl a térdeden, tenyérrel felfelé.","Csak a csuklódat hajlítva emeld a súlyzókat.","Alkarod maradjon támaszon; lassan engedd vissza."],"en":["Sit on the bench edge, forearms on your thighs, wrists beyond your knees and palms up.","Curl the dumbbells by bending only your wrists.","Keep your forearms supported; lower slowly."]},"reviewed":true,"summaryMethod":"curated"},"Seated_Dumbbell_Press":{"version":1,"steps":{"hu":["Fogj két kézisúlyzót, és ülj egy vállnyomó padra vagy háttámlás univerzális padra, miközben a kézisúlyzókat függőlegesen a combodra helyezed.","Fordítsd el a csuklódat úgy, hogy a tenyered előre nézzen.","Egy másodperces szünet után lassan engedd vissza őket a kiinduló helyzetbe, miközben belélegzel."],"en":["Grab a couple of dumbbells and sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs.","Rotate the wrists so that the palms of your hands are facing forward.","After a second pause, slowly come down back to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Flat_Bench_Leg_Pull-In":{"version":1,"steps":{"hu":["Ülj egy padra úgy, hogy a lábad kinyújtva van előtted kissé a párhuzam alatt, a kezeddel pedig a pad oldalába kapaszkodsz.","Húzd be a térdedet magad felé, miközben a törzsedet egyidejűleg közelebb viszed hozzájuk.","Egy másodperces szünet után térj vissza a kiinduló helyzetbe, miközben belélegzel."],"en":["Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench.","Bring the knees in toward you as you move your torso closer to them at the same time.","After a second pause, go back to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Floor_Hamstring_Stretch":{"version":1,"steps":{"hu":["Ülj egy szőnyegre úgy, hogy a jobb lábad kinyújtva van előtted, a bal lábad behajlítva, a talpad a jobb belső combodhoz támaszkodik.","Dőlj előre a csípődből, és nyúlj a bokád felé, amíg nyújtást nem érzel a combhajlítódban."],"en":["Sit on a mat with your right leg extended in front of you and your left leg bent with your foot against your right inner thigh.","Lean forward from your hips and reach for your ankle until you feel a stretch in your hamstring."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Front_Deltoid":{"version":1,"steps":{"hu":["Ülj egyenesen a földön behajlított lábbal, a társad pedig álljon mögötted.","A könyöködet kinyújtva tartva próbáld a karodat előre mozgatni, miközben a társad finoman visszatart, hogy 10–20 másodpercig ne legyen tényleges mozgás.","Most lazítsd el az izmaidat, és hagyd, hogy a társad finoman növelje a nyújtást a vállaidon és a mellkasodon."],"en":["Sit upright on the floor with your legs bent, your partner standing behind you.","Keeping your elbows straight, attempt to move your arms to the front, with your partner gently restraining you to prevent any actual movement for 10-20 seconds.","Now, relax your muscles and allow your partner to gently increase the stretch on the shoulders and chest."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Glute":{"version":1,"steps":{"hu":["Ülő helyzetben, behajlított térddel, keresztezd az egyik bokádat a másik térded fölött.","Próbáld hátrafelé tolni a törzsedet 10–20 másodpercig, miközben a társad megakadályozza a törzsed tényleges mozgását.","Most lazítsd el az izmaidat, miközben a társad növeli a nyújtást azzal, hogy finoman előre tolja a törzsedet 10–20 másodpercig."],"en":["In a seated position with your knees bent, cross one ankle over the opposite knee.","Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.","Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Good_Mornings":{"version":1,"steps":{"hu":["Állíts fel egy dobozt az erőállványban.","A rudat szorosan tartva hajolj előre a csípődből, amennyire csak lehet.","Állj meg közvetlenül a tartócsapok fölött, és fordítsd meg a mozdulatot, amíg a törzsed fel nem egyenesedik."],"en":["Set up a box in a power rack.","Keeping the bar tight, bend forward at the hips as much as possible.","Pause just above the pins and reverse the motion until your torso it upright."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Hamstring":{"version":1,"steps":{"hu":["Ülő helyzetben, kinyújtott lábbal, a társad álljon mögötted.","Próbáld hátrafelé tolni a törzsedet 10–20 másodpercig, miközben a társad megakadályozza a törzsed tényleges mozgását.","Most lazítsd el az izmaidat, miközben a társad növeli a nyújtást azzal, hogy finoman előre tolja a törzsedet 10–20 másodpercig."],"en":["In a seated position with your legs extended, have your partner stand behind you.","Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.","Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Hamstring_and_Calf_Stretch":{"version":1,"steps":{"hu":["Hurkolj egy övet, kötelet vagy gumiszalagot az egyik lábad köré.","Kissé előre dőlve húzd az övet, hogy a lábfejed ujjait magad felé húzd."],"en":["Loop a belt, rope, or band around one foot.","Leaning forward slightly, pull on the belt to draw the toes of your foot back."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Head_Harness_Neck_Resistance":{"version":1,"steps":{"hu":["Helyezz egy nyakhevedert a földre egy sík pad végénél.","Most helyezd mindkét kezedet a térdedre.","Kifújt levegővel told vissza a nyakadat a kiinduló helyzetbe."],"en":["Place a neck strap on the floor at the end of a flat bench.","Now place both hands on top of your knees.","While exhaling, bring your neck back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Leg_Curl":{"version":1,"steps":{"hu":["Ülj be, állítsd a hengert az alsó lábszáradra és rögzítsd a combod.","Hajlítsd a térded, húzd a hengert a szék alá.","Törzsed és combod maradjon támaszon; lassan engedd vissza."],"en":["Sit down, set the roller on your lower legs and secure your thighs.","Bend your knees, pulling the roller under the seat.","Keep your trunk and thighs supported; return slowly."]},"reviewed":true,"summaryMethod":"curated"},"Seated_Leg_Tucks":{"version":1,"steps":{"hu":["Ülj egy padra úgy, hogy a lábad kinyújtva van előtted kissé a párhuzam alatt, a kezeddel pedig a pad oldalába kapaszkodsz.","Húzd be a térdedet magad felé, miközben a törzsedet egyidejűleg közelebb viszed hozzájuk.","Egy másodperces szünet után térj vissza a kiinduló helyzetbe, miközben belélegzel."],"en":["Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench.","Bring the knees in toward you as you move your torso closer to them at the same time.","After a second pause, go back to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl":{"version":1,"steps":{"hu":["Ülj egy sík padra, a jobb kezedben egy kézisúlyzóval.","Engedd le a kézisúlyzót, amilyen mélyre csak tudod, miközben szorosan tartod.","Végezd el az előírt ismétlésszámot, majd cserélj kart, és ismételd meg a mozdulatot."],"en":["Sit on a flat bench with a dumbbell in your right hand.","Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell.","Perform for the recommended amount of repetitions, switch arms and repeat the movement."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl":{"version":1,"steps":{"hu":["Ülj egy sík padra, a jobb kezedben egy kézisúlyzóval.","Engedd le a kézisúlyzót, amilyen mélyre csak tudod, miközben szorosan tartod.","Végezd el az előírt ismétlésszámot, majd cserélj kart, és ismételd meg a mozdulatot."],"en":["Sit on a flat bench with a dumbbell in your right hand.","Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell.","Perform for the recommended amount of repetitions, switch arms and repeat the movement."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_One-arm_Cable_Pulley_Rows":{"version":1,"steps":{"hu":["A kiinduló helyzet felvételéhez ülj le a gépre, és tedd a lábadat az elülső lábtartóra vagy a rendelkezésre álló keresztrúdra, ügyelve arra, hogy a térded enyhén hajlított legyen, és ne legyen kiegyenesítve.","Kinyújtott karral húzd magad hátra, amíg a törzsed 90 fokos szöget nem zár be a lábaddal.","Tartsd meg a megfeszítést egy másodpercig, majd lassan menj vissza az eredeti helyzetbe, miközben belélegzel."],"en":["To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.","With your arm extended pull back until your torso is at a 90-degree angle from your legs.","Hold that contraction for a second and slowly go back to the original position while breathing in."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Overhead_Stretch":{"version":1,"steps":{"hu":["Ülj egyenesen egy tornaszőnyegen.","Helyezd az egyik kezedet a földre magad mellé, a másikat pedig a fejed mögé.","Emeld a könyöködet a plafon felé, miközben a törzsedet a másik oldalra döntöd."],"en":["Sit up straight on an exercise mat.","Place one hand on the floor beside you and your other hand behind your head.","Lift your elbow to the ceiling as you incline your torso to the other side."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Palm-Up_Barbell_Wrist_Curl":{"version":1,"steps":{"hu":["Fogj egy rudat mindkét kezeddel, tenyérrel felfelé; a kezed kb.","Dőlj előre, és helyezd az alkarodat a combod felső részére, tenyérrel felfelé.","Most hajlítsd fel a rudat a lehető legmagasabbra, miközben megfeszíted az alkarodat, és kifújod a levegőt."],"en":["Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.","Lean forward and place your forearms on top of your upper thighs with your palms up.","Now curl bar up as high as possible while flexing the forearms and exhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Palms-Down_Barbell_Wrist_Curl":{"version":1,"steps":{"hu":["Fogj egy rudat mindkét kezeddel, tenyérrel lefelé; a kezed kb.","Dőlj előre, és helyezd az alkarodat a combod felső részére, tenyérrel lefelé.","Most hajlítsd fel a rudat a lehető legmagasabbra, miközben megfeszíted az alkarodat, és kifújod a levegőt."],"en":["Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width.","Lean forward and place your forearms on top of your upper thighs with your palms down.","Now curl bar up as high as possible while flexing the forearms and exhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Side_Lateral_Raise":{"version":1,"steps":{"hu":["Ülj stabilan, a súlyzók a tested mellett legyenek, könyököd enyhén hajlítva.","Emeld a karod oldalra vállmagasságig.","Ne lendíts; lassan engedd le a súlyokat."],"en":["Sit steady with dumbbells by your sides and elbows slightly bent.","Raise your arms out to shoulder height.","Avoid swinging; lower slowly."]},"reviewed":true,"summaryMethod":"curated"},"Seated_Triceps_Press":{"version":1,"steps":{"hu":["Ülj le egy háttámlás padra, fogj meg egy kézisúlyzót mindkét kezeddel, és tartsd a fejed fölött, kinyújtott karral.","A felkarodat a fejed közelében (könyök befelé) és a talajra merőlegesen tartva engedd le a súlyt félkör alakú mozdulattal a fejed mögé, amíg az alkarod meg nem érinti a bicepszedet.","Térj vissza a kiinduló helyzetbe úgy, hogy a tricepsszel felemeled a kézisúlyzót."],"en":["Sit down on a bench with back support and grasp a dumbbell with both hands and hold it overhead at arm's length.","Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semi-circular motion behind your head until your forearms touch your biceps.","Go back to the starting position by using the triceps to raise the dumbbell."]},"reviewed":false,"summaryMethod":"source-extract"},"Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl":{"version":1,"steps":{"hu":["Helyezz egy padot egy alsó csigagép elé, amelyen rúd vagy EZ-rúd van.","Dőlj előre, és helyezd az alkarodat a combodra úgy, hogy a csuklód hátulja a térded fölött legyen.","Egy másodperces megfeszítés után fent térj vissza a kiinduló helyzetbe, miközben belélegzel."],"en":["Put a bench in front of a low pulley machine that has a barbell or EZ Curl attachment on it.","Lean forward and place the forearms on your thighs with the back of your wrists over your knees.","After a second contraction at the top go back to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"See-Saw_Press_Alternating_Side_Press":{"version":1,"steps":{"hu":["Fogj mindkét kezedbe egy-egy kézisúlyzót, és állj egyenesen.","Most kezdd el kinyújtani a bal karodat a fejed fölé, közben fordítsd el a csuklódat úgy, hogy felfelé haladva a tenyered előre nézzen.","A felső pontra érve lélegezz be."],"en":["Grab a dumbbell with each hand and stand up erect.","Now start extending your left arm overhead as you rotate the wrist so that the palm of your hand faces forward as you go up.","Once you reach the top position breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Shotgun_Row":{"version":1,"steps":{"hu":["Rögzíts egy egykezes fogantyút az alsó csigára.","A mozdulathoz húzd hátra a válladat, és hajlítsd be a könyöködet.","Rövid szünet után térj vissza a kiinduló helyzetbe."],"en":["Attach a single handle to a low cable.","Perform the movement by retracting the shoulder and flexing the elbow.","After a brief pause, return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Shoulder_Circles":{"version":1,"steps":{"hu":["Laza vállal, a tested mellett lazán lógó karral (ha ülsz, az öledben pihentetett kézzel) körözz finoman a válladdal: előre, fel, hátra, majd le.","Válts irányt."],"en":["With shoulders relaxed and arms resting loosely at your sides (or in your lap if you're seated), gently roll your shoulders forward, up, back, and down.","Reverse direction."]},"reviewed":false,"summaryMethod":"source-extract"},"Shoulder_Press_-_With_Bands":{"version":1,"steps":{"hu":["Kezdésként állj rá egy gumiszalagra úgy, hogy az már nyújtott karnál megfeszüljön.","Fordítsd el a csuklódat, hogy a tenyered előre nézzen.","Fújd ki a levegőt, és közben nyomd fel a fogantyúkat, amíg a karod teljesen ki nem nyúlik a fejed fölött."],"en":["To begin, stand on an exercise band so that tension begins at arm's length.","Rotate the wrists so that the palms of your hands are facing forward.","As you exhale, lift the handles up until your arms are fully extended overhead."]},"reviewed":false,"summaryMethod":"source-extract"},"Shoulder_Raise":{"version":1,"steps":{"hu":["Engedd le lazán a karodat a tested mellé, húzd fel a válladat a füled felé, majd engedd vissza."],"en":["Relax your arms to your sides and raise your shoulders up toward your ears, then back down."]},"reviewed":false,"summaryMethod":"source-extract"},"Shoulder_Stretch":{"version":1,"steps":{"hu":["Nyújtsd át a bal karodat a tested előtt, és tartsd egyenesen."],"en":["Reach your left arm across your body and hold it straight."]},"reviewed":false,"summaryMethod":"source-extract"},"Side-Lying_Floor_Stretch":{"version":1,"steps":{"hu":["Először feküdj a bal oldaladra, és hajlítsd be magad előtt a bal térdedet, hogy megtámaszd a törzsedet (a hasizmaidat is használd, hogy megtartsd magad).","Nyújtsd ki a jobb lábadat, és a jobb lábfejedet tedd le a talajra a bal mögé."],"en":["First lie on your left side, bending your left knee in front of you to stabilize your torso (use your abdominal muscles as well to hold you upright).","Straighten your right leg and rest the right foot on the floor behind your left."]},"reviewed":false,"summaryMethod":"source-extract"},"Side_Bridge":{"version":1,"steps":{"hu":["Feküdj oldalra, könyököd a vállad alatt, lábaid egymáson.","Emeld a csípőd, tarts egyenes vonalat a fejed és lábad között.","Ne ejtsd be a vállad; lassan engedd vissza a csípőd."],"en":["Lie on your side with your elbow below your shoulder and feet stacked.","Lift your hips into a straight line from head to feet.","Keep your shoulder supported; lower your hips slowly."]},"reviewed":true,"summaryMethod":"curated"},"Side_Hop-Sprint":{"version":1,"steps":{"hu":["Állj egy bója vagy gát mellé.","A gyakorlatot azzal kezdd, hogy oldalirányban átszökkensz az akadály fölött, majd a talajfogásból azonnal elrugaszkodva visszaszökkensz oda, ahonnan indultál.","Szökdelj a lehető leggyorsabban az előírt ismétlésszámban, és a gyakorlatot úgy fejezd be, hogy az utolsó szökkenés talajfogása után rövid távot sprintelsz."],"en":["Stand to the side of a cone or hurdle.","Begin this drill by hopping sideways over the obstacle, rebounding out of your landing to hop back to where you started.","Hop for a prescribed number or repetitions as quickly as possible, and finish this drill by sprinting a short distance upon landing the last hop."]},"reviewed":false,"summaryMethod":"source-extract"},"Side_Jackknife":{"version":1,"steps":{"hu":["Feküdj oldalra, felső kezed tedd a fejed mellé.","Emeld a felső lábad, és oldalsó haspréssel közelítsd hozzá a törzsed.","Ne húzd a nyakad; lassan engedd le a lábad és a törzsed."],"en":["Lie on your side with your upper hand beside your head.","Raise your top leg and side-crunch your torso toward it.","Do not pull your neck; lower your leg and torso slowly."]},"reviewed":true,"summaryMethod":"curated"},"Side_Lateral_Raise":{"version":1,"steps":{"hu":["Állj stabilan, a súlyzók a tested mellett legyenek, könyököd enyhén hajlítva.","Emeld a karod oldalra vállmagasságig.","Törzsed maradjon stabil; lassan engedd le."],"en":["Stand steady with dumbbells by your sides and elbows slightly bent.","Raise your arms out to shoulder height.","Keep your torso still; lower slowly."]},"reviewed":true,"summaryMethod":"curated"},"Side_Laterals_to_Front_Raise":{"version":1,"steps":{"hu":["Állva tarts egy pár kézisúlyzót a tested mellett.","Kontrollált mozdulattal engedd le a súlyokat.","Engedd le a súlyokat a kiinduló helyzetbe."],"en":["In a standing position, hold a pair of dumbbells at your side.","Lower the weights with a controlled motion.","Lower the weights to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Side_Leg_Raises":{"version":1,"steps":{"hu":["Állj egy szék mellé, amelybe támaszként megkapaszkodhatsz.","Nyújtva tartott lábadat emeld oldalra, amilyen messzire csak tudod, majd lendítsd vissza le úgy, hogy keresztezze a másik lábadat."],"en":["Stand next to a chair, which you may hold onto as a support.","Keeping your leg straight, raise it as far out to the side as possible, and swing it back down, allowing it to cross the opposite leg."]},"reviewed":false,"summaryMethod":"source-extract"},"Side_Lying_Groin_Stretch":{"version":1,"steps":{"hu":["Kezdésként feküdj a jobb oldaladra, és hajlítsd be magad előtt a jobb térdedet, hogy megtámaszd a törzsedet.","A fejedet pihentesd a jobb kezeden vagy a válladon.","Húzd a bal térdedet a bal vállad felé, és közben nyomd a lábfejedet vagy a térdedet lefelé, a talaj irányába."],"en":["Start off by lying on your right side and bend your right knee in front of you to stabilize the torso.","Rest your head on your right hand or shoulder.","Pull your left knee in toward your left shoulder and simultaneously press your foot or knee down to the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Side_Neck_Stretch":{"version":1,"steps":{"hu":["Laza vállal indulj, és döntsd finoman a fejedet a vállad felé.","Segítsd a nyújtást úgy, hogy a kezeddel finoman húzod a fejed oldalát."],"en":["Start with your shoulders relaxed, gently tilt your head towards your shoulder.","Assist stretch with a gentle pull on the side of the head."]},"reviewed":false,"summaryMethod":"source-extract"},"Side_Standing_Long_Jump":{"version":1,"steps":{"hu":["Állj csípőszéles terpeszbe, atlétikus alapállásba.","Dőlj jobbra, majd a csípőd, a térded és a bokád kinyújtásával rugaszkodj el.","Érkezz ugyanabba az irányba nézve, csípőszéles terpeszben, és az alsótesteddel tompítsd a talajfogás erejét."],"en":["Begin standing with your feet hip width apart in an athletic stance.","Leaning to your right, extend through your hips, knees, and ankles to jump into the air.","Land facing the same direction with your feet hip width apart, absorbing the impact through your lower body."]},"reviewed":false,"summaryMethod":"source-extract"},"Side_To_Side_Chins":{"version":1,"steps":{"hu":["Fogd meg a húzódzkodó rudat széles fogással, előre néző tenyérrel.","Egy másodpercnyi megfeszítés után ereszkedj vissza a kiinduló helyzetbe, közben lélegezz be.","Egy másodpercnyi megfeszítés után ereszkedj vissza a kiinduló helyzetbe, közben lélegezz be."],"en":["Grab the pull-up bar with the palms facing forward using a wide grip.","After a second of contraction, inhale as you go back to the starting position.","After a second of contraction, inhale as you go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Side_Wrist_Pull":{"version":1,"steps":{"hu":["Ez a nyújtás állva működik a legjobban.","Lassan nyújtsd ki, húzd, és emeld fel vállmagasságig, ahogy a képen látható."],"en":["This stretch works best standing.","Slowly straighten, pull, and lift it up to shoulder height, as pictured."]},"reviewed":false,"summaryMethod":"source-extract"},"Side_to_Side_Box_Shuffle":{"version":1,"steps":{"hu":["Állj a doboz egyik oldalára úgy, hogy a bal lábad a doboz közepén legyen.","Kezdésként ugorj fel és át a doboz másik oldalára úgy, hogy a jobb lábad a doboz tetejére, a bal lábad pedig a talajra érkezzen.","Folytasd az oda-vissza szökdelést a dobozon át."],"en":["Stand to one side of the box with your left foot resting on the middle of it.","To begin, jump up and over to the other side of the box, landing with your right foot on top of the box and your left foot on the floor.","Continue shuffling back and forth across the box."]},"reviewed":false,"summaryMethod":"source-extract"},"Single-Arm_Cable_Crossover":{"version":1,"steps":{"hu":["Fogd a két felső csiga fogantyúját, és lépj előre. Kezeid találkozzanak a tested előtt.","Az egyik kart tartsd helyben, a másikat nyisd oldalra, majd húzd vissza középre.","Könyököd enyhén hajlítva maradjon; váltogasd az oldalakat."],"en":["Hold both high-pulley handles and step forward with your hands together in front.","Keep one arm still; open the other to the side, then pull it back to the centre.","Keep a slight elbow bend and alternate sides."]},"reviewed":true,"summaryMethod":"curated"},"Single-Arm_Linear_Jammer":{"version":1,"steps":{"hu":["Helyezz egy rudat landmine-talpba, vagy rögzítsd biztonságosan egy sarokba.","A mozdulathoz nyújtsd ki a könyöködet, és nyomd fel a súlyt.","Térj vissza a kiinduló helyzetbe."],"en":["Position a bar into a landmine or securely anchor it in a corner.","Perform the movement by extending the elbow, pressing the weight up.","Return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Single-Arm_Push-Up":{"version":1,"steps":{"hu":["Feküdj hasra a talajon.","Ereszkedj le a könyököd hajlításával, amíg meg nem érinted a talajt.","Lassan ereszkedj, majd a karod kinyújtásával fordítsd meg a mozgást, és térj vissza a kiinduló helyzetbe."],"en":["Begin laying prone on the ground.","Lower yourself by allowing the elbow to flex until you touch the ground.","Descend slowly, and reverse direction be extending the arm to return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Single-Cone_Sprint_Drill":{"version":1,"steps":{"hu":["Ez a gyakorlat a gyors lábmunkát tanítja.","Dolgozz a lábaddal apró, szapora léptekkel, amilyen gyorsan csak tudsz, határozott karmunkával.","Három kör megtétele után pihenj."],"en":["This drill teaches quick foot action.","Chop the feet as quickly as possible, blocking with the arms.","Rest after three trips around the cone."]},"reviewed":false,"summaryMethod":"source-extract"},"Single-Leg_High_Box_Squat":{"version":1,"steps":{"hu":["Helyezz egy dobozt az állványba.","Állj a doboz elé, majd lépj fel rá teljesen kiegyenesedve, a másik lábadat pedig hagyd megtámasztás nélkül.","Folytasd a fel- és lelépést ugyanazzal a lábbal, majd válts a másik oldalra."],"en":["Position a box in a rack.","Standing in front of it, step onto the box to a full standing position, letting your other leg remain unsupported.","."]},"reviewed":false,"summaryMethod":"source-extract"},"Single-Leg_Hop_Progression":{"version":1,"steps":{"hu":["Állíts fel magad előtt egy sor bóját.","Bójáról bójára ellenmozgásos (rásüllyedésből indított) ugrással szökdelj.","A sor végén fordulj meg, és a másik lábadon gyere vissza."],"en":["Arrange a line of cones in front of you.","Use a countermovement jump to hop from cone to cone.","At the end, turn around and go back on the other leg."]},"reviewed":false,"summaryMethod":"source-extract"},"Single-Leg_Lateral_Hop":{"version":1,"steps":{"hu":["Állj egy bója vagy gát mellé.","Érkezz az elrugaszkodó lábadra, és azonnal rugaszkodj el újra, visszaugorva a kiinduló helyzetbe.","Folytasd az oda-vissza szökdelést."],"en":["Stand to the side of a cone or hurdle.","Land on your jumping leg, and immediately rebound out of it by jumping back to the start position.","Continue hopping back and forth."]},"reviewed":false,"summaryMethod":"source-extract"},"Single-Leg_Leg_Extension":{"version":1,"steps":{"hu":["Ülj be a gépbe, és állítsd be úgy, hogy megfelelő helyzetben legyél.","Helyes testtartás mellett nyújtsd ki teljesen az egyik lábadat, és a mozdulat tetején tarts szünetet.","Térj vissza a kiinduló helyzetbe anélkül, hogy a súly megállna, így az izom végig feszülés alatt marad."],"en":["Seat yourself in the machine and adjust it so that you are positioned properly.","Maintaining good posture, fully extend one leg, pausing at the top of the motion.","Return to the starting position without letting the weight stop, keeping tension on the muscle."]},"reviewed":false,"summaryMethod":"source-extract"},"Single-Leg_Stride_Jump":{"version":1,"steps":{"hu":["Állj egy doboz mellé úgy, hogy a belső lábad a doboz tetején legyen, közel a széléhez.","Kezdésként lendítsd a karodat felfelé, közben rugaszkodj el a dobozon lévő lábaddal, és ugorj fel, amilyen magasra csak tudsz.","Érkezz ugyanabba a helyzetbe, ahonnan indultál, és a belső lábaddal fékezd le a talajfogást."],"en":["Stand to the side of a box with your inside foot on top of it, close to the edge.","Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible.","Land in the same position that you started, using your inside leg to decelerate the impact."]},"reviewed":false,"summaryMethod":"source-extract"},"Single_Dumbbell_Raise":{"version":1,"steps":{"hu":["Széles terpeszben tarts egy kézisúlyzót két kézzel úgy, hogy a markolat helyett a súlyzó fejét fogod.","Emeld a súlyt vállmagasság fölé, végig nyújtott karral.","Térj vissza a kiinduló helyzetbe, és ismételd az előírt ismétlésszámban."],"en":["With a wide stance, hold a dumbell with both hands, grasping the head of the dumbbell instead of the handle.","Raise the weight until it is above shoulder level, keeping your arms extended.","Return to the starting position and repeat for the recommended amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Single_Leg_Butt_Kick":{"version":1,"steps":{"hu":["Állj egy lábra, a másik térdedet hajlítva emeld fel.","Azonnal hajlítsd be a térdedet, és próbáld megérinteni a fenekedet az elrugaszkodó lábad sarkával.","Vidd vissza a lábadat részben hajlított helyzetbe a csípőd alá, és érkezz le."],"en":["Begin by standing on one leg, with the bent knee raised.","Immediately flex the knee and attempt to touch your butt with the heel of your jumping leg.","Return the leg to a partially bent position underneath the hips and land."]},"reviewed":false,"summaryMethod":"source-extract"},"Single_Leg_Glute_Bridge":{"version":1,"steps":{"hu":["Feküdj hanyatt a talajra, a talpad legyen a talajon, a térded behajlítva.","A mozdulathoz told magad a sarkadon keresztül, nyújtsd felfelé a csípődet, és emeld el a farizmodat a talajról.","Nyújtsd ki a csípődet, amennyire csak tudod, tarts szünetet, majd térj vissza a kiinduló helyzetbe."],"en":["Lay on the floor with your feet flat and knees bent.","Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.","Extend as far as possible, pause and then return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Single_Leg_Push-off":{"version":1,"steps":{"hu":["Állj a talajon úgy, hogy az egyik lábad a dobozon van, a sarkad közel a széléhez.","Rugaszkodj el a dobozon lévő lábaddal, és a csípőd meg a térded kinyújtásával próbálj minél magasabbra emelkedni.","Érkezz ugyanazzal a lábbal a doboz tetejére, a másik lábadat pedig vidd vissza a kiinduló helyzetbe."],"en":["Stand on the ground with one foot resting on the box, heel close to the edge.","Push off with your foot on top of the box, trying to gain as much height as possible by extending through the hip and knee.","Land with the same foot on top of the box, returning your other foot back to the start position."]},"reviewed":false,"summaryMethod":"source-extract"},"Sit-Up":{"version":1,"steps":{"hu":["Feküdj le a talajra, a lábfejedet akaszd be valami mozdíthatatlan tárgy alá, vagy kérd meg egy társadat, hogy fogja le.","Emeld fel a felsőtestedet úgy, hogy a combjaiddal képzeletbeli V alakot formáljon.","Miután egy másodpercig érezted a megfeszítést, engedd vissza a felsőtestedet a kiinduló helyzetbe, közben lélegezz be."],"en":["Lie down on the floor placing your feet either under something that will not move or by having a partner hold them.","Elevate your upper body so that it creates an imaginary V-shape with your thighs.","Once you feel the contraction for a second, lower your upper body back down to the starting position while inhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Sit_Squats":{"version":1,"steps":{"hu":["Állj vállszéles terpeszbe.","A mozdulatot a térded és a csípőd hajlításával kezdd, a csípődet hátratolva, mintha leülnél.","Folytasd, amíg részben le nem guggoltál, de még a párhuzamos fölött vagy, majd gyorsan fordítsd meg a mozgást, és térj vissza a kiinduló helyzetbe."],"en":["Stand with your feet shoulder width apart.","Begin the movement by flexing your knees and hips, sitting back with your hips.","Continue until you have squatted a portion of the way down, but are above parallel, and quickly reverse the motion until you return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Skating":{"version":1,"steps":{"hu":["A görkorcsolyázás szórakoztató tevékenység, amely hatékonyan javíthatja a szív- és légzőrendszeri állóképességet, valamint az izom-állóképességet.","Korcsolyázhatsz kényelmes tempóban 30 percen át megszakítás nélkül."],"en":["Roller skating is a fun activity which can be effective in improving cardiorespiratory fitness and muscular endurance.","You can skate at a comfortable pace for 30 minutes straight."]},"reviewed":false,"summaryMethod":"source-extract"},"Sled_Drag_-_Harness":{"version":1,"steps":{"hu":["Kezdésként pakold meg a szánt a kívánt súllyal, és rögzítsd a húzóhevedert.","Akár előre, akár hátrafelé húzol, dőlj a haladás irányába, és a csípőd meg a térded kinyújtásával haladj."],"en":["To begin, load the sled with the desired weight and attach the pulling strap.","Whether pulling forwards or backwards, lean in the direction of travel and progress by extending through the hips and knees."]},"reviewed":false,"summaryMethod":"source-extract"},"Sled_Overhead_Backward_Walk":{"version":1,"steps":{"hu":["Rögzíts két fogantyút a szánhoz kötéllel vagy lánccal.","Fordulj a szán felé, és hátrálj, amíg a kötél meg nem feszül.","Sétálj hátrafelé, a karodat végig a fejed fölött tartva."],"en":["Attach dual handles to a sled connected by a rope or chain.","Face the sled, backing up until there is some tension in the line.","Walk backwards, keeping your arms raised above your head."]},"reviewed":false,"summaryMethod":"source-extract"},"Sled_Overhead_Triceps_Extension":{"version":1,"steps":{"hu":["Rögzíts két fogantyút a szánhoz lánccal vagy kötéllel.","Nyújtsd ki a könyöködet, hogy a karod kiegyenesedjen.","A teljes kinyújtás után lépj előre, hogy a kötél újra megfeszüljön."],"en":["Attach dual handles to a sled using a chain or rope.","Extend through the elbow to straighten the arm.","Upon full extension, step forward to take the slack out of the line."]},"reviewed":false,"summaryMethod":"source-extract"},"Sled_Push":{"version":1,"steps":{"hu":["Pakold meg a tolószánt a kívánt súllyal.","Vegyél fel atlétikus testtartást, dőlj a szánnak teljesen nyújtott karral, és fogd meg a fogantyúkat."],"en":["Load your pushing sled with the desired weight.","Take an athletic posture, leaning into the sled with your arms fully extended, grasping the handles."]},"reviewed":false,"summaryMethod":"source-extract"},"Sled_Reverse_Flye":{"version":1,"steps":{"hu":["Rögzíts két fogantyút a szánhoz kötéllel vagy lánccal.","A könyököd hajlítása nélkül húzd a fogantyúkat felfelé és szét, fordított tárogatást végezve némi kifelé rotációval.","Térj vissza a kiinduló helyzetbe, és lépj néhányat hátra, hogy a kötél újra megfeszüljön."],"en":["Attach dual handles to a sled connected by a rope or chain.","Without flexing the elbow, pull the handles upward and apart, performing a reverse fly with some external rotation.","Return to the starting position, taking a couple steps back to take the slack out of the line."]},"reviewed":false,"summaryMethod":"source-extract"},"Sled_Row":{"version":1,"steps":{"hu":["Rögzíts két fogantyút a szánhoz kötéllel vagy lánccal.","A mozdulat indításához hajlítsd be a könyöködet, közben zárd a lapockáidat, és húzd magad felé a szánt.","Lépj egyet-kettőt hátra, hogy a kötél megfeszüljön, és ismételd."],"en":["Attach dual handles to a sled connected by a rope or chain.","To initiate the movement, flex the elbow as you retract your shoulder blades, pulling the sled towards you.","Take a step or two back to get tension in the line and repeat."]},"reviewed":false,"summaryMethod":"source-extract"},"Sledgehammer_Swings":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz egy gumiabroncsra és egy pörölyre (nagykalapácsra) lesz szükséged.","Ha jobbkezes vagy, a bal kezed legyen a nyél végén, a jobb kezed pedig feljebb, a fejhez közelebb fogjon.","Amikor felemeled a pörölyt, a jobb kezed a fej felé csúszik; amikor lesújtasz, a jobb kezed lecsúszik a bal kezed mellé."],"en":["You will need a tire and a sledgehammer for this exercise.","If you are right handed, your left hand should be at the bottom of the handle, and your right hand should be choking up closer to the head.","As you bring the sledge up, your right hand slides toward the head; as you swing down, your right hand will slide down to join your left hand."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Incline_Shoulder_Raise":{"version":1,"steps":{"hu":["Tegyél egy ferde padot a Smith-gép alá.","Fújd ki a levegőt, és közben told fel a rudat, amíg a karod teljesen ki nem nyúlik.","Ha végeztél, tedd vissza a rudat a tartóba."],"en":["Place an incline bench underneath the smith machine.","As you breathe out, lift the bar up until your arms are fully extended.","When you are done, place the bar back in the rack."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Machine_Behind_the_Back_Shrug":{"version":1,"steps":{"hu":["A rudat állítsd combmagasságba, és pakolj fel megfelelő súlyt.","A mozdulat indításához húzd a válladat egyenesen felfelé.","Rövid szünet után engedd vissza a súlyt a kiinduló helyzetbe."],"en":["With the bar at thigh level, load an appropriate weight.","Initiate the movement by shrugging your shoulders straight up.","After a brief pause return the weight to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Machine_Bench_Press":{"version":1,"steps":{"hu":["Tegyél egy sík padot a Smith-gép alá.","Egy másodperc szünet után fújd ki a levegőt, és a mellizmaid erejével nyomd vissza a rudat a kiinduló helyzetbe.","Ha végeztél, akaszd vissza a rudat a tartóba."],"en":["Place a flat bench underneath the smith machine.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles.","When you are done, lock the bar back in the rack."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Machine_Bent_Over_Row":{"version":1,"steps":{"hu":["Állítsd a Smith-gép rúdját kb.","Most fogd meg a rudat felső (pronált) fogással, és akaszd ki a Smith-gép tartójából.","Lassan engedd vissza a súlyt a kiinduló helyzetbe, közben lélegezz be."],"en":["Set the barbell attached to the smith machine to a height that is about 2 inches below your knees.","Now grasp the barbell using an overhand (pronated) grip and unlock it from the smith machine rack.","Slowly lower the weight again to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Machine_Calf_Raise":{"version":1,"steps":{"hu":["Tegyél egy emelvényt vagy súlytárcsát a Smith-gép rúdja alá.","Emeld a sarkadat a lehető legmagasabbra úgy, hogy a talpad elülső részéről tolod el magad, és a mozdulat tetején feszítsd meg a vádlidat.","A sarkadat leengedve térj vissza lassan a kiinduló helyzetbe, közben lélegezz be."],"en":["Place a block or weight plate below the bar on the Smith machine.","Raise your heels as high as possible by pushing off of the balls of your feet, flexing your calf at the top of the contraction.","Return slowly to the starting position as you breathe in while lowering your heels."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Machine_Close-Grip_Bench_Press":{"version":1,"steps":{"hu":["Tegyél egy sík padot a Smith-gép alá.","Egy másodperc szünet után fújd ki a levegőt, és a tricepszed erejével nyomd vissza a rudat a kiinduló helyzetbe.","Ha végeztél, akaszd vissza a rudat a tartóba."],"en":["Place a flat bench underneath the smith machine.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles.","When you are done, lock the bar back in the rack."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Machine_Decline_Press":{"version":1,"steps":{"hu":["Helyezz egy negatív (lejtős) padot az állványba úgy, hogy a rúd a mellkasod fölé kerüljön.","A mozdulatot a karod hajlításával kezdd, és engedd le a rudat a mellkasodra.","A kívánt ismétlésszám elvégzése után fordítsd el a rudat, hogy visszaakaszd a súlyt."],"en":["Position a decline bench in the rack so that the bar will be above your chest.","Begin the movement by flexing your arms, lowering the bar to your chest.","After completing the desired number of repetitions, rotate the bar to rack the weight."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Machine_Hang_Power_Clean":{"version":1,"steps":{"hu":["Állítsd a rudat térdmagasságba, és pakold fel megfelelő súllyal.","A teljes kinyúlás után hajlítsd be újra a csípődet és a térdedet, hogy lejjebb kerülj a rúd fogadásához.","A mozdulat befejezéséhez nyújtsd ki a csípődet és a térdedet, és állj fel úgy, hogy a rúd a válladon nyugszik."],"en":["Position the bar at knee height and load it to an appropriate weight.","Upon full extension, rebend the hips and knees to lower your receiving position.","Extend through the hips and knees to come to a standing position with the bar racked on your shoulders to complete the movement."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Machine_Hip_Raise":{"version":1,"steps":{"hu":["Helyezz egy padot az állványba, és pakold fel a rudat megfelelő súllyal.","A mozdulat indításához billentsd a medencédet, és a gerinced hajlításával emeld el a csípődet a padról.","Rövid szünet után engedd vissza a csípődet a padra."],"en":["Position a bench in the rack and load the bar to an appropriate weight.","Initiate the movement by rotating your pelvis, flexing your spine to raise your hips off of the bench.","After a brief pause, return the hips to the bench."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Machine_Incline_Bench_Press":{"version":1,"steps":{"hu":["Tegyél egy ferde padot a Smith-gép alá.","Egy másodperc szünet után fújd ki a levegőt, és a mellizmaid erejével nyomd vissza a rudat a kiinduló helyzetbe.","Ha végeztél, tedd vissza a rudat a tartóba."],"en":["Place an incline bench underneath the smith machine.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles.","When you are done, place the bar back in the rack."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Machine_Leg_Press":{"version":1,"steps":{"hu":["Állítsd a Smith-gép rúdját kb.","A mozdulatot azzal kezdd, hogy a talpaddal felfelé tolod a rudat, közben kinyújtod a csípődet és a térdedet.","A mozdulat tetején tarts rövid szünetet, majd térj vissza a kiinduló helyzetbe."],"en":["Position a Smith machine bar a couple feet off of the ground.","Begin the movement by driving through your feet to move the bar upward, extending the hips and knees.","At the top of the motion, pause briefly before returning to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Machine_One-Arm_Upright_Row":{"version":1,"steps":{"hu":["A rudat állítsd combmagasságba, és pakolj fel megfelelő súlyt.","A mozdulatot a könyököd hajlításával kezdd, és emeld a felkarodat kifelé néző könyökkel.","Rövid szünet után engedd vissza a súlyt a kiinduló helyzetbe."],"en":["With the bar at thigh level, load an appropriate weight.","Begin the movement by flexing the elbow, raising the upper arm with the elbow pointed out.","After a brief pause, return the weight to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Machine_Overhead_Shoulder_Press":{"version":1,"steps":{"hu":["Kezdésként tegyél egy sík padot (vagy lehetőleg háttámlás padot) a Smith-gép alá.","Kezdd el lassan leengedni a rudat, amíg az álladdal egy magasságba nem kerül, közben lélegezz be.","Ezután a vállad erejével nyomd vissza a rudat a kiinduló helyzetbe, közben fújd ki a levegőt."],"en":["To begin, place a flat bench (or preferably one with back support) underneath a smith machine.","Slowly begin to lower the barbell until it is level with your chin while inhaling.","Then lift the barbell back to the starting position using your shoulders while exhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Machine_Pistol_Squat":{"version":1,"steps":{"hu":["Kezdésként állítsd a rudat a magasságodnak leginkább megfelelő helyzetbe.","Az egyik lábadat tedd kb.","Lent tarts rövid szünetet, majd a sarkadon keresztül tolva magad, a térded és a csípőd kinyújtásával térj vissza a kiinduló helyzetbe."],"en":["To begin, first set the bar to a position that best matches your height.","Move one foot forward about 12 inches in front of the bar.","Pause briefly at the bottom and then return to the starting position by driving through the heel of your foot, extending the knee and hip."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Machine_Reverse_Calf_Raises":{"version":1,"steps":{"hu":["Állítsd a Smith-gép rúdját a magasságodhoz, és tegyél egy emelvényt pontosan a rúd alá.","Most vidd a válladat a rúd alá a leírt lábtartást megtartva, és a csípőd meg a térded kinyújtásával told fel a rudat, amíg a törzsed ki nem egyenesedik.","Lassan ereszkedj vissza a kiinduló helyzetbe a talpad elülső részét és a lábujjaidat leengedve, közben lélegezz be."],"en":["Adjust the barbell on the smith machine to fit your height and align a raised platform right under the bar.","Now, place your shoulders under the barbell while maintaining the foot positioning described and push the barbell up by extending your hips and knees until your torso is standing erect.","Slowly go back down to the starting position as you breathe in by lowering the balls of your feet and toes."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Machine_Squat":{"version":1,"steps":{"hu":["Kezdésként állítsd a rudat a magasságodnak leginkább megfelelő helyzetbe.","Állj vállszéles, közepes terpeszbe, enyhén kifelé néző lábujjakkal.","Fújd ki a levegőt, és közben kezdd el felfelé tolni a rudat úgy, hogy a sarkaddal tolod a talajt, újra kinyújtod a lábadat, és visszatérsz a kiinduló helyzetbe."],"en":["To begin, first set the bar on the height that best matches your height.","Position your legs using a shoulder width medium stance with the toes slightly pointed out.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Machine_Stiff-Legged_Deadlift":{"version":1,"steps":{"hu":["Kezdésként állítsd a Smith-gép rúdját nagyjából a combod közepének magasságába.","A térdedet mozdulatlanul tartva, derékból hajolva, egyenes háttal engedd le a rudat a lábfejed fölé.","Amint érzed a combhajlító nyúlását, kezdd el újra felegyenesíteni a törzsedet a csípőd és a derekad kinyújtásával, amíg vissza nem érsz a kiinduló helyzetbe."],"en":["To begin, set the bar on the smith machine to a height that is around the middle of your thighs.","Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the waist while keeping your back straight.","Start bringing your torso up straight again as soon as you feel the hamstrings stretch by extending your hips and waist until you are back at the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Machine_Upright_Row":{"version":1,"steps":{"hu":["Kezdésként állítsd a Smith-gép rúdját nagyjából a combod közepének magasságába.","A vállad oldalsó részével húzd fel a rudat, közben fújd ki a levegőt.","Engedd vissza lassan a rudat a kiinduló helyzetbe."],"en":["To begin, set the bar on the smith machine to a height that is around the middle of your thighs.","Use your side shoulders to lift the bar as you exhale.","Lower the bar back down slowly to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Smith_Single-Leg_Split_Squat":{"version":1,"steps":{"hu":["Kezdésként tegyél egy sík padot kb.","Kezdd el lassan leengedni a rudat a térded hajlításával, egyenes testtartással, felemelt fejjel.","Cserélj lábat, és ismételd meg a mozdulatot."],"en":["To begin, place a flat bench 2-3 feet behind the smith machine.","Begin to slowly lower the bar by bending the knee as you maintain a straight posture with the head up.","Switch legs and repeat the movement."]},"reviewed":false,"summaryMethod":"source-extract"},"Snatch":{"version":1,"steps":{"hu":["Állj vállszéles terpeszbe úgy, hogy a rúd pontosan a lábujjaid töve fölött legyen.","Amikor a rúd a combod közepéhez ér, told a talajt a lábaddal, és robbanékony mozdulattal nyújtsd ki teljesen a testedet.","A mozdulat befejezéséhez állj fel a guggolásból."],"en":["Place your feet at a shoulder width stance with the barbell resting right above the connection between the toes and the rest of the foot.","As the bar reaches the middle of your thighs, push the floor with your legs and lift your body to a complete extension in an explosive motion.","Finalize the movement by rising up out of the squat position to finish the lift."]},"reviewed":false,"summaryMethod":"source-extract"},"Snatch_Balance":{"version":1,"steps":{"hu":["Indulj úgy, hogy a lábad húzó helyzetben van, a rúd a vállad hátsó részén nyugszik, a kezed pedig széles szakító fogásban fogja.","Fogadd a rudat a fejed fölött, teljesen kinyújtott karral, közel a guggolás alsó pontjához.","Ereszkedj tovább teljes mélységig, majd állj fel."],"en":["Begin with the feet in the pulling position, the bar racked across the back of the shoulders, and the hands placed in a wide snatch grip.","Receive the bar locked out overhead near the bottom of the squat.","Continue to descend to full depth, and return to a standing position."]},"reviewed":false,"summaryMethod":"source-extract"},"Snatch_Deadlift":{"version":1,"steps":{"hu":["A szakító fogású felhúzás a szakítás első húzását erősíti.","A mozdulat indításához told magad a sarkadon keresztül, és emeld a csípődet.","Ekkor told előre a csípődet a rúd felé, miközben hátradőlsz."],"en":["The snatch deadlift strengthens the first pull of the snatch.","Initiate the movement by driving through the heels, raising the hips.","At that point, drive your hips through the bar as you lay back."]},"reviewed":false,"summaryMethod":"source-extract"},"Snatch_Pull":{"version":1,"steps":{"hu":["A rúd legyen a talajon, közel a sípcsontodhoz; fogd meg széles szakító fogással.","Ezután következik a második húzás, amely a húzás fő gyorsító szakasza.","A súly gyorsításához nem kell a karoddal aktívan húznod; a második húzás végén a tested legyen teljesen kinyújtva, enyhén hátradőlve."],"en":["With a barbell on the floor close to the shins, take a wide snatch grip.","Next comes the second pull, the main source of acceleration for the pull.","There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back."]},"reviewed":false,"summaryMethod":"source-extract"},"Snatch_Shrug":{"version":1,"steps":{"hu":["Indulj széles fogással, a rúd lógjon a combközép magasságában.","Húzd fel a válladat a füled felé."],"en":["Begin with a wide grip, with the bar hanging at the mid thigh position.","Shrug your shoulders towards your ears."]},"reviewed":false,"summaryMethod":"source-extract"},"Snatch_from_Blocks":{"version":1,"steps":{"hu":["Indulj úgy, hogy a felpakolt rúd a kívánt magasságú dobozokon (bakokon) vagy állványokon fekszik.","Válts át a második húzásba a csípőd, a térded és a bokád kinyújtásával, a lehető leggyorsabban hajtva felfelé a rudat.","A rudat tartsd a sarkad elülső része fölött, a fejedet és a mellkasodat fent, majd a sarkadon keresztül tolva magad állj fel."],"en":["Begin with a loaded barbell on boxes or stands of the desired height.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible.","Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position."]},"reviewed":false,"summaryMethod":"source-extract"},"Speed_Band_Overhead_Triceps":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz rögzíts egy gumiszalagot a talaj közelében.","A mozdulathoz nyújtsd ki a könyöködet, hogy a karod kiegyenesedjen, és ügyelj rá, hogy a felkarod a helyén maradjon.","Tarts szünetet, majd térj vissza a kiinduló helyzetbe."],"en":["For this exercise anchor a band to the ground.","To perform the movement, extend through the elbow to to straighten your arms, ensuring that you keep your upper arm in place.","Pause, and then return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Speed_Box_Squat":{"version":1,"steps":{"hu":["Rögzíts a rúdra olyan gumiszalagokat, amelyek a talaj közelében biztonságosan ki vannak kötve.","Helyezd a rudat a hátad felső részére, a lapockáidat zárd össze, a hátadat homorítsd, és tetőtől talpig feszíts meg mindent.","Tarts rövid szünetet, majd robbanj fel a dobozról a csípőd és a térded kinyújtásával."],"en":["Attach bands to the bar that are securely anchored near the ground.","Position the bar on your upper back, shoulder blades retracted, back arched and everything tight head to toe.","Pause briefly, and explode off of the box, extending through the hips and knees."]},"reviewed":false,"summaryMethod":"source-extract"},"Speed_Squats":{"version":1,"steps":{"hu":["Ezt a gyakorlatot a biztonság kedvéért guggolókeretben érdemes végezni.","Lépj el az állványtól, és állj vállszéles, közepes terpeszbe, enyhén kifelé néző lábujjakkal.","Fújd ki a levegőt, és közben kezdd el a lehető leggyorsabban, de lendület nélkül felfelé tolni a rudat úgy, hogy főként a sarkaddal tolod a talajt, újra kinyújtod a lábadat, és visszatérsz a kiinduló helyzetbe."],"en":["This exercise is best performed inside a squat rack for safety purposes.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out.","Begin to raise the bar as fast as possible without involving momentum as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Spell_Caster":{"version":1,"steps":{"hu":["Fogj mindkét kezedbe egy-egy kézisúlyzót felső fogással.","A karodat egyenesen, a súlyzókat pedig a talajjal párhuzamosan tartva fordítsd el a törzsedet, és lendítsd át a súlyokat a másik oldaladra.","Folytasd váltakozva, egyik oldalról a másikra fordulva, amíg a sorozat véget nem ér."],"en":["Hold a dumbbell in each hand with a pronated grip.","Keeping your arms straight and the dumbbells parallel to the ground, rotate your torso to swing the weights to your opposite side.","Continue alternating, rotating from one side to the other until the set is complete."]},"reviewed":false,"summaryMethod":"source-extract"},"Spider_Crawl":{"version":1,"steps":{"hu":["Helyezkedj el hason fekve a talajon.","A mozdulat indításához emeld el az egyik lábadat a talajról.","Vidd vissza ezt a lábadat a kiinduló helyzetbe, és ismételd meg a másik oldalon."],"en":["Begin in a prone position on the floor.","Initiate the movement by raising one foot off of the ground.","Return this leg to the starting position and repeat on the opposite side."]},"reviewed":false,"summaryMethod":"source-extract"},"Spider_Curl":{"version":1,"steps":{"hu":["Kezdésként tedd a rudat a Scott-pad azon részére, ahol normál esetben ülnél.","Fogd meg a rudat alsó fogással (felfelé néző tenyérrel), nagyjából vállszélességben vagy annál kicsit szűkebben.","Kezdd el lassan visszaengedni a rudat a kiinduló helyzetbe, közben lélegezz be."],"en":["Start out by setting the bar on the part of the preacher bench that you would normally sit on.","Use your arms to grab the barbell with a supinated grip (palms facing up) at about shoulder width apart or slightly closer from each other.","Slowly begin to bring the barbell back to the starting position as your breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Spinal_Stretch":{"version":1,"steps":{"hu":["Ülj egy székre egyenes háttal, talpad legyen a földön.","Csavard el a felsőtestedet az egyik oldalra, amennyire csak tudod, kb.","Térj vissza függőleges helyzetbe, majd ismételd meg a másik oldalra."],"en":["Sit in a chair so your back is straight and your feet planted on the floor.","Twist your upper body to one side about 3 times as far as you can.","Return to upright position and then repeat for your other side."]},"reviewed":false,"summaryMethod":"source-extract"},"Split_Clean":{"version":1,"steps":{"hu":["A rúd a földön legyen, közel a sípcsontodhoz.","Amint elérted a teljes nyújtást, kezdd a harmadik húzást: erőteljesen vonj vállat és hajlítsd a karodat, a könyököd felfelé és kifelé mutat.","Azonnal állj fel: told át a sarkadon, tartsd egyenesen a törzsedet és felfelé a könyöködet."],"en":["With a barbell on the floor close to the shins, take an overhand grip just outside the legs.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out.","Immediately recover by driving through the heels, keeping the torso upright and elbows up."]},"reviewed":false,"summaryMethod":"source-extract"},"Split_Jerk":{"version":1,"steps":{"hu":["Állj úgy, hogy a súly a válladon, a mellkasod előtt nyugszik, és kezdd a lendítő lehajlással.","Abban a rövid pillanatban, amikor a lábad nem nyomja aktívan a talajt, a rúd felfelé nyomására tett erőfeszítésed lefelé nyom téged.","Térj vissza álló helyzetbe, és hozd össze a lábaidat."],"en":["Standing with the weight racked on the front of the shoulders, begin with the dip.","In the brief moment the feet are not actively driving against the platform, the athlete's effort to push the bar up will drive them down.","Return to a standing position, bringing the feet together."]},"reviewed":false,"summaryMethod":"source-extract"},"Split_Jump":{"version":1,"steps":{"hu":["Vegyél fel kitöréses állást: az egyik lábad elöl, a térde hajlítva, a hátsó térded majdnem a földet érinti.","Mindkét lábad nyújtásával ugorj olyan magasra, amennyire csak tudsz, a karjaiddal lendítve a nagyobb emelkedésért.","Nyeld el a landolás ütését, és térj vissza a kiinduló helyzetbe."],"en":["Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.","Extending through both legs, jump as high as possible, swinging your arms to gain lift.","Absorb the impact by reverting back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Split_Snatch":{"version":1,"steps":{"hu":["Kezdd egy megterhelt rúddal a földön.","Miközben a lábadat a fogadó helyzetbe mozgatod, erőteljesen húzd magad a rúd alá, miközben a rudat a fejed fölé emeled.","Óvatosan tedd vissza a súlyt a földre."],"en":["Begin with a loaded barbell on the floor.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead.","Carefully return the weight to floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Split_Squat_with_Dumbbells":{"version":1,"steps":{"hu":["Tarts kézisúlyzókat a tested mellett. Hátsó lábfejed támaszd a padra.","Hajlítsd az elülső térded, engedd le a csípőd.","Az elülső talpaddal nyomd vissza magad; térded kövesse a lábfejed irányát."],"en":["Hold dumbbells by your sides with your rear foot supported on a bench.","Bend your front knee to lower your hips.","Push through your front foot to stand; let the knee track with the foot."]},"reviewed":true,"summaryMethod":"curated"},"Split_Squats":{"version":1,"steps":{"hu":["Állj álló helyzetben.","Ahogy leereszkedsz, azonnal fordítsd meg a mozgást: állj vissza, és ugorj úgy, hogy közben felcseréled a lábaid helyzetét."],"en":["Being in a standing position.","As you descend, immediately reverse direction, standing back up and jumping, reversing the position of your legs."]},"reviewed":false,"summaryMethod":"source-extract"},"Squat_Jerk":{"version":1,"steps":{"hu":["Állj úgy, hogy a súly a válladon, a mellkasod előtt nyugszik, és kezdd a lendítő lehajlással.","Abban a pillanatban, ahogy a lábad elhagyja a földet, a lábat minél gyorsabban a fogadó helyzetbe kell helyezni.","A rudat tartsd a sarkad elülső része fölött, a fejed és a mellkasod felfelé, told át a sarkadon, hogy felállj."],"en":["Standing with the weight racked on the front of the shoulders, begin with the dip.","At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible.","Keeping the bar aligned over the front of the heels, your head and chest up, drive throught heels of the feet to move to a standing position."]},"reviewed":false,"summaryMethod":"source-extract"},"Squat_with_Bands":{"version":1,"steps":{"hu":["Rögzítsd a gumiszalagokat a rúd végein, az állvány rúdtartóihoz, az állványhoz vagy kézisúlyzókhoz, hogy megfelelő feszítés alakuljon ki.","A hátad, a vállad és a törzsed legyen feszes, told ki a térdedet és a feneked, és kezdd meg a lemenetelt.","A súlyt tartsd a sarkadon, told kifelé a lábadat és a térdedet, és told fel magad, miközben a fejeddel vezeted a mozgást."],"en":["Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent.","Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head."]},"reviewed":false,"summaryMethod":"source-extract"},"Squat_with_Chains":{"version":1,"steps":{"hu":["A láncok beállításához akaszd át a vezetőláncot a rúd végein.","A hátad, a vállad és a törzsed legyen feszes, told ki a térdedet és a feneked, és kezdd meg a lemenetelt.","A súlyt tartsd a sarkadon, told kifelé a lábadat és a térdedet, és told fel magad, miközben a fejeddel vezeted a mozgást."],"en":["To set up the chains, begin by looping the leader chain over the sleeves of the bar.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent.","Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head."]},"reviewed":false,"summaryMethod":"source-extract"},"Squat_with_Plate_Movers":{"version":1,"steps":{"hu":["Először állítsd a rudat az állványon közvetlenül a vállmagasság alá.","Told fel a rudat, miközben kifújod a levegőt: told a talpad sarkával a földet, és nyújtsd ki a csípődet és a térdedet.","Helyezd a belső lábadat a súlytárcsára, és vegyél fel széles terpeszt a következő ismétléshez."],"en":["To begin, first set the bar on a rack to just below shoulder level.","Raise the bar as you exhale by pushing the floor with the heels of your feet as you extend the hips and knees.","Place your inside foot on the weight plate, adopting a wide stance for the next repetition."]},"reviewed":false,"summaryMethod":"source-extract"},"Squats_-_With_Bands":{"version":1,"steps":{"hu":["Először győződj meg róla, hogy a gumiszalag egyenlően oszlik el a tested bal és jobb oldala között.","Lassan kezdd el hajlítani a térdedet és leengedni a tested, amíg a combod párhuzamos nem lesz a talajjal, közben fújd ki a levegőt.","A talpad sarkával told fel a tested a kiinduló helyzetbe, közben fújd ki a levegőt."],"en":["To start out, make sure that the exercise band is at an even split between both the left and right side of the body.","Slowly start to bend the knees and lower the legs so that your thighs are parallel to the floor while exhaling.","Use the heel of your feet to push your body up to the starting position as you exhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Stairmaster":{"version":1,"steps":{"hu":["Lépj fel a lépcsőzőgépre, és válaszd ki a kívánt opciót a menüből.","Mozgasd a lábadat fel-le egyenletes ritmusban, nyomd lefelé a pedálokat, de ne egészen a földig.","A lépcsőzőgépek kényelmesek, kardiovaszkuláris előnyökkel járnak, és általában kisebb terhelést jelentenek, mint a szabadtéri futás."],"en":["To begin, step onto the stairmaster and select the desired option from the menu.","Pump your legs up and down in an established rhythm, driving the pedals down but not all the way to the floor.","Stairmasters offer convenience, cardiovascular benefits, and usually have less impact than running outside."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Alternating_Dumbbell_Press":{"version":1,"steps":{"hu":["Állj egyenesen, mindkét kezedben egy-egy kézisúlyzóval.","Nyújtsd ki az egyik karodat, és told egyenesen felfelé a súlyzót, a másik kezed maradjon a helyén.","Rövid szünet után engedd vissza a súlyt a kiinduló helyzetbe."],"en":["Stand with a dumbbell in each hand.","Extend one arm to press the dumbbell straight up, keeping your off hand in place.","After a brief pause, return the weight to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Barbell_Calf_Raise":{"version":1,"steps":{"hu":["Ezt a gyakorlatot biztonsági okokból legjobb guggolóállványban végezni.","Lépj el az állványtól, és állj vállszéles terpeszben, a lábfejek kissé kifelé néznek.","Lassan térj vissza a kiinduló helyzetbe, miközben beszívod a levegőt: engedd le a sarkadat a boka hajlításával, amíg a vádlid meg nem nyúlik."],"en":["This exercise is best performed inside a squat rack for safety purposes.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Barbell_Press_Behind_Neck":{"version":1,"steps":{"hu":["Ezt a gyakorlatot legjobb guggolóállványban végezni, hogy könnyebb legyen felvenni a rudat.","Lépj el az állványtól, és állj vállszéles terpeszben, a lábfejek kissé kifelé néznek.","Tartsd meg a megfeszített helyzetet egy másodpercig, majd engedd vissza a rudat a kiinduló helyzetbe, közben szívd be a levegőt."],"en":["This exercise is best performed inside a squat rack for easier pick up of the bar.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out.","Hold the contraction for a second and lower the barbell back down to the starting position by inhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension":{"version":1,"steps":{"hu":["Fogj egy kézisúlyzót az egyik kezedbe úgy, hogy a tenyered a törzsed felé néz, hajlítsd meg kicsit a térdedet, és dőlj előre a derekadnál hajolva, egyenes háttal, amíg a hátad majdnem párhuzamos nem lesz a talajjal.","A felkarodat mozdulatlanul tartva told fel a súlyt a tricepsszel, miközben kifújod a levegőt, amíg az alkarod párhuzamos nem lesz a talajjal, és a teljes karod ki nem nyúlik.","Cserélj kart, és ismételd meg a gyakorlatot."],"en":["With a dumbbell in one hand and the palm facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor.","Keeping the upper arms stationary, use the triceps to lift the weights as you exhale until the forearms are parallel to the floor and the whole arm is extended.","Switch arms and repeat the exercise."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension":{"version":1,"steps":{"hu":["Fogj mindkét kezedbe egy-egy kézisúlyzót úgy, hogy a tenyered a törzsed felé néz, hajlítsd meg kicsit a térdedet, és dőlj előre a derekadnál hajolva, egyenes háttal, amíg a hátad majdnem párhuzamos nem lesz a talajjal.","A felkarodat mozdulatlanul tartva told fel a súlyokat a tricepsszel, miközben kifújod a levegőt, amíg az alkarod párhuzamos nem lesz a talajjal, és a teljes karod ki nem nyúlik.","Egy másodpercnyi megfeszítés után a csúcspontban lassan engedd vissza a kézisúlyzókat a kiinduló helyzetbe, közben szívd be a levegőt."],"en":["With a dumbbell in each hand and the palms facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor.","Keeping the upper arms stationary, use the triceps to lift the weights as you exhale until the forearms are parallel to the floor and the whole arms are extended.","After a second contraction at the top, slowly lower the dumbbells back to their starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Biceps_Cable_Curl":{"version":1,"steps":{"hu":["Állj egyenesen, törzsed függőleges, és fogj egy alsó csigára csatlakoztatott kábeles hajlítórudat.","A felkarodat mozdulatlanul tartva hajlítsd a súlyt, és feszítsd meg a bicepszedet, miközben kifújod a levegőt.","Lassan kezdd el visszavinni a hajlítórudat a kiinduló helyzetbe, közben szívd be a levegőt."],"en":["Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out.","Slowly begin to bring the curl bar back to starting position as your breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Biceps_Stretch":{"version":1,"steps":{"hu":["Kulcsold össze a kezeidet a hátad mögött, a tenyereid érjenek össze, nyújtsd ki a karjaidat, majd forgasd el őket úgy, hogy a tenyered lefelé nézzen.","Emeld fel a karjaidat, és tartsd meg, amíg nyújtást nem érzel a bicepszedben."],"en":["Clasp your hands behind your back with your palms together, straighten arms and then rotate them so your palms face downward.","Raise your arms up and hold until you feel a stretch in your biceps."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Bradford_Press":{"version":1,"steps":{"hu":["Helyezz egy megterhelt rudat vállmagasságba az állványon.","Told vissza a rudat a fejed fölé a könyököd kinyújtásával.","Ezt váltogatva ismételd az előírt ismétlésszám eléréséig."],"en":["Place a loaded bar at shoulder level in a rack.","Lift the bar back over your head by extending the elbows","Alternate in this manner until you complete the recommended amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Cable_Chest_Press":{"version":1,"steps":{"hu":["Állítsd a két csigát mellmagasságba, és válassz megfelelő súlyt.","A test többi részét mozdulatlanul tartva nyújtsd ki a könyöködet, és told előre a fogantyúkat úgy, hogy összehozod őket magad előtt.","Tarts szünetet a mozgás csúcspontján, majd térj vissza a kiinduló helyzetbe."],"en":["Position dual pulleys to chest height and select an appropriate weight.","Keeping the rest of the body stationary, extend through the elbows to press the handles forward, drawing them together in front of you.","Pause at the top of the motion, and return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Cable_Lift":{"version":1,"steps":{"hu":["Csatlakoztass egy szabványos fogantyút a tornyon, és told a kábelt a legalsó csigahelyzetbe.","Egyetlen mozdulattal húzd a fogantyút felfelé és át a tested előtt, amíg a karod teljesen kinyújtva a fejed fölé nem kerül.","Ezután helyezkedj át, és ismételd meg ugyanezt a mozdulatsort a másik oldalon."],"en":["Connect a standard handle on a tower, and move the cable to the lowest pulley position.","In one motion, pull the handle up and across your body until your arms are in a fully-extended position above your head.","Then, reposition and repeat the same series of movements on the opposite side."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Cable_Wood_Chop":{"version":1,"steps":{"hu":["Csatlakoztass egy szabványos fogantyút a toronyhoz, és told a kábelt a legmagasabb csigahelyzetbe.","Egyetlen mozdulattal húzd a fogantyút lefelé és át a tested előtt az elülső térdedhez, miközben elforgatod a törzsedet.","Ezután helyezkedj át, és ismételd meg ugyanezt a mozdulatsort a másik oldalon."],"en":["Connect a standard handle to a tower, and move the cable to the highest pulley position.","In one motion, pull the handle down and across your body to your front knee while rotating your torso.","Then, reposition and repeat the same series of movements on the opposite side."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Calf_Raises":{"version":1,"steps":{"hu":["A gép párnái a válladon legyenek. Lábujjpárnád támaszd az emelvényre.","Emeld a sarkad, állj lábujjhegyre.","Lassan engedd le a sarkad; ne rugózz."],"en":["Set the machine pads on your shoulders, balls of your feet on the platform.","Raise your heels onto your toes.","Lower your heels slowly; do not bounce."]},"reviewed":true,"summaryMethod":"curated"},"Standing_Concentration_Curl":{"version":1,"steps":{"hu":["Fogj egy kézisúlyzót a dolgozó kezedbe, és dőlj előre.","Hajlítsd a könyöködet, és emeld a súlyt, a felkarodat mozdulatlanul tartva.","Engedd vissza a kézisúlyzót a kiinduló helyzetbe."],"en":["Taking a dumbbell in your working hand, lean forward.","Flex the elbow to curl the weight, keeping the upper arm stationary.","Lower the dumbbell back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Dumbbell_Calf_Raise":{"version":1,"steps":{"hu":["Állj egyenes törzzsel, mindkét kezedben egy-egy kézisúlyzóval az oldalad mellett.","A lábujjak mutathatnak egyenesen előre (hogy minden részt egyenletesen terheljen), befelé (a külső fej nagyobb hangsúlyáért) vagy kifelé (a belső fej nagyobb hangsúlyáért).","Belégzés közben térj vissza a kiinduló helyzetbe a sarkad lassú leengedésével."],"en":["Stand with your torso upright holding two dumbbells in your hands by your sides.","With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves.","As you inhale, go back to the starting position by slowly lowering the heels."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Dumbbell_Press":{"version":1,"steps":{"hu":["Állj vállszéles terpeszben, és fogj egy-egy kézisúlyzót mindkét kezedbe.","Szigorú technikával, lábtolás és hátradőlés nélkül nyújtsd ki a könyöködet, és told a súlyokat együtt egyenesen a fejed fölé.","Tarts szünetet, majd lassan engedd vissza a súlyt a kiinduló helyzetbe."],"en":["Standing with your feet shoulder width apart, take a dumbbell in each hand.","Maintaining strict technique with no leg drive or leaning back, extend through the elbow to raise the weights together directly above your head.","Pause, and slowly return the weight to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Dumbbell_Reverse_Curl":{"version":1,"steps":{"hu":["Állj egyenesen, mindkét kezedben egy-egy kézisúlyzóval, felső fogással (tenyér lefelé néz).","A felkarodat mozdulatlanul tartva hajlítsd a súlyokat, és feszítsd meg a bicepszedet, miközben kifújod a levegőt.","Lassan kezdd el visszavinni a kézisúlyzókat a kiinduló helyzetbe, közben szívd be a levegőt."],"en":["To begin, stand straight with a dumbbell in each hand using a pronated grip (palms facing down).","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out.","Slowly begin to bring the dumbbells back to starting position as your breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head":{"version":1,"steps":{"hu":["Tartsd a kézisúlyzókat a combod előtt, a tenyered a combod felé néz.","Emeld a kézisúlyzókat félkör alakú mozdulattal a fejed fölé, karnyújtásnyira, közben fújd ki a levegőt.","Lassan térj vissza a kiinduló helyzetbe ugyanazon az úton, közben szívd be a levegőt."],"en":["Hold the dumbbells in front of your thighs, palms facing your thighs.","Raise the dumbbells in a semicircular motion to arm's length overhead as you exhale.","Slowly return to the starting position using the same path as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Dumbbell_Triceps_Extension":{"version":1,"steps":{"hu":["Állj fel úgy, hogy egy kézisúlyzót két kézzel tartasz.","A felkarodat közel tartva a fejedhez, a könyököd befelé, a talajra merőlegesen, engedd le a súlyt félkör alakú mozdulattal a fejed mögé, amíg az alkarod nem érinti a bicepszedet.","Térj vissza a kiinduló helyzetbe úgy, hogy a tricepsszel felemeled a kézisúlyzót."],"en":["To begin, stand up with a dumbbell held by both hands.","Keeping your upper arms close to your head with elbows in and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps.","Go back to the starting position by using the triceps to raise the dumbbell."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Dumbbell_Upright_Row":{"version":1,"steps":{"hu":["Fogj egy-egy kézisúlyzót mindkét kezedbe felső fogással (a tenyér előre néz), a vállszélességnél kicsit szűkebben.","Az oldalsó vállizmoddal told fel a kézisúlyzókat, közben fújd ki a levegőt.","Lassan engedd vissza a kézisúlyzókat a kiinduló helyzetbe."],"en":["Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width.","Use your side shoulders to lift the dumbbells as you exhale.","Lower the dumbbells back down slowly to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Elevated_Quad_Stretch":{"version":1,"steps":{"hu":["Állj háttal egy padnak vagy lépcsőfoknak, tőle kb.","Emeld fel az egyik lábadat hátra, és helyezd a lábfejedet a padra, vagy a lábfejed felső részével, vagy a lábujjpárnáddal, amelyik kényelmesebb.","A támaszkodó térded legyen enyhén behajlítva, és ne engedd, hogy kiessen a lábujjaid vonalán túlra."],"en":["Start by standing with your back about two to three feet away from a bench or step.","Lift one leg behind you and rest your foot on the step,either on your instep or the ball of your foot, whichever you find most comfortable.","Keep your supporting knee slightly bent and avoid letting that knee extend out beyond your toes."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Front_Barbell_Raise_Over_Head":{"version":1,"steps":{"hu":["Állj egyenesen, a kezedben egy rúddal.","Emeld a rudat egyenesen a fejed fölé, közben fújd ki a levegőt.","Amikor megérzed a megfeszítést, kezdd el leengedni a rudat a kiinduló helyzetbe, közben szívd be a levegőt."],"en":["To begin, stand straight with a barbell in your hands.","Lift the barbell up until it is directly over your head while exhaling.","Once you feel the contraction, begin to lower the barbell back down to the starting position as you inhale."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Gastrocnemius_Calf_Stretch":{"version":1,"steps":{"hu":["Tedd a jobb sarkadat egy lépcsőfokra kinyújtott térddel, és dőlj előre, hogy a jobb kezeddel megfogd a jobb lábujjadat.","A testsúlyodat a bal lábadra helyezd, a bal kezedet pedig tedd a bal combodra.","Húzd a jobb lábujjaidat a térded felé, amíg nyújtást nem érzel a vádlidban."],"en":["Place your right heel on a step with your knee extended and lean forward to grab your right toe with your right hand.","Support your weight on your left leg and place your left hand on your left thigh.","Pull your right toes toward your knee until you feel a stretch in your calf."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Hamstring_and_Calf_Stretch":{"version":1,"steps":{"hu":["Kezdd azzal, hogy egy övet, gumiszalagot vagy kötelet hurkolsz az egyik lábad köré.","Hajlítsd meg a hátsó lábadat, miközben az elülső egyenes marad.","Az övvel húzd meg a lábfejed tetejét, hogy fokozd a nyújtást a vádlidban."],"en":["Being by looping a belt, band, or rope around one foot.","Bend your back leg, while keeping the front one straight.","Using the belt, pull on the top of the foot to increase the stretch in the calf."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Hip_Circles":{"version":1,"steps":{"hu":["Állj az egyik lábadon, és tarts meg egy függőleges támasztékot.","Nyisd ki a csípődet, amennyire csak tudod, és próbálj nagy kört rajzolni a térdeddel.","Végezd el ezt a mozdulatot lassan több ismétlésben, majd ismételd meg a másik oldalon."],"en":["Begin standing on one leg, holding to a vertical support.","Open the hip as far as possible, attempting to make a big circle with your knee.","Perform this movement slowly for a number of repetitions, and repeat on the other side."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Hip_Flexors":{"version":1,"steps":{"hu":["Állj egyenesen, függőleges gerinccel, a bal lábad kissé a jobb előtt.","Hajlítsd meg mindkét térdedet, és emeld fel a hátsó sarkadat a földről, miközben a jobb csípődet előre tolod."],"en":["Stand up straight with the spine vertical, the left foot slightly in front of the right.","Bend both knees and lift the back heel off the floor as you press the right hip forward."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Inner-Biceps_Curl":{"version":1,"steps":{"hu":["Állj fel, mindkét kezedben egy-egy kézisúlyzóval, karnyújtásnyira tartva.","Csak az alkarnak szabad mozognia.","Lassan kezdd el visszavinni a kézisúlyzókat a kiinduló helyzetbe, közben szívd be a levegőt."],"en":["Stand up with a dumbbell in each hand being held at arms length.","Only the forearms should move.","Slowly begin to bring the dumbbells back to the starting position as your breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Lateral_Stretch":{"version":1,"steps":{"hu":["Állj a csípőszélességnél kicsit szélesebb terpeszbe, a térded legyen enyhén behajlítva.","Emeld fel a bal karodat függőlegesen, és tedd a bal kezedet a fejed mögé.","A testsúlyod oszoljon el egyenlően a két lábad között (ne dőlj rá a bal csípődre)."],"en":["Take a slightly wider than hip distance stance with your knees slightly bent.","Raise your left arm in a vertical line and place your left hand behind your head.","Keep your weight evenly distributed between both legs (don't lean into your left hip)."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Leg_Curl":{"version":1,"steps":{"hu":["Állítsd be a gép karját a magasságodhoz, és helyezkedj el úgy, hogy a törzsed a derekadnál kb.","Kifújás közben hajlítsd fel a jobb lábadat, amennyire csak tudod, anélkül, hogy a felsőcombod elemelnéd a párnától.","Most végezd el ugyanezt a gyakorlatot a bal lábbal."],"en":["Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad.","As you exhale, curl your right leg up as far as possible without lifting the upper leg from the pad.","Perform the same exercise now for the left leg."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Long_Jump":{"version":1,"steps":{"hu":["Ezt a gyakorlatot legjobb homokban vagy más puha földet érési felületen végezni.","Próbálj úgy landolni, hogy a lábaid magad előtt vannak, és a lábaiddal a lehető legmesszebbre nyúlsz.","Mérd meg a távolságot a landolási pont és a kiindulópont között, és jegyezd fel az eredményt."],"en":["This drill is best done in sand or other soft landing surface.","Attempt to land with your feet out in front you, reaching as far as possible with your legs.","Measure the distance from your landing point to the starting point and track results."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Low-Pulley_Deltoid_Raise":{"version":1,"steps":{"hu":["Állj az alsó csigás evezőgép jobb oldalára.","Kezdd el a bal kezeddel a tested előtt kifelé emelni a fogantyút, amíg vállmagasságba nem ér, közben fújd ki a levegőt.","Cserélj kart, és ismételd meg a gyakorlatot."],"en":["Start by standing to the right side of a low pulley row.","Begin to use the left hand and come across your body out until it is elevated to shoulder height while exhaling.","Switch arms and repeat the exercise."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Low-Pulley_One-Arm_Triceps_Extension":{"version":1,"steps":{"hu":["Fogj meg egy egyszeres fogantyút a bal karoddal az alsó csigás gép mellett.","Térj vissza a kiinduló helyzetbe úgy, hogy a tricepsszel felemeled az egyszeres fogantyút.","Cserélj kart, és ismételd meg a gyakorlatot."],"en":["Grab a single handle with your left arm next to the low pulley machine.","Go back to the starting position by using the triceps to raise the single handle.","Switch arms and repeat the exercise."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Military_Press":{"version":1,"steps":{"hu":["Állj stabilan, a rúd az elülső válladon legyen. Feszítsd meg a törzsed.","Nyomd a rudat a fejed fölé.","Ne homoríts derékból; kontrolláltan engedd vállhoz."],"en":["Stand steady with the bar on your front shoulders and brace your trunk.","Press the bar overhead.","Avoid arching your lower back; lower to your shoulders with control."]},"reviewed":true,"summaryMethod":"curated","board":"img/fig/press.webp"},"Standing_Olympic_Plate_Hand_Squeeze":{"version":1,"steps":{"hu":["Állj egyenesen, mindkét kezedben egy-egy súlytárcsát tartva a pereménél, karnyújtásnyira, kalapácsfogással (tenyér befelé néz).","Engedd le a tárcsákat, amíg az ujjaid majdnem kinyúlnak, de még tartani tudják a súlyokat.","Most emeld vissza a tárcsákat a kiinduló helyzetbe a kezeid összezárásával, közben fújd ki a levegőt."],"en":["To begin, stand straight while holding a weight plate by the ridge at arm's length in each hand using a neutral grip (palms facing in).","Lower the plates until the fingers are nearly extended but can still hold weights.","Now raise the plates back to the starting position as you exhale by closing your hands."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_One-Arm_Cable_Curl":{"version":1,"steps":{"hu":["Kezdd azzal, hogy megfogsz egy egyszeres fogantyút az alsó csigás gép mellett.","Lassan kezdd el felfelé hajlítani az egyszeres fogantyút a felkarod mozdulatlanul tartásával, amíg az alkarod nem érinti a bicepszedet, közben fújd ki a levegőt.","Cserélj kart a gyakorlat közben."],"en":["Start out by grabbing single handle next to the low pulley machine.","Slowly begin to curl the single handle upwards while keeping the upper arm stationary until your forearm touches your bicep while exhaling.","Switch arms while performing this exercise."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench":{"version":1,"steps":{"hu":["Állj a ferde pad hátoldalához, mintha valakit biztosítanál.","A felkarodat mozdulatlanul tartva hajlítsd felfelé a kézisúlyzót, és feszítsd meg a bicepszedet, miközben kifújod a levegőt.","Cserélj kart a gyakorlat közben."],"en":["Stand on the back side of an incline bench as if you were going to be a spotter for someone.","While holding the upper arm stationary, curl the dumbbell upward while contracting the biceps as you breathe out.","Switch arms while performing this exercise."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_One-Arm_Dumbbell_Triceps_Extension":{"version":1,"steps":{"hu":["Állj fel úgy, hogy egy kézisúlyzót az egyik kezedben tartasz.","Térj vissza a kiinduló helyzetbe úgy, hogy a tricepsszel felemeled a kézisúlyzót.","Cserélj kart, és ismételd meg a gyakorlatot."],"en":["To begin, stand up with a dumbbell held in one hand.","Go back to the starting position by using the triceps to raise the dumbbell.","Switch arms and repeat the exercise."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Overhead_Barbell_Triceps_Extension":{"version":1,"steps":{"hu":["Tartsd a rudat a fejed fölött, könyököd előre nézzen.","Könyökhajlítással engedd a rudat a fejed mögé.","Felkarod maradjon stabil; nyújtsd vissza a könyököd."],"en":["Hold the bar overhead with your elbows pointing forward.","Bend your elbows to lower it behind your head.","Keep your upper arms steady; extend your elbows again."]},"reviewed":true,"summaryMethod":"curated"},"Standing_Palm-In_One-Arm_Dumbbell_Press":{"version":1,"steps":{"hu":["Kezdd úgy, hogy egy kézisúlyzót tartasz az egyik kezedben, a karod teljesen kinyújtva oldalra, kalapácsfogással.","Belégzés közben engedd le a súlyt, amíg a karod ismét 90 fokos szögben nem áll.","Cserélj kart, és ismételd meg a gyakorlatot."],"en":["Start by having a dumbbell in one hand with your arm fully extended to the side using a neutral grip.","While inhaling lower the weight down until your arm is at a 90 degree angle again.","Switch arms and repeat the exercise."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Palms-In_Dumbbell_Press":{"version":1,"steps":{"hu":["Kezdd úgy, hogy mindkét kezedben egy-egy kézisúlyzót tartasz, a karod teljesen kinyújtva oldalra, kalapácsfogással.","A kalapácsfogást tartsd meg az egész gyakorlat alatt.","Belégzés közben engedd le a súlyokat, amíg a karod ismét 90 fokos szögben nem áll."],"en":["Start by having a dumbbell in each hand with your arm fully extended to the side using a neutral grip.","Continue to maintain a neutral grip throughout the entire exercise.","While inhaling lower the weights down until your arm is at a 90 degree angle again."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl":{"version":1,"steps":{"hu":["Állj egyenesen, és tarts egy rudat a feneked mögött, karnyújtásnyira, felső fogással (a tenyered hátrafelé, a farizomtól elfelé néz), a kezeid vállszélességnyire legyenek egymástól.","Kifújás közben lassan emeld a rudat a csuklód félkör alakú hajlításával a plafon felé.","Amikor végeztél, a térded hajlításával tedd vissza a rudat a guggolóállványra vagy a földre."],"en":["Start by standing straight and holding a barbell behind your glutes at arm's length while using a pronated grip (palms will be facing back away from the glutes) and having your hands shoulder width apart from each other.","While exhaling, slowly elevate the barbell up by curling your wrist in a semi-circular motion towards the ceiling.","When finished, lower the barbell down to the squat rack or the floor by bending the knees."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Pelvic_Tilt":{"version":1,"steps":{"hu":["Kezdd csípőszéles terpeszben.","Hajlítsd meg kissé a térdedet, hogy lazák és rugalmasak maradjanak.","Érdemes néhányszor előre-hátra mozgatni a medencédet, mielőtt ebben a nyújtásban előre tartod a farokcsontodat."],"en":["Start off with your feet hip-distance apart.","Bend your knees slightly to keep them soft and springy.","You may want to move your pelvis forward and backward and back few times before holding the tailbone forward in this stretch."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Rope_Crunch":{"version":1,"steps":{"hu":["Rögzíts egy kötelet a felső csigára, és válassz megfelelő súlyt.","Végezd a mozdulatot a gerinc hajlításával, nyomd le a súlyt, amilyen mélyre csak tudod.","Tartsd meg a csúcsponti megfeszítést egy pillanatig, majd térj vissza a kiinduló helyzetbe."],"en":["Attach a rope to a high pulley and select an appropriate weight.","Perform the movement by flexing the spine, crunching the weight down as far as you can.","Hold the peak contraction for a moment before returning to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Soleus_And_Achilles_Stretch":{"version":1,"steps":{"hu":["Állj csípőszéles terpeszben, az egyik lábad kicsit a másik előtt.","Hajlítsd meg mindkét térdedet, a hátsó sarkadat tartsd a földön."],"en":["Stand with your feet hip-distance apart, one foot slightly in front of the other.","Bend both knees, keeping your back heel on the floor."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Toe_Touches":{"version":1,"steps":{"hu":["Állj úgy, hogy elöl és hátul is legyen egy kis hely körülötted.","Hajolj előre a derekadnál, a lábaidat egyenesen tartva, amíg el nem tudsz lazulni, és hagyod, hogy a felsőtested lelógjon előtted."],"en":["Stand with some space in front and behind you.","Bend at the waist, keeping your legs straight, until you can relax and let your upper body hang down in front of you."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Towel_Triceps_Extension":{"version":1,"steps":{"hu":["Állj fel úgy, hogy mindkét karod teljesen ki van nyújtva a fejed fölött, és mindkét kezeddel egy törölköző egyik végét fogod.","Most beszélj meg az edzőpartnereddel, hogy megfogja a törölköző másik végét, és ellenállást adjon.","Térj vissza a kiinduló helyzetbe úgy, hogy a tricepsszel felemeled a törölközőt."],"en":["To begin, stand up with both arms fully extended above the head holding one end of a towel with both hands.","Now communicate with your partner so that he/she can grip the other side of the towel to apply resistance.","Go back to the starting position by using the triceps to raise the towel."]},"reviewed":false,"summaryMethod":"source-extract"},"Standing_Two-Arm_Overhead_Throw":{"version":1,"steps":{"hu":["Állj vállszéles terpeszben, mindkét kezedben egy medicinlabdával.","Dobd el a labdát erőteljesen előre, a csípőben meghajolva, és az egész testedet használva a mozdulat befejezéséhez.","A medicinlabdát eldobhatod egy edzőpartnernek vagy egy falnak, és elkaphatod, amikor visszapattan."],"en":["Stand with your feet shoulder width apart holding a medicine ball in both hands.","Violently throw the ball forward, flexing at the hip and using your whole body to complete the movement.","The medicine ball can be thrown to a partner or to a wall, receiving it as it bounces back."]},"reviewed":false,"summaryMethod":"source-extract"},"Star_Jump":{"version":1,"steps":{"hu":["Kezdj ellazult állásban, a lábaid vállszélességnyire legyenek egymástól, és tartsd a karod közel a testedhez.","A mozdulat megkezdéséhez guggolj le félig, majd robbanékonyan ugorj fel olyan magasra, amennyire csak tudsz.","Landoláskor húzd vissza a végtagjaidat, és nyeld el az ütközést a lábaiddal."],"en":["Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.","To initiate the move, squat down halfway and explode back up as high as possible.","As you land, bring your limbs back in and absorb your impact through the legs."]},"reviewed":false,"summaryMethod":"source-extract"},"Step-up_with_Knee_Raise":{"version":1,"steps":{"hu":["Állj egy megfelelő magasságú doboz vagy pad felé fordulva, összezárt lábakkal.","Kezdd a mozdulatot a fellépéssel: helyezd a bal lábadat a pad tetejére.","Fordítsd meg a mozdulatot, hogy lelépj a dobozról, majd ismételd meg a sorozatot a másik lábbal."],"en":["Stand facing a box or bench of an appropriate height with your feet together.","Begin the movement by stepping up, putting your left foot on the top of the bench.","Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg."]},"reviewed":false,"summaryMethod":"source-extract"},"Step_Mill":{"version":1,"steps":{"hu":["Lépj fel a lépcsőzőgépre, és válaszd ki a kívánt opciót a menüből.","A lépcsőzőgépek kényelmesek, kardiovaszkuláris előnyökkel járnak, és általában kisebb terhelést jelentenek, mint a szabadtéri futás, miközben hasonló kalóriaégetést kínálnak."],"en":["To begin, step onto the stepmill and select the desired option from the menu.","Stepmills offer convenience, cardiovascular benefits, and usually have less impact than running outside while offering a similar rate of calories burned."]},"reviewed":false,"summaryMethod":"source-extract"},"Stiff-Legged_Barbell_Deadlift":{"version":1,"steps":{"hu":["Fogd meg a rudat felső fogással (tenyér lefelé néz).","A térdedet mozdulatlanul tartva engedd le a rudat a lábfejed fölé a csípőd hajlításával, miközben a hátad egyenes marad.","Kezdd el újra felegyenesíteni a törzsedet a csípőd kinyújtásával, amíg vissza nem érsz a kiinduló helyzetbe."],"en":["Grasp a bar using an overhand grip (palms facing down).","Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back straight.","Start bringing your torso up straight again by extending your hips until you are back at the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Stiff-Legged_Dumbbell_Deadlift":{"version":1,"steps":{"hu":["Fogj két kézisúlyzót, és tartsd őket az oldalad mellett, karnyújtásnyira.","A térdedet mozdulatlanul tartva engedd le a kézisúlyzókat a lábfejed fölé a derekadnál hajolva, miközben a hátad egyenes marad.","Kezdd el újra felegyenesíteni a törzsedet a csípőd és a derekad kinyújtásával, amíg vissza nem érsz a kiinduló helyzetbe."],"en":["Grasp a couple of dumbbells holding them by your side at arm's length.","Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight.","Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Stiff_Leg_Barbell_Good_Morning":{"version":1,"steps":{"hu":["Ezt a gyakorlatot biztonsági okokból legjobb guggolóállványban végezni.","Lépj el az állványtól, és állj vállszéles terpeszben.","Kezdd el felemelni a rudat a törzsed visszaemelésével a kiinduló helyzetbe, közben fújd ki a levegőt."],"en":["This exercise is best performed inside a squat rack for safety purposes.","Step away from the rack and position your legs using a shoulder width medium stance.","Begin to raise the bar as you exhale by elevating your torso back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Stomach_Vacuum":{"version":1,"steps":{"hu":["Állj egyenesen, a lábaid vállszélességnyire legyenek egymástól.","Egy izometriás megfeszítés kb.","Miután begyakoroltad a gyakorlatot, próbáld meg 20 másodpercnél tovább végezni."],"en":["To begin, stand straight with your feet shoulder width apart from each other.","One isometric contraction is around 20 seconds.","Once you have practiced this exercise, try to perform this exercise for longer than 20 seconds."]},"reviewed":false,"summaryMethod":"source-extract"},"Straight-Arm_Dumbbell_Pullover":{"version":1,"steps":{"hu":["Állíts egy kézisúlyzót függőlegesen egy sík padra.","A karodat egyenesen tartva lassan engedd le a súlyt ívben a fejed mögé, közben szívd be a levegőt, amíg nyújtást nem érzel a mellkasodon.","Tartsd a súlyt a kiinduló helyzetben egy másodpercig, és ismételd a mozdulatot az előírt ismétlésszámban."],"en":["Place a dumbbell standing up on a flat bench.","While keeping your arms straight, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.","Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Straight-Arm_Pulldown":{"version":1,"steps":{"hu":["Kezdd azzal, hogy megfogod a széles rudat egy lehúzógép felső csigájáról, a vállszélességnél szélesebb felső fogással (tenyér lefelé néz).","A karodat egyenesen tartva told le a rudat a széles hátizmod megfeszítésével, amíg a kezed a combod oldala mellé nem ér.","A karodat egyenesen tartva térj vissza a kiinduló helyzetbe, közben szívd be a levegőt."],"en":["You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip.","While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs.","While keeping the arms straight, go back to the starting position while breathing in."]},"reviewed":false,"summaryMethod":"source-extract"},"Straight_Bar_Bench_Mid_Rows":{"version":1,"steps":{"hu":["Helyezz egy megterhelt rudat a pad végére.","Told a rudat a törzsedhez a lapockáid összehúzásával és a könyököd hajlításával.","Rövid szünet után lassan engedd vissza a rudat a kiinduló helyzetbe, ügyelve rá, hogy egészen lemenjen."],"en":["Place a loaded barbell on the end of a bench.","Row the bar to your torso by retracting the shoulder blades and flexing the elbows.","After a brief pause, slowly return the bar to the starting position, ensuring to go all the way down."]},"reviewed":false,"summaryMethod":"source-extract"},"Straight_Raises_on_Incline_Bench":{"version":1,"steps":{"hu":["Helyezz egy rudat a földre a ferde pad fejrésze mögé.","Kezdésként emeld a rudat előre a fejed elé, miközben a karod végig kinyújtva marad.","Térj vissza a kiinduló helyzetbe."],"en":["Place a bar on the ground behind the head of an incline bench.","To begin, raise the barbell out in front of your head while keeping your arms extended.","Return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Stride_Jump_Crossover":{"version":1,"steps":{"hu":["Állj egy doboz oldalához úgy, hogy a belső lábad a tetején van, közel a széléhez.","Kezdd azzal, hogy felfelé lendíted a karodat, miközben a felső lábaddal elrugaszkodsz, és olyan magasra ugrasz, amennyire csak tudsz.","Érkezz az ellenkező helyzetben, mint ahonnan indultál, a doboz másik oldalán."],"en":["Stand to the side of a box with your inside foot on top of it, close to the edge.","Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible.","Land in the opposite position that you started, on the opposite side of the box."]},"reviewed":false,"summaryMethod":"source-extract"},"Sumo_Deadlift":{"version":1,"steps":{"hu":["Kezdd egy megterhelt rúddal a földön.","Amikor a rúd elhalad a térded mellett, dőlj hátra, és told a csípődet a rúdnak, miközben összehúzod a lapockáidat.","Told vissza a súlyt a földre a csípőd hajlításával, és kontrolláld a súlyt lefelé menet."],"en":["Begin with a bar loaded on the ground.","As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."]},"reviewed":false,"summaryMethod":"source-extract"},"Sumo_Deadlift_with_Bands":{"version":1,"steps":{"hu":["Rövid gumiszalagokkal való felhúzáshoz egyszerűen hurkold őket a rúdra indulás előtt, és lépj beléjük a beálláshoz.","Végy egy mély lélegzetet, majd told le a csípődet, a fejed előre néz, a mellkasod kihúzva.","Told vissza a súlyt a földre a csípőd hajlításával, és kontrolláld a súlyt lefelé menet."],"en":["To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up.","Take a breath, and then lower your hips, looking forward with your head with your chest up.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."]},"reviewed":false,"summaryMethod":"source-extract"},"Sumo_Deadlift_with_Chains":{"version":1,"steps":{"hu":["A láncokat felcsatolhatod a rúd végeire, vagy a közepüket átvetheted a rúdon, így emeléskor egyre nagyobb lesz a súly.","Végy egy nagy levegőt, majd süllyeszd le a csípődet, a fejed előre nézzen, a mellkasod legyen kitolva.","Tedd vissza a súlyt a földre úgy, hogy csípőből hajolsz előre, és kontrollálod a súlyt lefelé menet."],"en":["You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift.","Take a breath, and then lower your hips, looking forward with your head with your chest up.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."]},"reviewed":false,"summaryMethod":"source-extract"},"Superman":{"version":1,"steps":{"hu":["Kezdéshez feküdj hasra, nyújtott testtel a földön vagy egy tornaszőnyegen.","Egyszerre emeld fel a karjaidat, a lábaidat és a mellkasodat a talajról, és tartsd ezt a megfeszített helyzetet 2 másodpercig.","Lassan engedd vissza a karjaidat, a lábaidat és a mellkasodat a kiinduló helyzetbe, közben lélegezz be."],"en":["To begin, lie straight and face down on the floor or exercise mat.","Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds.","Slowly begin to lower your arms, legs and chest back down to the starting position while inhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Supine_Chest_Throw":{"version":1,"steps":{"hu":["Ez a gyakorlat remek mellkasi passzoláshoz, ha nincs partnered vagy elég erős falad.","Robbanékonyan told fel, a könyöködet kinyújtva, és dobd a labdát egyenesen magad fölé, minél magasabbra.","Kapd el a labdát mindkét kezeddel, ahogy lejön."],"en":["This drill is great for chest passes when you lack a partner or a wall of sufficient strength.","Explode up, extending through the elbow to throw the ball directly above you as high as possible.","Catch the ball with both hands as it comes down."]},"reviewed":false,"summaryMethod":"source-extract"},"Supine_One-Arm_Overhead_Throw":{"version":1,"steps":{"hu":["Feküdj hanyatt a földön, behajlított térddel.","A mozdulatot a válladból indítsd: dobd a labdát egyenesen előre, miközben felülsz, és próbálj a lehető legnagyobb távolságra dobni.","A labdát dobhatod egy partnernek, vagy pattintsd a falról."],"en":["Lay on the ground on your back with your knees bent.","Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.","The ball can be thrown to a partner or bounced off of a wall."]},"reviewed":false,"summaryMethod":"source-extract"},"Supine_Two-Arm_Overhead_Throw":{"version":1,"steps":{"hu":["Feküdj hanyatt a földön, behajlított térddel.","A mozdulatot a válladból indítsd: dobd a labdát egyenesen előre, miközben felülsz, és próbálj a lehető legnagyobb távolságra dobni.","A labdát dobhatod egy partnernek, vagy pattintsd a falról."],"en":["Lay on the ground on your back with your knees bent.","Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.","The ball can be thrown to a partner or bounced off of a wall."]},"reviewed":false,"summaryMethod":"source-extract"},"Suspended_Fallout":{"version":1,"steps":{"hu":["Állítsd be a pántokat úgy, hogy a fogantyúk megfelelő magasságban, derékszint alatt legyenek.","Tartsd nyújtva a karjaidat, és dőlj még tovább a függesztő pántokba, közelebb vive a testedet a talajhoz, miközben a válladat nyújtva a karjaid felfelé, a fejed fölé emelkednek.","Tarts egy kis szünetet a csúcsponti megfeszítésnél, majd térj vissza a kiinduló helyzetbe."],"en":["Adjust the straps so the handles are at an appropriate height, below waist level.","Keeping your arms straight, lean further into the suspension straps, bringing your body closer to the ground, allowing your shoulders to extend, raising your arms up and over your head.","Pause during the peak contraction, and then return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Suspended_Push-Up":{"version":1,"steps":{"hu":["Rögzítsd biztonságosan a függesztő pántokat egy állvány tetejéhez vagy más tárgyhoz.","Tartsd egyenesen és merev törzzsel a testedet, és lassan ereszkedj le a könyöködet behajlítva.","Menj le addig, amíg a könyököd 90 foknál jobban behajlik, majd tarts egy kis szünetet, mielőtt felnyomod magad a kiinduló helyzetbe."],"en":["Anchor your suspension straps securely to the top of a rack or other object.","Maintaining a straight, rigid torso, descend slowly by allowing the elbows to flex.","Continue until your elbows break 90 degrees, pausing before you extend to return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Suspended_Reverse_Crunch":{"version":1,"steps":{"hu":["Rögzíts egy függesztő pántot úgy, hogy a fogantyúk kb.","A mozdulatot a térded és a csípőd behajlításával kezdd, húzd a térdedet a törzsed felé.","A kontrollált mozdulat csúcspontján térj vissza a kiinduló helyzetbe."],"en":["Secure a set of suspension straps with the handles hanging about a foot off of the ground.","Begin the movement by flexing the knees and hips, drawing the knees to your torso.","At the top of the controlled motion, return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Suspended_Row":{"version":1,"steps":{"hu":["Függeszd fel a pántokat kb.","A mozdulatot a könyököd behajlításával kezdd.","A mozdulat végén tarts egy kis szünetet, majd térj vissza a kiinduló helyzetbe."],"en":["Suspend your straps at around chest height.","Begin by flexing the elbow to initiate the movement.","At the completion of the motion pause, and then return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Suspended_Split_Squat":{"version":1,"steps":{"hu":["Függeszd fel a pántokat úgy, hogy a fogantyúk kb.","Ereszkedj le a térded és a csípőd behajlításával, süllyeszd a tested a talaj felé.","A mozdulat alsó pontján fordítsd meg a mozgást: nyújtsd ki a csípődet és a térdedet, hogy visszatérj a kiinduló helyzetbe."],"en":["Suspend your straps so the handles are 18-30 inches from the floor.","Descend by flexing the knee and hips, lowering yourself to the ground.","At the bottom of the movement, reverse the motion, extending through the hip and knee to return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Svend_Press":{"version":1,"steps":{"hu":["Kezdj álló helyzetben.","Szorítsd össze a tárcsákat a tenyereid között, és kontrolláltan nyújtsd ki a karjaidat egyenesen előre.","Tarts egy kis szünetet a mozdulat csúcspontján, majd lassan térj vissza a kiinduló helyzetbe."],"en":["Begin in a standing position.","Squeeze the plates between your palms and extend your arms directly out in front of you in a controlled motion.","Pause at the top of the motion, and then slowly return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"T-Bar_Row_with_Handle":{"version":1,"steps":{"hu":["Rögzíts egy rudat egy landmine tartóban vagy egy sarokban, hogy ne mozduljon el.","Vegyél fel széles terpeszt, a csípőd legyen hátratolva, a mellkasod kitolva.","Egy rövid szünet után térj vissza a kiinduló helyzetbe."],"en":["Position a bar into a landmine or in a corner to keep it from moving.","Assume a wide stance with your hips back and your chest up.","After a brief pause, return to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Tate_Press":{"version":1,"steps":{"hu":["Feküdj egy sík padra, mindkét kezedben egy-egy kézisúlyzóval a combodon.","Tartsd mozdulatlanul a felkarodat, és lassan mozgasd a súlyzókat befelé és lefelé egy félkör alakú mozdulattal, amíg meg nem érintik a felső mellkasodat; közben lélegezz be.","Kilégzés közben told fel a súlyzókat a tricepszeddel, ugyanazzal a félkör alakú mozdulattal, de fordított irányban."],"en":["Lie down on a flat bench with a dumbbell in each hand on top of your thighs.","Keeping the upper arms stationary, slowly move the dumbbells in and down in a semi circular motion until they touch the upper chest while inhaling.","As you breathe out, move the dumbbells up using your triceps and the same semi-circular motion but in reverse."]},"reviewed":false,"summaryMethod":"source-extract"},"The_Straddle":{"version":1,"steps":{"hu":["Kezdj egyenes háttal ülő helyzetben.","A kezeidet a földre téve dőlj előre, ameddig csak tudsz."],"en":["Begin in a seated, upright position.","With your hands on the floor, lean forward as far as possible."]},"reviewed":false,"summaryMethod":"source-extract"},"Thigh_Abductor":{"version":1,"steps":{"hu":["Kezdéshez ülj le a combtávolító gépre, és válassz egy kényelmes súlyt.","Lassan told a lábaiddal a gépet, hogy távolodjanak egymástól, közben fújd ki a levegőt.","Érezd a megfeszítést egy másodpercig, majd kezdd visszavinni a lábaidat a kiinduló helyzetbe, közben lélegezz be."],"en":["To begin, sit down on the abductor machine and select a weight you are comfortable with.","Slowly press against the machine with your legs to move them away from each other while exhaling.","Feel the contraction for a second and begin to move your legs back to the starting position while breathing in."]},"reviewed":false,"summaryMethod":"source-extract"},"Thigh_Adductor":{"version":1,"steps":{"hu":["Ülj a gépbe, a párnákat állítsd a combod belső oldalához.","Zárd össze a lábaidat a gép ívét követve.","Törzsed maradjon támaszon; lassan engedd vissza."],"en":["Sit in the machine with the pads against your inner thighs.","Bring your legs together along the machine’s path.","Keep your torso supported; return slowly."]},"reviewed":true,"summaryMethod":"curated"},"Tire_Flip":{"version":1,"steps":{"hu":["Kezdj úgy, hogy a gumiabroncs aljánál, a futófelületnél fogod meg, és kicsit hátrébb helyezed a lábadat.","Az abroncs felemeléséhez nyújtsd ki a csípődet, a térdedet és a bokádat, nekifeszülve az abroncsnak, és told felfelé.","Amikor az abroncs eléri a 45 fokos szöget, lépj előre, és told a térdedet az abroncsnak."],"en":["Begin by gripping the bottom of the tire on the tread, and position your feet back a bit.","To lift the tire, extend through the hips, knees, and ankles, driving into the tire and up.","As the tire reaches a 45 degree angle, step forward and drive a knee into the tire."]},"reviewed":false,"summaryMethod":"source-extract"},"Toe_Touchers":{"version":1,"steps":{"hu":["Kezdéshez feküdj le a földre vagy egy tornaszőnyegre, a hátad legyen a talajra nyomva.","Mozgasd a karjaidat úgy, hogy teljesen kinyújtva, a talajhoz képest 45 fokos szögben álljanak.","Lassan kezdd leengedni a törzsedet és a karjaidat a kiinduló helyzetbe, közben lélegezz be."],"en":["To begin, lie down on the floor or an exercise mat with your back pressed against the floor.","Move your arms so that they are fully extended at a 45 degree angle from the floor.","Slowly begin to lower your torso and arms back down to the starting position while inhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Torso_Rotation":{"version":1,"steps":{"hu":["Állj egyenesen, és tarts egy fitlabdát mindkét kezeddel.","Forgasd el a törzsedet az egyik oldalra, miközben a szemed a labdán van."],"en":["Stand upright holding an exercise ball with both hands.","Rotate your torso to one side, keeping your eyes on the ball as you move."]},"reviewed":false,"summaryMethod":"source-extract"},"Trail_Running_Walking":{"version":1,"steps":{"hu":["A terepen való futás vagy túrázás szinte azonnal felpörgeti a vérkeringést és a szívverést.","Egy 68 kg-os ember 30 perc emelkedőn való gyaloglással több mint 200 kalóriát éget el, míg sík terepen ez 175."],"en":["Running or hiking on trails will get the blood pumping and heart beating almost immediately.","A 150 lb person can burn over 200 calories for 30 minutes walking uphill, compared to 175 on a flat surface."]},"reviewed":false,"summaryMethod":"source-extract"},"Trap_Bar_Deadlift":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz terhelj meg egy trap bart (hex bar), amely a földön nyugszik, megfelelő súllyal.","A mozdulatot a sarkaddal való elrugaszkodással kezdd, és nyújtsd ki a csípődet és a térdedet.","A mozdulat végén kontrolláltan engedd vissza a súlyt a földre."],"en":["For this exercise load a trap bar, also known as a hex bar, to an appropriate weight resting on the ground.","Begin the movement by driving through the heels and extend your hips and knees.","At the completion of the movement, lower the weight back to the ground under control."]},"reviewed":false,"summaryMethod":"source-extract"},"Tricep_Dumbbell_Kickback":{"version":1,"steps":{"hu":["Kezdj úgy, hogy mindkét kezedben egy-egy kézisúlyzó van, a tenyered a törzsed felé néz.","Most, miközben a felkarod mozdulatlan marad, fújd ki a levegőt, és told fel a súlyokat a tricepszeddel, amíg a karod teljesen ki nem nyúlik.","A felső megfeszítésnél tarts egy rövid szünetet, majd lélegezz be, és lassan engedd vissza a súlyzókat a kiinduló helyzetbe."],"en":["Start with a dumbbell in each hand and your palms facing your torso.","Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended.","After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Tricep_Side_Stretch":{"version":1,"steps":{"hu":["Told a jobb karodat át a tested előtt a bal válladon túlra, és fogd meg a könyöködet a bal kezeddel, amíg nyújtást nem érzel a tricepszedben."],"en":["Bring right arm across your body and over your left shoulder, holding your elbow with your left hand, until you feel a stretch in your tricep."]},"reviewed":false,"summaryMethod":"source-extract"},"Triceps_Overhead_Extension_with_Rope":{"version":1,"steps":{"hu":["Rögzíts egy kötelet az alsó csigára.","A mozdulat végrehajtásához nyújtsd ki a könyöködet, miközben a felkarod a helyén marad, és emeld a kezedet a fejed fölé.","Feszítsd meg a tricepszedet a mozdulat csúcspontján, majd lassan engedd vissza a súlyt a kiinduló helyzetbe."],"en":["Attach a rope to a low pulley.","To perform the movement, extend through the elbow while keeping the upper arm in position, raising your hands above your head.","Squeeze your triceps at the top of the movement, and slowly lower the weight back to the start position."]},"reviewed":false,"summaryMethod":"source-extract"},"Triceps_Pushdown":{"version":1,"steps":{"hu":["Rögzíts egy egyenes vagy ívelt rudat a felső csigára, és fogd meg felső fogással (tenyér lefelé), vállszélességben.","A tricepszedet használva told le a rudat, amíg meg nem érinti a combod elejét, és a karjaid teljesen ki nem nyúlnak, merőlegesen a talajra.","Egy másodperces tartás után a megfeszített helyzetben lassan vidd vissza a rudat a kiindulóponthoz."],"en":["Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.","Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor.","After a second hold at the contracted position, bring the bar slowly up to the starting point."]},"reviewed":false,"summaryMethod":"source-extract"},"Triceps_Pushdown_-_Rope_Attachment":{"version":1,"steps":{"hu":["Rögzíts egy kötelet a felső csigára, és fogd meg kalapácsfogással (a tenyered egymás felé néz).","A tricepszedet használva told le a kötelet, miközben a kötél mindkét végét a combod oldalához viszed.","Egy másodperces tartás után a megfeszített helyzetben lassan vidd vissza a kötelet a kiindulóponthoz."],"en":["Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).","Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs.","After holding for a second, at the contracted position, bring the rope slowly up to the starting point."]},"reviewed":false,"summaryMethod":"source-extract"},"Triceps_Pushdown_-_V-Bar_Attachment":{"version":1,"steps":{"hu":["Rögzíts egy V-fogantyút a felső csigára, és fogd meg felső fogással (tenyér lefelé), vállszélességben.","A tricepszedet használva told le a rudat, amíg meg nem érinti a combod elejét, és a karjaid teljesen ki nem nyúlnak, merőlegesen a talajra.","Egy másodperces tartás után a megfeszített helyzetben lassan vidd vissza a V-fogantyút a kiindulóponthoz."],"en":["Attach a V-Bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.","Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor.","After a second hold at the contracted position, bring the V-Bar slowly up to the starting point."]},"reviewed":false,"summaryMethod":"source-extract"},"Triceps_Stretch":{"version":1,"steps":{"hu":["Nyúlj a kezeddel a fejed mögé, fogd meg a könyöködet, és finoman húzd."],"en":["Reach your hand behind your head, grasp your elbow and gently pull."]},"reviewed":false,"summaryMethod":"source-extract"},"Tuck_Crunch":{"version":1,"steps":{"hu":["Kezdéshez feküdj le a földre vagy egy tornaszőnyegre, a hátad legyen a talajra nyomva.","Emeld fel a karjaidat a talajról, és keresztezd őket úgy, hogy a mellkasodon pihenjenek.","Lassan kezdd leengedni a törzsedet a kiinduló helyzetbe, közben lélegezz be."],"en":["To begin, lie down on the floor or an exercise mat with your back pressed against the floor.","Move your arms from the floor and cross them so they are resting on your chest.","Slowly begin to lower your torso back down to the starting position while inhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Two-Arm_Dumbbell_Preacher_Curl":{"version":1,"steps":{"hu":["Fogj egy-egy kézisúlyzót mindkét kezedbe, és helyezd a felkarodat a Scott-pad vagy a ferde pad tetejére.","Kilégzés közben a bicepszeddel hajlítsd fel a súlyokat, amíg a bicepszed teljesen meg nem feszül, és a súlyzók vállmagasságba nem érnek.","Szorítsd meg erősen a bicepszedet egy másodpercig a megfeszített helyzetben, majd ismételd az előírt ismétlésszámban."],"en":["Grab a dumbbell with each arm and place the upper arms on top of the preacher bench or the incline bench.","As you exhale, use the biceps to curl the weights up until your biceps is fully contracted and the dumbbells are at shoulder height.","Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions."]},"reviewed":false,"summaryMethod":"source-extract"},"Two-Arm_Kettlebell_Clean":{"version":1,"steps":{"hu":["Helyezz két kettlebellt a lábaid közé.","Vedd fel a kettlebelleket a válladra úgy, hogy kinyújtod a lábadat és a csípődet, miközben emeled a kettlebelleket a válladhoz.","Engedd vissza a kettlebelleket a kiinduló helyzetbe, és ismételd."],"en":["Place two kettlebells between your feet.","Clean the kettlebells to your shoulders by extending through the legs and hips as you raise the kettlebells towards your shoulders.","Lower the kettlebells back to the starting position and repeat."]},"reviewed":false,"summaryMethod":"source-extract"},"Two-Arm_Kettlebell_Jerk":{"version":1,"steps":{"hu":["Vedd fel két kettlebellt a válladra."],"en":["Clean two kettlebells to your shoulders."]},"reviewed":false,"summaryMethod":"source-extract"},"Two-Arm_Kettlebell_Military_Press":{"version":1,"steps":{"hu":["Vedd fel két kettlebellt a válladra.","Told fel és kifelé a kettlebelleket."],"en":["Clean two kettlebells to your shoulders.","Press the kettlebells up and out."]},"reviewed":false,"summaryMethod":"source-extract"},"Two-Arm_Kettlebell_Row":{"version":1,"steps":{"hu":["Helyezz két kettlebellt a lábad elé.","Fogd meg mindkét kettlebellt, és húzd őket a hasadhoz, a lapockáidat összehúzva és a könyöködet behajlítva."],"en":["Place two kettlebells in front of your feet.","Grab both kettlebells and pull them to your stomach, retracting your shoulder blades and flexing the elbows."]},"reviewed":false,"summaryMethod":"source-extract"},"Underhand_Cable_Pulldowns":{"version":1,"steps":{"hu":["Rögzítsd a combod. Fogd a rudat vállszélességnél szűkebb alsó fogással.","Húzd a rudat a felső mellkasodhoz.","Ne rángasd; lassan engedd vissza."],"en":["Secure your thighs and take an underhand grip narrower than shoulder width.","Pull the bar toward your upper chest.","Avoid jerking; return slowly."]},"reviewed":true,"summaryMethod":"curated"},"Upper_Back-Leg_Grab":{"version":1,"steps":{"hu":["Ülő helyzetben hajolj előre, és öleld át alulról a combodat mindkét karoddal.","Tartsd a térdedet összezárva és a lábaidat kinyújtva, miközben a mellkasodat a térdedhez viszed."],"en":["While seated, bend forward to hug your thighs from underneath with both arms.","Keep your knees together and your legs extended out as you bring your chest down to your knees."]},"reviewed":false,"summaryMethod":"source-extract"},"Upper_Back_Stretch":{"version":1,"steps":{"hu":["Kulcsold össze az ujjaidat úgy, hogy a hüvelykujjaid lefelé mutassanak, görbítsd be a válladat, miközben a kezeidet előre nyújtod."],"en":["Clasp fingers together with your thumbs pointing down, round your shoulders as you reach your hands forward."]},"reviewed":false,"summaryMethod":"source-extract"},"Upright_Barbell_Row":{"version":1,"steps":{"hu":["Fogj meg egy rudat felső fogással, kicsit vállszélességnél keskenyebben.","Most fújd ki a levegőt, és a válladnak az oldalsó részével emeld fel a rudat, a könyöködet felfelé és oldalra emelve.","Lassan engedd vissza a rudat a kiinduló helyzetbe."],"en":["Grasp a barbell with an overhand grip that is slightly less than shoulder width.","Now exhale and use the sides of your shoulders to lift the bar, raising your elbows up and to the side.","Lower the bar back down slowly to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Upright_Cable_Row":{"version":1,"steps":{"hu":["Fogj meg egy alsó csigára rögzített egyenes rudat felső fogással (a tenyered a combod felé néz), kicsit vállszélességnél keskenyebben.","A válladnak az oldalsó részével emeld fel a kábelrudat kilégzés közben.","Lassan engedd vissza a rudat a kiinduló helyzetbe."],"en":["Grasp a straight bar cable attachment that is attached to a low pulley with a pronated (palms facing your thighs) grip that is slightly less than shoulder width.","Use your side shoulders to lift the cable bar as you exhale.","Lower the bar back down slowly to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Upright_Row_-_With_Bands":{"version":1,"steps":{"hu":["Kezdéshez állj rá a gumiszalagra úgy, hogy a feszülés karnyújtásnyi távolságban kezdődjön.","A válladnak az oldalsó részével emeld fel a fogantyúkat kilégzés közben.","Lassan engedd vissza a fogantyúkat a kiinduló helyzetbe."],"en":["To begin, stand on an exercise band so that tension begins at arm's length.","Use your side shoulders to lift the handles as you exhale.","Lower the handles back down slowly to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Upward_Stretch":{"version":1,"steps":{"hu":["Nyújtsd ki mindkét kezedet egyenesen a fejed fölé, a tenyereid összeérjenek.","Lassan told a kezeidet felfelé és hátrafelé, közben tartsd egyenesen a hátadat."],"en":["Extend both hands straight above your head, palms touching.","Slowly push your hands up and back, keeping your back straight."]},"reviewed":false,"summaryMethod":"source-extract"},"V-Bar_Pulldown":{"version":1,"steps":{"hu":["Ülj le egy lehúzógépre, amelynek a felső csigájára V-fogantyú van rögzítve.","Fogd meg a V-fogantyút kalapácsfogással (a tenyered egymás felé néz).","Egy másodperces tartás után a megfeszített helyzetben lassan vidd vissza a fogantyút a kiinduló helyzetbe, közben lélegezz be."],"en":["Sit down on a pull-down machine with a V-Bar attached to the top pulley.","Grab the V-bar with the palms facing each other (a neutral grip).","After a second hold on the contracted position, slowly bring the bar back to the starting position as you breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"V-Bar_Pullup":{"version":1,"steps":{"hu":["Kezdd úgy, hogy a V-fogantyú közepét a húzódzkodó rúd közepére helyezed (feltéve, hogy az általad használt húzódzkodó állványon nincsenek kalapácsfogású fogantyúk).","A széles hátizmaiddal húzd fel a törzsedet, miközben a fejedet kissé hátradöntöd, hogy ne üsd meg magad az állal a rúddal.","Egy másodperces tartás után a megfeszített helyzetben lassan engedd vissza a tested a kiinduló helyzetbe, közben lélegezz be."],"en":["Start by placing the middle of the V-bar in the middle of the pull-up bar (assuming that the pull-up station you are using does not have neutral grip handles).","Using your lats, pull your torso up while leaning your head back slightly so that you do not hit yourself with the chin-up bar.","After a second hold on the contracted position, slowly lower your body back to the starting position as you breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Vertical_Swing":{"version":1,"steps":{"hu":["Hagyd, hogy a kézisúlyzó karnyújtásnyira lógjon a lábaid között, mindkét kezeddel tartva.","Erőteljesen fordítsd meg a mozdulatot a csípőd, a térded és a bokád kinyújtásával, hogy felfelé told magad, miközben a kézisúlyzót a fejed fölé lendíted.","Ahogy visszaérsz a földre, nyeld el az ütközést a lábaiddal, és húzd a kézisúlyzót a törzsedhez a következő ismétlés előtt."],"en":["Allow the dumbbell to hang at arms length between your legs, holding it with both hands.","Powerfully reverse the motion by extending at the hips, knees, and ankles to propel yourself upward, swinging the dumbell over your head.","As you land, absorb the impact through your legs and draw the dumbbell to your torso before the next repetition."]},"reviewed":false,"summaryMethod":"source-extract"},"Walking_Treadmill":{"version":1,"steps":{"hu":["Kezdéshez lépj fel a futópadra, és válaszd ki a kívánt opciót a menüből.","A futópad kényelmes, szív- és érrendszeri előnyöket nyújt, és általában kisebb terhelést jelent, mint a szabadtéri gyaloglás."],"en":["To begin, step onto the treadmill and select the desired option from the menu.","Treadmills offer convenience, cardiovascular benefits, and usually have less impact than walking outside."]},"reviewed":false,"summaryMethod":"source-extract"},"Weighted_Ball_Hyperextension":{"version":1,"steps":{"hu":["Kezdéshez feküdj hasra egy fitlabdára úgy, hogy a törzsed a labdának nyomódik és párhuzamos a talajjal.","Lassan emeld fel a törzsedet a derekad és az alsó hátad behajlításával.","Tartsd a megfeszített helyzetet az alsó hátadban egy másodpercig, majd engedd vissza a törzsedet a kiinduló helyzetbe, közben lélegezz be."],"en":["To begin, lie down on an exercise ball with your torso pressing against the ball and parallel to the floor.","Slowly raise your torso up by bending at the waist and lower back.","Hold the contraction on your lower back for a second and lower your torso back down to the starting position while inhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Weighted_Ball_Side_Bend":{"version":1,"steps":{"hu":["Kezdéshez feküdj egy fitlabdára úgy, hogy a törzsed bal oldala (derék, csípő és váll) a labdának nyomódik.","Emeld fel a törzsed oldalát a derekadnál oldalra hajolva, közben fújd ki a levegőt.","Cserélj oldalt, és ismételd meg a gyakorlatot."],"en":["To begin, lie down on an exercise ball with your left side of the torso (waist, hips and shoulder) pressed against the ball.","Raise the side of your torso up by laterally flexing at the waist while exhaling.","Switch sides and repeat the exercise."]},"reviewed":false,"summaryMethod":"source-extract"},"Weighted_Bench_Dip":{"version":1,"steps":{"hu":["Ehhez a gyakorlathoz egy padra van szükséged a hátad mögött, és egy másikra magad előtt.","Belégzés közben lassan engedd le a tested a könyöködet behajlítva, amíg a felkarod és az alkarod között kicsit 90 foknál kisebb szög nem lesz.","A tricepszedet használva told fel a törzsedet, és emeld vissza magad a kiinduló helyzetbe, közben fújd ki a levegőt."],"en":["For this exercise you will need to place a bench behind your back and another one in front of you.","Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm.","Using your triceps to bring your torso up again, lift yourself back to the starting position while exhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Weighted_Crunches":{"version":1,"steps":{"hu":["Feküdj hanyatt, a talpad legyen a földön, vagy egy padon pihenjen, a térded 90 fokban behajlítva.","Most fújd ki a levegőt, és lassan kezdd leemelni a válladat a talajról.","Ezután lélegezz be, és lassan engedd vissza magad a kiinduló helyzetbe."],"en":["Lie flat on your back with your feet flat on the ground or resting on a bench with your knees bent at a 90 degree angle.","Now, exhale and slowly begin to roll your shoulders off the floor.","Then inhale and slowly lower yourself back down to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Weighted_Jump_Squat":{"version":1,"steps":{"hu":["Helyezz egy könnyen terhelt rudat a válladra, a hátad mögé.","Ellenmozgást használva guggolj le részlegesen, és azonnal fordítsd meg az irányt, hogy robbanékonyan elrugaszkodj a földtől, kinyújtva a csípődet, a térdedet és a bokádat.","Amikor visszaérkezel a földre, nyeld el az ütközést a lábaiddal."],"en":["Position a lightly loaded barbell across the back of your shoulders.","Using a countermovement, squat partially down and immediately reverse your direction to explode off of the ground, extending through your hips, knees, and ankles.","As you return to the ground, absorb the impact through your legs."]},"reviewed":false,"summaryMethod":"source-extract"},"Weighted_Pull_Ups":{"version":1,"steps":{"hu":["Rögzíts egy súlyt egy tolódzkodó övre, és csatold a derekadra.","Most fújd ki a levegőt, és húzd fel a törzsedet, amíg a fejed a kezeid fölé nem kerül.","A felső, megfeszített helyzetben egy rövid szünet után lélegezz be, és lassan engedd vissza a törzsedet a kiinduló helyzetbe, kinyújtott karokkal és teljesen megnyúlt széles hátizmokkal."],"en":["Attach a weight to a dip belt and secure it around your waist.","Now, exhale and pull your torso up until your head is above your hands.","After a brief moment at the top contracted position, inhale and slowly lower your torso back to the starting position with your arms extended and your lats fully stretched."]},"reviewed":false,"summaryMethod":"source-extract"},"Weighted_Sissy_Squat":{"version":1,"steps":{"hu":["Egyenesen állva, vállszéles terpeszben, a lábujjaidat felemelve, az egyik kezeddel kapaszkodj a guggolóállvány oszlopaiba, a másik karoddal pedig tarts egy súlytárcsát a mellkasodon.","Miközben az egyik karoddal tartod magad, hajlítsd be a térdedet, és lassan engedd a törzsedet a talaj felé úgy, hogy a medencédet és a térdedet előre viszed.","Az egy másodperces tartás után a combizmaiddal told vissza a törzsedet a kiinduló helyzetbe."],"en":["Standing upright, with feet at shoulder width and toes raised, use one hand to hold onto the beams of a squat rack and the opposite arm to hold a plate on top of your chest.","As you use one arm to hold yourself, bend at the knees and slowly lower your torso toward the ground by bringing your pelvis and knees forward.","After your one second hold, use your thigh muscles to bring your torso back up to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Weighted_Sit-Ups_-_With_Bands":{"version":1,"steps":{"hu":["Kezdd úgy, hogy a gumiszalagokat a negatív pad aljához rögzíted.","Dugd át a lábaidat a negatív padon, amíg biztosan rögzítve nem lesznek.","Told fel a törzsedet, amíg a felsőtested merőleges nem lesz a talajra, közben fújd ki a levegőt."],"en":["Start out by strapping the bands around the base of the decline bench.","Position your legs through the decline machine until they are secured.","Move your torso upward until your upper body is perpendicular to the floor while exhaling."]},"reviewed":false,"summaryMethod":"source-extract"},"Weighted_Squat":{"version":1,"steps":{"hu":["Kezdd úgy, hogy két sík padot helyezel egymástól vállszélességnyire.","Kezdd el behajlítani a térdedet, miközben egyenes testtartást és felemelt fejet tartasz.","Kezdd el visszamozgatni a tested úgy, hogy főként a lábfejed párnájával nyomod a pad felszínét, miközben újra kinyújtod a lábaidat, és visszatérsz a kiinduló helyzetbe."],"en":["Start by positioning two flat benches shoulder width apart from each other.","Begin by bending the knees as you maintain a straight posture with the head up.","Begin to move the body back up by pushing the floor of the flat bench with the ball of your foot mainly as you straighten the legs again and go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Wide-Grip_Barbell_Bench_Press":{"version":1,"steps":{"hu":["Feküdj hanyatt egy sík padra, a talpad szilárdan a földön.","Belégzés közben lassan engedd le, amíg a rudat nem érzed a mellkasod közepén.","Egy másodperces szünet után told vissza a rudat a kiinduló helyzetbe, közben fújd ki a levegőt, és a mellizmaiddal told a rudat."],"en":["Lie back on a flat bench with feet firm on the floor.","As you breathe in, come down slowly until you feel the bar on your middle chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles."]},"reviewed":false,"summaryMethod":"source-extract"},"Wide-Grip_Decline_Barbell_Bench_Press":{"version":1,"steps":{"hu":["Feküdj hanyatt egy negatív padra, a lábaidat biztonságosan rögzítve a pad elején.","Belégzés közben lassan engedd le, amíg a rudat nem érzed a mellkasod alsó részén.","Egy másodperces szünet után told vissza a rudat a kiinduló helyzetbe, közben fújd ki a levegőt, és a mellizmaiddal told a rudat."],"en":["Lie back on a decline bench with the feet securely locked at the front of the bench.","As you breathe in, come down slowly until you feel the bar on your lower chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles."]},"reviewed":false,"summaryMethod":"source-extract"},"Wide-Grip_Decline_Barbell_Pullover":{"version":1,"steps":{"hu":["Feküdj egy negatív padra, mindkét lábadat biztonságosan rögzítve.","Kezdd el visszavinni a rudat lefelé félkör alakú mozdulattal, mintha le akarnád tenni a földre, de ehelyett állj meg, amikor a karjaid párhuzamosak a talajjal.","Amikor végeztél a sorozattal, lassan engedd le a rudat, amíg a fejeddel egy szintbe nem kerül, és engedd el."],"en":["Lie down on a decline bench with both legs securely locked in position.","Begin by moving the barbell back down in a semicircular motion as if you were going to place it on the floor, but instead, stop when the arms are parallel to the floor.","When finished with your set, slowly lower the barbell back down until it is level with your head and release it."]},"reviewed":false,"summaryMethod":"source-extract"},"Wide-Grip_Lat_Pulldown":{"version":1,"steps":{"hu":["Rögzítsd a combod. Fogd a rudat széles felső fogással.","Húzd a rudat magad előtt a felső mellkasodhoz.","Ne lendülj hátra; lassan engedd vissza."],"en":["Secure your thighs and take a wide overhand grip.","Pull the bar in front of you toward your upper chest.","Do not swing back; return slowly."]},"reviewed":true,"summaryMethod":"curated","board":"img/fig/lat-wide.webp"},"Wide-Grip_Pulldown_Behind_The_Neck":{"version":1,"steps":{"hu":["Ülj le egy lehúzógépre, amelynek a felső csigájára széles rúd van rögzítve.","Miközben mindkét karod kinyújtva van magad előtt, a rudat a választott fogásszélességben tartva, told előre a törzsedet és a fejedet.","Egy másodperces tartás után a megfeszített helyzetben, a lapockáidat összeszorítva, lassan told vissza a rudat a kiinduló helyzetbe, amikor a karjaid teljesen kinyúlnak, és a széles hátizmok teljesen megnyúlnak."],"en":["Sit down on a pull-down machine with a wide bar attached to the top pulley.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso and head forward.","After a second on the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched."]},"reviewed":false,"summaryMethod":"source-extract"},"Wide-Grip_Rear_Pull-Up":{"version":1,"steps":{"hu":["Fogd meg a húzódzkodó rudat úgy, hogy a tenyered előre néz, széles fogással.","Húzd fel a törzsedet, amíg a rúd a tarkód közelébe nem ér.","Egy másodperces tartás után a megfeszített helyzetben kezdj belélegezni, és lassan engedd vissza a törzsedet a kiinduló helyzetbe, amikor a karjaid teljesen kinyúlnak, és a széles hátizmok teljesen megnyúlnak."],"en":["Grab the pull-up bar with the palms facing forward using a wide grip.","Pull your torso up until the bar is near the back of your neck.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched."]},"reviewed":false,"summaryMethod":"source-extract"},"Wide-Grip_Standing_Barbell_Curl":{"version":1,"steps":{"hu":["Állj egyenesen, és tarts egy rudat a széles, külső markolatnál.","Folytasd a mozdulatot, amíg a bicepszed teljesen meg nem feszül, és a rúd vállmagasságba nem ér.","Lassan kezdd visszavinni a rudat a kiinduló helyzetbe, közben lélegezz be."],"en":["Stand up with your torso upright while holding a barbell at the wide outer handle.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level.","Slowly begin to bring the bar back to starting position as your breathe in."]},"reviewed":false,"summaryMethod":"source-extract"},"Wide_Stance_Barbell_Squat":{"version":1,"steps":{"hu":["Ezt a gyakorlatot biztonsági okokból a legjobb guggolóállványban végezni.","Lépj el az állványtól, és vegyél fel vállszélességnél szélesebb terpeszt, a lábujjaid kissé kifelé mutassanak.","Kezdd emelni a rudat kilégzés közben, a sarkaddal nyomva a talajt, miközben újra kinyújtod a lábaidat, és visszatérsz a kiinduló helyzetbe."],"en":["This exercise is best performed inside a squat rack for safety purposes.","Step away from the rack and position your legs using a wider-than-shoulder-width stance with the toes slightly pointed out.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Wide_Stance_Stiff_Legs":{"version":1,"steps":{"hu":["Kezdj a földre terhelt rúddal.","Kezdd a mozdulatot a csípőd bevonásával, told előre, miközben a karjaidat egyenesen lógni hagyod."],"en":["Begin with a barbell loaded on the floor.","Begin the movement be engaging the hips, driving them forward as you allow the arms to hang straight."]},"reviewed":false,"summaryMethod":"source-extract"},"Wind_Sprints":{"version":1,"steps":{"hu":["Lógj a húzódzkodó rúdon felső fogással.","Azonnal fordítsd meg a mozdulatot, és told vissza azt a lábat a kiinduló helyzetbe.","Folytasd a lábak váltogatását, amíg a sorozat véget nem ér."],"en":["Hang from a pull-up bar using a pronated grip.","Immediately reverse the motion, returning that leg to the starting position.","Continue alternating between legs until the set is complete."]},"reviewed":false,"summaryMethod":"source-extract"},"Windmills":{"version":1,"steps":{"hu":["Feküdj hanyatt, a karjaid oldalra kinyújtva, a lábaid egyenesen.","Emeld fel az egyik lábadat, és gyorsan told át a tested fölött, próbálva megérinteni a talajt az ellenkező kéz közelében.","Térj vissza a kiinduló helyzetbe, és ismételd a másik lábbal."],"en":["Lie on your back with your arms extended out to the sides and your legs straight.","Lift one leg and quickly cross it over your body, attempting to touch the ground near the opposite hand.","Return to the starting position, and repeat with the opposite leg."]},"reviewed":false,"summaryMethod":"source-extract"},"Worlds_Greatest_Stretch":{"version":1,"steps":{"hu":["Ez egy háromrészes nyújtás.","Most told az elülső lábaddal azonos oldali karodat a talajra, a könyököd az elülső láb mellett legyen.","10–20 másodperc után told a kezeidet az elülső lábfejed két oldalára."],"en":["This is a three-part stretch.","Now, place the arm on the same side as your front leg on the ground, with the elbow next to the foot.","After 10-20 seconds, place your hands on either side of your front foot."]},"reviewed":false,"summaryMethod":"source-extract"},"Wrist_Circles":{"version":1,"steps":{"hu":["Kezdj úgy, hogy egyenesen állsz, a lábaid vállszélességben.","Tartsd mozdulatlanul az egész testedet a csuklókon kívül, és kezdd el körbeforgatni mindkét csuklódat előre."],"en":["Start by standing straight with your feet being shoulder width apart from each other.","Keeping your entire body stationary except for the wrists, begin to rotate both wrists forward in a circular motion."]},"reviewed":false,"summaryMethod":"source-extract"},"Wrist_Roller":{"version":1,"steps":{"hu":["Kezdéshez állj egyenesen, és fogd meg a csuklóhengert felső fogással (a tenyered lefelé néz).","Forgasd az egyik csuklódat egyszerre felfelé irányban, hogy a súlyt felhozd a rúdhoz, miközben a kötelet feltekered a hengerre.","Amikor a súly elérte a rudat, lassan kezdd leengedni a súlyt a csuklód lefelé forgatásával, amíg a súly vissza nem ér a kiinduló helyzetbe."],"en":["To begin, stand straight up grabbing a wrist roller using a pronated grip (palms facing down).","Rotate one wrist at a time in an upward motion to bring the weight up to the bar by rolling the rope around the roller.","Once the weight has reached the bar, slowly begin to lower the weight back down by rotating the wrist in a downward motion until the weight reaches the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Wrist_Rotations_with_Straight_Bar":{"version":1,"steps":{"hu":["Tarts egy rudat mindkét kezeddel, a tenyered lefelé nézzen; a kezeid kb.","A kezeid között váltogatva hajtsd végre a mozdulatot a csukló nyújtásával, mintha egy újságot tekernél fel.","Fordítsd meg a mozdulatot a csukló behajlításával, ellenkező irányba tekerve."],"en":["Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width.","Alternating between each of your hands, perform the movement by extending the wrist as though you were rolling up a newspaper.","Reverse the motion by flexing the wrist, rolling the opposite direction."]},"reviewed":false,"summaryMethod":"source-extract"},"Yoke_Walk":{"version":1,"steps":{"hu":["A yoke-ot általában yoke eszközzel végzik, de néha hűtőszekrénnyel vagy más nehéz tárgyakkal is látni.","Kezdd azzal, hogy az eszközt a válladra helyezed hátul.","Kezdj el járni a lehető leggyorsabban, rövid, gyors léptekkel."],"en":["The yoke is usually done with a yoke apparatus, but is sometimes seen with refrigerators or other heavy objects.","Begin by racking the apparatus across the back of the shoulders.","Begin walking as quickly as possible using short, quick steps."]},"reviewed":false,"summaryMethod":"source-extract"},"Zercher_Squats":{"version":1,"steps":{"hu":["Ezt a gyakorlatot biztonsági okokból a legjobb guggolóállványban végezni.","Lépj el az állványtól, és vegyél fel vállszéles, közepes terpeszt, a lábujjaid kissé kifelé mutassanak.","Kezdd emelni a rudat kilégzés közben, főként a lábfejed párnájával nyomva a talajt, miközben újra kinyújtod a lábaidat, és visszatérsz a kiinduló helyzetbe."],"en":["This exercise is best performed inside a squat rack for safety purposes.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out.","Begin to raise the bar as you exhale by pushing the floor with the ball of your foot mainly as you straighten the legs again and go back to the starting position."]},"reviewed":false,"summaryMethod":"source-extract"},"Zottman_Curl":{"version":1,"steps":{"hu":["Állj egyenesen, mindkét kezedben egy-egy kézisúlyzóval, karnyújtásnyira lelógatva.","Tartsd a megfeszített helyzetet egy másodpercig, miközben megszorítod a bicepszedet.","Amikor a kézisúlyzók a combodhoz közelednek, kezdd el forgatni a csuklódat, hogy visszatérj a kalapácsfogásba (a tenyered a tested felé néz)."],"en":["Stand up with your torso upright and a dumbbell in each hand being held at arms length.","Hold the contracted position for a second as you squeeze the biceps.","As the dumbbells close your thighs, start rotating the wrist so that you go back to a neutral (palms facing your body) grip."]},"reviewed":false,"summaryMethod":"source-extract"},"Zottman_Preacher_Curl":{"version":1,"steps":{"hu":["Fogj egy-egy kézisúlyzót mindkét kezedbe, és helyezd a felkarodat a Scott-pad vagy a ferde pad tetejére.","Most forgasd el a csuklódat a mozdulat alsó pontján úgy, hogy a tenyered felfelé nézzen.","Szorítsd meg erősen a bicepszedet egy másodpercig a megfeszített helyzetben, és forgasd el a csuklódat úgy, hogy a tenyered újra lefelé nézzen."],"en":["Grab a dumbbell in each hand and place your upper arms on top of the preacher bench or the incline bench.","Now rotate your wrists once you are at the bottom of the movement so that the palms of the hands are facing up.","Squeeze the biceps hard for a second at the contracted position and rotate your wrists so that the palms are facing down again."]},"reviewed":false,"summaryMethod":"source-extract"},"Medium_Grip_Lat_Pulldown":{"version":1,"steps":{"hu":["Rögzítsd a combod. Fogd a rudat vállszéles felső fogással.","Könyöködet lefelé vezetve húzd a rudat a mellkasodhoz.","Törzsed maradjon stabil; kontrolláltan engedd vissza."],"en":["Secure your thighs and take a shoulder-width overhand grip.","Drive your elbows down, bringing the bar toward your chest.","Keep your torso steady; return with control."]},"reviewed":true,"summaryMethod":"curated","board":"img/fig/lat-medium.webp"}};
